let input = readLine()!.split(separator: " ").map { Int($0)! }
let H = input[0]
let W = input[1]
let K = input[2]

enum Square: Character {
    case white = "."
    case black = "#"
}

var c = [[Square]]()
let numberOfRowCombinations = 1 << H
let numberOfColumnCombinations = 1 << W
var dp = Array(repeating: Array(repeating: Optional<Int>.none, count: numberOfColumnCombinations), count: numberOfRowCombinations)
dp[0][0] = 0

for _ in stride(from: 0, to: H, by: 1) {
    let row = Array(readLine()!).map { Square(rawValue: $0)! }
    c.append(row)
    dp[0][0]! += row.filter { $0 == .black }.count
}

for i in stride(from: 0, to: H, by: 1) {
    for state in stride(from: 0, to: numberOfRowCombinations, by: 1) {
        guard state & (1 << i) == 0,
            let value = dp[state][0] else { continue }
        let nextState = state | (1 << i)
        dp[nextState][0] = value - c[i].filter { $0 == .black }.count
    }
}

for j in stride(from: 0, to: W, by: 1) {
    for rowState in stride(from: 0, to: numberOfRowCombinations, by: 1) {
        for columnState in stride(from: 0, to: numberOfColumnCombinations, by: 1) {
            guard columnState & (1 << j) == 0,
                let value = dp[rowState][columnState] else { continue }
            let nextColumnState = columnState | (1 << j)
            var numberOfBlackSquares = 0
            for i in stride(from: 0, to: H, by: 1) {
                if rowState & (1 << i) == 0, c[i][j] == .black {
                    numberOfBlackSquares += 1
                }
            }
            dp[rowState][nextColumnState] = value - numberOfBlackSquares
        }
    }
}

let result = dp.reduce(0) { sum, row in
    sum + row.filter { $0 == K }.count
}
print(result)

