struct Combinations<Seq: Sequence>: Sequence, IteratorProtocol {
    let pool: [Seq.Element]
    let r: Int

    var indecies: [Int]
    var first = true

    init(_ seq: Seq, _ r: Int) {
        self.pool = [Seq.Element](seq)
        self.r = r
        self.indecies = [Int](0..<r)
    }

    mutating func next() -> [Seq.Element]? {
        let n = pool.count
        guard 0...n ~= r else { return nil }
        guard !first else {
            first = false
            return indecies.map { pool[$0] }
        }

        var i = r - 1
        while indecies[i] == i + n - r {
            if i > 0 {
                i -= 1
            } else {
                return nil
            }
        }

        indecies[i] += 1
        for j in i+1..<r {
            indecies[j] = indecies[j - 1] + 1
        }

        return indecies.map { pool[$0] }
    }
}

