func pow(_ source: Int, _ count: Int) -> Int {
	var n = 1
	for _ in 0..<count {
		n *= source
	}
	return n
}
func gentf(_ n: Int, _ len: Int) -> [Bool] {
	let bin = String(n, radix: 2)
	var tf = Array(repeating: false, count: len)
	var i = len - bin.count
	for b in bin {
		if b == "1" { tf[i] = true }
		i += 1
	}
	return tf
}

