      (0 until 1 << w).map {bitw =>
        val res = c.map(_.clone)
        for (i <- (0 until h); j <- (0 until w)){
          if ((1 & (bith >> i)) == 1 || (1 & (bitw >> j)) == 1) {
            res(i)(j) = 'r'
          }
        }
        res.flatten.count(_ == '#')
      }
    }
    resList.count(_ == k).toString
  }

  def divideDigits(num: Long, base: Long = 10L): List[Long] = {
    def proc(num: Long, base: Long, flg: Boolean): List[Long] = {
      var flag = flg
      val quotient = num / base
      val remainder = if (num % base == 0) {
        flag = true
        base
      } else if (flag) {
        flag = false
        val temp = num % base - 1
        if (temp == 0) {
          flag = true
          base - 1
        } else temp
      } else {
        flag = flg
        num % base
      }
      quotient match {
        case 0 =>
          if (flag) {
            List.empty
          } else List(remainder)
        case _ => remainder :: proc(quotient, base, flag)
      }
    }

    proc(num, base, false).reverse//.filterNot(_ == 0)
  }


