object Main extends App {
	val pw = new java.io.PrintWriter(System.out)

	@scala.annotation.tailrec
	def loop(start: Int, end: Int)(f: Int => Unit): Unit =
		if (start < end) {
			f(start)
			loop(start + 1, end)(f)
		}

	val h, w, k = Scanner.nextInt
	val c = Array.fill(h)(Scanner.next.toArray.map(_ == '#'))

	val cnt = c.map(_.count(cij => cij)).sum

	def f(hs: Seq[Int], ws: Seq[Int]): Int =
		hs.map(i => c(i).count(cij => cij)).sum + ws.map(j => c.count(ci => ci(j))).sum -
		hs.map { i =>
			ws.map { j =>
				if (c(i)(j)) 1 else 0
			}.sum
		}.sum

	var ans = 0
	loop(0, h+1) { i =>
		loop(0, w+1) { j =>
			for {
				hs <- (0 until h).combinations(i)
				ws <- (0 until w).combinations(j)
				if (cnt - f(hs, ws) == k)
			} {
				ans += 1
			}
		}
	}

	pw.println(ans)
	pw.flush()
}

