	for (int j = 0; j < H; j++) {
		string temp;
		cin >> temp;
		for (int i = 0; i < W; i++) {

			if (temp[i] == '#') {
				c[j][i] = 1;
			}
			else {
				c[j][i] = 0;
			}
		}
	}
	int ans = 0;
	// 愚直に全部数える
	vector<int> i_line(W, 0), j_line(H, 0);
	for (int i = 0; i < W; i++) {
		for (int j = 0; j < H; j++) {
			i_line[i] += c[j][i];
		}
	}
	for (int j = 0; j < H; j++) {
		for (int i = 0; i < W; i++) {
			j_line[j] += c[j][i];
		}
	}
	int all_sum = 0;
	for (int j = 0; j < H; j++) {
		for (int i = 0; i < W; i++) {
			all_sum += c[j][i];
		}
	}

	int W_m = (1 << W) - 1;
	int H_m = (1 << H) - 1;
	for (int w = 0; w <= W_m; w++) {
		for (int h = 0; h <= H_m; h++) {
			int temp_sum = all_sum;
			for (int i = 0; i < W; i++) {
				if (((w >> i)&1) == 1) {
					temp_sum -= i_line[i];
				}
			}
			for (int j = 0; j < H; j++) {
				if (((h >> j) & 1) == 1) {
					temp_sum -= j_line[j];
				}
			}
			for (int j = 0; j < H; j++) {
				for (int i = 0; i < W; i++) {
				if (((h >> j) & 1) == 1 && ((w >> i) & 1) == 1)
					temp_sum += c[j][i];
				}
			}
			if (temp_sum == K) {
				ans++;
			}
		}

	}

	cout << ans << endl;
	return 0;
}

