int H, W, K;
char grid[6][6];
int res = 0;

int countblack() {
    int black = 0;
    for(int r=0; r<H; r++) {
        for(int c=0; c<W; c++) {
            if(grid[r][c]=='#') {
                black++;
            }
        }
    }
    return black;
}

//ith row or col
void fillways(int i) {
    if(i>=H+W) {
        //see if there is a solution
        int black = countblack();
        if(black==K) {
            res++;
        }
        return;
    }
    //rows
    if(i<H) {
        //consider not coloring this row red
        fillways(i+1);
        //consider filling this row with red
        for(int c=0; c<W; c++) {
            if(grid[i][c]=='.') {
                grid[i][c] = 'W';
            } else if(grid[i][c]=='#') {
                grid[i][c] = 'B';
            }
        }
        fillways(i+1);
        //backtrack
        for(int c=0; c<W; c++) {
            if(grid[i][c]=='W') {
                grid[i][c] = '.';
            } else if(grid[i][c]=='B') {
                grid[i][c] = '#';
            }
        }
    } else {
        //cols
        int c = i-H;
        //consider not coloring this col red
        fillways(i+1);
        //consider filling this row with red
        for(int r=0; r<H; r++) {
            if(grid[r][c]=='.') {
                grid[r][c] = 'E';
            } else if(grid[r][c]=='#') {
                grid[r][c] = 'F';
            }
        }
        fillways(i+1);
        //backtrack
        for(int r=0; r<H; r++) {
            if(grid[r][c]=='E') {
                grid[r][c] = '.';
            } else if(grid[r][c]=='F') {
                grid[r][c] = '#';
            }
        }
    }
}

