    for(int r=0; r<H; r++) {
        for(int c=0; c<W; c++) {
            cin >> grid[r][c];
        }
    }
    //brute force
    //fill row then fill column
    //at most 2^12 combinations
    //decide whether to fill row or not
    fillways(0);
    cout << res << "\n";
    return 0;
}

