        }
      }
    }

    auto Count = [&]() -> int64_t {
      int64_t cnt = 0;
      for (int64_t r = 0; r < H; ++r) {
        for (int64_t c = 0; c < W; ++c) {
          if (remaining[r][c]) {
            ++cnt;
          }
        }
      }
      return cnt;
    };
