    cin >> h >> w >> k;
    for(int i = 0; i < h; i++)
        cin >> s[i];
    int ans = 0;
    for(int S = 0; S < (1 << h); S++){
        for(int t = 0; t < (1 << w); t++){
            int rs = 0;
            for(int i = 0; i < h; i++){
                for(int j = 0; j < w; j++){
                    if(S & (1 << i) || t & (1 << j))    continue;
                    rs += (s[i][j] == '#');
                }
            }
            ans += (rs == k);
        }
    }
    cout << ans << endl;
}
