void brute (vector <int> h, vector <int> w) {
    if (used[{h, w}])
        return;
    int q = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            auto it1 = lower_bound(all(h), i);
            auto it2 = lower_bound(all(w), j);
            bool ok1, ok2;
            ok1 = ok2 = true;
            if (it1 != h.end() && *it1 == i) {
                ok1 = false;
            }
            if (it2 != w.end() && *it2 == j) {
                ok2 = false;
            }
            if (ok1 && ok2 && a[i][j] == '#') {
                q++;
            }
        }
    }
    if (q == k) {
        ans++;
        used[{h, w}] = true;
    }

    int st_h, st_w;
    if (h.size() > 0) {
        st_h = h.back() + 1;
    }
    else {
        st_h = 0;
    }

    if (w.size() > 0) {
        st_w = w.back() + 1;
    }
    else {
        st_w = 0;
    }


    for (int i = st_h; i < n; i++) {
        h.push_back(i);
        brute(h, w);
        h.pop_back();
    }

    for (int i = st_w; i < m; i++) {
        w.push_back(i);
        brute(h, w);
        w.pop_back();
    }
}

