void function2(int initial,int final,vector<int> &vec,int status)
{
	if(initial>final)
	{
		if(status==1)
		{
			vec1.push_back(vec);
		}
		else
		{
			vec2.push_back(vec);
		}
	}
	else
	{
		vec.push_back(initial);
		function2(initial+1,final,vec,status);
		vec.pop_back();
		function2(initial+1,final,vec,status);
	}
}
