char G[6][6];
char dup[6][6];

int main() {
    i64 H, W, K; cin >> H >> W >> K;
    REP(i, H) REP(j, W) cin >> G[i][j];

    i64 ans = 0;
    for (i64 bit = 0; bit < (1 << (H + W)); bit++) {
        REP(i, H) REP(j, W) dup[i][j] = G[i][j];

        REP(i, H) {
            if (bit & (1 << i)) {
                REP(j, W) {
                    dup[i][j] = '@';
                }
            }
        }

        REP(i, W) {
            if (bit & (1 << (i + H))) {
                REP(j, H) {
                    dup[j][i] = '@';
                }
            }
        }

        i64 cnt = 0;
        REP(i, H) {
            REP(j, W) {
                if (dup[i][j] == '#') cnt++;
            }
        }
        if (cnt == K) ans++;
    }

    cout << ans << endl;

    return 0;
}

#include <iostream>

using namespace std;

const int N = 8;
char grid[N][N];
int h, w, k;
int res;

void dfs(int r, int c)
{
  //cout << "r: " << r << ", c: " << c << endl;
  if(r == h && c == w)
  {
    int cnt = 0;
    for(int i = 0; i < h; ++i)
    {
      for(int j = 0; j < w; ++j)
      {
        //cout << grid[i][j] << " ";
        if(grid[i][j] == '#')
          cnt++;
      }
      //cout << endl;
    }
    if(cnt == k)
      res++;
    return;
  }

  if(r < h)
  {
    dfs(r+1, c);

    char r_copy[N];
    for(int j = 0; j < w; ++j)
    {
      r_copy[j] = grid[r][j];
      grid[r][j] = '0';
    }

    dfs(r+1, c);

    for(int j = 0; j < w; ++j)
    {
      grid[r][j] = r_copy[j];
    }
  }
  else if(c < w)
  {
    dfs(r, c+1);
    char c_copy[N];
    for(int i = 0; i < h; ++i)
    {
      c_copy[i] = grid[i][c];
      grid[i][c] = '0';
    }

    dfs(r, c+1);

    for(int i = 0; i < h; ++i)
    {
      grid[i][c] = c_copy[i];
    }
  }

}

int main()
{
  cin >> h >> w >> k;
  for(int i = 0; i < h; ++i)
    for(int j = 0; j < w; ++j)
      cin >> grid[i][j];

  dfs(0, 0);
  cout << res << endl;

  return 0;
}

