int main(void){
	int h,w,k,count=0;
	scanf("%d %d %d",&h,&w,&k);
	char c[h][w+1];
	char a;

	for(int i=0;i<h;i++){
		scanf("%c",&a);
		c[i][w]=0;
		for(int j=0;j<w;j++){
			scanf("%c",&c[i][j]);
			if(c[i][j]=='#'){
				c[i][w]++;
				count++;
			}
		}
	}

	int num,numnum,ans=0;

	for(int i=0;i<pow(2,h);i++){
		num=count;
		for(int j=0;j<h;j++){
			if(i&(1<<j)){
				num-=c[j][w];
				if(num<k){
					break;
				}
			}
		}
		for(int l=0;l<pow(2,w);l++){
			numnum=num;
			for(int m=0;m<w;m++){
				if(l&(1<<m)){
					for(int n=0;n<h;n++){
						if(c[n][m]=='#'&&!(i&(1<<n))){
							numnum-=1;
						}
					}
					if(numnum<k){
						break;
					}
				}		
			}
			if(numnum==k){
				ans++;
			}
		}

	}
