using namespace std;

int Count(const vector<string>& grid, const vector<bool>& rows, const vector<bool>& cols) {
  int cnt = 0;
  for (size_t h = 0; h < grid.size(); ++h) {
    if (rows[h]) continue;
    const string& row = grid[h];
    for (size_t w = 0; w < row.size(); ++w) {
      if (cols[w]) {
        continue;
      } else if (row[w] == '#') {
        ++cnt;
      }
    }
  }
  return cnt;
}

int64_t PaintCols(const vector<string>& grid, const int K, const vector<bool>& rows,
                  vector<bool>&cols, const size_t col) {
  if (col >= grid[0].size()) {
    if (Count(grid, rows, cols) == K) {
      return 1;
    }
    return 0;
  }
  int64_t result = 0;
  { // Paint col
    vector<bool> paint_cols = cols;
    paint_cols[col] = true;
    result += PaintCols(grid, K, rows, paint_cols, col + 1);
  }
  result += PaintCols(grid, K, rows, cols, col + 1);

  return result;
}

int64_t PaintRows(const vector<string>& grid, const int K, vector<bool>& rows, const size_t row) {
  if (row >= grid.size()) {
    vector<bool> cols(grid[0].size(), false);
    return PaintCols(grid, K, rows, cols, 0);
  }
  int64_t result = 0;
  {  // paint row
    vector<bool> paint_rows = rows;
    paint_rows[row] = true;
    result += PaintRows(grid, K, paint_rows, row + 1);
  }
  result += PaintRows(grid, K, rows, row + 1);
  return result;
}

int64_t Solve(vector<string>& grid, int K) {
  vector<bool> rows(grid.size(), false);
  return PaintRows(grid, K, rows, 0);
}

