string toBin(int n, int k)
{
    string t;
    if(n == 0) t = "0";
    while(n)
    {
        t += to_string(n%2)[0];
        n /= 2;
    }
    reverse(t.begin(), t.end());
    n = t.size();
    return str.substr(0, k-n) + t;
