    dbg(combo);
    ll ans = 0;
    F0R(i, combo) {
       // dbg(i);
        //first n bits are rows
        int num = i;
        vvi tmp = grid;
        F0R(j, n + m + 1) {
            if (isBitSet(num, j)) {
                //jth bit set
                if (j < n) {
                    F0R(k, m) {
                        tmp[j][k] = 0;
                    }
                } else {
                    F0R(k, n) {
                        tmp[k][j - n] = 0;
                    }
                }
            }
        }
        int total = 0;
        F0R(j, n) {
            F0R(k, m) {
                total += tmp[j][k];
            }
        }
        if (total == k) {
            ++ans;
        }
    }

    cout << ans << endl;

}

