int H, W;
bool f(  vector<vector<bool> > a, int hmask, int wmask, int K) {
  REP(h, H) {
    if((hmask >> h) & 1) {
      REP(w, W) a[h][w] = false;
    }
  }
  REP(w, W) {
    if((wmask >> w) & 1) {
      REP(h, H) a[h][w] = false;
    }
  }
  int cnt = 0;
  REP(h,H) REP(w,W) {
    if(a[h][w]) cnt++;
  }
  return cnt == K;
}

int main() {
  vector<vector<bool> > a;
  int K; cin>>H>>W>>K;
  a = vector<vector<bool> > (H, vector<bool>(W, false));
  REP(h,H) {
    string line ; cin>>line;
    REP(w,W) {
      if(line[w] == '#') a[h][w] = true;
    }
  }
  int ans = 0;
  REP(h, 1<<H) {
    REP(w, 1<<W) {
      bool ret = f(a, h, w, K);
      if(ret) ans++;
    }
  }
  cout << ans << endl;
  return 0;
}

