int ans = 0; //count answer

void func(int r, int c)
{
	//first loop row, second loop column
	//r, c = current row, current column
	if(r<h) //r<h => looking at a row r
	{
		//process row
		//choose not paint
		func(r+1,c); 
		//choose paint
		char original[10]; //store the original colors of row r
		for(int i=0;i<w;i++) //paint the row
		{
			original[i] = a[r][i];
			a[r][i]='R'; //R = red
		}
		func(r+1,c);
		for(int i=0;i<w;i++) //return to original color (unpaint)
		{
			a[r][i] = original[i];
		}
	}
	else //r>=h => rows finish processing
	{
		if(c<w) //c<w => looking at column c
		{
			func(r,c+1);
			char original[10]; //store the original colors of row r
			for(int i=0;i<h;i++) //paint the row
			{
				original[i] = a[i][c];
				a[i][c]='R'; //R = red
			}
			func(r,c+1);
			for(int i=0;i<h;i++) //return to original color (unpaint)
			{
				a[i][c] = original[i];
			}
		}
		else //processed everything, update answer
		{
			//count number of black squares
			int cnt = 0;
			for(int i=0;i<h;i++)
			{
				for(int j=0;j<w;j++)
				{
					if(a[i][j]=='#') cnt++;
				}
			}
			if(cnt==k) ans++; //found valid way
		}
	}
}

