class HAndV{
public:
	int choices(vector<string> &grid, int k){
		int ans = 0;
		int h = grid.size();
		int w = grid[0].size();
		int bl;
		rep(0, (1 << h), 1, i){
			rep(0, (1 << w), 1, j){
