int assign(int R, int C)
{
	int ans = 0;

	for (int i = 1; i <= R; i *= 2)
		if (i & R)
		{
			int rn = log2(i);

			for (int j = 0; j < c; ++j)
				ans += cpy[rn][j],
				       cpy[rn][j] = 0;
		}

	for (int i = 1; i <= C; i *= 2)
		if (i & C)
		{
			int cn = log2(i);

			for (int j = 0; j < r; ++j)
				ans += cpy[j][cn],
				       cpy[j][cn] = 0;
		}

	return ans;
}

