string binary(int x, int size){
    string b;
    for(int i = 0; i < size; ++i){
        if((x >> i) % 2 == 1)
            b.push_back('1');
        else
            b.push_back('0');
    }
    reverse(b.begin(), b.end());
    return b;
}

