typedef long long ll;
bool solve(vector<string> C, int rs, int cs, int k) {
  int blk = 0;
  for (unsigned i = 0; i < C.size(); i++) {
    for (unsigned j = 0; j < C[0].size(); j++) {
      int im = 1 << i;
      int jm = 1 << j;
      if ((im & rs) == 0 && (jm & cs) == 0) {
        if (C[i][j] == '#')
          blk++;
      }
    }
  }
  return blk == k;
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(NULL);
  int h, w, k;
