  for (auto &s : C)
    cin >> s;
  int rm = 1 << h;
  int cm = 1 << w;
  int ans = 0;
  for (int rs = 0; rs < rm; rs++) {
    for (int cs = 0; cs < cm; cs++) {
      ans += (solve(C, rs, cs, k));
    }
  }
  cout << ans << "\n";
}

