using namespace std;

char matrix[6][6];
int totalBlack = 0;
int h, w, k;
map<pair<vector<int>, vector<int>>, bool> memo;

int dp(vector<int> r, vector<int> c, int ir, int ic)
{
    if (memo[make_pair(r, c)])
        return 0;
    int res = 0;
    if (ir == r.size() && ic == c.size())
    {
        res = totalBlack;

        for (int i = 0; i < h; i++)
        {
            for (int k = 0; k < w; k++)
            {
                if ((r[i] || c[k]) && matrix[i][k] == '#')
                {
                    res--;
                }
            }
        }

        memo[make_pair(r, c)] = true;
        res == k ? res = 1 : res = 0;
        return res;
    }
    for (int i = 0; i < 2; i++)
    {
        for (int k = 0; k < 2; k++)
        {
            int rsum = 0, csum = 0;
            if (ir < r.size())
            {
                r[ir] = i;
                rsum++;
            }
            if (ic < c.size())
            {
                c[ic] = k;
                csum++;
            }
            res += dp(r, c, ir + rsum, ic + csum);
        }
    }
    return res;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin >> h >> w >> k;
    for (int i = 0; i < h; i++)
    {
        for (int k = 0; k < w; k++)
        {
            cin >> matrix[i][k];
            if (matrix[i][k] == '#')
            {
                totalBlack++;
            }
        }
    }
    vector<int> r(h, -1);
    vector<int> c(w, -1);
    int ans = dp(r, c, 0, 0);
    cout << ans;
    cin >> h;
}

