int check(int x, int y){
	vector<int> r, c;
	while(x){
		r.pb(x & 1);
		x >>= 1;
	}
	while(y){
		c.pb(y & 1);
		y >>= 1;
	}
	while(r.size() < h) r.pb(0);
	while(c.size() < w) c.pb(0);
	char t[10][10];
	for(int i = 1; i <= h; ++i) strcpy(t[i] + 1, s[i] + 1);

	for(int i = 1; i <= h; ++i){
		if(r[i - 1] == 1){
			for(int j = 1; j <= w; ++j) t[i][j] = '!';
		}
	}
	for(int i = 1; i <= w; ++i){
		if(c[i - 1] == 1){
			for(int j = 1; j <= h; ++j) t[j][i] = '!';
		}
	}	
	int cnt = 0;
	for(int i = 1; i <= h; ++i){
		for(int j = 1; j <= w; ++j){
			cnt += (t[i][j] == '#' ? 1 : 0);
		}
	}
	return cnt;
}

