int n, m, k, cnt, com;
int b[8][8];
bool a[8][8];
string s;

int main() {
	ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> n >> m >> k;
	for (int i = 1; i <= n; i++) {
		cin >> s;
		for (int j = 1; j <= m; j++) {
			a[i][j] = (s[j-1] == '#');
			b[i][j] = b[i-1][j] + b[i][j-1] - b[i-1][j-1] + a[i][j];
		}
	}

	cnt = b[n][m];

	int ti = 1 << n;
	int tj = 1 << m;

	for (int i = 1; i < ti; i++) {					// all horizontal line case
		int sum = cnt;
		for (int j = 1; j <= n; j++) {
			if (i & (1 << (j - 1)))  sum -= b[j][m] - b[j-1][m];
		}
		if (sum == k)  com++;
	}

	for (int i = 1; i < tj; i++) {					// all vertical line case
		int sum = cnt;
		for (int j = 1; j <= m; j++) {
			if (i & (1 << (j - 1)))  sum -= b[n][j] - b[n][j-1];
		}
		if (sum == k)  com++;
	}

	for (int i = 1; i < ti; i++) {
		for (int j = 1; j < tj; j++) {				// cross lines cases
			int sum = cnt;
			for (int z = 1; z <= n; z++) {
				if (i & (1 << (z - 1)))  sum -= b[z][m] - b[z-1][m];
			}
			for (int z = 1; z <= m; z++) {
				if (j & (1 << (z - 1)))  sum -= b[n][z] - b[n][z-1];
			}
			for (int z = 1; z <= n; z++) {
				for (int l = 1; l <= m; l++) {
					if (i & (1 << (z - 1)) && j & (1 << (l - 1))) {
						sum += a[z][l];
					}
				}
			}

			if (sum == k)  com++;
		}
	}

	if (cnt == k)  com++;
	cout << com << endl;
	return 0;
}

