int solve(ll H, ll i, vector<int>&Hb, ll W, ll j, vector<int>&Wb, ll K, vector<string>& c){

    // 終了条件
    if( i==H and j==W ){
        int cnt = 0;
        for(ll ik=0; ik<H; ik++) {
            for(ll jk=0; jk<W; jk++) {
                if( Hb[ik] == 0 and Wb[jk] == 0 and c[ik][jk] == '#'){
                    cnt++;
                }
            }
        }
        /*
        for(auto &&elm : Hb) {
                cout << elm << " ";
            }
            cout << endl;

            for(auto &&elm : Wb) {
                cout << elm << " ";
            }
            cout << endl;
        */
        if(cnt == K) {
            return 1;
        }
        else {
            return 0;
        }
    }

    int ans = 0;
    if( i<H ){
        Hb[i] = 0;                  // 選択しない
        ans += solve(H,i+1,Hb,W,j,Wb,K,c);
        Hb[i] = 1;                  // 選択する
        ans += solve(H,i+1,Hb,W,j,Wb,K,c);
    }
    else{
        Wb[j] = 0;
        ans += solve(H,i,Hb,W,j+1,Wb,K,c);
        Wb[j] = 1;
        ans += solve(H,i,Hb,W,j+1,Wb,K,c);
    }
    return ans;

}


