int h, w, k;
char c[6][6];
int ans;

void dfs(int i, bool row[], int j, bool col[]) {
    if (i < h) {
        bool rowFalse[h], rowTrue[h];
        REP(x, h) rowFalse[x] = rowTrue[x] = row[x];
        dfs(i + 1, rowFalse, j, col);
        rowTrue[i] = true;
        dfs(i + 1, rowTrue, j, col);
    } else if (j < w) {
        bool colFalse[w], colTrue[w];
        REP(y, w) colFalse[y] = colTrue[y] = col[y];
        dfs(i, row, j + 1, colFalse);
        colTrue[j] = true;
        dfs(i, row, j + 1, colTrue);
    } else {
        int count = 0;
        REP(x, h) REP(y, w) {
            if (!row[x] && !col[y] && c[x][y] == '#') {
                count++;
            }
        }
        if (count == k) {
            ans++;
        }
    }
}

