    for(int i = 0;i < H;i++) {
        for(int j = 0;j < W;j++) {
            cin >> vec.at(i).at(j);
        }
    }
    int ret = 0;
    for(int bit = 0;bit < (1 << (H + W));bit++) {
        vector<bool> cnt(H + W);
        for(int i = 0;i < H + W;i++) {
            if(bit & (1 << i)) {
                cnt.at(i) = true;
            }
