void dfs(int r,int c)
{
	if(r<n)
	{
		vis_row[r]=1;
		dfs(r+1,c);
		vis_row[r]=0;
		dfs(r+1,c);
	}
	else if(c<m)
	{
		vis_col[c]=1;
		dfs(r,c+1);
		vis_col[c]=0;
		dfs(r,c+1);
	}
	else
	{
		for(int i=0;i<n;i++)
