using namespace std;

int main(void)
{
    int height, width;
    int black_req;

    cin >> height >> width >> black_req;

    bool is_black[6][6];

    for(int i = 0; i < height; i++){
        for(int j = 0; j < width; j++){
            char c;
            cin >> c;
            if(c == '#'){
                is_black[i][j] = true;
            }else{
                is_black[i][j] = false;
            }
        }
    }

    bool cp_is_black[6][6];

    int fulfill_cnt = 0;
    for(int vert = 0; vert < (1 << height); vert++){
        for(int horiz = 0; horiz < (1 << width); horiz++){
            for(int i = 0; i < height; i++){
                for(int j = 0; j < width; j++){
                    cp_is_black[i][j] = is_black[i][j];
                }
            }

            for(int h = 0; h < height; h++){
                if(vert & (1 << h)){
                    for(int w = 0; w < width; w++){
                        cp_is_black[h][w] = false;
                    }
                }
            }

            for(int w = 0; w < width; w++){
                if(horiz & (1 << w)){
                    for(int h = 0; h < height; h++){
                        cp_is_black[h][w] = false;
                    }
                }
            }
            int black_cnt = 0;
            for(int i = 0; i < height; i++){
                for(int j = 0; j < width; j++){
                    if(cp_is_black[i][j]){
                        black_cnt += 1;
                    }
                }
            }

            if(black_cnt == black_req){
                fulfill_cnt += 1;
            }
        }
    }

    cout << fulfill_cnt << endl;

    return 0;
}

