#include <bits/stdc++.h>
using namespace std;

int H, W, K;
char grid[11][11];

vector<int> extract(int bits)
{
	vector<int> ans;
	for(int i = 0; i < 6; i++)
	{
		ans.push_back(bits % 2);
		bits /= 2;
	}

	return ans;
}

bool isBlack[11][11];
void fillRow(int row)
{
	for(int i = 0; i < W; i++)
		isBlack[row][i] = false;
}

void fillCol(int col)
{
	for(int i = 0; i < H; i++)
		isBlack[i][col] = false;
}

void resetGrid()
{
	for(int i = 0; i < H; i++)
	{
		for(int j = 0; j < W; j++)
			isBlack[i][j] = (grid[i][j] == '#');
	}
}

int main()
{
	scanf("%d%d%d", &H, &W, &K);
	for(int i = 0; i < H; i++)
	{
		for(int j = 0; j < W; j++)
			scanf(" %c", &grid[i][j]);
	}

	const int maxHBits = (1 << H) - 1, maxWBits = (1 << W) - 1;
	int ans = 0;

	for(int hBits = 0; hBits <= maxHBits; hBits++)
	{
		for(int wBits = 0; wBits <= maxWBits; wBits++)
		{
			resetGrid();

			vector<int> extractedH = extract(hBits), extractedW = extract(wBits);
			for(int i = 0; i < 6; i++)
			{
				if(extractedH[i])
					fillRow(i);

				if(extractedW[i])
					fillCol(i);
			}

			int blackCount = 0;
			for(int i = 0; i < H; i++)
			{
				for(int j = 0; j < W; j++)
					blackCount += (int)(isBlack[i][j]);
			}

			if(blackCount == K)
			{
				//printf("hBits = %d, wBits = %d\n", hBits, wBits);
				ans++;
			}
		}
	}

	printf("%d", ans);
}

