    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, K;
    cin >> H >> W >> K;

    vector<vector<int>> C;
    REP(i, H)
    {
        string t;
        cin >> t;

        C.push_back(vector<int>());

        REP(j, W)
        {
            //黒が１、白が０
            C[i].push_back(t[j] == '#' ? 1 : 0);
        }
    }

    int ans = 0;
    REP(i, pow(2, H))
    {
        REP(j, pow(2, W))
        {
            //作業用配列
            vector<vector<int>> CT;
            REP(y, H)
            {
                CT.push_back(vector<int>());
                REP(x, W)
                {
                    CT[y].push_back(C[y][x]);
                }
            }

            //行を染めていく
            int q = i;
            REP(ii, H)
            {
                int r = q % 2;
                q = q / 2;

                if (r == 1)
                {
                    REP(jj, W)
                    {
                        CT[ii][jj] = 0;
                    }
                }
            }

            //列を染めていく
            q = j;
            REP(jj, W)
            {
                int r = q % 2;
                q = q / 2;

                if (r == 1)
                {
                    REP(ii, H)
                    {
                        CT[ii][jj] = 0;
                    }
                }
            }

            //数え上げる
            int sum = 0;
            REP(y, H)
            {
                REP(x, W)
                {
                    sum += CT[y][x];
                }
            }

            if (sum == K)
                ans++;
        }
    }

    cout << ans << endl;

    return 0;
}

