ll dfs(ll x, ll y) {
  ll ans = 0;
  if (x == h) {
    if (y == w) {
      for (ll i = 0; i < h; i++) for (ll j = 0; j < w; j++) {
        if (nh[i] == 0 && nw[j] == 0 && c[i][j] == '#') ans++;
      }
      return ans == k ? 1 : 0;
    }
    ans += dfs(x, y+1);
    nw[y] = 1;
    ans += dfs(x, y+1);
    nw[y] = 0;
    return ans;
  }
  ans += dfs(x+1, y);
  nh[x] = 1;
  ans += dfs(x+1, y);
  nh[x] = 0;
  return ans;
}

