/// BIT
struct BIT {
 private:
  vector<ll> node;
  int n;

 public:
  void init(int n_) {
    n = n_;
    node.resize(n, 0);
  }
  // 0-indexed
  void add(int pos, ll val) {
    for (int i = pos; i < n; i |= i + 1) node[i] += val;
  }
  // [0, pos)
  ll sum(int pos) {
    ll ret = 0;
    for (int i = pos - 1; i >= 0; i = (i & (i + 1)) - 1) ret += node[i];
    return ret;
  }
  // [start, end)
  ll sum(int start, int end) { return sum(end) - sum(start); }
};

