vector<vector<int>> comb1,comb2;

void func(int ind,vi& temp,vi cur,int c){
    int sz=sz(temp);

    if(ind==sz){
        if(c==0)
        comb1.pb(cur);
        else
        comb2.pb(cur);

        return;    
    }

    func(ind+1,temp,cur,c);
    cur.pb(temp[ind]);
    func(ind+1,temp,cur,c);
    cur.pop_back();

}

bool chk(vector<int> c1,vector<int> c2,vector<vector<char>> mat,int k){
    int n=sz(mat);
    int m=sz(mat[0]);

    for(auto u:c1){
        forn(i,0,m)
        mat[u][i]='.';   
    }

    for(auto u:c2){
        forn(i,0,n)
        mat[i][u]='.';   
    }

    int cnt=0;

    forn(i,0,n){
        forn(j,0,m){
            if(mat[i][j]=='#')
            cnt++;
        }
    }

    return cnt==k;
}

void solve(){
    int n,m,k;
    cin>>n>>m>>k;

    vector<vector<char>> mat(n,vector<char>(m));

    forn(i,0,n){
        forn(j,0,m){
            cin>>mat[i][j];
        }
    }

    vi temp;

    temp.resize(n);

    forn(i,0,n){
        temp[i]=i;
    }

    func(0,temp,{},0);

    temp.resize(m);

    forn(i,0,m){
        temp[i]=i;
    }            

    func(0,temp,{},1);

    int sz1=sz(comb1);
    int sz2=sz(comb2);

    int ans=0;

    for(int i=0;i<sz1;i++){
        for(int j=0;j<sz2;j++){
            if(chk(comb1[i],comb2[j],mat,k))
            ans++;
        }
    }
    cout<<ans;
}    

int main(){
