int n, m, k, tot;
ll ans;

set<set<pair<int,int>>> check;
void rec(int black, vector<vector<int>>& grid, set<pair<int,int>>& used) {
	if (black == k) {
		if (!check.count(used)) {
			++ans;
			check.insert(used);
		}
		return;
	}
	else if (black < k) {
		return;
	}

	for (int i = 0; i < n; ++i) {
		if (!used.count({0, i})) {
			int cnt = 0;
			vector<int> pos;
			for (int j = 0; j < m; ++j) {
				if (grid[i][j]) {
					++cnt, grid[i][j] = 0;
					pos.push_back(j);
				}
			}

			used.insert({0, i});
			rec(black - cnt, grid, used);

			used.erase({0, i});
			for (int j : pos)
				grid[i][j] = 1;
		}
	}

	for (int j = 0; j < m; ++j) {
		if (!used.count({1, j})) {
			int cnt = 0;
			vector<int> pos;
			for (int i = 0; i < n; ++i)
				if (grid[i][j]) {
					++cnt, grid[i][j] = 0;
					pos.push_back(i);
				}

			used.insert({1, j});
			rec(black - cnt, grid, used);

			used.erase({1, j});
			for (int i : pos)
				grid[i][j] = 1;
		}
	}
}

