bool solve(int mask) {
	int ile = 0;
	REP(i, n) {
		s2[i] = s[i];
	}
	REP(i, n) {
		if (mask & (1 << i)) {
			REP(j, m) {
				s2[i][j] = '.';
			}
		}
	}
	FOR(i, n, n + m - 1) {
		if (mask & (1 << i)) {
			int j = i - n;
			REP(k, n) {
				s2[k][j] = '.';
			}
		}
	}
	REP(i, n) {
		REP(j, m) {
			if (s2[i][j] == '#') ile++;
		}
	}
	return ile == k;
}

