void solve() {
	ll n, m, k;
	cin >> n >> m >> k;
	int ans = 0;
	vector<VI> grid(n + 1,VI(m + 1));
	rep(i, 1, n + 1) {
		string s;
		cin >> s;
		rep(j, 1, m + 1)grid[i][j] = s[j-1];
	}
	for (int row = 0; row < (1 << n); row++) {
		for (int col = 0; col < (1 << m); col++) {
			VI rows, cols;
			int r = row, c = col;
			int p = 1;
			while (r) {
				if (r & 1)rows.push_back(p);
				r >>= 1;
				p++;
			}
			p = 1;
			while (c) {
				if (c & 1)cols.push_back(p);
				c >>= 1;
				p++;
			}
			vector<VI> copy = grid;
			for (int i = 0; i < rows.size(); i++) {
				for (int j = 1; j <= m; j++)copy[rows[i]][j] = '*';
			}
			for (int i = 0; i < cols.size(); i++) {
				for (int j = 1; j <= n; j++)copy[j][cols[i]] = '*';
			}
			int cnt1 = 0;
			rep(i, 1, n + 1)rep(j, 1, m + 1)if (copy[i][j] == '#')cnt1++;
			if (cnt1 == k)ans++;
		}
	}
	cout << ans << endl;
}
