	for(auto r : row) {
		for(int i = 0; i < cols; i++) {
			v[r][i] = '.';
		}
	}
	for(auto c : col) {
		for(int i = 0; i < rows; i++) {
			v[i][c] = '.';
		}
	}
	fr(i, rows) {
		fr(j, cols) {
			if(v[i][j] == '#') count++;
		}
	}
	if(count == k) return true;
	return false;
}

