int main()
{
	SPEED
	char ch;
	int h, w, k;			//h for rows, w for columns
	cin >> h >> w >> k;
	int total_blacks = 0;

	vector<vector<int>> grid(h+1, vector<int>(w+1, 0));

	for (int i = 1; i <= h; ++i)
	{
		for (int j = 1; j <= w; ++j)
		{
			cin >> ch;
			if (ch=='#')
			{
				grid[i][j] = 1;
				total_blacks++;
			}
		}
	}

	vector<int> red_row(h+1, 0);
	vector<int> red_col(w+1, 0);

	for (int i = 1; i <= w; ++i)
	{
		int sum_col = 0;
		for (int j = 1; j <= h; ++j)
		{
			sum_col += grid[j][i]; 
		}

		red_col[i] = sum_col;
	}


	for (int i = 1; i <= h; ++i)
	{
		int sum_row = 0;
		for (int j = 1; j <= w; ++j)
		{
			sum_row += grid[i][j]; 
		}

		red_row[i] = sum_row;
	}


	int rows = 1;
	rows = rows << h;

	int cols = 1;
	cols = cols << w;

	int result = 0;

	for (int r = 0; r < rows; ++r)
	{
		for (int c = 0; c < cols; ++c)
		{
			int count_blacks = total_blacks;

			vector<int> row_index, col_index;

			int pointer = 1;
			int shift = 0;
			while(pointer <= r)
			{
				if (r&pointer)
				{
					count_blacks -= red_row[shift+1];
					row_index.push_back(shift+1);
				}
				pointer = pointer << 1;
				shift++;
			}


			pointer = 1;
			shift = 0;
			while(pointer <= c)
			{
				if (c&pointer)
				{
					count_blacks -= red_col[shift+1];
					col_index.push_back(shift+1);
				}
				pointer = pointer << 1;
				shift++;
			}

			for(int r2 : row_index)
			{
				for (int c2 : col_index)
				{
					if (grid[r2][c2]==1)
					{
						count_blacks++;
					}
				}
			}


			if (count_blacks==k)
			{
				result++;
			}
		}
	}

	cout << result;
	return 0;
}

