template<typename T> class in {
    T value;
public:
    in() { cin >> value; }
    operator const T&() const { return value; }
    operator T&() { return value; }
    in& operator=(T source) { value = source; return *this; }
};
template<> class in<string> : public string {
public:
    in() { cin >> *this; }
};
template<class T> class inseq : public T {
public:
    template<typename... Arg> inseq(Arg... arg) : T(forward<Arg>(arg)...) { for (auto&& i : *this) cin >> i; }
};
template<class T> using invec = inseq<vector<T>>;

auto solve() {
  in<ll> H,W,K;
  invec<string> c(H);
  ll rest = 0;
 for (auto&& i : c)
      rest += count(i.cbegin(), i.cend(), '#');


  auto solve = [&](auto f, int rest, int hei, int wid, vector <string> c) -> ll{
      ll res = 0;
    if (hei<H) {
      res += f(f, rest, hei+1, wid, c);
      rest -= count(c[hei].cbegin(), c[hei].cend(), '#');
      c[hei] = "";
      res += f(f, rest, hei+1, wid, move(c));
    }
    else if (wid < W){
      res += f(f, rest, hei, wid+1, c);
      for (auto&& i : c)
        if (i.length() > wid && i[wid] == '#')
      		rest--;
      res += f(f, rest, hei, wid+1, move(c));

    }
    else {
      return (rest == K ? 1 : 0);
    }

    return res;
  };
  return solve(solve, rest, 0, 0, c);
}

