int BIT(std::vector<int> &a,int A)
{
  int c=0;
  int N=a.size();

  std::vector<std::vector<int>> result;
  result.reserve(N);
  for (int bit=0;bit!=(1<<N);bit++)
  {
    c++;
    std::vector<int> t;
    t.reserve(N);
    int sum=0;
    for (int i=0;i!=N;i++)
    {
      if (bit&(1<<i))
      {
        t.push_back(a[i]);
        sum+=a[i];
      }
    }

    if (sum==A)
    {
      result.push_back(std::move(t));
    }
  }

  return result.size();
}

