int main()
{
	int H, W, K; //入力
	//int board[6][6]; //盤面の入力
	int board[36] = { 0 }, boardTrial[36] = { 0 };
	char input; //個別の記号の入力
	int blackCells = 0, blackCellsResult = 0, successfulResults = 0; //入力された黒の総数
	int trials = 1, maxTrials = 1, trialNum;

	cin >> H >> W >> K;

	for (int i = 1; i <= H; i++) {
		for (int j = 1; j <= W; j++) {
			cin >> input;
			if (input == '#') {
				board[(i - 1) * 6 + (j - 1)] = 1;
			}
		}
	}

	for (int i = 1;i <= H + W; i++) {
		maxTrials *= 2;
	}

	for (int i = 1; i <= maxTrials; i++) {
		//初期設定
		trialNum = i;
		for (int j = 1; j <= 36; j++) {
			boardTrial[j - 1] = board[j - 1];
		}
		blackCellsResult = 0;

		//行の赤変更
		for (int j = 1; j <= H; j++) {
			if (trialNum % 2 == 1) {
				for (int k = 1; k <= 6; k++) {
					boardTrial[(j - 1) * 6 + k - 1] = 0;
				}
			}
			trialNum /= 2;
		}

		//列の赤変更
		for (int j = 1; j <= W; j++) {
			if (trialNum % 2 == 1) {
				for (int k = 1; k <= 6; k++) {
					boardTrial[j - 1 + (k - 1) * 6] = 0;
				}
			}
			trialNum /= 2;
		}

		//点数確認
		for (int j = 1; j <= 36; j++) {
			if (boardTrial[j - 1] == 1) {
				blackCellsResult++;
			}
		}

		if (blackCellsResult == K) {
			successfulResults++;
		}

	}

	cout << successfulResults;

	return 0;

}

