int n, m, k;
int a[10][10], b[10][10], c[10][10];
int ans;

void dfs(int now, int type) {
    if (type == 0 && now == n + 1) { memcpy(c, b, sizeof(b)); dfs(1, 1); return; }
    if (type == 1 && now == m + 1) {
        int sum = 0;
        for (int i = 1; i <= n; ++i)
            for (int j = 1; j <= m; ++j)
                sum += c[i][j];
        if (sum == k) ++ans;
        return;
    }
    dfs(now + 1, type);
    if (type == 0)
        for (int i = 1; i <= m; ++i)
            b[now][i] = 0;
    else
        for (int i = 1; i <= n; ++i)
            c[i][now] = 0;
    dfs(now + 1, type);
    if (type == 0)
        for (int i = 1; i <= m; ++i)
            b[now][i] = a[now][i];
    else
        for (int i = 1; i <= n; ++i)
            c[i][now] = b[i][now];
}

