#define rep(i,n) for(ll i=0; i<(n); i++)

int h,w,k;
int field[6][6];

int main(){

    cin>>h>>w>>k;
    rep(i,6){
        rep(j,6){
            field[i][j]=0;
        }
    }


    char tmp;
    rep(i,h){
        rep(j,w){
            cin>>tmp;
            if(tmp=='.')field[i][j]=0;
            else field[i][j]=1;
        }
    }

    int ans=0;
    int calc_f[6][6];

    // bit全探索
    for(int bit=0; bit < (1<<(w+h));++bit){
        //計算用field生成
        rep(i,6){
            rep(j,6){
                calc_f[i][j]=field[i][j];
            }
        }
        int sum=0;
        rep(i,(w+h)){
            if(bit&(1<<i)){
                //0で塗りつぶし
                if(i<h){
                    rep(j,6){
                        calc_f[i][j]=0;
                    }
                    // cout<<" h["<<i<<"]"<<endl;
                }else{
                    int tmp_i =i-h;
                    rep(i,6){
                        calc_f[i][tmp_i]=0;
                    }
                    // cout<<" w["<<tmp_i<<"]"<<endl;
                }

            }
        }

        //集計
        rep(i,6){
            rep(j,6){
                sum += calc_f[i][j];
            }
        }
        // cout<<bit<<":"<<sum<<endl;
        // cout<<"---"<<endl;

        if(sum==k){
            ans++;
        }
    }

    cout<<ans<<endl;
}

