void solve(){
    int H, W, K;
    cin >> H >> W >> K;
    char grid[H][W];
    int black = 0;
    for(int i = 0; i < H; ++i){
        for(int j = 0; j < W; ++j){
            cin >> grid[i][j];
            black += grid[i][j] == '#';
        }
    }
    int ways = 0;
    int mask1 = (1<<H);
    int mask2 = (1<<W);
    for(int m1 = 0; m1 < mask1; ++m1){
        for(int m2 = 0; m2 < mask2; ++m2){
            int removed = 0;
            bool mark[H][W];
            for(int i = 0; i < H; ++i)
                for(int j = 0; j < W; ++j)
                    mark[i][j] = false;
            for(int i = 0; i < H; ++i){
                if(m1&(1<<i)){
                    for(int j = 0; j < W; ++j){
                        if(grid[i][j] == '#')
                            removed++;
                        mark[i][j] = true;
                    }
                }
            }
            for(int j = 0; j < W; ++j){
                if(m2&(1<<j)){
                    for(int i = 0; i < H; ++i){
                        if(mark[i][j])
                            continue;
                        if(grid[i][j] == '#')
                            removed++;
                        mark[i][j] = true;
                    }
                }
            }
            if(black - removed == K){
                ways++;
            }
        }
    }
    cout << ways << '\n';
}



