int main () {
	int H, W, K;
	char grid[6][6];
	cin >> H >> W >> K;
	int cnt = 0;
	for (int col=0; col<H; col++) {
		for (int row=0; row<W; row++) {
			cin >> grid[col][row];
			if (grid[col][row]=='#')
				cnt ++;
		}
	}
	if (cnt < K) {
		cout << 0 << endl;
		return 0;
	} else if (cnt == K) {
		cout << 1 << endl;
		return 0;
	}
	int ans = 0;
	for (int cb=0; cb < (1<<H); cb++) {
		vector<int> cv;
		for (int i=0; i<H; i++) {
			if (cb & (1<<i)) {
				cv.push_back (i);
			}
		}
		for (int rb=0; rb<(1<<W); rb++) {
			vector<int> rv;
			for (int j=0; j<W; j++) {
				if (rb & (1<<j)) {
					rv.push_back (j);
				}
			}
			int nb = 0;
			for (int &c: cv) {
				for (int j=0; j<W; j++) {
					if (grid[c][j] == '#')
						nb ++;
				}
			}
			for (int& r: rv) {
				for (int i=0; i<H; i++) {
					if (grid[i][r] == '#')
						nb ++;
				}
			}
			for (int& c: cv) {
				for (int& r: rv) {
					if (grid[c][r] == '#') {
						nb--;
					}
				}
			}
			if (nb+K==cnt) {
				ans ++;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

