int dfs(int h, int w, int k, int row, int col, vector<string> s){

    // row
    for(int i=0; i<h; i++){
        if(( row>>i )%2 == 1){
            for(int j=0; j<w; j++){ s[i][j] = '?';}
        }
    }
    // col
    for(int i=0; i<w; i++){
        if(( col>>i )%2 == 1){
            for(int j=0; j<h; j++){ s[j][i] = '?';}
        }
    }
    // sum
    for(int i=0; i<h; i++){
        for(int j=0; j<w; j++){
            k -= s[i][j] == '#';
        }
    }
    if(k==0){
        return 1;
    }
    return 0;
}

