int main()
{
	scanf("%d%d%d", &h, &w, &k);
	int sum = 0;
	for (int i = 1; i <= h; i++) {
		for (int j = 1; j <= w; j++) {
			scanf(" %c", &a[i][j]);
			if (a[i][j] == '#') sum++;
		}
	}
	for (int i = 1; i <= h; i++) {
		for (int j = 1; j <= w; j++) {
			if (a[i][j] == '#') r[i]++;
		}
	}
	for (int i = 1; i <= w; i++) {
		for (int j = 1; j <= h; j++) {
			if (a[j][i] == '#') c[i]++;
		}
	}
	long long ans = 0;
	for (int i = 0; i < (1<<h); i++) {
		for (int j = 0; j < (1<<w); j++) {
			bitset<8> b1(i), b2(j);
			int tmp = sum;
			for (int ii = 0; ii < 6; ii++) if (b1.test(ii)) tmp -= r[ii+1];
			for (int ii = 0; ii < 6; ii++) if (b2.test(ii)) tmp -= c[ii+1];
			for (int ii = 0; ii < 6; ii++) {
				for (int jj = 0; jj < 6; jj++) {
					if (b1.test(ii) && b2.test(jj) && a[ii+1][jj+1] == '#') tmp++;
				}
			}
			if (tmp == k)
				ans++;
		}
	}
	printf("%lld\n", ans);
	return 0;
}

