	for(int i = 0;i < H;i++){
		for(int j = 0;j < W;j++){
			cin>>arr[i][j];
		}
	}

    for(int mi=0; mi<(1<<H); mi++) { // for every combination of rows (2^H)
        for(int mj=0; mj<(1<<W); mj++) { // for every combination of columns (2^W)
            int total = 0;
            for(int i=0; i<H; i++) {
                for(int j=0; j<W; j++) {
                    // a cell stay black
                    // if the color is black
                    // and i-th row is not colored red
                    // and j-th col is not colored red
                    if (arr[i][j]=='#' && ((mi & (1<<i)) == 0) && ((mj & (1<<j)) == 0)) {
                        total++;
                    }
                }
            }
            if (total == K) {
                ans++;
            }
        }
    }

	cout<<ans<<endl;
}

