void solve()
{   
    int h,w,total=0,k;
    cin>>h>>w>>k;
    vector<string> mat(h);
    vector<int> row(h);
    vector<int> col(w);
    for(int i=0;i<h;++i)
        cin>>mat[i];
    int r=(1LL<<h);
    int c=(1LL<<w);
    for(int i=0;i<h;++i)
    {
        int cnt=0;
        for(int j=0;j<w;++j){
            cnt+=(mat[i][j]=='#');
        }
        row[i]=cnt;
    }
    for(int i=0;i<w;++i)
    {
        int cnt=0;
        for(int j=0;j<h;++j)
            cnt+=(mat[j][i]=='#');
        col[i]=cnt;
    }
    for(int i=0;i<h;++i)
        for(int j=0;j<w;++j)
            if(mat[i][j]=='#')
            total+=1;
    ll ans=0;
    if(total==k)
        ans++;
    for(int i=0;i<r;++i){
        for(int j=0;j<c;++j){
            if(i==0 && j==0) continue;
            int cnt=total; 
            int c=0;
            for(int bit=0;bit<h;++bit){
                if(i&(1LL<<bit)){
                    for(int bit1=0;bit1<w;++bit1){
                        if(j&(1LL<<bit1)){
                            if(mat[bit][w-bit1-1]=='#')
                                ++cnt;
                        }
                    }
                    cnt-=row[bit];
                }
            }
            for(int bit=0;bit<w;++bit){
                if(j&(1LL<<bit))
                    cnt-=col[w-bit-1];
            }
            //if(i==1 && j==1) cout<<cnt<<'\n';
            if(cnt==k){
                //cout<<i<<' '<<j<<'\n';
                ans++;
            }
        }
    }
    cout<<ans;

}

