int dfs(int h, int w, int k, int n, vector<string> f){
  if(n == h + w){
    int ret = 0;
    for(int i = 0; i < h; i++){
      for(int j = 0; j < w; j++){
        if(f[i][j] == '#') ret++;
      }
    }
    return 1 * (ret == k);
  }
  int ret = 0;
  if(n < h){
    vector<string> s = f;
    ret += dfs(h, w, k, n+1, s);
    for(int j = 0; j < w; j++){
      s[n][j] = '.';
    }
    ret += dfs(h, w, k, n+1, s);
  }
  else{
    vector<string> s = f;
    ret += dfs(h, w, k, n+1, s);
    for(int i = 0; i < h; i++) s[i][n-h] = '.';
    ret += dfs(h, w, k, n+1, s);
  }
  return ret;
}

