void solve(int r,int c,int idx){
  if(idx == h){
    if(vis[r][c])
      return;
    vis[r][c] = true;
    int cnt = 0;
    for(int i=0;i<h;i++){
      for(int j=0;j<w;j++){
        if(r & (1 << i) || c & (1 << j))
