template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}


void solve(istream& in, ostream& out) {
  auto h = next<int>(in);
  auto w = next<int>(in);
  auto k = next<int>(in);
  vec<string> f(h);
  FOR(i, h) {
    f[i] = next<string>(in);
  }

  auto getCnt = [&] (int mh, int mw) -> int {
    int res = 0;
    FOR(i, h) {
      if (!get_bit(mh, i)) {
        FOR(j, w) {
          if (!get_bit(mw, j)) {
            if (f[i][j] == '#') {
              ++res;
            }
          }
        }
      }
    }
    return res;
  };

  int res = 0;
  FOR(mh, 1 << h) {
    FOR(mw, 1 << w) {
      auto cnt = getCnt(mh, mw);
      if (cnt == k) {
        ++res;
      }
    }
  }
  out << res << "\n";
}

