class BitComb {
 private:
  ll _digits;
  ll _base;
  ll _data[512];
  ll _finished;
  ll _i;

 public:
  BitComb(ll digits, ll base) {
    _digits = digits;
    _base = base;
    _finished = false;
    _i = 0;
    fill_n(_data, 512, 0);
  }

  void next() {
    if (_finished) {
      return;
    }
    for (ll i = 0; i < _digits; i++) {
      if (_data[i] + 1 < _base) {
        _data[i] += 1;
        break;
      } else {
        _data[i] = 0;

        if (i == _digits - 1) {
          _finished = true;
          break;
        }
      }
    }
  }

  ll* data() { return _data; }

  void print() {
    for (ll i = _digits - 1; i >= 0; i--) {
      cout << _data[i];
    }
    cout << endl;
  }

  bool finished() { return _finished; }
};

int main() {
  ll H, W, K;
  scanf("%lld %lld %lld", &H, &W, &K);

  ll total = 0;
  vector<string> lines;
  for (ll i = 0; i < H; i++) {
    string line;
    cin >> line;

    lines.emplace_back(line);

    for (ll i = 0; i < W; i++) {
      if (line[i] == '#') {
        total++;
      }
    }
  }

  auto bc_h = BitComb(H, 2);

  ll ans = 0;

  while (!bc_h.finished()) {
    auto bc_w = BitComb(W, 2);
    while (!bc_w.finished()) {
      ll black_count = 0;
      for (ll y = 0; y < H; y++) {
        for (ll x = 0; x < W; x++) {
          if (lines[y][x] == '#' && (bc_h.data()[y] || bc_w.data()[x])) {
            black_count += 1;
          }
        }
      }
      if (total - black_count == K) {
        ans++;
      }

      bc_w.next();
    }
    bc_h.next();
  }
  cout << ans << endl;
}

