int numbit(int j){
    unsigned int i = static_cast<unsigned int>(j);
    i = i - ((i >> 1) & 0x55555555);
    i = (i & 0x33333333) + ((i >> 2) & 0x33333333);
    i = (i + (i >> 4)) & 0x0f0f0f0f;
    i = i + (i >> 8);
    i = i + (i >> 16);
    return static_cast<int>(i & 0x3f);
}

