void dfs_col(vector<int> rows, vector<int> cols) {
  vector<vector<bool>> reverse(h, vector<bool>(w, false));
  for (int r : rows) {
    for (int i = 0; i < w; i++) {
      reverse.at(r).at(i) = true;
    }
  }
  for (int c : cols) {
    for (int i = 0; i < h; i++) {
      reverse.at(i).at(c) = true;
    }
  }
  int cnt_b = 0;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (!reverse[i][j] && c[i][j] == '#') {
        cnt_b++;
      }
    }
  }
  if (cnt_b == k) {
    ans++;
  }

  if (rows.size() == h) {
    return;
  }
  if (rows.empty()) {
    rows.push_back(0);
  } else {
    rows.push_back(rows.back() + 1);
  }
  while (rows.back() != h) {
    dfs_col(rows, cols);
    rows.back()++;
  }
}

void dfs_row(vector<int> rows, vector<int> cols) {
  dfs_col(rows, cols);
  if (cols.size() == w) {
    return;
  }
  if (cols.empty()) {
    cols.push_back(0);
  } else {
    cols.push_back(cols.back() + 1);
  }
  while (cols.back() != w) {
    dfs_row(rows, cols);
    cols.back()++;
  }
}
