int test(int key, int* org){
    int tst[H][W];
    for(int r=0;r<H;r++){
        for(int c=0;c<W;c++){
            tst[r][c] = org[r*W+c];
        }
    }

    for(int rn=0;rn<H;rn++){
        if(((key >> rn) & 0x01) == 1){
            for(int c=0;c<W;c++)
                tst[rn][c]=0;
        }
    }
    for(int cn=0;cn<W;cn++){
        if(((key >> (H+cn)) & 0x01) == 1){
            for(int r=0;r<H;r++)
                tst[r][cn]=0;
        }
    }
    int sum=0;
    for(int r=0;r<H;r++){
        for(int c=0;c<W;c++){
            sum += tst[r][c];
        }
    }
    return sum;
}

