int main(){
    int h,w,k; cin >> h >> w >> k;
    vector<string> H(h);
    vector<string> W(w);
    map<int,int> C;
    int how=0;
    for (int i=0;i<h;i++){
        C[i]=0;
    }
    for (int i=0;i<h;i++){
        string a; cin >> a;
        H[i]=a;
        for (int j=0;j<a.size();j++){
            if (a[j]=='#'){
                W[j]+=a[j];
                how++;
            }
            else W[j]+='.';
        }
    }
    int ans=0;
    int check=0;
    for (int i=0;i<(1<<h+w);i++){
        for (int j=0;j<h;j++){
            if (i&(1<<j)){
                C[j]=1;
                string r=H[j];
                for (int k=0;k<w;k++){
                    if(r[k]=='#') {
                        check++;
                    }
                }
            }
        }
        for (int j=h;j<h+w;j++){
            if (i&(1<<j)){
                string r=W[j-h];
                for (int k=0;k<h;k++){
                    if (C[k]==0 && r[k]=='#') check++;
                }
            }
        }
        if (how-check==k){
            ans++;
        }
        check=0;
        for (int i=0;i<h;i++){
            C[i]=0;
        }
    }
    cout << ans << "\n";
}

