int dfs(string bit){
	if(bit.size()==h+w){
		string tate=bit.substr(0,h);
		string yoko=bit.substr(h,w);
		auto table=ta;
		int co=0;
		rep(i,h)if(tate[i]=='1')rep(j,w)table[i][j]='.';
		rep(i,w)if(yoko[i]=='1')rep(j,h)table[j][i]='.';
		rep(i,h)rep(j,w)if(table[i][j]=='#')co++;
		if(co==k)ans++;
		return 0;
	}else{
		dfs(bit+'0');
		dfs(bit+'1');
	}
	return 0;
}

