using namespace std;
int main(void){

    int h, w, target;
    cin >> h >> w >> target ;

    vector<vector<int>> tile(h, vector<int>(w));
    string s;
    vector<int> line(h), row(w);
    int sum = 0, treat;

    for(int i = 0; i < h; i++){
        cin >> s ;
        for(int j = 0; j < w; j++){
            if(s.at(j) == '#'){
                tile.at(i).at(j) = 1;
                line.at(i)++;
                row.at(j)++;
                sum++;
            } else {
                tile.at(i).at(j) = 0;
            }
            //cout << tile.at(i).at(j) ;
        }
        //cout << endl;
    }

    /*
    for(int i = 0; i < h; i++){
        cout << line.at(i) << endl;
    }
    cout << endl;

    for(int j = 0; j < w; j++){
        cout << row.at(j) << endl;
    }
    cout << endl;
    */

    int tri, trk, hsum, ans = 0;
    set<int> lpaint;
    for(int i = 0; i < pow(2, h); i++){
        lpaint.clear();
        tri = i;
        treat = sum;
        for(int j = 0; tri != 0; j++){
            if(tri % 2 != 0){
                treat -= line.at(j);
                lpaint.insert(j);
            }
            tri /= 2;
        }
        //cout << treat << endl;
        for(int k = 0; k < pow(2, w); k++){
            trk = k;
            hsum = treat;
            for(int l = 0; trk != 0; l++){
                if(trk % 2 != 0){
                    hsum -= row.at(l);
                    for(int m = 0; m < h; m++){
                        if(lpaint.count(m) == 1){
                            if(tile.at(m).at(l) == 1){
                                hsum++;
                            }
                        }
                    }
                }
                trk /= 2;
            }
            //cout << hsum << endl;
            if(hsum == target){
                ans++;
            }
        }
    }

    cout << ans << endl;

}

