//horwはhならtrue, wならfalse
void search(bool sh[], bool sw[], int num, bool horw) {
    if (num == w && !horw) {
        count(sh, sw);
        return;
    }
    if (num == h && horw) {
        horw = false;
        num = -1;
    }
    if (horw) {
        search(sh, sw, num + 1, true);
        sh[num] = true;
        search(sh, sw, num + 1, true);
        sh[num] = false;
    } else {
        search(sh, sw, num + 1, false);
        sw[num] = true;
        search(sh, sw, num + 1, false);
        sw[num] = false;
    }
}

