    static constexpr int W_MAX = 6;

    int H = {};
    int W = {};
    int K = {};
    std::string masu[H_MAX];

    void Run()
    {

      std::cin >> H;
      std::cin >> W;
      std::cin >> K;

      for (int i = 0; i < H; ++i)
      {
        std::cin >> masu[i];
      }


      int answer = 0;
      int hparam_max = 1;
      int wparam_max = 1;
      for (int i = 0; i < H; ++i) hparam_max *= 2;
      for (int i = 0; i < W; ++i) wparam_max *= 2;


      for (int i = 0; i < hparam_max; ++i)
      {
        for (int j = 0; j < wparam_max; ++j)
        {
          if (Solve(i, j)) answer++;
        }
      }

      std::cout << answer << std::endl;
    }

    bool Solve(int hparam, int wparam)
    {
      std::string m[H_MAX];
      for (int i = 0; i < H; ++i) m[i] = masu[i];

      for (int i = 0; i < H; ++i)
      {
        if ((hparam & (1 << i)) > 0)
        {
          for (int j = 0; j < W; ++j) m[i].at(j) = 'r';
        }
      }

      for (int i = 0; i < W; ++i)
      {
        if ((wparam & (1 << i)) > 0)
        {
          for (int j = 0; j < H; ++j) m[j].at(i) = 'r';
        }
