ll subsetsum(ll k_, ll n_) {
	if (k_<0) return 0;
	if (n_==0 && k_!=0) return 0;
	if (n_==0) return 1;
	return (subsetsum(k_,n_-1) + subsetsum(k_-r[n_], n_-1));
}

void countans(ll i, vi selectedcols, ll &ans) {
	if (i==m+1) {
		ans += subsetsum(k, n);
		return;
	}
	//ith column is not selected
	countans(i+1, selectedcols, ans);
	//ith column is selected
	k -= c[i];
	rep(j, 0, sz(rowsofcol[i])) --r[rowsofcol[i][j]];
	selectedcols.pb(i);
	countans(i+1, selectedcols, ans);
	k += c[i];
	rep(j, 0, sz(rowsofcol[i])) ++r[rowsofcol[i][j]];
	selectedcols.pop_back();
}

