ll check(char d[10][10]) {
    ll cnt = 0;
    for (long long i = 1; i < h + 1; i++) {
        for (long long j = 1; j < w + 1; j++) {
            if (d[j][i] == '#') cnt++;
        }
    }
    return cnt;
}

ll f(ll gyo, ll retu, char e[10][10]) {
    if (gyo >= h or retu >= w) return 0;

    ll ans = 0;
    char g[10][10];
    memcpy(g, e, sizeof(g));

    ans += f(gyo + 1, retu, g) + f(gyo, retu + 1, g);

    if (gyo > 0) {
        for (long long k = 1; k < w + 1; k++) {
            g[k][gyo] = 'r';
        }
    }
    if (retu > 0) {
        for (long long k = 1; k < h + 1; k++) {
            g[retu][k] = 'r';
        }
    }
    if (check(g) == k) ans++;
    return f(gyo + 1, retu, g) + f(gyo, retu + 1, g) + ans;
}

