int black(vvii S,int bh,int bw){
    REP(i,H){
        if(bh & (1<<i)){
            REP(k,W){
                S[i][k] = 0;
            }
        }
    }
    REP(i,W){
        if(bw & (1 << i)){
            REP(l,H){
