  // H×Wの配列に "." or "#"を代入
  for(int i=0; i<H; i++) {
    for(int j=0; j<W; j++) {
      char c;
      cin >> c;
      clist.at(i).at(j) = c;
    }
  }

  //----------ここまでは問題なしと思われる----------

