  int ans = 0; 
  // ansは答えとして出力したい値を表す変数, 
  // 条件に合致する行列の選び方をしたときに+1していく

  //----------ビット全探索で行列の選び方を決定していく----------
  for (int tmp1 = 0; tmp1 < (1 << H); tmp1++) {
    bitset<6> s(tmp1);
