int findBlack()
{
	int cnt=0;
	for(int i=0;i<H;i++)
	{
		for(int j=0;j<W;j++)
		{
			if(v[i][j]=='#' && (strow.count(i)!=0 || stcol.count(j)!=0))
			cnt++;
		}
	}
	return cnt;
}
