vector<vector<int>> bit_w;
vector<vector<int>> bit_h;
void dfs(vector<int> &A, int size)
{
    if (A.size() == size)
    {
        bit_w.push_back(A);
        return;
    }

    for (int v = 0; v < M; ++v)
    {
        A.push_back(v);
        dfs(A, size);
        A.pop_back();
    }
}

void dfs2(vector<int> &A, int size)
{
    if (A.size() == size)
    {
        bit_h.push_back(A);
        return;
    }

    for (int v = 0; v < M; ++v)
    {
        A.push_back(v);
        dfs2(A, size);
        A.pop_back();
    }
}

