map<int, int> black;

void rec2(vector<string> s, int k){
  if(k == s[0].size()){
    int cnt = 0;
    rep(i, 0, sz(s)){
      rep(j, 0, sz(s[0])){
        if(s[i][j] == '#'){
          cnt++;
        }
      }
    }
    black[cnt]++;
    return;
  }
  rec2(s, k + 1);
  rep(i, 0, sz(s)){
    s[i][k] = '.';
  }
  rec2(s, k + 1);
}

void rec1(vector<string> s, int k){
  if(k == s.size()){
    rec2(s, 0);
    return;
  }
  rec1(s, k + 1);
  rep(i, 0, sz(s[0])){
    s[k][i] = '.';
  }
  rec1(s, k + 1);
}


