void copy_matrix(vector <vector <char>> &a, vector<vector <char>> &b) {
    for (int i = 0; i < a.size(); ++i) {
        for (int j = 0; j < a[0].size(); ++j) {
            b[i][j] = a[i][j];
        }
    }
}
void color(vector <vector <char>> &b, int row, int col, int tot_row, int tot_col) {
    for (int i = 0; i < tot_row; ++i) {
        if (row & (1 << i)) {
            for (int j = 0; j < tot_col; ++j) {
                b[i][j] = '$';
            }
        }
    }
    for (int i = 0; i < tot_col; ++i) {
        if (col & (1 << i)) {
            for (int j = 0; j < tot_row; ++j) {
                b[j][i] = '$';
            }
        }
    }
}
int cnt(vector <vector <char>> &b, int k) {
    int ans = 0;
    for (int i = 0; i < b.size(); ++i) {
        for (int j = 0; j < b[0].size(); ++j) {
            if (b[i][j] == '#') {
                ++ ans;
            }
        }
    }
    return ans;
}
