vector<string> data;
int h, w, n;

int judge(vector<int> a, vector<int> b) {
  int ret = 0;
  for (auto x : a) {
    for (auto y : b) {
      if (data[x][y] == '#') ret++;
    }
  }
  return ret;
}

int main() {
  cin >> h >> w >> n;
  unordered_map<int, int> h_map;
  unordered_map<int, int> w_map;
  int sum = 0;
  int ans = 0;
  REP(i, h) {
    string x;
    cin >> x;
    data.push_back(x);
  }

  REP(i, h) {
    REP(j, w) {
      if (data[i][j] == '#') {
        h_map[i]++;
        w_map[j]++;
        sum++;
      }
    }
  }

  for (int bit = 0; bit < (1 << h); ++bit) {
    for (int bit2 = 0; bit2 < (1 << w); ++bit2) {
      vector<int> a;
      vector<int> b;
      int tmp = 0;
      for (int i = 0; i < h; ++i) {
        if (bit & (1 << i)) {
          a.push_back(i);
          tmp += h_map[i];
        }
      }

      for (int j = 0; j < w; ++j) {
        if (bit2 & (1 << j)) {
          b.push_back(j);
          tmp += w_map[j];
        }
      }

      if (sum - tmp + judge(a, b) == n) {
        ans++;
      }
    }
  }

  cout << ans << endl;
}

#include <bits/stdc++.h>

using namespace std;

int n, m, k;
char mat[10][10];

bool row[10], col[10];

bool check_board() {
	int black = 0;
	for(int i = 0; i < n; i++) {
		for(int j = 0; j < m; j++) {
			bool painted_red = row[i] or col[j];
			if(!painted_red) {
				black += mat[i][j] == '#';
			}
		}
	}
	return black == k;
}

int brute_col(int c) {
	bool finished_painting_cols = c == m;
	if(finished_painting_cols) {
		if(check_board()) {
			return 1;
		}
		return 0;
	}
	int ans = 0;
	{ // considere paint the col c
		col[c] = true;
		ans += brute_col(c + 1);
	}
	{ // considere not paint the col c
		col[c] = false;
		ans += brute_col(c + 1);
	}
	return ans;
}

int brute_row(int r) {
	bool finished_painting_rows = r == n;
	if(finished_painting_rows) return brute_col(0);
	int ans = 0;
	{ // considere paint the row r
		row[r] = true;
		ans += brute_row(r + 1);
	}
	{ // considere not paint the row r
		row[r] = false;
		ans += brute_row(r + 1);
	}
	return ans;
}

int main() {
	scanf("%d %d %d", &n, &m, &k);

	for(int i = 0; i < n; i++) {
		scanf("%s", mat[i]);
	}

	printf("%d\n", brute_row(0));
}

