typedef long long int ll; 
ll rbinary[10],cbinary[10];

void rToBin(ll n,ll size)
{
	for(ll kk=0;kk<size;kk++)
		rbinary[kk] = 0;

	ll ridx = 0;
	while(n>0) 
	{
		rbinary[ridx++] = n%2;
		n = n/2;
	}
	/// now reverse the array
	for(ll i=0;i<size/2;i++)
	{
		ll tt = rbinary[i];
		rbinary[i]=rbinary[size-1-i];
		rbinary[size-1-i]=tt;
	}
}
void cToBin(ll n,ll size)
{
	for(ll kk=0;kk<size;kk++)
		cbinary[kk] = 0;

	ll cidx = 0;
	while(n>0) 	
	{
		cbinary[cidx++] = n%2;
		n = n/2;
	}
	/// now reverse the array
	for(ll i=0;i<size/2;i++)
	{
		ll tt = cbinary[i];
		cbinary[i]=cbinary[size-1-i];
		cbinary[size-1-i]=tt;
	}
}
