int beki(int a, int b){
  int ans = 1;
  for(int i = 0; i < b; i++){
    ans *= a;
  }
  return ans;
}

int main() {

  int H, W, K;
  cin >> H >> W >> K;

  char c[H][W];

  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      cin >> c[i][j];
    }
  }

  int tmp;
  int ans = 0;

  for(int i = 0; i < beki(2, H); i++){
    for(int j = 0; j < beki(2, W); j++){
      tmp = 0;
      for(int k = 0; k < H; k++){
        for(int l = 0; l < W; l++){
          if(i & (1 << k) && j & (1 << l)){
            if(c[k][l] == '#'){
              tmp++;
            }
          }
        }
      }
      if(tmp == K){
        ans++;
      }
    }
  }
  cout << ans << endl;
}

