using namespace std;

int ipow(int x, int y)
{
	int z = 1;
	for (int i = 0; i < y; i++) {
		z *= x;
	}

	return z;
}

void arnext(int x, bool* ar)
{
	for (int i = 0; i < 6; i++) {
		if (x % 2) {
			ar[i] = true;
		} else {
			ar[i] = false;
		}
		x = x >> 1;
	}
}


int main()
{
	int h, w, k;
	cin >> h >> w >> k;
	bool row[6];
	bool line[6];
	int maxh = ipow(2, h);
	int maxw = ipow(2, w);
	vector<vector<bool>> dp(h, vector<bool>(w, false));

	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			char tmp;
			cin >> tmp;
			if (tmp == '#') {
				dp[i][j] = true;
			}
		}
	}

	int sum = 0;
	int ans = 0;
	for (int i = 0; i < maxh; i++) {
		arnext(i, line);
		for (int j = 0; j < maxw; j++) {
			arnext(j, row);
			for (int ki = 0; ki < h; ki++) {
				if (line[ki])continue;
				for (int kj = 0; kj < w; kj++) {
					if (row[kj])continue;
					if (dp[ki][kj])sum++;
				}
			}
			if (sum == k)ans++;
			sum = 0;
		}
	}

	printf("%d", ans);


	return 0;
}

