	int N = a.size();
	if (N % 2 == 1)
		return (double)a[N / 2];
	else
		return (double)(a[N / 2 - 1] + a[N / 2]) / 2;
}
int collatz(int n, int cou) {
	if (m.count(n))
		return m[n] + cou;
	if (n == 1)
		return cou;
	if (n % 2 == 0)
		return collatz(n / 2, cou + 1);
	return collatz(3 * n + 1, cou + 1);
}





