template <class T>
T modinv(T a, const T &p)
{
    T b = p, u = 1, v = 0;
    while (b)
    {
        T t = a / b;
        a -= t * b;
        swap(a, b);
        u -= t * v;
        swap(u, v);
    }
    u %= p;
    if (u < 0)
    {
        u += p;
    }
    return u;
}
