void colored_red(int row_col[MAX], int K, int black, int index, int limit,
		 int& cnt, bool color_map[MAX][MAX], vector<int> colored)
{
  if (index == limit){
    if (black == K)
      cnt++;
    return;
  }
  int temp = 0;
  for (int i = 0; i < colored.size(); i++)
    if (color_map[index][colored[i]])
      temp++;
  colored.push_back(index);
  colored_red(row_col, K, black - row_col[index] + temp, index + 1, limit, cnt
	      , color_map, colored);
  colored.erase(colored.end() - 1);
  colored_red(row_col, K, black, index + 1, limit, cnt, color_map, colored);
}

