ll modpow(ll x, ll n, const ll &p)
{
    ll ret = 1;
    while (n > 0)
    {
        if (n & 1)
        {
            (ret *= x) %= p;
        }
        (x *= x) %= p;
        n >>= 1;
    }
    return ret;
}
template <class T>
T modinv(T a, const T &p)
{
    T b = p, u = 1, v = 0;
    while (b)
    {
        T t = a / b;
        a -= t * b;
        swap(a, b);
        u -= t * v;
        swap(u, v);
    }
    u %= p;
    if (u < 0)
    {
        u += p;
    }
    return u;
}
template <class T>
T math_P(T m, T n)
{
    T ret = 1;
    for (T i = m; i > m - n; i--)
    {
        ret *= i;
    }
    return ret;
}
template <class T>
T math_C(T m, T n)
{
    T ret = math_P(m, n);
    for (T i = 2; i <= n; i++)
    {
        ret /= i;
    }
    return ret;
