void judge(int wi, int hi, int h_b, int w_b)
{
    int black = 0;
    if(hi == -1 && wi == -1)
    {
        char c_cp[6][6];
        for(int i=0; i<h; i++)
        {
            for(int j=0; j<w; j++)
            {
                c_cp[i][j] = c[i][j];
            }
        }
        for(int i=0; i<w; i++)
        {
            if(w_b & 1 << i)
            {
                for(int j=0; j<h; j++)
                {
                    c_cp[j][i] = 'r';
                }
            }
        }
        for(int i=0; i<h; i++)
        {
            if(h_b & 1 << i)
            {
                for(int j=0; j<w; j++)
                {
                    c_cp[i][j] = 'r';
                }
            }
        }
        for(int i=0; i<h; i++)
        {
            for(int j=0; j<w; j++)
            {
                if(c_cp[i][j] == '#') black++;
            }
        }
        if(black == k)
        {
            for(int i=0; i<h; i++)
            {
                for(int j=0; j<w; j++)
                {
  //                  cout << c_cp[i][j];
                }
 //               cout << endl;
            }
            ans++;
//            cout << endl;
        }
    }
    else if(hi == (h-1) && wi == (w-1))
    {
        judge(-1, -1, h_b, w_b);
        h_b += 1 << hi;
        judge(-1, -1, h_b, w_b);
    }
    else if(wi == (w-1) && hi == -1)
    {
        judge(wi, hi+1, h_b, w_b);
        w_b += 1 << wi;
        judge(wi, hi+1, h_b, w_b);
    }
    else if(wi == (w-1))
    {
        judge(wi, hi+1, h_b, w_b);
        h_b += 1 << hi;
        judge(wi, hi+1, h_b, w_b);
    }
    else
    {
        judge(wi+1, hi, h_b, w_b);
        w_b += 1 << wi;
        judge(wi+1, hi, h_b, w_b);
    }
    return;
}

