bool ok(int H, int W, int K, vector<string> c, int mask_r, int mask_c)
{
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
			if ((mask_r & (1 << i)) || (mask_c & (1 << j))) {
				c[i][j] = 'R';
			}
		}
