inline void check()
{
	memcpy(g, s, sizeof g);
	for (int i = 1; i <= n; i+=1)
		if (vis[i])
		{
			for (int j = 1; j <= m; j+=1)
				g[i][j] = 'R';
		}
	for (int i = n + 1; i <= n + m; i+=1)
		if (vis[i])
		{
			for (int j = 1; j <= n; j+=1)
				g[j][i - n] = 'R';
		}
	int cnt = 0;
	for (int i = 1; i <= n; i+=1)
		for (int j = 1; j <= m; j+=1)
			if (g[i][j] == '#')
				++cnt;
	if (cnt == k) ++ans;
}

