LL power(LL num,LL base) {
	if(base==0)
		return 1;

	if(base%2)
		return (num%MOD*power(num,base-1)%MOD)%MOD;
	else {
		LL x=power(num,base/2);
		x=(x*x)%MOD;
		return x;
	}
}
const int MM = 7;
