int ans = 0;
int tot = 0;

void fillHW() {
	for(int i = 1; i <= W; i++) {
		int cnt = 0;
		for (int j = 1; j <= H; j++) {
			cnt += grids[j][i] == '#';	
		}
		w[i] = cnt;
	}
	for(int i = 1; i <= H; i++) {
		 int cnt = 0;
		for (int j = 1; j <= W; j++) {
			cnt += grids[i][j] == '#';	
		}
		h[i] = cnt;
	}
}
int countOne(vector<int> rows, vector<int> cols) {
	int kk = 0;
	for (auto r : rows) kk += h[r];
	for (auto c : cols) kk += w[c];
	for (auto r : rows)  {
			for (auto c : cols) {
				kk -= grids[r][c] == '#';
			}
	}
	return tot - kk;
}

