            a[i][j] = '.';
        }
    }

    for(int i = wmin; i <= wmax; i++){
        for(int j = 0; j < a.size(); j++){
            a[j][i] = '.';
        }
    }

    int black = 0;
    for(int i = 1; i < a.size(); i++){
        for(int j = 1; j < a.at(0).size(); j++){
            if(a[i][j] == '#') black++;
        }
