int solve(int H, int W, int K, vector<vector<string>> t) {
  int ans = 0;
  for (int n=0; n < pow(2,H); n++) {
    for (int m=0; m < pow(2,W); m++) {
      int cnt = 0;
      for (int i=0; i < H; i++) {
        for (int j=0; j < W; j++) {
          if ((n >> i & 1) == 0 && (m >> j & 1) == 0) {
            if (t.at(i).at(j) == "#") {
              cnt++;
            }
          }
        }
      }
      if (cnt == K) ans++;
    }
  }
  return ans;
}

int main () {
  int H, W, K;
  cin >> H >> W >> K;
  vector<vector<string>> t(H, vector<string>(W));
  for (int i=0; i<H; i++) {
    char line[W];
    cin >> line;
    for (int j=0; j<W; j++) {
      t.at(i).at(j) = line[j];
    }
  }
  cout << solve(H, W, K, t) << endl;
  return 0;
}

