{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    program();
}

void program() {
    i32 h, w, k;
    readValues(h, w, k);
    auto c = vector<string>();
    i32 blackCount = 0;
    rep(i, h) {
        c.push_back(*readLine());
        blackCount += count(allOf(c[i]), '#');
    }

    i32 result = 0;

    if(blackCount == k) ++result;

    for(i32 i = 1; i <= h; ++i) {
        foreachWithCombination(h, i, [&](vector<i32>& hIndexes) {
            i32 count = 0;
            for(const auto& hIndex: hIndexes){
                rep(i, w) {
                    if(c[hIndex][i] == '#') { 
                        ++count;
                    }
                }
            }
            if(blackCount - count == k) ++result;
        });
    }

    for(i32 j = 1; j <= w; ++j) {
        foreachWithCombination(w, j, [&](vector<i32>& wIndexes) {
            i32 count = 0;
            for(const auto& wIndex: wIndexes){
                rep(i, h) {
                    if(c[i][wIndex] == '#') {
                        ++count;
                    }
                }
            }
            if(blackCount - count == k) ++result;
        });
    }

    for(i32 i = 1; i <= h; ++i) {
        for(i32 j = 1; j <= w; ++j) {
            foreachWithCombination(h, i, [&](vector<i32>& hIndexes) {
                foreachWithCombination(w, j, [&](vector<i32>& wIndexes) {
                    i32 count = 0;
                    for(const auto& hIndex: hIndexes){
                        rep(i, w) {
                            if(c[hIndex][i] == '#') { 
                                ++count;
                                c[hIndex][i] = 'r';
                            }
                        }
                    }
                    for(const auto& wIndex: wIndexes){
                        rep(i, h) {
                            if(c[i][wIndex] == '#') {
                                ++count;
                            }
                        }
                    }
                    if(blackCount - count == k) ++result;
                    for(const auto& hIndex: hIndexes){
                        rep(i, w) {
                            if(c[hIndex][i] == 'r') { 
                                c[hIndex][i] = '#';
                            }
                        }
                    }
                });
            });
        }
    }
    writeLine(result);
}

