{
	int count = 0;
	for (int i = 0; i < N; i++) {
		if ((p >> i) % 2 == 0) {
			for (int j = 0; j < W; j++) {
				if ((q >> j) % 2 == 0) {
					if (tbl[i][j] == '#') {
						count++;
					}
				}
			}
		}
	}
	return count;
}

