int ans = 0;

void result_col(int cur_w,int& w,vector<vector<char> >& v, vector<int>& rows, vector<int>& cols, int& k) {
	ans+=check(v,k,rows,cols);
	for(int j = cur_w; j < w; j++) {
			cols.push_back(j);
			result_col(j + 1,w,v,rows,cols,k);
			cols.pop_back();
		}
}


void result(int cur_h,int& h, int& w,vector<vector<char> >& v, vector<int>& rows, vector<int>& cols, int& k) {
	result_col(0,w,v,rows,cols,k); //all possible columns
	for(int i = cur_h; i < h;i++){
		rows.push_back(i);
		result(i + 1,h , w, v, rows,cols,k);
		rows.pop_back();
	}
}


