void dfs(int r, int c, int sum)//行 列 涂去的黑色
{
	int add = 0;
	if (r == n && c == m)
	{
		if (num - sum == k)
			ans++;
		return;
	}
	if (r == n)
	{
		for (int i = 0; i < n; i++)
		{
			if (a[i][c] == '#' && (!used[i]))
			{
				add++;
			}
		}
		dfs(r, c + 1, sum + add);
		dfs(r, c + 1, sum);
	}
	else
	{
		for (int i = 0; i < m; i++)
		{
			if (a[r][i] == '#')
			{
				add++;
			}
		}
		used[r] = 1;
		dfs(r + 1, c, sum + add);
		used[r] = 0;
		dfs(r + 1, c, sum);
	}

}
