int h, w, n;

int judge(vector<int> a, vector<int> b, vector<string> data) {
  int ret = 0;
  for (auto x : a) {
    for (auto y : b) {
      if (data[x][y] == '#') ret++;
    }
  }
  return ret;
}

int main() {
  cin >> h >> w >> n;
  unordered_map<int, int> h_map;
  unordered_map<int, int> w_map;
  vector<string> data;
  int sum = 0;
  int ans = 0;
  REP(i, h) {
    string x;
    cin >> x;
    data.push_back(x);
  }

  REP(i, h) {
    REP(j, w) {
      if (data[i][j] == '#') {
        h_map[i]++;
        w_map[j]++;
        sum++;
      }
    }
  }

  for (int bit = 0; bit < (1 << h); ++bit) {
    for (int bit2 = 0; bit2 < (1 << w); ++bit2) {
      vector<int> a;
      vector<int> b;
      int tmp = 0;
      for (int i = 0; i < h; ++i) {
        if (bit & (1 << i)) {
          a.push_back(i);
          tmp += h_map[i];
        }
      }

      for (int j = 0; j < w; ++j) {
        if (bit2 & (1 << j)) {
          b.push_back(j);
          tmp += w_map[j];
        }
      }

      if (sum - tmp + judge(a, b, data) == n) {
        ans++;
      }
    }
  }

  cout << ans << endl;
}

