bool match(vector<int>&choseH, vector<int>&choseW) {
    int cnt = 0;
    rep(i, H) {
        auto itr = find(choseH.begin(), choseH.end(), i);
        if(itr != choseH.end()) {
            continue;
        }
        rep(j, W) {
            itr = find(choseW.begin(), choseW.end(), j);
            if(itr != choseW.end()) {
                continue;
            }
            if(TABLE[i][j] == '#') {
                cnt++;
            }
            if(cnt > K)
                return false;
        }
    } 
#if 0
    cout << "H:";
    rep(i, choseH.size()) {
        cout << choseH[i] << ", ";

    }
