    rep(i, choseH.size()) {
        cout << choseW[i] << ", ";

    }
    cout << endl;
    cout << cnt << ", " << K << endl;
#endif
    return cnt == K;
}

int main() {
    cin >> H >> W >> K;
    rep(i, H) {
        rep(j, W) {
            cin >> TABLE[i][j];
        }
    }
    int cand = 0;
    for(int bitH=0; bitH < (1<<(H)); ++bitH) {
        vector<int> choseH;
        for(int i=0; i<H; ++i) {
            if(bitH & (1<<i))
                choseH.push_back(i);
        }
        for(int bitW=0; bitW < (1<<W); ++bitW) {
