            vector<int> choseW;
            for(int i=0; i<W; ++i) {
                if(bitW & (1<<i))
                    choseW.push_back(i);
            }
            if(match(choseH, choseW)) {
                cand++;
            }
        }
    }
    cout << cand << endl;


    return 0;
}

