int calcSum(int row, int col, int row_selection, int col_selection, vector<vector<int>>& c){
    int sum = 0;

    for(int y = 0; y < row; ++y){
        int cur_y = 1 << y;

        if((row_selection & cur_y) != 0){
            continue;
        }

        for(int x = 0; x < col; ++x){
            int cur_x = 1 << x;

            if((col_selection & cur_x) != 0){
                continue;
            }

            sum += c[y][x];
        }
    }
    return sum;
}


int colCheck(int row, int col, int row_selection, vector<vector<int>>& c, LONG K){
    int col_max = (1 << col) - 1;
    LONG i;

    int count = 0;
    FOR(i, 0, col_max){
        if(calcSum(row, col, row_selection, i, c) == K){
            ++count;
        }
    }

    return count;
}


