vector<int> col_count;
vector<int> row_count;
int total_back = 0;

int find_ways(vector<vector<char>>& grid, int k, int h, int w){
    int ans = 0;
    for(int rows = 0; rows < (1<<h); rows++){
        for(int cols = 0; cols < (1<<w); cols++){
            int black_count = total_back;
            int i, j;
            for(i=0; i<h; i++) {
                if (rows & (1 << i)) { // that means ith row is selected to paint red
                    black_count -= row_count[i];
               }
            }
            for(j=0; j<w; j++){
                if(cols&(1<<j)){ // that means jth col is selected to paint red
                    black_count -= col_count[j];
                }
            }
            for(int i=0; i<h; i++){
                for(int j=0; j<w; j++){
                    if(rows&(1<<i) and cols&(1<<j) and grid[i][j] == '#') black_count++;
                }
            }
            if(black_count == k) ans++;
        }
    }
    return ans;
}

