int H, W, K, ans = 0;
int rows[10], cols[10];

void dfs_cols(int col, int curr_black) {
	if (curr_black < K) return;

	if (col < W) {
		dfs_cols(col+1, curr_black);
		dfs_cols(col+1, curr_black - cols[col]);
	}
	else {
		ans += curr_black == K;
	}
}

void dfs_rows(int row, int curr_black) {
	// no point in searching this branch anymore
	if (curr_black < K) return;

	if (row < H) {
		// fill the row or don't fill the row
		dfs_rows(row+1, curr_black);
		dfs_rows(row+1, curr_black - rows[row]);
	}
	else {
		// consider cols now
		dfs_cols(0, curr_black);
	}
}

