int H, W, K;
int result;

void process(vector<vector<int>> map_info, int row_cnt, int row_start, int col_cnt, int col_start)
{
	if (row_cnt > 0)
	{
		for (int i = row_start; i < H; i++)
		{
			vector<vector<int>> new_map_info = map_info;
			for (int j = 0; j < W; j++)
			{
				new_map_info[i][j] = 0;
			}
			process(new_map_info, row_cnt - 1, i + 1, col_cnt, col_start);
		}
	}
	else if (col_cnt > 0)
	{
		for (int i = col_start; i < W; i++)
		{
			vector<vector<int>> new_map_info = map_info;
			for (int j = 0; j < H; j++)
			{
				new_map_info[j][i] = 0;
			}
			process(new_map_info, row_cnt, row_start, col_cnt - 1, i + 1);
		}
	}
	else
	{
		int total_cnt = 0;
		for (int i = 0; i < H; i++)
		{
			for (int j = 0; j < W; j++)
			{
				total_cnt += map_info[i][j];
			}
		}

		if (K == total_cnt)
		{
			result++;
		}
	}
}

