				map_info[i][j] = 1;
				total_cnt++;
			}
		}
	}

	process(map_info, 0, 0, 0, 0);
	for (int i = 1; i <= H; i++)
	{
		process(map_info, i, 0, 0, 0);
	}

	for (int i = 1; i <= W; i++)
	{
		process(map_info, 0, 0, i, 0);
	}

	for (int i = 1; i <= H; i++)
	{
		for (int j = 1; j <= W; j++)
		{
			process(map_info, i, 0, j, 0);
		}
	}

