//素因数分解（O(sqrt(N))）
//素因数分解したい値が10^8以上ならこっちを使う
vector<pair<ll, ll>> factorize(ll n) {
    ll tmpNum = n;
    vector<pair<ll, ll>> res, tmp;
    if (!mp[n].empty()) {
        return mp[n];
    }
    for (ll i = 2; i * i <= n; ++i) {
        if (n % i) continue;
        else {
            res.emplace_back(i, 0);
            if (tmpNum == 20) {
                ll x = 20;
            }
            while (n % i == 0) {
                if (tmpNum != n)break;
                n /= i;
                res.back().second++;
                if (!mp[n].empty()) {
                    tmp = factorize(n);
                    if (n % i == 0) {
                        for (ll k = 0; k < tmp.size(); k++) {
                            if (tmp[k].first == i) {
                                tmp[k].second++;
                            }
                        }
                    }
                    else {
                        tmp.emplace_back(i, 1);
                    }
                    mp[tmpNum] = tmp;
                    break;
                }
            }
        }
    }
    if (mp[tmpNum].empty()) {
        if (n != 1) res.emplace_back(n, 1);
        mp[tmpNum] = res;
        return res;
    }
    return mp[tmpNum];
}
//エラストテネスの篩（O(NloglogN))
struct Sieve {
    ll n;
    vector <ll> f, primes;
    Sieve(ll n = 1) :n(n), f(n + 1) {
        f[0] = f[1] = -1;
        for (ll i = 2; i <= n; ++i) {
            if (f[i]) continue;
            primes.push_back(i);
            f[i] = i;
            for (ll j = i * i; j <= n; j += i) {
                if (!f[j]) f[j] = i;
            }
        }
    }

    //素数判定
    bool isPrime(ll x) { return f[x] == x; }
    vector<ll> factorList(ll x) {
        vector<ll> res;
        while (x != 1) {
            res.push_back(f[x]);
            x /= f[x];
        }
        return res;
    }

    //素因数分解
    vector<P> factor(ll x) {
        vector<ll> fl = factorList(x);
        if (fl.size() == 0) return {};
        vector<P> res(1, P(fl[0], 0));
        for (ll p : fl) {
            if (res.back().first == p) {
                res.back().second++;
            }
            else {
                res.emplace_back(p, 1);
            }
        }
        return res;
    }
};
ll gcd(ll a, ll b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}
ll lcm(ll a, ll b) {
    return a / gcd(a, b) * b;
}
