// Function to find modulo inverse of a 
lo modInverse(lo a, lo m) 
{ 
    lo x, y; 
    lo g = gcdExtended(a, m, &x, &y); 
    if (g != 1) 
        cout << "Inverse doesn't exist"; 
    else
    { 
        // m is added to handle negative x 
        lo res = (x%m + m) % m; 
        return res; 
    } 
} 

// C function for extended Euclidean Algorithm 
lo gcdExtended(lo a, lo b, lo *x, lo *y) 
{ 
    // Base Case 
    if (a == 0) 
    { 
        *x = 0, *y = 1; 
        return b; 
    } 

    lo x1, y1; // To store results of recursive call 
    lo gcd = gcdExtended(b%a, a, &x1, &y1); 

    // Update x and y using results of recursive 
    // call 
    *x = y1 - (b/a) * x1; 
    *y = x1; 

    return gcd; 
} 

