using namespace std;

int main()
{
    int H, W, K;
    cin >> H >> W >> K;
    bool is_black[H][W];
    for (int i = 0; i < H; i++)
    {
        string s;
        cin >> s;
        for (int j = 0; j < W; j++)
        {
            if (s[j] == '.')
            {
                is_black[i][j] = false;
            }
            else
            {
                is_black[i][j] = true;
            }
        }
    }

    //cout << "hoge" << endl;

    vector<int> n_black(H, 0);
    int sum_black = 0;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (is_black[i][j])
            {
                n_black[i]++;
                sum_black++;
            }
        }
    }

    if (K > sum_black)
    {
        cout << 0 << endl;
        return 0;
    }

    int ans = 0;

    for (int i = 0; i < (1 << H); i++)
    {

        vector<bool> h_used(H, false);
        int deleted_black = 0;
        for (int j = 0; j < H; j++)
        {
            if (i & (1 << j))
            {
                h_used[j] = true;
                deleted_black += n_black[j];
            }
        }

        vector<int> n_w_black(W, 0);
        for (int j = 0; j < W; j++)
        {
            for (int k = 0; k < H; k++)
            {
                if (is_black[k][j] && !h_used[k])
                {
                    n_w_black[j]++;
                }
            }
        }

        //count deleted black
        int dp[W][sum_black + 1];
        for (int j = 0; j < W; j++)
        {
            for (int k = 0; k < sum_black + 1; k++)
            {
                dp[j][k] = 0;
            }
        }
        dp[0][deleted_black]++;
        dp[0][deleted_black + n_w_black[0]]++;
        for (int j = 1; j < W; j++)
        {
            for (int k = 0; k < sum_black + 1; k++)
            {
                if (dp[j - 1][k] > 0)
                {
                    dp[j][k] += dp[j - 1][k];
                    dp[j][k + n_w_black[j]] += dp[j - 1][k];
                }
            }
        }
        ans += dp[W - 1][sum_black - K];
        //cout << deleted_black << " " << ans << endl;
    }

    cout << ans << endl;
}

