void solvej(int now) {
	if(now==m+1) {
		int tmp=0;
		for(int i=1; i<=n; ++i)
			for(int j=1; j<=m; ++j)
				if(a[i][j]==1&&num[i][j]==0) tmp++;
		if(tmp==k) ans++;
		return ;
	}
	for(int i=0; i<=1; ++i) {
		if(i==1)
			for(int j=1; j<=n; ++j) num[j][now]++;
		solvej(now+1);
		if(i==1)
			for(int j=1; j<=n; ++j) num[j][now]--;
	}
}
