	char a[h][w];
	for(int i=0;i<h;i++)
		for(int j=0;j<w;j++)
			cin >> a[i][j];
	int n = (int)pow(2,h);
	int m = (int)pow(2,w);
	unordered_map<int,bool> row,col;
	int ans = 0;
	for(int i=0;i<n;i++) {
		for(int j=0;j<m;j++) {
			for(int p=0;p<h;p++) {
				if((i & (1<<p)) != 0)
					row[p] = true;
				else
