			}
			for(int p=0;p<w;p++) {
				if((j & (1<<p)) != 0)
					col[p] = true;
				else
					col[p] = false;
			}
			int cnt = 0;
			for(int x=0;x<h;x++)
				for(int y=0;y<w;y++)
					if(!row[x] and !col[y] and a[x][y] == '#')
						cnt++;
			if(cnt == k)
				ans++;
			row.clear();
			col.clear();
		}
	}
	cout << ans << endl;
}

