int main() {
    unsigned H, W, K, sum = 0, ans = 0;
    cin >> H >> W >> K;
    V<string> grid(H);
    V<int> tate(H, 0), yoko(W, 0);
    VV<int> cross(H, V<int>(W, 0));
    for (int i = 0; i < H; ++i) {
        cin >> grid[i];
    }
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (grid[i][j] == '#') {
                tate[i]++;
                cross[i][j]++;
                sum++;
            }
        }
    }
    for (int i = 0; i < W; ++i) {
        for (int j = 0; j < H; ++j) {
            if (grid[j][i] == '#')yoko[i]++;
        }
    }

    for (unsigned mask1 = 0; mask1 < (1u << H); ++mask1)
        for (unsigned mask2 = 0; mask2 < (1u << W); ++mask2) {
            int cnt = 0;
            for (unsigned i = 0; i < H; i++) {
                if ((mask1 >> i) % 2)cnt += tate[i];
            }
            for (unsigned i = 0; i < W; i++) {
                if ((mask2 >> i) % 2)cnt += yoko[i];
            }
            for (unsigned i = 0; i < H; i++) {
                for (unsigned j = 0; j < W; j++) {
                    if ((mask1 >> i) % 2 && (mask2 >> j) % 2)cnt -= cross[i][j];
                }
            }
            if (sum - cnt == K) ans++;
        }
    cout << ans << endl;

    return 0;
}

