vector<vector<int>> generateSubsets(int n){

	vector<vector<int>> ans;

	for(int i = 0 ; i < (1<<n) ; ++i){

		vector<int> tmp;
		for(int j = 0 ; j < n ; ++j){

			if(i&(1<<j))
				tmp.pb(j);
		}
		ans.pb(tmp);
	}
	return ans;
}

