int main() {
	int h, w, k;
	int count=0;
	int ans=0;
	cin >> h >> w >> k;
	Graph g(h+1);
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			char c;
			int t;
			cin >> c;
			if (c == '#') {
				t = 1;
				count++;
			}
			else {
				t = 0;
			}
			g.at(i).push_back(t);
			//cout << g.at(i).at(j) << ',' << h << ',' << j << endl;
		}
	}
	for (int biti = 0; biti < (1 << h); ++biti) {
		for (int bitj = 0; bitj < (1 << w); ++bitj) {
			Graph gc;
			gc = g;
			int ansm = 0;
			for (int i = 0; i < h; i++) {
				if (biti & (1 << i)) {
					for (int t = 0; t < w; t++) {
						if (gc.at(i).at(t) == 1) {
							ansm++;
							gc.at(i).at(t) = -1;
						}

					}
				}
			}
			for (int j = 0; j < w; j++) {
				if (bitj & (1 << j)) {
					for (int t = 0; t < h; t++) {
						if (gc.at(t).at(j) == 1) {
							ansm++;
							gc.at(t).at(j) = -1;
						}

					}
				}
			}
			//cout << ansm << endl;
			if (k == count - ansm) {
				ans++;
			}
		}

	}
	cout << ans << endl;
}

