const int N = 1e2 + 10;

int n, m, k;
LL ans;
char c[N][N];
vector<int>vec[2];

void check() {

	int sum = 0;
	for (int i = 1;i <= n;i++)
		for (int j = 1;j <= m;j++) {

			bool q = 0;
			for (auto x : vec[0])
				q |= x == i;
			for (auto x : vec[1])
				q |= x == j;

			if (q)continue;
			sum += c[i][j] == '#';
		}

	if (sum == k)
		ans++;
}

void bt(int i,int k) {

	if (i == n + 1 && !k) {
		bt(1, 1);
		return;
	}

	if (i == m + 1 && k) {
		check();
		return;
	}

	vec[k].push_back(i);
	bt(i + 1, k);
	vec[k].pop_back();
	bt(i + 1, k);
}

