void path(vector<string> v,int K,set<int> &r,set<int> &c,vector<pair<int,int> > &vv)
{
	if(K==0)
	{
		vector<pair<int,int> > v1;
		v1=vv;
		sort(v1.begin(),v1.end());
		ss.insert(v1);
		return;
	}
	else if(K<0)
	return ;
	for(int i=0;i<v.size();i++)
	{
		if(r.find(i)==r.end())
		{
			int cnt=0;
			for(int j=0;j<v[i].length();j++)
			{
				if(v[i][j]=='#'&&c.find(j)==c.end())
				cnt++;
			}
			r.insert(i);
			vv.push_back(make_pair(1,i));
			path(v,K-cnt,r,c,vv);
			vv.pop_back();
			r.erase(i);
		}
	}
	for(int i=0;i<v[0].length();i++)
	{
		if(c.find(i)==c.end())
		{
			int cnt=0;
			for(int j=0;j<v.size();j++)
			{
				if(v[j][i]=='#'&&r.find(j)==r.end())
				cnt++;
			}
			c.insert(i);
			vv.push_back(make_pair(0,i));
			path(v,K-cnt,r,c,vv);
			vv.pop_back();
			c.erase(i);
		}
	}
}
