int rec(VI a,VI b) {
	if (SZ(a)==h&&SZ(b)==w) {
		memset(vis,0,sizeof(vis));
		int tmp=0;
		rep(i,0,h) {
			if (a[i]==1) {
				rep(j,0,w) {
					if (!vis[i][j]&&s[i][j]=='#') {
						vis[i][j]=true;
						tmp++;
					}
				}
			}
		}
		rep(i,0,w) {
			if (b[i]==1) {
				rep(j,0,h) {
					if (!vis[j][i]&&s[j][i]=='#') {
						vis[j][i]=true;
						tmp++;
					}
				}
			}
		}
		if (sum-tmp==k) return 1;
		return 0;
	}
	if (SZ(a)==h) {
		VI mir_b=b;
