using namespace std;

int h, w, k;
int oriB[10][10];

int newB[10][10];

bool isPaint[20];

int wayCount = 0;

void doScan(int depth) {
	if (depth == (h + w)) {
		for (int r = 0 ; r < h ; r++) {
			for (int c = 0 ; c < w ; c++) {
				newB[r][c] = oriB[r][c];
			}
		}

		for (int i = 0 ; i < h ; i++) {
			if (isPaint[i] == false)
				continue;

			for (int c = 0 ; c < w ; c++) {
				newB[i][c] = -1;
			}
		}

		for (int i = h ; i < h + w ; i++) {
			if (isPaint[i] == false)
				continue;

			for (int r = 0 ; r < h ; r++) {
				newB[r][i - h] = -1;
			}
		}

		int numCount = 0;
		for (int r = 0 ; r < h ; r++) {
			for (int c = 0 ; c < w ; c++) {
				if (1 == newB[r][c])
					numCount++;
			}
		}

		if (numCount == k)
		 	wayCount++;
	} else {
		isPaint[depth] = false;
		doScan(depth + 1);
		isPaint[depth] = true;
		doScan(depth + 1);
		isPaint[depth] = false;
	}

}



