            // cout<<"Number Of Rows Selected = "<<i<<" Number Of Columns Selected = "<<j<<endl;
            vector<vector<int>> rowChoices = comb(H, i);
            vector<vector<int>> colChoices = comb(W, j);
            // cout<<"Row Choices"<<endl;
            // for(auto x:rowChoices){
            //     for(auto y:x) cout<<y<<" ";
