            // }
            // cout<<"Col Choices"<<endl;
            // for(auto x:colChoices){
            //     for(auto y:x) cout<<y<<" ";
            //     cout<<endl;
            // }
            for(auto x:rowChoices){
                for(auto y:colChoices){
                    // cout<<"-----------------------"<<endl;
                    int visited[H][W];
                    for(int p=0; p<H; ++p){
                        for(int q=0; q<W; ++q) visited[p][q] = 0;
                    }
                    ll count = 0;
                    for(auto rowChoice1:x){
                        // cout<<"Row -> "<<rowChoice1<<endl;
                        for(int alpha=0; alpha<W; alpha++){
                            if(grid[rowChoice1][alpha]=='#' && visited[rowChoice1][alpha]==0) count++;
                            visited[rowChoice1][alpha] = 1;
                        }
                    }
                    for(auto colChoice1:y){
                        // cout<<"Col -> "<<colChoice1<<endl;
                        for(int alpha=0; alpha<H; alpha++){
