int main() {
  int H, W, K;
  cin >> H >> W >> K;
  vector<string> c(H);
  for (int i=0; i<H; i++) cin >> c[i];
  // 行と列の選び方を全探索
  int res = 0;
  for (int tmp_line=0; tmp_line<(1<<6); tmp_line++) {
    for (int tmp_column=0; tmp_column<(1<<6); tmp_column++) {
      bitset<6> line(tmp_line), column(tmp_column);
      // 1のビットに対応する行を選んだと考える
      vector<string> c_copy = c;
      for (int i=0; i<H; i++) {
        if (line.test(i)) {
          for (int j=0; j<W; j++) c_copy[i][j] = '.';
        }
      }
      // 列について
      for (int j=0; j<W; j++) {
        if (column.test(j)) {
          for (int i=0; i<H; i++) c_copy[i][j] = '.';
        }
      }
      // 黒のマスを数える
      int num = 0;
      for (int i=0; i<H; i++) {
        for (int j=0; j<W; j++) {
          if (c_copy[i][j]=='#') num++;
        }
      }
      if (num==K) res++;
    }
  }
  // 重複して数えている分を除く
  res /= (int)pow(2, 6-H)*(int)pow(2, 6-W);
  cout << res << endl;
  return 0;
}

