int find (string x,string y,vs &s){
    int i,j,k=0,n=s.size(),m=s[0].size();
    for (i=0;i<6;i++){
        if (x[i]=='1'){
            for(j=0;j<m;j++){
                if (s[i][j]=='#')k++;
            }
        }

        if (y[i]=='1'){
            for  (j=0;j<n;j++){
                if (s[j][i]=='#')k++;
            }
        }
    }
    for  (i=0;i<6;i++){
        for(j=0;j<6;j++){
            if  (x[i]=='1'&& y[j]=='1'){
                if (s[i][j]=='#')k--;
            }
        }
    }
    return k;
}






