constexpr char black= '#';
constexpr char red= 'x';

void paint(vector<string> *trial, int tmp_h, int tmp_w){
  const int H= trial->size();
  const int W= trial->at(0).size();

  int h= 0;
  while(tmp_h > 0){
    if(tmp_h & 1){
      for(int w_t=0; w_t<W; w_t++){
        trial->at(h).at(w_t)= red;
      }
    }
    tmp_h>>= 1;
    h++;
  }

  int w= 0;
  while(tmp_w > 0){
    if(tmp_w & 1){
      for(int h_t=0; h_t<H; h_t++){
        trial->at(h_t).at(w)= red;
      }
    }
    tmp_w>>= 1;
    w++;
  }
}

int count(vector<string> &trial){
  const int H= trial.size();
  const int W= trial.at(0).size();

  int cnt= 0;
  for(int h_t=0; h_t<H; h_t++){
    for(int w_t=0; w_t<W; w_t++){
      if(trial.at(h_t).at(w_t)==black){
        cnt++;
      }
    }
  }

  return cnt;
}

int main(){
  int H,W,K;
  cin >> H >> W >> K;

  vector<string> board(H);
  for(int i=0; i<H; i++){
