  for(int tmp_h=0; tmp_h< (1<<H); tmp_h++){
    for(int tmp_w=0; tmp_w< (1<<W); tmp_w++){
      vector<string> trial= board;
      paint(&trial, tmp_h, tmp_w);

      if(count(trial)==K){ ans++; }
    }
  }

  cout << ans << endl;
}

