int solve2(string s[], int r[], int c[], int s1, int s2, int h, int w, int k, vector<int> &v){
	if(s2 == w){
		return (k == 0);
	}

	int so1 = solve2(s, r, c, s1, s2 + 1, h, w, k, v);
	int temp = k - c[s2];
	rep(j, 0, v.size()){
		if(s[v[j]][s2] == '#')
			temp++;
	}
	int so2 = solve2(s, r, c, s1, s2 + 1, h, w, temp, v);

	return so1 + so2;
}
int solve(string s[], int r[], int c[], int s1, int s2, int h, int w, int k, vector<int> &v){
	if(s1 == h){
		return solve2(s, r, c, s1, s2, h, w, k, v);
	}

	int so1 = solve(s, r, c, s1 + 1, s2, h, w, k, v);
	v.pb(s1);
	int so2 = solve(s, r, c, s1 + 1, s2, h, w, k - r[s1], v);
	v.pop_back();
	return so1 + so2;
