void setrow(vvi &arr, int r) {
    fill(ALL(arr[r]), 0);
}

void setcol(vvi &arr, int c) {
    iter(i, arr) {
        i[c] = 0;
    }
}

int countblack(vvi &arr) {
    int sum = 0;
    iter(i, arr) {
        iter(j, i) {
            sum += j;
        }
    }
    return sum;
}

void solve() {
    int h, w, k; cin >> h >> w >> k;
    vvi arr(h, vi(w));
    iter(i, arr) {
        iter(j, i) {
            char temp; cin >> temp;
            j = (temp == '#') ? 1 : 0;
        }
    }

    // iter(i, arr) {debn(i);}

    int res = 0;
    for (int i = 0; i < (1 << h); ++i) {
        for (int j = 0; j < (1 << w); ++j) {
            vvi cp = arr;

            int x = i, y = j;
            int r = h, c = w;

            while (r >= 0) {
                --r;
                if (x%2) setrow(cp, r);
                x = x >> 1;
            }
            while (c >= 0) {
                --c;
                if (y%2) setcol(cp, c);
                y = y >> 1;
            }

            if (countblack(cp) == k) {
                ++res;
                // deb(i, j, countblack(cp));
                // iter(t, cp) {debn(t);}
            }
        }
    }

    printf("%d\n", res);
}

