using namespace std;

char c[6][6];

bool judge(bool *patternH, bool *patternW, int H, int W, int K) {
    int cnt = 0;
    for(int i = 0; i < H; i++) {
        if(patternH[i]) {
            continue;
        }
        for(int j = 0; j < W; j++) {
            if(patternW[j]) {
                continue;
            }
            if(c[i][j] == '#') {
                cnt++;
            }
        }
    }

    return cnt == K;
}

int main() {
    int H, W, K;

    cin >> H >> W >> K;

    for(int y = 0; y < H; y++) {
        for(int x = 0; x < W; x++) {
            cin >> c[y][x];
        }
    }

    bool patternH[(int)pow(2, H)][H];
    for(int bit = 0; bit < (1 << H); bit++) {
        for(int i = 0 ; i < H; i++) {
            patternH[bit][i] = bit & (1<<i);
        }
    }

    bool patternW[(int)pow(2, W)][W];
    for(int bit = 0; bit < (1 << W); bit++) {
        for(int i = 0 ; i < W; i++) {
            patternW[bit][i] = bit & (1<<i);
        }
    }

    int ans = 0;
    for(int i = 0; i < pow(2, H); i++) {
        for(int j = 0; j < pow(2, W); j++) {
            if(judge(patternH[i], patternW[j], H, W, K)) {
                ans++;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

