		}
	}
	int ret = 0;
	for(int i=0; i<(1<<h); i++){
		for(int j=0; j<(1<<w); j++){
			copy();
			paint(i,j);
			if(solve()==k) ret++;
		}
	}
	cout<<ret;
}

