int main() {
  //----------変数置いたり代入したり----------

  int H, W, K; // それぞれの変数は問で与えられた通り
  cin >> H >> W >> K;

  vector<vector<char>> clist(H, vector<char>(W)); 
  // H×Wの配列に "." or "#"を代入
  for(int i=0; i<H; i++) {
    for(int j=0; j<W; j++) {
      char c;
      cin >> c;
      clist.at(i).at(j) = c;
    }
  }

  //----------ここまでは問題なしと思われる----------

  //----------処理していく(ここから不安)----------

  int ans = 0; 
  // ansは答えとして出力したい値を表す変数, 
  // 条件に合致する行列の選び方をしたときに+1していく

  //----------ビット全探索で行列の選び方を決定していく----------
  for (int tmp1 = 0; tmp1 < (1 << H); tmp1++) {
    bitset<6> s(tmp1);
    for (int tmp2 = 0; tmp2 < (1 << W); tmp2++) {
      bitset<6> t(tmp2);

      int jud=0; // "#"の個数を数えるための変数, 見つけ次第+1していく
      for(int i=0; i<H; i++) {
        for(int j=0; j<W; j++) {

          //----------最も怪しいと思われる部分----------
          //自分の考えでは、clistの要素のうち、選ばれていない行と列に属し、
          //かつ、"#"であればカウントする
          if(s.test(i) && t.test(j) && clist.at(i).at(j)=='#') {
            jud++;
          }
          //------------------------------------------

        }
      }

      //judによりカウントされた"#"の数がKであれば、
      //その行列の選び方がOKということになるため、ansに+1する
      if (jud==K) {
        ans++;
      }
    }
  }
  cout << ans << endl;
}

