using namespace std;

void dfs(int c, int h, int w, int k, const vector<vector<char>>& s, vector<int>& hs, vector<int>& ws, int& ans) {
  if (c == h + w) {
    int sum(0);
    for (int i = 0; i < h; ++i)
      for (int j = 0; j < w; ++j) {
        if (hs[i] || ws[j]) continue;
        sum += (s[i][j] == '#');
      }
    if (sum == k) ans++;
    return;
  }
  if (c < h) {
    //for (int i = c; i < h; ++i) {
    dfs(c + 1, h, w, k, s, hs, ws, ans);
    hs[c] = 1;
    dfs(c + 1, h, w, k, s, hs, ws, ans);
    hs[c] = 0;
    //}
  } else {
    dfs(c + 1, h, w, k, s, hs, ws, ans);
    ws[c - h] = 1;
    dfs(c + 1, h, w, k, s, hs, ws, ans);
    ws[c - h] = 0;
  }
}
