  vector<int> hs(h), ws(w);
  for (int i = 0; i < h; ++i)
    for (int j = 0; j < w; ++j)
      cin >> s[i][j];
  dfs(0, h, w, k, s, hs, ws, ans);
  cout << ans << endl;
  return 0;
}

