	if(k==r+1){
		v1.push_back(subset1);

	}
	else{
		subset1.push_back(k);//include k
		search1(k+1);
		subset1.pop_back();// don't include k
		search1(k+1);
	}
}
void search2(int k){// start with 1
	if(k==c+1){
		v2.push_back(subset2);
	}
	else{
		subset2.push_back(k);//include k
		search2(k+1);
		subset2.pop_back();// don't include k
		search2(k+1);
	}
}

