#include<bits/stdc++.h>
using namespace std;

vector<int> col_count;
vector<int> row_count;
int total_back = 0;

int find_ways(vector<vector<char>>& grid, int k, int h, int w){
    int ans = 0;
    for(int rows = 0; rows < (1<<h); rows++){
        for(int cols = 0; cols < (1<<w); cols++){
            cout << "rows : "  << rows << ", cols : " << cols << "\n";
            int black_count = total_back;
            int i, j;
            for(i=0; i<h; i++) {
                if (rows & (1 << i)) { // that means ith row is selected to paint red
                    black_count -= row_count[i];
               }
            }
            for(j=0; j<w; j++){
                if(cols&(1<<j)){ // that means jth col is selected to paint red
                    black_count -= col_count[j];
                }
            }
            for(int i=0; i<h; i++){
                for(int j=0; j<w; j++){
                    if(rows&(1<<i) and cols&(1<<j) and grid[i][j] == '#') black_count++;
                }
            }
            if(black_count == k) ans++;
        }
    }
    return ans;
}

int main(){
    int h, w, k; cin >> h >> w >> k;
    total_back = 0;
    vector<vector<char>> grid(h, vector<char>(w));
    for(int i=0; i<h; i++){
        for(int j=0; j<w; j++){
            cin >> grid[i][j];
            if(grid[i][j] == '#') total_back++;
        }
    }
    col_count.resize(w,0);
    row_count.resize(h,0);
    for(int i=0; i<h; i++){
        int count = 0;
        for(int j=0; j<w; j++){
            if(grid[i][j] == '#') count++;
        }
        row_count[i] = count;
    }
    for(int i=0; i<w; i++){
        int count = 0;
        for(int j=0; j<h; j++){
            if(grid[j][i] == '#') count++;
        }
        col_count[i] = count;
    }
    int ways = find_ways(grid,k,h,w);
    cout << ways << "\n";
    return 0;
}

