#include <bits/stdc++.h>
using namespace std;


int main()
{
    int r, c, k; cin >> r >> c >> k;
    char ch;
    int row[r] = {}, col[c] = {}, table[r][c]={};
    int countn{0}, result{0};
    for(int i = 0; i < r*c; i++)
    {
        cin >> ch;
        if(ch == '#')
        {
            col[i%c] += 1;
            row[i/c] += 1;
            countn++;
            table[i/c][i%c] = 1;
        }
    }
    /*
    for(int i = 0; i < r; i++)
        cout << row[i] << " ";
    cout << endl;
    for(int j = 0; j < c; j++)
        cout << col[j] << " ";
    cout << endl;
    */
    // すべての選び方を試して、総和がkになるものがあるかを調べる
    for (int tmp = 0; tmp < (1 << r); tmp++) 
    {
        bitset<6> sr(tmp);  // 最大r個なのでrビットのビット列として扱う

        // ビット列の1のビットに対応する整数を選んだとみなして総和を求める
        int sum = 0, temp;
        for (int i = 0; i < r; i++) {
            if (sr.test(i)) {
                sum += row[i];
            }
        }
        temp = sum;
        for (int tmpj = 0; tmpj < (1 << c); tmpj++) 
        {
            bitset<6> sc(tmpj);  // 最大r個なのでrビットのビット列として扱う

            // ビット列の1のビットに対応する整数を選んだとみなして総和を求める
            sum = temp;
            for (int j = 0; j < c; j++) {
                if (sc.test(j)) {
                    sum += col[j];
                }
            }
            for(int ri = 0; ri < r; ri++)
                if(sr.test(ri))
                    for(int ci = 0; ci < c; ci++)
                        if(sc.test(ci))
                            sum -= table[ri][ci];
            if ((countn - sum) == k) {
                result++;
            }
            //cout << sum << " ";
        }

    }

    cout << result << endl;
    return 0;
}

