void solve()
{	
    ll h,w,k;
    cin>>h>>w>>k;

    ll a[h][w];
    char stri[w];

    for(ll i=0;i<h;i++){
        cin>>stri;
        for(ll j=0;j<w;j++){
            if(stri[j]=='.') a[i][j]=0;
            else a[i][j]=1;
        }
    }
    ll ans=0;

    for(ll i=0;i<pow(2,w);i++){
        for(ll j=0;j<pow(2,w);j++){
            ll ti = i;
            ll tj = j;
            ll row[h] = {0};
            ll ctrh=0;
            while(ti){
                if(ti%2==1) row[ctrh]=1;
                ti/=2;
                ctrh++;
            }
            ll col[w] = {0};
            ll ctrw=0;
            while(tj){
                if(tj%2==1) col[ctrw]=1;
                tj/=2;
                ctrw++;
            }     
            ll b[h][w];
            for(ll ai = 0;ai<h;ai++){
                for(ll aj=0;aj<w;aj++){
                    b[ai][aj] = a[ai][aj];
                }
            }    
            for(ll ai = 0;ai<h;ai++){
                if(row[ai]==1){
                    for(ll aj=0;aj<w;aj++){
                        b[ai][aj]=0;
                    }
                }
            }  
            for(ll ai = 0;ai<w;ai++){
                if(col[ai]==1){
                    for(ll aj=0;aj<h;aj++){
                        b[aj][ai]=0;
                    }
                }
            }               
            ll ctr = 0;
            for(ll ai = 0;ai<h;ai++){
                for(ll aj=0;aj<w;aj++){
                    if(b[ai][aj]) ctr++;
                }
            }                
            if (ctr==k){
                ans++;
            }
        }
    }
    cout<<ans;



}

