map<ll,ll> countDivisors(ll n) 
{ 
    ll cnt = 0; 
    map<ll,ll> m;
    for (ll i = 1; i <= sqrt(n); i++) 
    { 
        if (n % i == 0) 
        {  
         m[i]++;
            // If divisors are equal, 
            // count only one 
            if (n / i == i) 
                cnt++; 

            else // Otherwise count both 
                {cnt = cnt + 2; 
                    m[n/i]++;}
        } 
    } 
    return m; 
} 


