class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    ll M, N, K;

    vector<vector<char>> bord;
    bool input() {
        is >> N >> M >> K;
        bord = VEC(N, M, '0');
        is >> bord;
        return !!is;
    }

    ll dfs(ll x, vector<int>& ok){
        if(x >= N) return dfs2(0,0, ok);
        ll ans = dfs(x+1, ok);
        ok.push_back(x);
        ans += dfs(x+1, ok);
        ok.pop_back();
        return ans;
    }

    ll dfs2(ll x, ll k, const vector<int>& ok){
        if(ok.empty()) return 0;
        if(x >= M) return k == K;
        ll ans = dfs2(x+1, k, ok);
        for (auto &&j : ok) {
            if(bord[j][x] == '#') k++;
        } // end j
        ans += dfs2(x+1, k, ok);
        return ans;
    }

    void run();
};

