int main(){
  int H, W, K; cin >> H >> W >> K;
  char c[H][W];
  int bsum = 0;
  map<char, int> mh,mw;
  rep(i,H){
    rep(j,W){
      cin >> c[i][j];
      if (c[i][j] == '#'){
        bsum++;
        mh[char(i)]++;
        mw[char(j)]++;
      }
    }
  }
  int ans = 0;
  for (int bitH = 0; bitH < (1<<H); bitH++){
    vector<int> hvec;
    for (int i = 0; i < H; ++i){
      if(bitH & (1<<i)){
        hvec.push_back(i);
      }
    }
    for (int bitW = 0; bitW < (1<<W); bitW++){
      vector<int> wvec;
      for (int j = 0; j < W; j++){
        if(bitW & (1<<j)){
          wvec.push_back(j);
        }
      }
      int temp = bsum;
      for (int h = 0; h<hvec.size(); h++){
        temp -= mh[char(hvec[h])];
      }
      for (int w = 0; w < wvec.size(); w++){
        temp -= mw[char(wvec[w])];
      }
      for (int h = 0; h<hvec.size(); h++){
        for (int w = 0; w< wvec.size(); w++){
          if(c[hvec[h]][wvec[w]] == '#'){
            temp++;
          }
        }
      }
      if (temp == K){
        ans++;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

