#include<bits/stdc++.h>
using namespace std;
int h,w,k;
int ans=0;
int a[10][10],b[10][10],cnt[10][10];
void dfs(int num,int goal,int x){
   // cout<<"***"<<goal<<" "<<x<<" "<<endl;
    if(x>h+w)return ;
    if(num==goal){
        int sum=0;
        for(int i=0;i<h;++i){
            for(int j=0;j<w;++j){
                sum+=b[i][j];
            }
        }
        if(sum==k)ans++;
        return ;
    }
    if(x>=h){
        for(int i=0;i<h;++i){
            cnt[i][x-h]++;
            b[i][x-h]=0;
        }
        dfs(num+1,goal,x+1);
        for(int i=0;i<h;++i){
            cnt[i][x-h]--;
            if(!cnt[i][x-h])b[i][x-h]=a[i][x-h];
        }
        dfs(num,goal,x+1);
    }
    else{
        for(int i=0;i<w;++i){
             cnt[x][i]++;
             b[x][i]=0;
         }
         dfs(num+1,goal,x+1);
         for(int i=0;i<w;++i){
             cnt[x][i]--;
             if(!cnt[x][i])b[x][i]=a[x][i];
         }
         dfs(num,goal,x+1);
    }
}
int main(){
    scanf("%d%d%d",&h,&w,&k);
    for(int i=0;i<h;++i){
        for(int j=0;j<w;++j){
            char x;
            scanf(" %c",&x);
            if(x=='.')a[i][j]=b[i][j]=0;
            else a[i][j]=b[i][j]=1;
        }
    }
    for(int k=0;k<=h+w;++k){
        for(int i=0;i<h;++i){
             for(int j=0;j<w;++j){
                b[i][j]=a[i][j];
             }
         }
        memset(cnt,0,sizeof(cnt));
        dfs(0,k,0);
    }
    printf("%d\n",ans);
    return 0;
}

