inline void dfs (int nwwwwwww) {
	if (nwwwwwww == n + m + 1) {
		for (int i = 1; i <= n; ++ i) {
			for (int j = 1; j <= m; ++ j) change[i][j] = ch[i][j];
		}
		int cnt = 0;
		for (int i = 1; i <= n; ++ i) {
			for (int j = 1; j <= m; ++ j) {
				if (vis[i] || visitttttttttt[j]) change[i][j] = '.';
			}
		}
		for (int i = 1; i <= n; ++ i) {
			for (int j = 1; j <= m; ++ j) cnt += (change[i][j] == '#');
		}
		if (cnt == k) ++ ans;
		return;
	}
	if (nwwwwwww > n) {
		visitttttttttt[nwwwwwww - n] = true; dfs (nwwwwwww + 1);
		visitttttttttt[nwwwwwww - n] = false; dfs (nwwwwwww + 1);
