ll cnts(vec<std::string> vs, ll r, ll c, ll sr, ll sc) {
    for (ll i = 0; i < r; i++) {
        ll mask = 1ll << i;
        if (!(sr & mask)) continue;
        for (ll j = 0; j < c; j++) vs[i][j] = '.';
    }
    for (ll i = 0; i < c; i++) {
        ll mask = 1ll << i;
        if (!(sc & mask)) continue;
        for (ll j = 0; j < r; j++) vs[j][i] = '.';
    }

    ll ans = 0;
    for (auto &&v : vs) for (char c : v) ans += (c == '#');
    return ans;
}

