int arr[10][10],sumr[10],sumc[10];

void solve(){
	int h,w;
	cin>>h>>w;
	int k;
	cin>>k;
	int cnt=0;
	fr(i,1,h+1){
		fr(j,1,w+1){
			char t;
			cin>>t;
			if(t=='.'){
				arr[i][j]=0;
			}
			else{
				cnt++;
				sumc[j]++;
				sumr[i]++;
				arr[i][j]=1;
			}
		}
	}
	int x=cnt-k;
	if(x<0){
		cout<<0<<endl;
		return;
	}
	int ans=0;
	for(int i=0;i<(1<<h);i++){
		for(int j=0;j<(1<<w);j++){
			vi col;
			int del=0;
			int cc=j,rr=i;
			int kk=1;
			while(cc>0){
				if(cc&1){
					col.pb(kk);
					del+=sumc[kk];
				}
				kk++;
				cc>>=1;
			}
			kk=1;
			while(rr>0){
				if(rr&1){
					del+=sumr[kk];
					for(auto cl: col){
						if(arr[kk][cl]==1)
							del--;
					}
				}
				kk++;
				rr>>=1;
			}
			if(del==x){
				ans++;
			}
		}
	}
	cout<<ans<<endl;
	return;
}

