//累積和系ライブラリ
struct cul {
    vector<ll>culSum;

    //値渡し(&なし）だとvectorの受け取りにサイズ分かかるので、必ず参照渡しである&をつける必要がある。
    cul(vector<ll>& v) :culSum(v.size() + 1, 0) {
        rep(i, v.size()) {
            culSum[i + 1] = culSum[i] + v[i];
        }
    }
    //累積和の配列自体を返す。
    vector<ll> culAll() {
        return culSum;
    }

    //部分和。
    ll partialSum(ll l, ll r) {
        l++; r++;//0-indexedに直す
        return culSum[r] - culSum[l - 1];
    }
};
//いもす法(O(N));
vector<ll> imos(vector<ll>& v, vector<tuple<ll, ll, ll>>& lra) {
    ll n = v.size();
    vector<ll>imosV(n + 1, 0);
    rep(i, lra.size()) {
        ll& l = get<0>(lra[i]);
        ll& r = get<1>(lra[i]);
        ll& a = get<2>(lra[i]);
        if (l == -INF) {
            imosV[min(n, r)] += a;
        }
        else {
            imosV[max(0LL, l)] += a;
            imosV[min(n, r + 1)] -= a;
        }
    }
    cul imosCul(imosV);
    vector<ll> imosCulSum = imosCul.culAll();
    //既にある配列に足す。
    rep(i, n) {
        v[i] += imosCulSum[i + 1];
        //min(v[i],n);
    }
    return v;
}
//組み合わせ(剰余付き)
//combination c(n)で初期化する必要がある。（nはCの左側の数）
struct combination {
    vector<mint> fact, ifact;
    combination(int n) :fact(n + 1), ifact(n + 1) {
        assert(n < mod);
        fact[0] = 1;
        for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i;
        ifact[n] = fact[n].inv();
        for (int i = n; i >= 1; --i) ifact[i - 1] = ifact[i] * i;
    }
    mint operator()(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * ifact[k] * ifact[n - k];
    }
};
