                    tmp = factorize(n);
                    if (n % i == 0) {
                        for (ll k = 0; k < tmp.size(); k++) {
                            if (tmp[k].first == i) {
                                tmp[k].second++;
                            }
                        }
                    }
                    else {
                        tmp.emplace_back(i, 1);
                    }
                    mp[tmpNum] = tmp;
                    break;
                }
