void combi(int before, int n, int r, vector<vector<int> > & vec, vector<int> & tmp){
    if(tmp.size() == r){
        vector<int> to_copied = tmp;
        vec.push_back(to_copied);
        return;
    }
    for(int i=before+1; i<n; i++){
        tmp.push_back(i);
        combi(i, n, r, vec, tmp);
        tmp.pop_back();
    }
}

