void dfs(int dep)
{
    if(dep==h+w)
    {
        int cnt=0;
        for(int i=0;i<h;i++)
        {
            for(int j=0;j<w;j++)
            {
                if(mp[i][j]=='#')
                    cnt++;
            }
        }
        if(cnt==k) 
        {
            ans++;
        }
        return ;
    }
    char tmp[10];
    if(dep<h)
    {
        for(int i=0;i<w;i++)
        {
            tmp[i]=mp[dep][i];
            mp[dep][i]='r';
        }
        dfs(dep+1);
        for(int i=0;i<w;i++)
        {
            mp[dep][i]=tmp[i];
        }
    }
    else
    {
        for(int i=0;i<h;i++)
        {
            tmp[i]=mp[i][dep-h];
            mp[i][dep-h]='r';
        }
        dfs(dep+1);
        for(int i=0;i<h;i++)
        {
            mp[i][dep-h]=tmp[i];
        }
    }
    dfs(dep+1);
    return ;
}

