int count_black(vector<string> vec){
    int H, W;
    H = vec.size();
    W = vec[0].size();
    int ret = 0;
    for (int i=0; i<H; i++){
        for (int j=0; j<W; j++)if (vec[i][j] == '#')ret++;
    }

    return ret;
}

//列を色付け
vector<string> column_coloring( vector<string>vec, int cbit){
    int H, W;
    H = vec.size();
    W = vec[0].size();
    for (int i=0; i<W; i++){
        if (cbit & (1 << i)){
            //列i を塗る
            for (int j=0; j<H; j++)vec[j][i] = 'R';
        }
    }
    return vec;
}


//行を色付け
vector<string> row_coloring(vector<string>vec, int rbit){
    int H, W;
    H = vec.size();
    W = vec[0].size();
    string row;
    for (int i=0; i<W; i++)row += "R";

    for (int i=0; i<H; i++){
        if (rbit & (1 << i)){
            vec[i] = row;
        }
    }
    return vec;
}


int main() {
    int H, W, K;
    cin >> H >> W >> K;
    vector<string>c(H);
    for (int i=0; i<H; i++)cin >> c[i];
    int ans = 0;

    //どの行を選ぶかのbit, どの列を選ぶかのbitがあればよい
    //どの行を選ぶか
    for (int rbit=0; rbit<(1<<H); rbit++){
        //どの列を選ぶか
        for (int cbit = 0; cbit<(1<<W); cbit++){
            vector<string>vec = row_coloring(c, rbit);
            vec = column_coloring(vec, cbit);
            if (count_black(vec) == K){
                ans++;
            }
        }
    }

    cout << ans << endl;
}

