	rep(S1, 1 << H) rep(S2, 1 << W) {
		int a_c[H][W];
		rep(i, H) rep(j, W) a_c[i][j] = a[i][j];

		rep(i, H) {
			if (S1 >> i & 1) {
				rep(j, W) {
					a_c[i][j] = -1;
				}
			}
		}
		rep(i, W) {
			if (S2 >> i & 1) {
				rep(j, H) {
					a_c[j][i] = -1;
				}
			}
		}

		int counter = 0;

		rep(i, H) rep(j, W) if (~a_c[i][j]) counter += a_c[i][j];

		if (counter == K) ans++;
	}

	cout << ans << endl;
}

