using namespace std;

int Count(const vector<string>& grid, const bitset<6>& rows, const bitset<6>& cols) {
  int result = 0;
  for (size_t h = 0; h < grid.size(); ++h) {
    if (rows.test(h)) {
      continue;
    }
    for (size_t w = 0; w < grid[0].size(); ++w) {
      if (!cols.test(w) && grid[h][w] == '#') {
        ++result;
      }
    }
  }
  return result;
}

int main() {
  int H, W, K;
  cin >> H >> W >> K;
  vector<string> grid(H);
  for (int h = 0; h < H; ++h) {
    cin >> grid[h];
  }
  int result = 0;
  for (int h = 0, end_h = 2 << H-1; h < end_h; ++h) {
    bitset<6> rows(h);
    for (int w = 0, end_w = 2 << W-1; w < end_w; ++w) {
      bitset<6> cols(w);
      if (Count(grid, rows, cols) == K) {
        ++result;
      }
    }
  }
  cout << result << endl;

  return 0;
}

