void calc_primefactorization(long long in, vector<vector<long long> >& out){

	long long N = in, Ntmp;
	long long p,e,p_init = 2;
	vector<long long> out_tmp(2);

	if( in == 1 ){
		out_tmp[0] = 1;
		out_tmp[1] = 1;
	}
	else{
		while( 1 ){

			Ntmp = N;

			p = N;
			e = 1;

			for(long long i = p_init;i * i <= N;i++){

				if( Ntmp % i == 0 ){
					e = 0;
					while( 1 ){
						if( Ntmp % i != 0 ){
							break;
						}
						else{
							Ntmp = Ntmp / i;
							e++;
						}
					}
					p = i;
					break;
				}

			}

			out_tmp[0] = p;
			out_tmp[1] = e;
			out.push_back(out_tmp);

			for(int i = 0;i < e;i++){
				N = N / p;
			}

			if( N == 1 ){
				break;
			}

		}
	}

}

