      }
    }
    for (size_t col = 0; col < W; col++) {
      if (get_col(col, H, W, state)) {
        for (size_t i = 0; i < H; i++) {
          board_tmp[i][col] = false;
        }
      }
    }

    if (count_true(H, W, board_tmp) == K) {
      retv++;
    }
  }
  return retv;
}

