    cin>>h>>w>>k;
    int total=0;
    for(int i=0;i<h;++i)
        for(int j=0;j<w;++j)
        {
            cin>>grid[i][j];
            if (grid[i][j]=='#')
                total++;
        }

    int ans=0;
    // i from 0 to 2^(h+w)
    for(int i=0;i<(1LL<<(h+w));i++)
    {
        // used for avoiding overlapping
        set<pair<int,int>>st;

        // if binary repesents of i is '10001011.....(w+h) bits'
        // then we assume (w+h)th bit for row 1, (w+h-1) bit for row 2,.....
        // (w+1)th bit  for row h and wth bit for column 1,(w-1)th bit for col 2,
        // 1st bit for column w. 

        // (w+h)th bit-> (w+1)th bit for row 0 to row h-1
        // wth bit -> 1st bit for column 0 to w-1

        //  Now, when we right shift i by 0 then we get (h+w)th bit,similarl right shift i by 1 we get (h+w-1)bit
        //  simalarly when we right shift i by (h+w-1) we get 1st bit.



        // for row 
        // we get bit from (w+h)th -> (w+1)th 
        for(int j=0;j<h;j++)
        {
            if((i>>j)&1) // jth bits from right side
            {
                int row=j;
                for(int col=0;col<w;col++)
                    if(grid[row][col]=='#')
                        st.insert({row,col});
            }
        }

        // for column
        // we get bit from wth -> 1st
        for(int j=h;j<(h+w);j++)
        {
            if((i>>j)&1)
            {
                int col=j-h;
                for(int row=0;row<h;row++)
                    if(grid[row][col]=='#')
                        st.insert({row,col});
            }
        }

        int c1=total-st.size();

        if(c1==k)
            ans++;
    }

    cout<<ans;

}











