#include<bits/stdc++.h>
using namespace std;

vector<int> binaryExp(int n) {
    vector<int> v = {0};
    while (n > 0) {
        v.push_back(n%2);
        n /= 2;
    }
    return v;
}

int main()
{

#ifdef _d
    freopen("input.txt", "r", stdin);
#endif

    int h, w, k;
    cin >> h >> w >> k;
    vector<vector<char> > a(h+1, vector<char> (w+1));
    int white = 0;
    int black = 0;
    vector<int> rb(h+1, 0);
    vector<int> cb(w+1, 0);
    for (int i = 1; i <= h; ++i) {
        for (int j = 1; j <= w; ++j) {
            cin >> a[i][j];
            if (a[i][j] == '.') {
                ++white;
            } else if (a[i][j] == '#') {
                ++black;
                ++rb[i];
                ++cb[j];
            }
        }
    }
    int rmx = (int)pow(2, h)-1;
    int cmx = (int)pow(2, w)-1;
    int ans = 0;
    for (int i = 0; i <= rmx; ++i) {
        for (int j = 0; j <= cmx; ++j) {
            vector<int> p = binaryExp(i);
            vector<int> q = binaryExp(j);
            int m = p.size()-1;
            int n = q.size()-1;
            int candy = 0;
            for (int x = 1; x <= m; ++x) {
                if (p[x] == 1) {
                    candy += rb[x];
                }
            }
            for (int y = 1; y <= n; ++y) {
                if (q[y] == 1) {
                    candy += cb[y];
                }
            }
            for (int x = 1; x <= m; ++x) {
                for (int y = 1; y <= n; ++y) {
                    if (p[x] == 1 && q[y] == 1) {
                        if (a[x][y] == '#') {
                            --candy;
                        }
                    }
                }
            }
            if (black-candy == k) {
                // cerr << i << " " << j << "\n";
                ++ans;
            }
        }
    }
    cout << ans << "\n";

    return 0;
}

