#include <bits/stdc++.h>
using namespace std;

int H, W, K, ans = 0;
int rows[8], cols[8];
bool grid[8][8];

void dfs_cols(int col, int curr_black) {
	if (curr_black < K) return;

	if (col < W) {
		dfs_cols(col+1, curr_black);
		dfs_cols(col+1, curr_black - cols[col]);
	}
	else {
		ans += curr_black == K;
	}
}

void dfs_rows(int row, int curr_black) {
	// no point in searching this branch anymore
	if (curr_black < K) return;

	if (row < H) {
		// do nothing (dont fill the row)
		dfs_rows(row+1, curr_black);
		// fill the row and make sure we dont overcount the cols
		for (int c = 0; c < W; ++c)
			cols[c] -= grid[row][c];
		dfs_rows(row+1, curr_black - rows[row]);
		for (int c = 0; c < W; ++c)
			cols[c] += grid[row][c];
	}
	else {
		// consider cols now
		dfs_cols(0, curr_black);
	}
}

int main() {
	ios_base::sync_with_stdio(false);
	cin >> H >> W >> K;

	int total_black = 0;
	for (int r = 0; r < H; ++r) {
		for (int c = 0; c < W; ++c) {
			char square; cin >> square;
			grid[r][c] = square == '#';
			rows[r] += square == '#';
			cols[c] += square == '#';
			total_black += square == '#';
		}
	}

	dfs_rows(0, total_black);
	cout << ans << endl;
}

