ll a[10][10],b[10]={0},c[10]={0},d[10];
ll m,n,k,cnt=0;
void solve3(ll i,ll ss){
	if(i==n){
		if(ss==k)
			cnt++;
		return;
	}
	if(ss-c[i]>=k){
		solve3(i+1,ss-c[i]);
		solve3(i+1,ss);
	}
	else
		solve3(i+1,ss);
}
void solve2(ll k,ll sss){
	ll i,j,z,s;
	if(k!=0)
		for(i=0;i<n;i++){
			s=0;
			for(j=0,z=0;j<m;j++){
				if(z<k&&j==d[z]){
					z++;
					continue;
				}
				if(a[j][i]=='#')
					s++;
			}
			c[i]=s;
		}
	else
		for(i=0;i<n;i++){
			s=0;
			for(j=0;j<m;j++){
				if(a[j][i]=='#')
					s++;
			}
			c[i]=s;
		}
	solve3(0,sss);
//	for(i=0;i<k;i++)
//		cout<<d[i]<<" ";
//	cout<<endl;
//	for(i=0;i<n;i++)
//		cout<<c[i]<<" ";
//	cout<<endl<<endl;
	return;
}
void solve(ll i,ll j,ll ss){
	if(i==m){
		solve2(j,ss);
		return;
	}
	if(ss-b[i]>=k){
		d[j]=i;
		solve(i+1,j+1,ss-b[i]);
		solve(i+1,j,ss);
	}
	else
		solve(i+1,j,ss);
}

int main(){
	scanf("%lld%lld%lld",&m,&n,&k);
	ll i,j,s=0;
	for(i=0;i<m;i++){
		getchar();
		for(j=0;j<n;j++){
			scanf("%c",&a[i][j]);
			if(a[i][j]=='#'){
				s++;
				b[i]++;
			}
		}
	}
	if(s<k)
		cout<<"0";
	else{
		solve(0,0,s);
		cout<<cnt<<endl;
	}
}

