using namespace std;
typedef long long int ll;
char field[6][6];

int main()
{
	int H,W,K;
	cin>>H>>W>>K;
	vector<int> row(H,0);
	vector<int> column(W,0);
	int blackNum = 0;
	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			cin>>field[i][j];
			if(field[i][j] == '#'){
				row[i]++;
				column[j]++;
				blackNum++;
			}
		}
	}

	ll ans = 0;
	for(ll bitR = 0; bitR <(1<<H); bitR++){
		int rowNum = 0;
		for(int i = 0; i < H; i++){
			if( (1<<i) & bitR){
				rowNum += row[i];
			}
		}
		for(ll bitC = 0; bitC < (1<<W); bitC++){
			int columnNum = 0;
			for(int j = 0; j < W; j++){
				if( (1<<j) & bitC){
					columnNum += column[j];
				}
			}
			ll sum = columnNum + rowNum;
			for(int i = 0; i < H; i++){
				if( (1<<i) & bitR){
					for(int j = 0; j < W; j++){
						if( (1<<j) & bitC && field[i][j] == '#') sum--;
					}
				}
			}
			if( (blackNum - sum) == K) ans++;
		}
	}
	cout<<ans<<endl;
	return 0;
}

