		for(int j = 0; j < m; j++) {
			bool painted_red = row[i] or col[j];
			if(!painted_red) {
				black += mat[i][j] == '#';
			}
		}
	}
	return black == k;
}

int brute_col(int c) {
	bool finished_painting_cols = c == m;
	if(finished_painting_cols) {
		if(check_board()) {
			return 1;
		}
		return 0;
	}
	int ans = 0;
	{ // try to paint the col c
		col[c] = true;
		ans += brute_col(c + 1);
	}
	{ // try to not paint the col c
		col[c] = false;
		ans += brute_col(c + 1);
	}
	return ans;
}

int brute_row(int r) {
	bool finished_painting_rows = r == n;
	if(finished_painting_rows) return brute_col(0);
	int ans = 0;
	{ // try to paint the row r
		row[r] = true;
		ans += brute_row(r + 1);
	}
	{ // try to not paint the row r
		row[r] = false;
		ans += brute_row(r + 1);
	}
	return ans;
}

