void convert(int x, int *bt, int size)
{
    for (int i = 0; i < size; i++)
        bt[i] = 0;
    int k = 0;
    while (x != 0)
    {
        if (x % 2 == 1)
        {
            bt[k] = 1;
        }
        x /= 2;
        k++;
    }
}
int pow(int i, int j){
    int prod = 1;
    while(j--) prod *= i;
    return prod;
}
void solve()
{
    int h, w, k;
    cin >> h >> w >> k;
    char arr[h][w];
    for (int i = 0; i < h; i++)
    {
        for (int j = 0; j < w; j++)
        {
            cin >> arr[i][j];
        }
    }
    int count = 0;
    int x = h + w;
    int target = (int)pow(2, x) - 1;
    for (int i = 0; i <= target; i++)
    {
        int *bt = new int[x];
        convert(i, bt, x);
        char temp[h][w];
        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
            {
                temp[i][j] = arr[i][j];
            }
        }
        for (int j = 0; j < h; j++)
        {
            if (bt[j] == 1)
            {
                for (int m = 0; m < w; m++)
                    temp[j][m] = '.';
            }
        }
        for (int j = h; j < x; j++)
        {
            if (bt[j] == 1)
            {
                for (int m = 0; m < h; m++)
                    temp[m][j - h] = '.';
            }
        }
        int ans = 0;
        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
            {
                if (temp[i][j] == '#')
                    ans++;
            }
        }
        if (ans == k)
            count++;
    }
    cout << count;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    solve();

    return 0;
}

