int gcnt(int h, int w, Vi A, Vs G)
{
	for (int u : A) {
		if (u < h) {
			rep(i, w) G[u][i] = '.';
		}
		else {
			rep(i, h) G[i][u - h] = '.';
		}
	}

	int t = 0;
	rep(i, h) {
		rep(j, w) {
			if (G[i][j] == '#') t++;
		}
	}
	return t;
}


