signed main()
{
	int N, K;
	cin >> N >> K;
	vector<ll> A(N);
	int minnum=0;
	vector<ll> minA;
	int plnum=0;
	vector<ll> plA;
	REP(i, N){
		ll a;
		cin >> a;
		A[i] = a;
		if(a<0){
			minnum++;
			minA.PB(a);
		}else if(a>0){
			plnum++;
			plA.PB(a);
		}
	}
	sort(ALL(minA));
	sort(ALL(plA), greater<ll>());
	ll ans = 1;
	if((plnum+minnum<K) or (plnum==0 and K%2==1 and N>minnum)){
		cout << 0 << endl;
		return 0;
	}
	if(plnum+minnum == K){
		if(minnum%2==1 and N>plnum+minnum){
			cout << 0 << endl;
			return 0;
		}
		REP(i, plnum){
			ans = (ans * plA[i])%MOD;
		}
		REP(i, minnum){
			ans = (ans * ((minA[i]+MOD)%MOD))%MOD;
		}
		cout << ans << endl;
		return 0;
	}
	if(N==K){
		REP(i, N){
			ans = (ans * ((A[i] + MOD)%MOD))%MOD;
		}
		cout << ans << endl;
		return 0;
	}
	if(plnum==0 and K%2==1){
		for(int i=0; i<K; i++){
			ans = (ans*((minA[minA.size()-1-i]+MOD)%MOD))%MOD;
		}
		cout << ans << endl;
		return 0;
	}
	if(plnum==0 and K%2 == 0){
		for(int i=0; i<K; i++){
			ans = (ans * (minA[i] + MOD)%MOD) % MOD;
		}
		cout << ans << endl;
		return 0;
	}
	if(minnum==0){
		for(int i=0; i<K; i++){
			ans = (ans * plA[i]) % MOD;
		}
		cout << ans << endl;
		return 0;
	}
	int mind=0;
	int pind=0;
	int now=0;
	REP(i, K){
		if(pind<plnum and plA[pind]>=-minA[mind]){
			pind++;
			now=1;
		}else{
			mind++;
			now=-1;
		}
	}
	if(mind %2 == 1){
		if(mind == minnum){
			mind--;
			pind++;
		}else if(pind == plnum){
			mind++;
			pind--;
		}else{
			if(now == -1){
				mind--;
				pind++;
			}else{
				pind--;
				mind++;
			}
		}
	}
	REP(i, mind){
		ans = (ans*((minA[i]+MOD)%MOD))%MOD;
	}
	REP(i, pind){
		ans = (ans*plA[i])%MOD;
	}
	cout << ans << endl;
}

