      vector<vector<char>> tmp_c = c;
      if (i == 0) { // 0なら赤く塗るとする
        if (now_count < h) { // 行で塗る
          for (int k = 0;k < w;k++) {
            if (tmp_c[now_count][k] == '#') tmp_black_count--;
            tmp_c[now_count][k] = '?'; // ?が赤とする
          }
        } 
        else { // 列で塗る
          for (int k = 0;k < h;k++) {
            if (tmp_c[k][now_count - h] == '#') tmp_black_count--;
            tmp_c[k][now_count - h] = '?'; 
          }
        }
      }

      bitDfs (tmp_c, now_count + 1, tmp_black_count);
    }
  }
}

