inline int read()
{
	int x = 0, f = 1; char ch = getchar();
	for (; ch < '0' || ch > '9'; ch = getchar()) if (ch == '-') f = -1;
	for (; ch >= '0' && ch <= '9'; ch = getchar()) x = (x << 1) + (x << 3) + ch - '0';
	return x * f;
}

const int N = 10;
char s[N][N];

int main()
{
	int n = read(), m = read(), k = read();
	int ans = 0;

	for (int i = 1; i <= n; ++i) scanf("%s", s[i] + 1);
	for (int i = 0; i < (1 << n); ++i)
		for (int j = 0; j < (1 << m); ++j)
		{
			int cnt = 0;
			for (int k = 1; k <= n; ++k)
				for (int l = 1; l <= m; ++l)
					if (s[k][l] == '#' && !((1 << (k - 1)) & i) && !((1 << (l - 1)) & j))
						++cnt;
			ans += (cnt == k);
		}
	printf("%d\n", ans);

	return 0;
}

