        H = readInt(), W = readInt(), K = readInt();

        for (int i = 0; i < H; ++i) {
            s.push_back(readString());
        }
    }

    void colorRow(int i) {
        for (int j = 0; j < W; ++j)
            c[i][j] = '.';
    }

    void colorCol(int j) {
        for (int i = 0; i < H; ++i)
            c[i][j] = '.';
    }

    void color(int rmask, int cmask) {
        c = s;

        for (int i = 0; i < H; ++i)
            if (rmask & (1 << i))
                colorRow(i);

        for (int j = 0; j < W; ++j)
            if (cmask & (1 << j))
                colorCol(j);

        int p = 0;

        for (int i = 0; i < H; ++i)
            for (int j = 0; j < W; ++j)
                if (c[i][j] == '#')
                    ++p;

        if (p == K)
            ++answer;
    }

    void solve() {
        answer = 0;

        for (int i = 0; i < (1 << H); ++i) {
            for (int j = 0; j < (1 << W); ++j) {
                color(i, j);
            }
        }

        cout << answer << endl;
    }

    void perform() {
        readInput();
        solve();
    }
};

