int dfs(vector<string> c, int a, int h, int w, int k) {
  if (a == h+w) {
    int s = 0;
    rep(i,h) {
      rep(j,w) {
        if (c[i][j] == '#') s++;
      }
    }
    if (s == k) return 1;
    else return 0;
  }


  vector<string> d(h);
  rep(i,h) {
    d[i] = c[i];
  }

  if (a < h) {
    rep(j,w) {
      c[a][j] = '.';
    }
    return dfs(c,a+1,h,w,k) + dfs(d,a+1,h,w,k);
  }

  else {
    rep(i,h) {
      c[i][a-h] = '.';
    }
    return dfs(c,a+1,h,w,k) + dfs(d,a+1,h,w,k);
  }

}

