const int maxn = 10;
int n, m, k;
int a[maxn][maxn], mp[maxn][maxn];
int ans, tot;
int vis1[maxn], vis2[maxn];

void dfs2(int layer) {
	if (layer == m + 1) {
		for (int i = 1; i <= n; i++) for (int j = 1; j <= m; j++) mp[i][j] = a[i][j];
		int tmp = tot;
		for (int i = 1; i <= n; i++) {
			if (vis1[i]) {
				for (int j = 1; j <= m; j++) {
					if (mp[i][j] > 0) {
						mp[i][j] = 0;
						tmp--;
					}
				}
			}
		}
		for (int j = 1; j <= m; j++) {
			if (vis2[j]) {
				for (int i = 1; i <= n; i++) {
					if (mp[i][j] > 0) {
						mp[i][j] = 0;
						tmp--;
					}
				}
			}
		}
		if (tmp == k) ans++;
		return ;
	}
	vis2[layer] = 1;
	dfs2(layer + 1);
	vis2[layer] = 0;
	dfs2(layer + 1);
}

void dfs1(int layer) {
	if (layer == n + 1) {
		dfs2(1);
		return ;
	}
	vis1[layer] = 1;
	dfs1(layer + 1);
	vis1[layer] = 0;
	dfs1(layer + 1);
}

