ll positive(vector<ll> p, vector<ll> n, ll k) {
    sort(all(p), [](ll a, ll b) {return abs(a) >= abs(b); });
    sort(all(n), [](ll a, ll b) {return abs(a) >= abs(b); });
    vector<pair<ll, ll>> a;
    for (ll b : p)
        a.push_back({ b, 1 });

    rep(i, n.size() / 2)
        a.push_back({ n[2 * i] * n[2 * i + 1] % MM, 2 });

    sort(rall(a));
    ll ans = 1;
    rep (i, a.size()) {
        if (a[i].second <= k) {
            ans *= a[i].first;
            ans %= MM;
            k -= a[i].second;
        }
        if (k == 0)
            break;
    }
    if (k == 0) {
        return ans;
    } else {
        return -MM;
    }
}

ll negative(vector<ll> p, vector<ll> n, ll k) {
    if (n.empty())
        return -MM;

    --k;
    sort(all(p), [](ll a, ll b) {return abs(a) <= abs(b); });
    sort(all(n), [](ll a, ll b) {return abs(a) <= abs(b); });

    vector<pair<ll, ll>> a;
    for (ll b : p)
        a.push_back({ b, 1 });

    ll ans = n[0];
    n.erase(n.begin());
    rep(i, n.size() / 2)
        a.push_back({ n[2 * i] * n[2 * i + 1] % MM, 2 });

    sort(all(a));
    rep (i, a.size()) {
        if (a[i].second <= k) {
            ans *= a[i].first;
            ans %= MM;
            k -= a[i].second;
        }
        if (k == 0)
            break;
    }
    if (k == 0) {
        return -ans;
    } else {
        return -MM;
    }
}

