	for (int i = 0; i < n; i++)
	{
		char input[10];
		string str;

		scanf("%s", input);
		str = input;

		grid.push_back(str);
	}

	int rmask = (int)pow(2.0, n);
	int cmask = (int)pow(2.0, m);
	int cell[6][6];

	int sol = 0;

	for (int i = 0; i < rmask; i++)
	{
		vector<int> rows;

		int temp = i;

		for (int z = 0; z < n; z++)
		{
			rows.push_back(temp % 2);

			temp /= 2;
		}

		for (int j = 0; j < cmask; j++)
		{
			memset(cell, 0, sizeof(cell));

			vector<int> cols;

			int temp = j;

			for (int z = 0; z < m; z++)
			{
				cols.push_back(temp % 2);

				temp /= 2;
			}

			for (int z = 0; z < n; z++)
			{
				if (rows[z])
				{
					for (int y = 0; y < m; y++)
					{
						cell[z][y] = 1;
					}
				}
			}

			for (int z = 0; z < m; z++)
			{
				if (cols[z])
				{
					for (int y = 0; y < n; y++)
					{
						cell[y][z] = 1;
					}
				}
			}

			int cnt = 0;

			for (int z = 0; z < n; z++)
			{
				for (int y = 0; y < m; y++)
				{
					if (grid[z][y] == '#' && !cell[z][y])
					{
						cnt++;
					}
				}
			}

			if (cnt == k)
			{
				sol++;
			}
		}
	}

	printf("%d\n", sol);

	return 0;
}

