struct MyMain {
	int H = in;
	int W = in;
	int K = in;

	void Run() {
		arr2<int> C(W, H);
		REP(y, H) {
			REP(x, W) {
				char c = in;
				if (c == '#') {
					C(x, y) = 1;
				}
			}
		}

		int ans = 0;
		REP(selectH, 1<<H) {
			REP(selectW, 1<<W) {
				arr2<int> T = C;

				REP(y, H) {
					if ((selectH >> y) & 1) {
						REP(x, W) {
							T(x, y) = 0;
						}
					}
				}

				REP(x, W) {
					if ((selectW >> x) & 1) {
						REP(y, H) {
							T(x, y) = 0;
						}
					}
				}

				int cnt = 0;
				REP(y, H) {
					REP(x, W) {
						if (T(x, y)) {
							cnt++;
						}
					}
				}

				if (cnt == K) {
					ans++;
				}
			}
		}

		out << ans;
	}
};

