}

class GridColor{
public:
  int getNumSel(int h, int w, int k, vector<string>&grid){
    int nSel = 0;
    int nPerms = 1<<(h+w);
    for(int i=0;i<nPerms;i++){
      if(checkSel(h,w,k,grid,i)){
	nSel++;
      }
    }
    return nSel;
  }

  bool checkSel(int h, int w, int k, vector<string>&grid, int pNum){
    unordered_map<int,bool>rUsed;
    unordered_map<int,bool>cUsed;
    rUsed.clear();
    cUsed.clear();
    for(int i=0;i<h;i++){
      if((pNum%2)==1){
	rUsed[i] = true;
      }
      pNum/=2;
    }
    for(int i=0;i<w;i++){
      if((pNum%2)==1){
	cUsed[i] = true;
      }
      pNum/=2;
    }
    int nBlack = 0;
    for(int i=0;i<h;i++){
      for(int j=0;j<w;j++){
	if((grid[i][j]=='#')&&(rUsed.find(i)==rUsed.end())&&(cUsed.find(j)==cUsed.end())){
	  nBlack++;
	}
      }
    }
    return (nBlack==k);
  }
};

