int H, W, K;

int calc_K(vector<vector<int>> vec, vector<int> HL){
    int K = 0;
    for ( int i = 0; i < H; i++){
        if (HL[i] == 1) continue;
        for ( int j = 0; j < W; j++){
          if (HL[j+H] == 1) continue;     
          if (vec[i][j] == BLACK) K += 1;
        }
    }   
    return K;
}

int rec(vector<vector<int>> vec, vector<int> HL, int decision_H){
    int number_of_choice;
    number_of_choice = 0;
    int next_decision_H = decision_H;
    if (decision_H == H + W){
        if (calc_K(vec, HL) == K) return 1;
        else return 0;
    }
    next_decision_H += 1;
    vector<int> HL1 = HL; 
    vector<int> HL2 = HL;
    HL1[decision_H] = 0;
    HL2[decision_H] = 1;
    number_of_choice += rec(vec, HL1, next_decision_H);
    number_of_choice += rec(vec, HL2, next_decision_H);
    return number_of_choice;
}

