char mz[10][10], tmp[7][7];
bool vis[2][10];
void dfs(int r, int c) {
	if (r == n + 1 && c == m + 1) {
		for (int i = 1; i <= n; i++)for (int j = 1; j <= m; j++)tmp[i][j] = mz[i][j];
		for (int i = 1; i <= n; i++) {
			if (vis[0][i]) {
				for (int j = 1; j <= m; j++)tmp[i][j] = '.';
			}
		}
		for (int j = 1; j <= m; j++) {
			if (vis[1][j]) {
				for (int i = 1; i <= n; i++)tmp[i][j] = '.';
			}
		}
		int ct = 0;
		for (int i = 1; i <= n; i++)for (int j = 1; j <= m; j++)if (tmp[i][j] == '#')ct++;
		if (ct == k)ans++;
		return;
	}
	if (r == n + 1) {
		vis[1][c] = 1;
		dfs(r, c + 1);
		vis[1][c] = 0;
		dfs(r, c + 1);
	}
	else {
		vis[0][r] = 1;
		dfs(r + 1, c);
		vis[0][r] = 0;
		dfs(r + 1, c);
	}
}
int main() {
	scanf("%d%d%d", &n, &m, &k);
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {
			scanf(" %c", &mz[i][j]);
			if (mz[i][j] == '#')cnt++;
		}
	}
	dfs(1, 1);
	printf("%d\n", ans);
	return 0;
}

