    go(h, 1, 0, height_value_container_1);
    go(h, 1, 1, height_value_container_2);
    auto combination_height = combination;

    combination = {};
    go(w, 1, 0, width_value_container_1);
    go(w, 1, 1, width_value_container_2);
    auto combination_width = combination;

