	if(bl < k){
		cout << "0";
		return;
	}

	int r=0;
	int upR = pow(2, h);
	while(r < upR){
		vb row;
		for(int i=0 ; i<h ; ++i){
			row.pb(r&(1<<i));
		}
		int c=0;
