{
    ll cnt=0;
    map<pll,ll> vis;
    for(ll k=0;k<sz(row);k++){
        ll r=row[k];
        if(r==0)continue;
        for(ll j=1;j<=w;j++){
            if(a[r][j] == '#' && !vis[{r,j}])
                cnt++;
            vis[{r,j}]=1;
        }
    }
    for(ll k =0 ;k<sz(col);k++){
        ll c=col[k];
        if(c==0)continue;
        for(ll i=1;i<=h;i++){
            if(a[i][c] == '#' && !vis[{i,c}])
                cnt++;
            vis[{i,c}]=1;
        }
    }
    if((tot-cnt) == k)return true;
    else return false;
}
