int main() {
  int H, W, K;  //行, 列, 残る黒いマス
  cin >> H >> W >> K;
  int c[H][W];  //マスの情報, 0:白, 1:黒
  string S[H];  //入力データ

  int black = 0;  //黒いマスの数

  //入力
  for (int i = 0; i <= H - 1; i++) {
    cin >> S[i];
    for (int j = 0; j <= W - 1; j++) {
      if (S[i][j] == '.') {  //白
        c[i][j] = 0;
      } else {  //黒
        c[i][j] = 1;
        black++;
      }
    }
  }

  int ans = 0;
  int c_original[H][W];

  for (int i = 0; i <= H - 1; i++) {
    for (int j = 0; j <= W - 1; j++) {
      c_original[i][j] = c[i][j];
    }
  }

  for (int i = 0; i <= pow(2, H) - 1; i++) {    // 2のH乗通り
    for (int j = 0; j <= pow(2, W) - 1; j++) {  // 2のW乗通り

      /*行*/
      for (int t = 0; t <= H - 1; t++) {  //ずらすビット
        if (((i >> t) & 1) == 1) {  //二進数表示したときにbitが1なら塗りつぶす
          for (int k = 0; k <= W - 1; k++) {
            c[t][k] = 0;  // x行目の塗りつぶし
          }
        }
      }

      /*列*/
      for (int s = 0; s <= W - 1; s++) {
        if (((j >> s) & 1) == 1) {
          for (int k = 0; k <= H - 1; k++) {
            c[k][s] = 0;
          }
        }
      }

      //計測
      int black_cnt = 0;
      for (int l = 0; l <= H - 1; l++) {
        for (int ll = 0; ll <= W - 1; ll++) {
          if (c[l][ll] == 1) {
            black_cnt++;
          }
        }
      }
      if (black_cnt == K) {
        ans++;
      }

      //初期化
      for (int l = 0; l <= H - 1; l++) {
        for (int ll = 0; ll <= W - 1; ll++) {
          c[l][ll] = c_original[l][ll];
        }
      }
    }
  }

  cout << ans << endl;
  return 0;
}

