void fun1(vector<int> v, vector<int> f, int ind)
{
	if(f.size() == ind)
	{
		cal(v,f);
		return;
	}
	f[ind] = 1;
	fun1(v,f,ind+1);
	f[ind] = 0;
	fun1(v,f,ind+1);
}
void fun(vector<int> v,int ind)
