LL fp(LL a, LL n, LL mod = MOD)
{
    if(n < 0) a = fp(a, mod - 2, mod), n = -n;
    LL res = 1;
    for(; n; n >>= 1, a = a * a % mod)
        if(n & 1)
            res = res * a % mod;
    return res;
}

struct Mint
{
    int x;
    Mint():x(0) {}
    Mint(int _x): x(_x)
    {
        if(x < 0 || x >= MOD) x %= MOD;
        if(x < 0) x += MOD;
    }
    Mint(LL _x)
    {
        if(_x < 0 || _x >= MOD) _x %= MOD;
        if(_x < 0) _x += MOD;
        x = _x;
    }
    Mint operator - () const {return Mint(MOD - x);}
    Mint operator + (const Mint &rhs) const {return Mint(x + rhs.x >= MOD ? x + rhs.x - MOD : x + rhs.x);}
    Mint operator - (const Mint &rhs) const {return Mint(x - rhs.x < 0 ? x - rhs.x + MOD : x - rhs.x);}
    Mint operator * (const Mint &rhs) const {return Mint((LL)x * rhs.x % MOD);}
    Mint operator / (const Mint &rhs) const {return Mint((LL)x * fp(rhs.x, -1) % MOD);}
    bool operator == (const Mint &rhs) const {return x == rhs.x;}
    bool operator != (const Mint &rhs) const {return x != rhs.x;}
    Mint& operator += (const Mint &rhs) {x += rhs.x; if(x >= MOD) x -= MOD; return *this;}
    Mint& operator -= (const Mint &rhs) {x -= rhs.x; if(x < 0) x += MOD; return *this;}
    Mint& operator *= (const Mint &rhs) {x = (LL)x * rhs.x % MOD; return *this;}
    Mint& operator /= (const Mint &rhs) {x = (LL)x * fp(rhs.x, -1) % MOD; return *this;}
    friend ostream& operator << (ostream &out, Mint &rhs) {return out << to_string(rhs.x);}
    Mint inv() {return Mint(fp(x, -1));}
    Mint pow(int k) {return Mint(fp(x, k));}
    Mint pow(const Mint &t) {return Mint(fp(x, t.x));}
};


