    for(int i=0; i<(1<<6); i++){
        bitset<6> row(i);
        for(int j=0; j<(1<<6); j++){
            bitset<6> col(j);

            int cnt=0;
            vector<vector<int>> used(H,vector<int>(W,0));
            for(int m=0; m<H; m++){
                if( row.test(m) ){
                    cnt += hcnt.at(m);
                    for(int l=0; l<W; l++){
                        used.at(m).at(l) = 1;
                    }
                }
            }
            for(int m=0; m<W; m++){
                if( col.test(m) ){
                    cnt += wcnt.at(m);
                    for(int l=0; l<H; l++){
                        if( used.at(l).at(m)==1 ){ 
                            if( c.at(l).at(m) == '#' ){
                                cnt--;
                            }
                        }
                    }
                }
            }
            if( K==total-cnt ) ans++;

            if( j == pow(2,W)-1 ) break; 
        }
        if( i == pow(2,H)-1 ) break; 
    }

	cout << ans << endl;
}

