const int N = 10;

int h, w, k, ans;
char C[N][N];
bool choose_row[N];
bool choose_col[N];

void dfs(int row, int col) {
	if (row <= h) {
		choose_row[row] = true;
		dfs(row + 1, col);
		choose_row[row] = false;
		dfs(row + 1, col);
	} else if (col <= w) {
		choose_col[col] = true;
		dfs(row, col + 1);
		choose_col[col] = false;
		dfs(row, col + 1);
	} else {
		char MP[N][N] = {};
		for (int i = 1; i <= h; i++)
			for (int j = 1; j <= w; j++)
				MP[i][j] = C[i][j];
		for (int i = 1; i <= h; i++)
			if (choose_row[i])
				for (int j = 1; j <= w; j++)
					MP[i][j] = '.';
		for (int i = 1; i <= w; i++)
			if (choose_col[i])
				for (int j = 1; j <= h; j++)
					MP[j][i] = '.';
		int cnt = 0;
		for (int i = 1; i <= h; i++)
			for (int j = 1; j <= w; j++)
				if (MP[i][j] == '#')
					++cnt;
		if (cnt == k) ++ans;
	}
}

