    ans[0][0] = 0;

    for (ll i = 1; i <= n; i++)
    {
        for (ll j = 0; j <= i; j++)
        {
            if (j == 0 || j == i)
            {
                ans[i][j] = 1;
                continue;
            }
            ans[i][j] = ans[i - 1][j] + ans[i - 1][j - 1];
        }
    }

    return ans;
}

