int g(vector<vc> &datao, vb &checkrow, vb &checkcol, int H, int W, int K, int n) {
    if (n == 0) {
        vector<vc> data = datao;
        for (int i = 0; i < H; i++) {
            if (!checkrow.at(i)) {
                continue;
            }
            for (int j = 0; j < W; j++) {
                if (data.at(i).at(j) == '#') {
                    data.at(i).at(j) = '.';
                }
            }
        }
        for (int j = 0; j < W; j++) {
            if (!checkcol.at(j)) {
                continue;
            }
            for (int i = 0; i < H; i++) {
                if (data.at(i).at(j) == '#') {
                    data.at(i).at(j) = '.';
                }
            }
        }
        int count = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (data.at(i).at(j) == '#') {
                    count++;
                }
            }
        }
        if (K == count) {
            return 1;
        }
        return 0;
    }
    checkcol.at(W - n) = true;
    int a = g(datao, checkrow, checkcol, H, W, K, n - 1);
    checkcol.at(W - n) = false;
    int b = g(datao, checkrow, checkcol, H, W, K, n - 1);
    int ans = a + b;
    return ans;
}

int f(vector<vc> &data, vb &checkrow, vb &checkcol, int H, int W, int K, int n) {
    if (n == 0) {
        int ans = g(data, checkrow, checkcol, H, W, K, W);
        return ans;
    }
    checkrow.at(H - n) = true;
    int a = f(data, checkrow, checkcol, H, W, K, n - 1);
    checkrow.at(H - n) = false;
    int b = f(data, checkrow, checkcol, H, W, K, n - 1);
    int ans = a + b;
    return ans;
}

int main() {
    int H, W, K;
    cin >> H >> W >> K;
