    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> data.at(i).at(j);
        }
    }
    vb checkrow(H, true);
    vb checkcol(W, true);
    int ans = f(data, checkrow, checkcol, H, W, K, H);
    cout << ans << endl;
}

