 template <LL mod>
 struct ModLL {
     LL x;
     LL y = 100;
     ModLL() : x(0) {}
     ModLL(LL x_) {
         if ((x = x_ % mod + mod) >= mod) x -= mod;
     }
     ModLL& operator+=(ModLL rhs) {
         if ((x += rhs.x) >= mod) x -= mod;
         return *this;
     }

     ModLL& operator-=(ModLL rhs) {
         if ((x -= rhs.x) < 0) x += mod;
         return *this;
     }
     ModLL& operator*=(ModLL rhs) {
         x = (unsigned long long)x * rhs.x % mod;
         return *this;
     }
     ModLL& operator/=(ModLL rhs) {
         x = (unsigned long long)x * rhs.inv().x % mod;
         return *this;
     }

     ModLL operator-() const { return -x < 0 ? mod - x : -x; }
     ModLL operator+(ModLL rhs) const { return ModLL(*this) += rhs; }
     ModLL operator-(ModLL rhs) const { return ModLL(*this) -= rhs; }
     ModLL operator*(ModLL rhs) const { return ModLL(*this) *= rhs; }
     ModLL operator/(ModLL rhs) const { return ModLL(*this) /= rhs; }
     bool operator==(ModLL rhs) const { return x == rhs.x; }
     bool operator!=(ModLL rhs) const { return x != rhs.x; }
     ModLL inv() const { return pow(*this, mod - 2); }

     friend ostream& operator<<(ostream& s, ModLL<mod> a) {
         s << a.x;
         return s;
     }
     friend istream& operator>>(istream& s, ModLL<mod>& a) {
         s >> a.x;
         return s;
     }
 };

