void secondThreadApproach(){
    int H,W,K;
    cin>>H>>W>>K;
    char** arr= new char*[H];
    for(int i=0;i<H;i++){
        arr[i]=new char[W];
    }

    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            cin>>arr[i][j];
        }
    }

    int range = (1<<(H+W))- 1;                //2^(H+W)-1
    int ans=0;                              //int as ans can be at max 2^(H+W) and H,W<=6

    for(int mask=0;mask<=range;mask++){
        int count=0;
        for(int i=0;i<H;i++){
            for(int j=0;j<W;j++){
                if(arr[i][j]!='#') continue;
                if ((mask&(1<<(H-i-1+W)|(1<<(W-j-1))))!=0) continue;              //For mask 10010 => R0,R1,C0,C1,C2. 1=>Painted, 0=>Not Painted
                //if((mask&((1<<W+i)|(1<<j)))!=0) continue;                      //For mask 10010 => R1,R0,C2,C1,C2. 1=>Painted, 0=>Not Painted
                count++;
            }
        }
        if(count==K)
            ans++;
    }

    cout<<ans<<endl;
}

//https://atcoder.jp/contests/abc173/tasks/abc173_c
void solve(){
    int H,W,K;
    cin>>H>>W>>K;
    char** arr= new char*[H];
    for(int i=0;i<H;i++){
        arr[i]=new char[W];
    }

    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            cin>>arr[i][j];
        }
    }

    int range = (1<<H+W)- 1;                //2^(H+W)-1
    ll ans=0;
    for(int i=0;i<=range;i++){
        int t=i,count=0;
        map<int,bool> row;
        map<int,bool>col;
        while(t>0){
            if(t&1==1){
                if(count<W) col[count]=true;
                else row[count-W]=true;
            }
            t=t>>1;
            count++;
        }

        ll temp=0;
        for(int p=0;p<H;p++){
            if(row[p]) continue;
            for(int q=0;q<W;q++){
                if(col[q]) continue;
                if(arr[p][q]=='#') temp++;
            }
        }
        if(temp==K) ans++;

    }

    cout<<ans<<endl;




}




