void add(int* a, int b) {
	for (int i = b - 1; i >= 0; i--) {
		if (a[i] == 0) {
			a[i] = 1;
			break;
		}
		else if (a[i] == 1) {
			a[i] = 0;
			continue;
		}
	}
}

