	cin >> h >> w >> k;
	// マス目
	rep(i,h){
		rep(j,w){
			char t;
			cin >> t;
			if(t == '#'){
				c[i][j] = 1;
			}
			else{
				c[i][j] = 0;
			}
		}
	}

	// bit全探索
