using namespace std;
int m,n,k,black=0,cha;
int s[10][10]={0},blackm[10]={0},blackn[10]={0};
bool used[10][10]={0};
bool valid(int x,int y,int cc)
{
    //debug(x)debug(y)
    for(int i=0;i<=m-1;i++)
    {
        if((1<<i) & x)//选中第i行
        {
            for(int l=1;l<=n;l++)
            {
                if(s[i+1][l]==1 && !used[i+1][l])
                {
                    used[i+1][l]=true;
                    cc--;
                }
            }
        }
    }
    for(int i=0;i<=n-1;i++)
    {
        if((1<<i) & y)//选中第i列
            for(int l=1;l<=m;l++)
            {
                //debug(i)
                if(s[l][i+1]==1 && !used[l][i+1])
                {
                    used[l][i+1]=true;
                    cc--;
                }
            }
    }

    //debug(cc)
    if(cc==0)
        return true;
    else
        return false;
}
int dalao()
{
    ios::sync_with_stdio(false);
    cin>>m>>n>>k;
    for(int i=1;i<=m;i++)
    {
        for(int j=1;j<=n;j++)
        {
            char c=getchar();
            if(c=='#')
            {
                s[i][j]=1;//1黑0白
                black++;
                blackm[i]++;//第m行的黑色个数
                blackn[j]++;//第n列的黑色个数
            }
            else
                s[i][j]=0;
        }
        getchar();//吃掉空格
    }

    cha=black-k;//要去掉的黑块个数

    if(cha==0)
    {
        cout<<1;
        return 0;
    }
    ll ans=0;

    for(int i=0;i<=(1<<m)-1;i++)
        for(int j=0;j<=(1<<n)-1;j++)
        {
            memset(used,0,sizeof(used));
            ans+=valid(i,j,cha);
        }

    cout<<ans;
    return 0;
}

