int main() {
  int h, w, k;
  cin >> h >> w >> k;
  int c[h][w];
  for (int i = 0; i < h; i++) {
    string s;
    cin >> s;
    for (int j = 0; j < w; j++) {
      if (s[j] == '.') {
        c[i][j] = 0;
      } else {
        c[i][j] = 1;
      }
    }
  }

  int ans = 0;
  // 選び方全探索 (2^6)^2通り
  for (int i = 0; i < (1 << h); i++) {
    for (int j = 0; j < (1 << w); j++) {
      // 選んだところは省いて数える
      int cnt = 0;
      for (int ii = 0; ii < h; ii++) {
        if (i & (1 << ii)) continue;
        for (int jj = 0; jj < w; jj++) {
          if (j & (1 << jj)) continue;
          cnt += c[ii][jj];
        }
      }
      if (cnt == k) ans++;
    }
  }

  cout << ans << endl;
  return 0;
}

