int R, C, K, toplamblack = 0;
vector<vector<char>> grid;
int say(int r, int c){
    set<pll> s;
    for(int i = 0; i < R; ++i){
        if( (1<<i)&r ) for(int j = 0; j < C; ++j) if(grid[i][j] == '#') s.insert(mp(i, j));
    }
    for(int i = 0; i < C; ++i){
        if( (1<<i)&c ) for(int j = 0; j < R; ++j) if(grid[j][i] == '#') s.insert(mp(j, i));
    }
    return (toplamblack - ((int)s.size()) == K);
}

int main(int argc, char **argv){
    ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);

    cin >> R >> C >> K;

    ll ans = 0;
    int r = (1<<R), c = (1<<C);
    grid.resize(R, vector<char>(C));
    for(int i = 0; i < R; ++i)
        for(int j = 0; j < C; ++j){
            cin >> grid[i][j];
            if(grid[i][j] == '#') toplamblack++;
        }

    for(int i = 0; i < r; ++i)
        for(int j = 0; j < c; ++j)
            ans += say(i, j);
    cout << ans << endl;

    return 0;
}

