int f(int h, int w, int H, int W, int K, vector<string> board) {
    REP(i, H) if (h >> i & 1) {
        REP(j, W) board[i][j] = '.';
    }
    REP(j, W) if (w >> j & 1) {
        REP(i, H) board[i][j] = '.';
    }
    int res = 0;
    REP(i, H) REP(j, W) res += board[i][j] == '#';
    return int(res == K);
}

