void solve()
{
    int h, w, k;
    cin >> h >> w >> k;
    int black = 0;
    vector<vector<char>>v(h, vector<char>(w));
    for (int i = 0; i < h; i++)
    {
        for (int j = 0;j < w; j++)
        {
            cin >> v[i][j];
            if (v[i][j] == '#')
                black++;
        }
    }
    int x = 1 << h;
    int y = 1 << w;
    int ans = 0;
    for (int i = 0; i < x; i++)
    {
        int p = i;
        vector<bool>hb(h, false);
        for(int hl=0;hl<h;hl++)
        {
            if (p & (1 << hl))
                hb[hl] = true;
        }
         for (int j = 0; j < y; j++)
         {
             int count = 0;
             int pj = j;
             vector<bool>wb(w, false);
             for (int wl = 0; wl < w; wl++)
             {
                 if (pj & (1 << wl))
                     wb[wl] = true;
             }
             for (int y = 0; y < h; y++)
             {
                 for (int z = 0; z < w; z++)
                 {
                     if (v[y][z] == '#' && (hb[y] == true || wb[z] == true))
                         count++;
                 }
             }
             if (black-count == k)
                 ans++;
         }

    }
    cout << ans << "\n";
}
