using namespace std;
int count_black(int h , int w, vector<vector<char>> hw , vector<bool> ignore_h , vector<bool> ignore_w){
    int ret_ans = 0;
    for(int i = 0 ;i < h ;i++){
        for(int j = 0;j < w ;j++){
            if (ignore_h[i]) continue;
            if (ignore_w[j]) continue;
            if (hw[i][j] == '#') ++ret_ans;
        }
    }
    return ret_ans;
}


int main(){
int h,w,k;
cin >> h >> w >>k;
vector<vector<char>> vec(h ,vector<char>(w));
for (int i = 0;i < h;i++){
    for (int j = 0;j < w;j++){
        cin >> vec.at(i).at(j);
    }
}
int ans = 0;

//(h+w)^2の回数計算するために、左ビットシフトを(h+w)回している、ビット全探索をしている
for(int i = 0; i < (1<<(h+w)); i++){
    vector<bool> ignore_h(h, false);
    vector<bool> ignore_w(w, false);
    for(int j = 0; j < (h + w) ; j++){
    //j個シフトしながら各ビットが1か0か判定
        if ((i>>j) & 1) {
            if (j < w) {
                ignore_w[j] = true;
            }
            else {
                ignore_h[j-w] = true;
            }
        }
    }


    if (count_black(h, w, vec, ignore_h, ignore_w) == k) {
        ++ans;
    }
}
cout << ans << endl;
}

