using namespace std;

class Solution {
 private:
  int c(int n) {
    if (n < 2) return 0;
    return n * (n - 1) / 2;
  }

 public:
  int hAndV(const vector<vector<char>>& squares, int k) {
    int n = squares.size(), m = squares[0].size();
    int w = n + m;

    int ans = 0;
    auto test_row = [&](int sel, int row) { return sel & (1 << row); };
    auto test_col = [&](int sel, int col) { return sel & (1 << (n + col)); };
    for (int sel = 0; sel < (1 << w); ++sel) {
      int count = 0;
      for (int row = 0; row < n; ++row) {
        if (!test_row(sel, row)) continue;
        for (int col = 0; col < m; ++col) {
          if (!test_col(sel, col)) continue;
          if (squares[row][col] == '#') ++count;
        }
      }
      if (count == k) ++ans;
    }
    return ans;
  }
};

int main() {
  int h, w, k;
  cin >> h >> w >> k;

  vector<vector<char>> squares(h, vector<char>(w));
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) cin >> squares[i][j];
  }

  Solution sol;
  const int ans = sol.hAndV(squares, k);
  cout << ans << endl;
  return 0;
}

