int main()
{
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  int h,w,k;
  std::cin>>h>>w>>k;

  std::vector<std::vector<char>> g(h,std::vector<char>(w,0));
  std::vector<int> HValue(h,0);
  std::vector<int> WValue(w,0);
  for(int i=0;i!=h;i++)
  {
    for(int j=0;j!=w;j++)
    {
      std::cin>>g[i][j];

      if(g[i][j]=='#')
      {
        HValue[i]++;
        WValue[j]++;
      }
    }
  }

  int result=0;
  for(int bit=0;bit!=(1<<h);bit++)
  {
    std::vector<int> hvalue=HValue;
    std::vector<int> wvalue=WValue;

    int sum=0;
    for(int i=0;i!=h;i++)
    {
      if(bit&(1<<i))
      {
        for(int j=0;j!=w;j++)
        {
          if(g[i][j]=='#')
          {
            hvalue[i]=0;
            wvalue[j]--;
          }
        }
      }
      sum+=hvalue[i];
    }

    int over=sum-k;

    if(over<0)
      continue;

    auto &a=wvalue;
    int A=over;
    int N=a.size();

    for (int bit=0;bit!=(1<<N);bit++)
    {
      int sum=0;
      for (int i=0;i!=N;i++)
      {
        if (bit&(1<<i))
        {
          sum+=a[i];
        }
      }

      if (sum==A)
      {
        result++;
      }
    }
  }

  std::cout<<result<<std::endl;

  return 0;
}

