const int MOD = 1e9+7;
const int MAXN = 2e6+3;
const int INF = 1e9;

void solve() {
    int h,w,k; cin >> h >> w >> k;
    vector<string> s(h);
    fori(i,w) cin >> s[i];

    auto f = [&](int mh, int mw) {
        vector<string> q(h);
        fori(x,h) q[x] = s[x];
        fori(i,h) if((mh>>i) & 1) {
            fori(j,w) q[i][j] = '.';
        }
        fori(j,w) if((mw>>j) & 1) {
            fori(i,h) q[i][j] = '.';
        }
        int cnt = 0;
        fori(i,h) fori(j,w) cnt += q[i][j] == '#';
        return cnt;
    };

    int ans = 0;
    for(int mh = 0; mh < (1<<h); mh++) {
        for(int mw = 0; mw < (1<<w); mw++) { 
            if(f(mh,mw) == k) ans++;
        }
    }
    cout << ans << '\n';
} 

