int main(){
  ll  H,W,K;
  cin >>H >> W >>K;
  rep(i,H){
    rep(j,W){
      char X;
      cin >> X;
      if(X=='.'){
        C[i][j]=0;
      }
      else{
        C[i][j]=1;
      }
    }
  }
  rep (i,1<<H) {  // 0~2^N-1 までのbit 全探索
    rep(k,H){
      if(1<<k & i){
        rep(j,W){
          R[k][j]=1;
        }
      }
      else{
        rep(j,W){
          R[k][j]=0;
        }
      }
    }
    rep (j,1<<W) {  // 0~2^N-1 までのbit 全探索
      ll SUM=0;
      rep(k,W){
        if(1<<k & j){
          rep(t,H){
            if(R[t][k]==0 && C[t][k]==1){
              SUM++;
            }
          }
        }
      }
      if(SUM==K){
        ANS++;
      }
    }
  }
  cout << ANS <<  endl;
}

