void solve() {
  int n, m, k; cin >> n >> m >> k;
  int black = 0;
  char g[n][m];
  for(int i = 0; i < n; i++) {
    for(int j = 0; j < m; j++) {
      cin >> g[i][j];
      if(g[i][j] == '#') black++;
    }
  }
  int ans = 0;
  for(int i = 0; i < (1 << n); i++) {
    for(int j = 0; j < (1 << m); j++) {
      bool used[n][m];
      memset(used, 0, sizeof used);
      int have = black;
      for(int k = 0; k < n; k++) {
        if(((i >> k) & 1) == 0) continue;
        for(int u = 0; u < m; u++) {
          if(used[k][u] == 1) continue;
          if(g[k][u] == '#') {
            used[k][u] = 1;
            have--;
          }
        }
      }
      for(int k = 0; k < m; k++) {
        if(((j >> k) & 1) == 0) continue;
        for(int u = 0; u < n; u++) {
          if(used[u][k] == 1) continue;
          if(g[u][k] == '#') {
            used[u][k] = 1;
            have--;
          }
        }
      }
      if(have == k) ans++;
    }
  }
  print(ans);
}

