vll decToBinary(int n)
{
    vll binaryNum(6);

    // counter for binary array 
    int i = 0;
    while (n > 0) { 

        // storing remainder in binary array 
        binaryNum[i] = n % 2; 
        n = n / 2; 
        i++; 
    } 
    return binaryNum;
}

