long solve(auto &a, long h, long w, long k, long i, bool row)
{
    if (not row and i == w) {
        long count = 0;
        for (long i = 0; i < h; i++) {
            for (long j = 0; j < w; j++) {
                if (a[i][j] == '#') count++;
            }
        }
        return count == k;
    }
    long total = 0;
    auto b = a;
    if (row) {
        long next = (i + 1) % h;
        bool r = true;
        if (next == 0) r = false;
        total += solve(a, h, w, k, next, r);
        for (long j = 0; j < w; j++) {
            b[i][j] = '@';
        }
        total += solve(b, h, w, k, next, r);
    } else {
        long next = i + 1;
        total += solve(a, h, w, k, next, false);
        for (long j = 0; j < h; j++) {
            b[j][i] = '@';
        }
        total += solve(b, h, w, k, next, false);
    }
    return total;
}

