int intp(int a, int b)
{
    int ans = 1;
    for (auto count = 0; count < b; ++count)
    {
        ans *= a;
    }

    return ans;
}

int FillRow(std::vector<std::vector<bool>> &dest, int row)
{
    int ans = 0;
    for (int i = 0; i < dest[row].size(); ++i)
    {
        if (dest[row][i])
        {
            dest[row][i] = false;
            ++ans;
        }
    }
    return ans;
}

int FillColumn(std::vector<std::vector<bool>>& dest, int column)
{
    int ans = 0;
    for (int i = 0; i < dest.size(); ++i)
    {
        if (dest[i][column])
        {
            dest[i][column] = false;
            ++ans;
        }
    }
    return ans;
}

int main()
{
    int w, h, k;
    std::cin >> h >> w >> k;
    constexpr bool WHITE = false, BLACK = true;
    std::vector<std::vector<bool>> field(h, std::vector<bool>(w, WHITE));

    int blackCount = 0;
    for (auto y = 0; y < h; ++y)
    {
        std::string s;
        std::cin >> s;
        for (auto x = 0; x < w; ++x)
        {
            if (s[x] == '#')
            {
                field[y][x] = BLACK;
                ++blackCount;
            }
            else
            {
                field[y][x] = WHITE;
            }
        }
    }

    int reqDelta = blackCount - k;
    if (reqDelta < 0)
    {
        std::cout << 0;
        return 0;
    }

    int ansCnt = 0;
    for (int y = 0; y < intp(2, h); ++y)
    {
        auto workR = field;
        int deltaR = 0;
        for (int yi = 0; yi < h; ++yi)
        {
            if (y & intp(2, yi))
            {
                deltaR += FillRow(workR, yi);
            }
        }

        for (int x = 0; x < intp(2, w); ++x)
        {
            auto workC = workR;
            int deltaC = 0;
            for (int xi = 0; xi < w; ++xi)
            {
                if (x & intp(2, xi))
                {
                    deltaC += FillColumn(workC, xi);
                }
            }
            if (deltaR + deltaC == reqDelta)
            {
                ++ansCnt;
            }
        }
    }

    std::cout << ansCnt;
}

