void solve(int tc) {
    int h, w, k;
    cin >> h >> w >> k;

    int tot = 0;
    vector<int> row(h, 0);
    vector<int> col(w, 0);
    vector<string> grid(h, "");
    for (int i = 0; i < h; ++i) {
        cin >> grid[i];
        for (int j = 0; j < w; ++j) {
            if (grid[i][j] == '#') {
                row[i] += 1;
                col[j] += 1;
                tot += 1;
            }
        }
    }

    int cnt = 0;
    for (int r = 0; r < (1 << h); ++r) {
        int rrem = 0;
        int b = 0;
        while (b < h) {
            if (r & (1 << b)) {
                rrem += row[b];
            }
            b += 1;
        }

        for (int c = 0; c < (1 << w); ++c) {
            int crem = 0;
            b = 0;
            while (b < w) {
                if (c & (1 << b)) {
                    for (int i = 0; i < h; ++i) {
                        if (grid[i][b] == '#') {
                            if ((r & (1 << i)) == 0) {
                                crem += 1;
                            }
                        }
                    }
                }
                b += 1;
            }

            if (tot - rrem - crem == k) {
                cnt += 1;
            }
        }
    }

    cout << cnt << endl;
}

