vector <string> grid;
bool vis[1000][1000];
int ans;

void solve(int r,int c,int idx){
  if(idx == h){
    if(vis[r][c])
      return;
    vis[r][c] = true;
    int cnt = 0;
    for(int i=0;i<h;i++){
      for(int j=0;j<w;j++){
        if(r & (1 << i) || c & (1 << j))
          continue;
        if(grid[i][j] == '#')
          cnt++;
      }
    }
    if(cnt == k)
      ans++;
    return;
  }

  solve(r,c,idx+1);
  for(int j=0;j<w;j++){
    solve(r | (1 << idx),c,idx+1);
    solve(r,c | (1 << j),idx+1);
    solve(r | (1 << idx),c | (1 << j),idx+1);
  }

}

int main(){

  ios_base :: sync_with_stdio(false);
  cin.tie(NULL);

  cin >> h >> w >> k;

  grid.resize(h);

  for(int i=0;i<h;i++)
    cin >> grid[i];

  solve(0,0,0);

  cout << ans << endl;

  return 0;
}

