{
	vector<pair<char, ll>> moji_cnt;
	moji_cnt.pb(mp(s[0], 0));
	REP(i, SZ(s))
	{
		if (moji_cnt.back().first == s[i])
		{
			moji_cnt.back().second++;
		}
		else
		{
			moji_cnt.pb(mp(s[i], 1));
		}
	}
	return moji_cnt;
}

