void dfs_maze(vector<vector<ll>>& maps, ll row, ll col, ll& cnt) {
	if (rangeCheck(row, SZ(maps), col, SZ(maps[0])) && maps[row][col]) {
		maps[row][col] = 0;
		REP(k, 8) {
			dfs_maze(maps, row + dy8[k], col + dx8[k], cnt);
		}
	}
}

