void func(vector <int> R,vector <int> C,int r,int c,int h,int w)
{
    if(r==h+1 && c==w+1)
    {
        solve(R,C,h,w);
        return;
    }

    if(r<=h && c<=w)
    {
        func(R,C,r+1,c+1,h,w);
        R.push_back(r);
        func(R,C,r+1,c+1,h,w);
        C.push_back(c);
        R.pop_back();
        func(R,C,r+1,c+1,h,w);
        R.push_back(r);
        func(R,C,r+1,c+1,h,w);
    }
    else if(r<=h)
    {
        func(R,C,r+1,c,h,w);
        R.push_back(r);
        func(R,C,r+1,c,h,w);
    }
    else if(c<=w)
    {
        func(R,C,r,c+1,h,w);
        C.push_back(c);
        func(R,C,r,c+1,h,w);
    }
    return;
}
