{ 
    ll res = 1; 
    for (ll i = 2; i <= n; i++) 
        res = res * i; 
    return res; 
} 

ll nCr(ll n,ll r) 
{ 
    return fact(n)/(fact(r)*fact(n-r)); 
} 

void f(ll a[],ll d[],ll st,ll ed,ll idx,ll r)
{
	if(idx==r)
	{
		ll flag=0;
		set<ll> cl,ro;
