					sub += n[ bit ][ k ];
					n[ bit ][ k ] = false;
				}
			}
		}
		rep( bit, 0, W ){
			if (pattern & ( 1 << bit + H )){
				rep( k, 0, H ){
					sub += n[ k ][ bit ];
					n[ k ][ bit ] = false;
				}
			}
		}
		if (sum_black - sub == K)
			cnt++;
	}
