    char c;
    int total = 0;
    for (int i = 0; i < h; i++) {
        sq.push_back(vector<char> ());
        for (int j = 0; j < w; j++) {
            cin >> c;
            if (c == '#') {
                total += 1;
            }
            sq[i].push_back(c);
        }
    }
    int solutions = 0;
    if (total == k) {
        solutions += 1;
    }
    vector<bool> rows(h,0);
    for (int j = 0; j < w; j++) {
        solutions += helpercol(j,h,w,k,total,sq,rows);
    }   
    for (int i = 0; i < h; i++) {
        vector<bool> rows(h,0);
        solutions += helper(i,h,w,k,total,sq,rows);
    }
    cout << solutions;
}

