ll calc(vector<ll> use, ll index, ll H, ll W, vector<vector<ll>> c, ll K){
  if(index == H+W){
    //for(ll i=0;i<H+W;i++){
    //  cout << use[i] << ' ';
    //}
    //cout << '\n';
    ll sum = 0;
    for(ll i=0;i<H;i++){
      for(ll j=0;j<W;j++){
        sum += use[i]*use[H+j]*c[i][j];
      }
    }
    if(sum==K)
      return 1;
    return 0;
  }
  use[index]=0;
  ll a = calc(use, index+1, H, W, c, K);
  use[index]=1;
  ll b = calc(use, index+1, H, W, c, K);
  return a+b;
}

