#include <bits/stdc++.h>
using namespace std;

void GABS(int n, vector <vector <int>> &perms, vector <int> arr, int i) 
{ 
    if (i == n) { 
    	perms.push_back(arr); 
        return; 
    } 

    arr[i] = 0; 
    GABS(n, perms, arr, i + 1); 

    arr[i] = 1; 
    GABS(n, perms, arr, i + 1); 
} 


int main()
{
	ios::sync_with_stdio(0);
	cin.tie(0);
	int h,w,k;
	cin>>h>>w>>k;

	vector <vector <char>> grid;
	for(int j = 0 ; j < h; j++)
	{
		vector <char> crow(w);
		for(int k = 0 ; k < w; k++)
		{
			cin>>crow[k];
		}
		grid.push_back(crow);
	}

	vector <vector <int>> perms_row;
	vector <int> arr_row(h);

	vector <vector <int>> perms_col;
	vector <int> arr_col(w);

	int counts = 0;

	GABS(h, perms_row, arr_row, 0);
	GABS(w, perms_col, arr_col, 0);

	for(int i = 0 ; i < (int) perms_row.size(); i++)
	{
		vector <int> cr = perms_row[i];
		for(int j = 0 ; j < (int) perms_col.size(); j++)
		{
			vector <int> cc = perms_col[j];
			int black_counts = 0;
			for(int k = 0 ; k < h; k++)
			{
				if(cr[k] == 1)
				{
					continue;
				}
				else
				{
					for(int l = 0 ; l < w; l++)
					{
						if(cc[l] != 1)
						{
							if(grid[k][l] == '#')
							{
								black_counts += 1;
							}
						}
					}
				}
			}
			if(black_counts == k)
			{
				counts += 1;
			}
		}
	}

	cout<<counts;

	return 0;
}

