vector<bool> isprime;
void sieveInit(int size){
    int sb = size + 9;
    isprime.resize(sb);

    isprime[0] = isprime[1] = false;
    isprime[2] = true;
    for(int i=2; i<sb; i++) {
        if(i%2 == 0) isprime[i] = false;
        else isprime[i] = true;
    }
    for(int i=3; i*i<=sb; i+=2){
        if(isprime[i]){
            int m = 3*i;
            while(m < sb){isprime[m] = false; m += 2*i;}
        } else {
            continue;
        }
    }
}
