vector<int64_t> mybit(int64_t p, int64_t q, int64_t N) //p bit探索 N桁
{
    vector<int64_t> bit;
    while (q >= p)
    {
        int64_t tmp = q % p;
        bit.push_back(tmp);
        q /= p;
    }
    bit.push_back(q % p);
    bit.resize(N);
    return bit;
}

