vector<vector<int>> Bitwise_AllSearch(int digit) {
	vector<vector<int>> res;

	for (int bit = 0; bit < (1 << digit); bit++) {
		vector<int> S;
		for (int i = 0; i < digit; i++) {
			if (bit & (1 << i)) {
				S.push_back(i);
			}
		}

		res.push_back(S);
	}

	return res;
}
