		}
	}
	return cnt;
}
int solve(vvi table, vi Ha, vi Wb, int K) {
	int H = table.size();
	int W = table[0].size();
	for (auto h : Ha) {
		for (int j = 0; j < W; j++)
			table[h][j] = 2;
	}
	for (auto w : Wb) {
		for (int i = 0; i < H; i++) {
			table[i][w] = 2;
		}
	}

	if (calcBlackC(table) == K) {
		return 1;
	}
	else {
		return 0;
	}
}

