int solve() {
	ll h, w, k;
	cin >> h >> w >> k;

	vector<string> cs(h);
	for (ll i = 0; i < h; ++i) {
		cin >> cs[i];
	}

	ll res = 0;
	for (ll i = 0; i < (1LL << ll(h + w)); ++i) {
		vector<string> copy_cs = cs;
		for (ll j = 0; j < h; ++j) {
			if (((i >> j) & 1LL) == 1LL) {
				for (ll l = 0; l < w; ++l) {
					copy_cs[j][l] = '.';
				}
			}
		}
		for (ll j = 0; j < w; ++j) {
			if (((i >> (h + j)) & 1LL) == 1LL) {
				for (ll l = 0; l < h; ++l) {
					copy_cs[l][j] = '.';
				}
			}
		}

		ll black = 0LL;
		for (ll j = 0; j < h; ++j) {
			for (ll l = 0; l < w; ++l) {
				if (copy_cs[j][l] == '#') black++;
			}
		}
		if (black == k) {
			++res;
		}
	}

	cout << res << endl;

	return 0;
}

