static void exec()
{
	int H, W, K;
	get(H, W, K);

	std::vector<std::string> grid(H);
	for (int i = 0; i < H; i++) {
		get(grid[i]);
	}

	int total = 0;
	std::vector<int> row(H, 0), col(W, 0);
	std::vector<std::vector<int>> cross(H, std::vector<int>(W, 0));
	for (int h = 0; h < H; h++) {
		for (int w = 0; w < W; w++) {
			if (grid[h][w] == '#') {
				cross[h][w]++;
				row[h]++;
				col[w]++;
				total++;
			}
		}
	}

	int ans = 0;
	for (int hBit = 0; hBit < (1 << H); hBit++) {
		for (int wBit = 0; wBit < (1 << W); wBit++) {
			int sum = 0;
			for (int h = 0; h < H; h++) {
				if (hBit & (1 << h)) {
					sum += row[h];
				}
			}
			for (int w = 0; w < W; w++) {
				if (wBit & (1 << w)) {
					sum += col[w];
				}
			}
			for (int h = 0; h < H; h++) {
				for (int w = 0; w < W; w++) {
					if ((hBit & (1 << h)) && (wBit & (1 << w))) {
						sum -= cross[h][w];
					}
				}
			}
			if ((total - sum) == K) {
				ans++;
			}
		}
	}

	printf("%d\n", ans);
}

