template <class T>
inline T mpower(T x, T n)
{
    if (n == 0)
    {
        return 1;
    }
    else if (n % 2 == 0)
    {
        return mpower(x * x % MOD, n / 2);
    }
    else
    {
        return x * mpower(x, n - 1) % MOD;
    }
}

template <class T>
inline T q_power(T x, T n)
{
    if (n == 0)
    {
        return 1;
    }
    else if (n % 2 == 0)
    {
        return q_power(x * x, n / 2);
    }
    else
    {
        return x * q_power(x, n - 1);
    }
}

LL mfrac(LL x)
{
    LL res = 1;
    for (LL i = x; i >= 1; i--)
    {
        res *= i;
        res %= MOD;
    }
    return res;
}

