void dfsy(int y,int k) {
	if(y > m) return ;
	if(k < K) return ; 
	for(int i = y;i <= m;i ++) {
		int sum = 0;
		for(int j = 1;j <= n;j ++) {
			if(vis[j] && mp[j][i] == '#') sum ++;
		}
		if(k - toty[i] + sum == K) {
			ans ++;
			continue;
		}
		dfsy(i + 1,k - toty[i] + sum);
	} 
}
void dfsx(int x,int k) {
	if(x > n) return ;
	if(k < K) return ;
	for(int i = x;i <= n;i ++) {
		vis[i] = 1;
		if(k - totx[i] == K) {
			ans ++;
			continue;
		}
		dfsy(1,k - totx[i]);
		dfsx(i + 1,k - totx[i]);
		vis[i] = 0;
	} 
} 
