int main()
{
	cin>>n>>m>>k;
	for(int i=0;i<n;++i) cin>>s[i];
	int sum=0;
	memset(a,0,sizeof a);
	memset(b,0,sizeof b);
	for(int i=0;i<n;++i)
	{
		for(int j=0;j<m;++j)
		{
			if(s[i][j]=='#') a[i]++,b[j]++,sum++; 
		}
	}
	int ans=0;
	for(int i=0;i<(1<<n);++i)
	{
		for(int j=0;j<(1<<m);++j)
		{
			int t=sum;
			for(int y=0;y<n;++y)
			{
				if(i&(1<<y)) t=t-a[y];
			}
			for(int y=0;y<m;++y)
			{
				if(j&(1<<y)) t=t-b[y];
			}
			for(int x=0;x<n;++x)
			{
				for(int y=0;y<m;++y)
				{
					if(i&(1<<x)&&j&(1<<y))
					{
						if(s[x][y]=='#') t++;
					}
				}
			}
			if(t==k) ans++;
		}
	 }
	 cout<<ans<<endl; 
	return 0;
}

