vector<int> tobase4(int n)
{
    vector<int> ans;
    while (n)
    {
        ans.push_back(n % 4);
        n /= 4;
    }

    int ns = 6 - ans.size();
    while (ns > 0)
    {
        ans.push_back(0);
        ns--;
    }
    reverse(ans.begin(), ans.end());
    return ans;
}
char mp[6][6];

void dbg(pair<set<int>, set<int>> const &es)
{
    cerr << "r:[";
    for (auto e : es.first)
        cerr << e << ",";
    cerr << "] -> c:[";
    for (auto e : es.second)
        cerr << e << ",";
    cerr << "]\n";
}

int solve(set<pair<set<int>, set<int>>> const &filt, int k, int n, int m)
{
    int ans = 0;
    for (auto e : filt)
    {
        int count = 0;
        for (int a = 0; a < n; a++)
            for (int b = 0; b < m; b++)
            {
                if (e.first.find(a) != e.first.end())
                    continue;
                if (e.second.find(b) != e.second.end())
                    continue;
                if (mp[a][b] == '#')
                    count++;
            }
        if (count == k)
        {
            // dbg(e);
            ans++;
        }
    }
    return ans;
}

int main()
{
    int n, m, k;
    cin >> n >> m >> k;
    for (int a = 0; a < n; a++)
    {
        string sd;
        cin >> sd;
        int j = 0;
        for (auto e : sd)
            mp[a][j++] = e;
    }

    vector<pair<set<int>, set<int>>> sup;
    for (int a = 0; a < 4097; a++)
    {
        auto exsp = tobase4(a);
        pair<set<int>, set<int>> asas;
        for (int t = 0; t < exsp.size(); t++)
        {
            if (exsp[t] == 1)
                asas.first.insert(t);
            else if (exsp[t] == 2)
                asas.second.insert(t);
            else if (exsp[t] == 3)
            {
                asas.second.insert(t);
                asas.first.insert(t);
            }
        }
        sup.push_back(asas);
    }
    set<pair<set<int>, set<int>>> filt;
    for (auto e : sup)
    {
        bool include = true;

        for (int a = n; a < 6; a++)
        {
            if (e.first.find(a) != e.first.end())
            {
                include = false;
                break;
            }
        }

        for (int a = m; a < 6 && include; a++)
        {
            if (e.second.find(a) != e.second.end())
            {
                include = false;
                break;
            }
        }

        if (include)
            filt.insert(e);
    }
    cout << solve(filt, k, n, m);
}

