vector <int> decToBinary(ll n, ll pad) 
{ 
    int binaryNum[32];  
    int i = 0; 
    while (n > 0) { 
        binaryNum[i] = n % 2; 
        n = n / 2; 
        i++; 
    } 

    while(i < pad){
    	binaryNum[i] = 0;
    	++i;
    }

  	vector <int> binary;
    for (int j = i - 1; j >= 0; j--) 
        binary.push_back(binaryNum[j]); 


    return binary;
} 


