void solve(int _t){
	int h, w, k;
	cin >> h >> w >> k;
	int g[h][w];
	int tc = 0;
	rep(i, 0, h){
		string s;
		cin >> s;
		rep(j, 0, w)
		{
			if(s[j] == '.') g[i][j] = 0;
			else{
				g[i][j] = 1;
				tc++;
			} 
		}
	}
	int ans = 0;
	for(int c1 = 0; c1 < (1<<h); c1++){
		for(int c2 = 0; c2 < (1<<w); c2++){
			vi v1, v2;
			rep(i, 0, h){
				if((c1&(1<<i)) > 0){
					v1.pb(i);
				}
			}
			rep(j, 0, w){
				if((c2&(1<<j))>0){
					v2.pb(j);
				}
			}
			int cnt1 = 0;
			int tmp[7][7];
			rep(i, 0, h) rep(j, 0, w) tmp[i][j] = g[i][j];
			for(int i = 0; i < sz(v1); i++){
				for(int j = 0; j < w; j++){
					tmp[v1[i]][j] = 0;
				}
			}
			int cnt2 = 0;
			for(int i = 0; i < sz(v2); i++){
				for(int j = 0; j < h; j++){
					tmp[j][v2[i]] = 0;
				}
			}
			rep(i, 0, h) rep(j, 0, w) cnt1+=tmp[i][j];
				// tr(v1,v2, cnt1, cnt2);
			if(k == (cnt1)){
				ans++;
			}

		}
	}
	cout<<ans<<endl;
}
