int main()
{
    auto judge = [&](const std::string& a) {
        bool ans;
        if (a == "#") {
            ans = 1;
        } else {
            ans = 0;
        }
        return ans;
    };
    int h,
        w,
        k_input;
    std::cin >> h >> w >> k_input;
    std::array<std::string, 6> T = {};
    std::array<std::array<std::string, 6>, 6> S = {};
    std::array<std::array<int, 6>, 6> N = {};
    int ans_last = 0;
    //std::array<std::array<int, 7>, 7> N = {};
    for (int i = 0; i < h; ++i) {
        std::cin >> T.at(i);
        for (int j = 0; j < T[i].size(); ++j) {
            S[i][j] = T[i].substr(j, 1);
        }
    }
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < T[i].size(); ++j) {
            N[i][j] = judge(S[i][j]);
        }
    }
    for (int i = 0; i < static_cast<int>(std::pow(2, h)); ++i) {
        for (int j = 0; j < static_cast<int>(std::pow(2, w)); ++j) {
            //ここで列のサイクル
            int number_black = 0;
            for (int k = 0; k < h; ++k) {
                for (int l = 0; l < w; ++l) {
                    if (N[k][l] == 1 && (i / static_cast<int>(std::pow(2, k))) % 2 == 1 && (j / static_cast<int>(std::pow(2, l))) % 2 == 1) {
                        number_black += 1;
                    }
                }
            }
            if (number_black == k_input) {
                ++ans_last;
            }
        }
    }
    std::cout << ans_last << std::endl;
    return 0;
}

