ll power(ll x, ll y, ll p)
{
    ll res = 1;  
    x = x % p;  
    while (y > 0)
    {
        if (y & 1)
            res = (res*x) % p;
        y = y>>1; 
        x = (x*x) % p;  
    }
    return res;
}
ll modInverse(ll A,ll M)
{
    return power(A,M-2,M);
}

void solve(){
    int n,m,k; cin>>n>>m>>k;
    int b = 0, ans = 0;
    char a[n][m];
    f(i,n) f(j,m){
    	cin>>a[i][j];
    	if(a[i][j] == '#') b++;
	}
    int xx = pow(2,n+m);
    for(int i=0;i<xx;i++){
    	int j=0;
    	int z = i;
    	vector<int> r,c;
    	while(z>0){
    		if(z%2 == 1){
    			if(j < n) r.pb(j);
    			else c.pb(j-n);
			}
			z /= 2;
			j++;
		}
		int tmp = 0;
		f(x,r.size()){
			for(int k=0;k<m;k++) if(a[r[x]][k] == '#') tmp++;
		}
		f(x,c.size()){
			for(int k=0;k<n;k++) if(a[k][c[x]] == '#') tmp++;
		}
		for(int l=0;l<r.size();l++){
			for(int p=0;p<c.size();p++){
				if(a[r[l]][c[p]] == '#') tmp--;
			}
		}
		if(b-tmp == k) ans++;
	}
	cout<<ans<<endl;
}

