ll solve(int a, int b, int na, int nb){
  if (na == h && nb == w){
    for (int i = 0; i < h; i++){
      if ((a >> i) & 1){
        for (int j = 0; j < w; j++){
          t[i][j] = '.';
        }
      }
    }
    for (int j = 0; j < w; j++){
      if ((b >> j) & 1){
        for (int i = 0; i < h; i++){
          t[i][j] = '.';
        }
      }
    }
    ll num = 0;
    for (int i = 0; i < h; i++){
      for (int j = 0; j < w; j++){
        if (t[i][j] == '#')
          num++;
      }
    }
    for (int i = 0; i < h; i++){
      t[i] = c[i];
    }
    if (num == k)
      return 1;
    else
      return 0;
  }
  else if (na == h){
    return solve(a, b | (1 << nb), na, nb+1)
        + solve(a, b, na, nb+1);
  }
  else {
    return solve(a | (1 << na), b, na+1, nb)
        + solve(a, b, na+1, nb);
  }
}

