	for (int j = 0; j < n; j++) {
		if (v[j][idx] == '#') {
			cnt--;
			v[j][idx] = '.';
		}
	}
	rec2(idx+1, v, cnt);
}

void rec(int idx, vector<string> v, int cnt) {
	if (idx == n) {
		rec2(0, v, cnt);
		return;
	}
	rec(idx+1, v, cnt);
	for (int j = 0; j < m; j++) {
		if (v[idx][j] == '#') {
			cnt--;
			v[idx][j] = '.';
		}
	}
	rec(idx+1, v, cnt);
}


