void solve(){
    int h,w,k,all=0;
    cin>>h>>w>>k;
    char grid[h][w];
    loop(h,i,0)
        loop(w,j,0)
            cin>>grid[i][j],all+=(grid[i][j]=='#');
    int r[h]{},c[w]={};
    loop(h,i,0)
        loop(w,j,0)
            r[i]+=(grid[i][j]=='#');
    loop(w,j,0)
        loop(h,i,0)
            c[j]+=(grid[i][j]=='#');

    int res=0;
    loop((1<<h),i,0){
        int s1=0,s2=0;
        vi row;
        loop(h,q,0){
            if(i&(1ll<<q)){
                s1+=r[q];
                row.pb(q);
            }
        }
        loop((1<<w),j,0){
            vi col;
            loop(w,q,0){
                if(j&(1ll<<q)){
                    s2+=c[q];
                    col.pb(q);
                }
            }
            int intersect=0;
            for(auto x:row){
                for(auto y:col){
                    if(grid[x][y]=='#')
                        intersect++;
                }
            }
            if(all-(s1+s2-intersect)==k)
                res++;
            s2=0;
        }
    }
    cout<<res<<endl;
}
