int count(vector<string> &g) {
  int res = 0;
  for (auto row : g) {
    for (auto c : row) {
      res += (c == '#');
    }
  }
  return res;
}

vector<string> paint(int h, int w, int rmask, int cmask, vector<string> &g) {
  auto res = g;
  for (int i = 0; i < h; i++) {
    if (rmask & (1 << i)) {
      for (int j = 0; j < w; j++) {
        res[i][j] = '.';
      }
    }
  }
  for (int j = 0; j < w; j++) {
    if (cmask & (1 << j)) {
      for (int i = 0; i < h; i++) {
        res[i][j] = '.';
      }
    }
  }
  return res;
}

