void dfs(int x,int g){
 if(check()<k)
  return;
 if(x==n+m+1&&g==1){
  if(check()==k)
   ans++;//,print();
   return;
 }
 if(x==n+m+1&&g==0){
  return;
 }
 if(g==0){
  dfs(x+1,0),dfs(x+1,1);
  return;
 }
 int t=x;
 if(g==1)
 if(x>n){
  t=x-n;
  for(int i=1;i<=n;++i)
   vis[i][t]++;
  dfs(x+1,0);
  dfs(x+1,1);
  for(int i=1;i<=n;++i)
   vis[i][t]--;
 }
 else{
  for(int i=1;i<=m;++i)
   vis[x][i]++;
  dfs(x+1,0);
  dfs(x+1,1);
  for(int i=1;i<=m;++i)
   vis[x][i]--;
 }
}
