struct Sum {
    int sum;
    vector<int> pos;
};




int main() {
    int h, w, k;
    cin >> h >> w >> k;
    vector<vector<int>> C(h, vector<int>(w, 0));
    vector<Sum> rowSum(h), colSum(w);
    vector<Sum> rowSumCpy(h), colSumCpy(w);
    char x;
    int total = 0;

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            cin >> x;
            if (x == '.') { C.at(i).at(j) = 0; }
            else {
                C.at(i).at(j) = 1;
                total++;
                rowSum.at(i).sum++;
                rowSum.at(i).pos.push_back(j);
                colSum.at(j).sum++;
                colSum.at(j).pos.push_back(i);
            }
            //cout << C.at(i).at(j) << " ";
        }
        //cout << endl;
    }



    int all = 1 << (h+w);
    int row, col, dup, ans=0;
    int totCpy;
    for (int i = 0; i < all; i++) {
        totCpy = total;
        copy(rowSum.begin(), rowSum.end(), rowSumCpy.begin());
        copy(colSum.begin(), colSum.end(), colSumCpy.begin());
        for (int j = 0; j < (h + w); j++) {
            if ((i >> j) & 1 == 1) {
                if (j < h) {
                    totCpy -= rowSumCpy.at(j).sum;
                    for (int m = 0; m < rowSumCpy.at(j).pos.size(); m++) {
                        dup = rowSumCpy.at(j).pos.at(m);
                        colSumCpy.at(dup).sum--;
                    }
                }
                else {
                    totCpy -= colSumCpy.at(j-h).sum;
                }

            }
        }
        if (totCpy == k) { ans++; }
    }

    cout << ans << endl;
    return 0;
}

