int bit_search(int H, int W, int K, vector<vector<char>> c) {
    int sum = 0;
    vector<vector<char>> d;
    for (int bit_h = 0; bit_h < (1 << H); ++bit_h) {
        for (int bit_w = 0; bit_w < (1 << W); ++bit_w) {
            int black = 0;
            d = c;
            for (int i = 0; i < H; i++) {
                if (bit_h & (1 << i)) {
                    for (int j = 0; j < W; j++){
                        d.at(i).at(j) = '-';
                    }
                }
            }
            for (int j = 0; j < W; j++) {        
                if (bit_w & (1 << j)) {
                    for (int i = 0; i < H; i++) {
                        d.at(i).at(j) = '-';
                    }
                }
            }
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (d.at(i).at(j) == '#') black++;
                }
            }
            if (black == K) sum++;
        }
    }
    return sum;
}

