static int wdfs(std::vector<int>& row, std::vector<int>& col,
	std::vector<std::vector<int>>& cross, int noww,
	std::vector<bool>& hUse,
	std::vector<bool>& wUse,
	int total, int H, int W, int K)
{
	int val = 0, ans = 0;
	if (noww >= W) {
		val = 0;
		for (int h = 0; h < H; h++) {
			if (hUse[h]) {
				val += row[h];
			}
		}
		for (int w = 0; w < W; w++) {
			if (wUse[w]) {
				val += col[w];
			}
		}
		for (int h = 0; h < H; h++) {
			for (int w = 0; w < W; w++) {
				if (hUse[h] && wUse[w]) {
					val -= cross[h][w];
				}
			}
		}
		if ((total - val) == K) {
			ans = 1;
		}
	}
	else {
		for (int i = 0; i <= 1; i++) {
			wUse[noww] = i;
			ans += wdfs(row, col, cross, noww + 1, hUse, wUse, total, H, W, K);
		}
	}
	return ans;
}

static int hdfs(std::vector<int>& row, std::vector<int>& col,
	std::vector<std::vector<int>>& cross, int nowh,
	std::vector<bool>& hUse,
	std::vector<bool>& wUse,
	int total, int H, int W, int K)
{
	int ans = 0;
	if (nowh >= H) {
		ans = wdfs(row, col, cross, 0, hUse, wUse, total, H, W, K);
	}
	else {
		for (int i = 0; i <= 1; i++) {
			hUse[nowh] = i;
			ans += hdfs(row, col, cross, nowh + 1, hUse, wUse, total, H, W, K);
		}
	}
	return ans;
}

