void go(int i, int j) {
  if(i == n  && j == m) {
    int sum = 0;
    for(int I = 0; I < n; ++I) {
      for(int J = 0; J < m; ++J) {
        if(!row[I] && !col[J] && g[I][J] == '#') sum += 1;
      }
    }
    ans += sum == k;
  } else {
    if(i < n && j < m) {
      row[i] = true;
      col[j] = true;
      go(i + 1, j + 1);
      row[i] = false;
      col[j] = false;
    }
    if(i < n) {
      row[i] = true;
      go(i + 1, j + (j < m));
      row[i] = false;
    }
    if(j < m) {
      col[j] = true;
      go(i + (i < n), j + 1);
      col[j] = false;
    }
    go(i + (i < n), j + (j < m));
  }
}

