void dfs( ll d, ll a, ll rem )
{
	if ( rem == k ) {
		bit[a] = 1;
	}
//	if ( rem < k ) {
//		return;
//	}
	if ( d == (h + w) ) {
		return;
	}

	// 選ばない
	dfs(d + 1, a, rem);

	// 選ぶ
	a += (1 << d);
	if ( d < h ) {
		// 行を選ぶ
		ll r = rem;
		rep ( x, w ) {
			if ( e[d][x] == '#' ) {
				r--;
			}
			e[d][x] = '.';
		}
		dfs(d + 1, a, r);
		rep ( x, w ) {
			e[d][x] = c[d][x];
		}
	}
	else {
		// 列を選ぶ
		ll r = rem;
		rep ( y, h ) {
			if ( e[y][d - h] == '#' ) {
				r--;
			}
			e[y][d - h] = '.';
		}
		dfs(d + 1, a, r);
		rep ( y, h ) {
			e[y][d - h] = c[y][d - h];
		}
	}
	a -= (1 << d);
}


