			if ( c[y][x] == '#' ) {
				rem++;
			}
		}
	}

	dfs(0, 0, rem);

	ll cnt = 0;
	rep ( i, (1 << 12) ) {
		cnt += bit[i];
	}

	cout << cnt << endl;

	return 0;
}

