vector < vector <string> > power_set(int index, vector <string> &elements) {
    if (index == -1) {
        return {{}};
    }
    auto ps = power_set(index - 1, elements);
    vector < vector <string> > add;
    for (auto &i: ps) {
        vector <string> j(i);
        j.push_back(elements[index]);
        add.push_back(j);
    }
    ps.insert(ps.end(), add.begin(), add.end());
    return ps;
}

