typedef long long int ll;

template <typename T> bool next_combination(const T first, const T last, int k) {
    const T subset = first + k;
    if (first == last || first == subset || last == subset) {
        return false;
    }
    T src = subset;
    while (first != src) {
        src--;
        if (*src < *(last - 1)) {
            T dest = subset;
            while (*src >= *dest) {
                dest++;
            }
            iter_swap(src, dest);
            rotate(src + 1, dest + 1, last);
            rotate(subset, subset + (last - dest) - 1, last);
            return true;
        }
    }
    rotate(first, subset, last);
    return false;
}

vector<string> fillf(vector<int> ys, vector<int> xs, vector<string> f) {
    int y = (int)f.size();
    int x = (int)f[0].size();
    for (int yidx = 0; yidx < (int)ys.size(); yidx++) {
        int target_y = ys[yidx];
        for (int i = 0; i < x; i++) {
            f[target_y][i] = 'r';
        }
    }
    for (int xidx = 0; xidx < (int)xs.size(); xidx++) {
        int target_x = xs[xidx];
        for (int i = 0; i < y; i++) {
            f[i][target_x] = 'r';
        }
    }
    return f;
}
int cntf(vector<string> f) {
    int y = (int)f.size();
    int x = (int)f[0].size();
    int ret = 0;
    for (int i = 0; i < y; i++) {
        for (int j = 0; j < x; j++) {
            if (f[i][j] == '#') {
                ret++;
            }
        }
    }
    return ret;
}

