void fillrow(vector<string> &a,int k){
    for(int i=0;i<m;i++) a[k][i]='.';
}
void fillcol(vector<string> &a,int k){
    for(int i=0;i<n;i++) a[i][k]='.';
}

vector<string> fill(vector<string> a,int row,int col){
    for(int i=0;i<n;i++){
        if( (1<<i) & row ) fillrow(a,i);
    }
    for(int i=0;i<m;i++){
        if( (1<<i) & col ) fillcol(a,i);
    }
    return a;
}

