}

ll full_search(int h, int w, vector<vector<char>> &vec){
    ll ret=0;
    if(h==H){
        if(w==W){
            return judge(vec);
        }else{
            col[w]=true;
            ret+=full_search(h,w+1,vec);
            col[w]=false;
            ret+=full_search(h,w+1,vec);
        }
    }else{
        row[h]=true;
        ret+=full_search(h+1,w,vec);
        row[h]=false;
        ret+=full_search(h+1,w,vec);
    }
    return ret;
}

