void solve()
{
    int n, m, k;
    scanf("%d%d%d", &n, &m, &k);

    char a[n][m];
    int total_black = 0;

    rep(i, 0, n) {
        rep(j, 0, m) {
            cin >> a[i][j];
            total_black += a[i][j] == '#';
        }
    }

    int ways = 0;

    for(int row=0; row<(1<<n); row++) {
        for(int col=0; col<(1<<m); col++) {
            int here = total_black;

            rep(i, 0, n) {
                rep(j, 0, m) {
                    if((row>>i)&1 and (col>>j)&1)
                        here -= a[i][j] == '#';
                }
            }

            ways += here == k;
        }
    }

    prin(ways);
}

