    if(nx == w && ny == h){
        int bcnt = 0;
        string s = "\n";
        for(ll y = 0;y < h;++y){
            for(ll x = 0;x < w;++x){
                if(grid[x][y] == '#')++bcnt;
                s += grid[x][y];
            }
            s += '\n';
        }
        //cout << s << endl;
        if(bcnt == k){
            return 1;
        }
    }
    else if(nx < w && ny < h){
        vector<vector<char>> ngrid1 = grid;
        for(ll y = 0;y < h;++y){
            ngrid1[nx][y] = '!';
        }

        vector<vector<char>> ngrid2 = grid;
        for(ll x = 0;x < w;++x){
            ngrid2[x][ny] = '!';
        }

        vector<vector<char>> ngrid3 = ngrid1;
        for(ll x = 0;x < w;++x){
            ngrid3[x][ny] = '!';
        }


        cnt += search(grid,nx + 1,ny + 1,w,h,k);
        cnt += search(ngrid1,nx + 1,ny + 1,w,h,k);
        cnt += search(ngrid2,nx + 1,ny + 1,w,h,k);
        cnt += search(ngrid3,nx + 1,ny + 1,w,h,k);
    }
    else if(nx < w){
        vector<vector<char>> ngrid1 = grid;
        for(ll y = 0;y < h;++y){
            ngrid1[nx][y] = '!';
        }
        cnt += search(grid,nx + 1,ny,w,h,k);
        cnt += search(ngrid1,nx + 1,ny,w,h,k);
    }
    else{
        vector<vector<char>> ngrid2 = grid;
        for(ll x = 0;x < w;++x){
            ngrid2[x][ny] = '!';
        }

        cnt += search(grid,nx,ny + 1,w,h,k);
        cnt += search(ngrid2,nx,ny + 1,w,h,k);
    }
    return cnt;
}


