int GetBkNum(vector<string> area, int h, int w)
{
	int H = (int)area.size();
	int W = (int)area.front().length();
	string row(W, ' ');
	for (int i = 0; i < H; ++i) {
		if ((h >> i) & 0x1) {
			area[i] = row;
		}
	}
	for (int i = 0; i < W; ++i) {
		if ((w >> i) & 0x1) {
			for (int j = 0; j < H; ++j) {
				area[j][i] = ' ';
			}
		}
	}
	int numBk = 0;
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
			if (area[i][j] == '#')
				++numBk;
		}
	}
	return numBk;
}

