{
	auto& in = cin;
	int H, W, K;
	in >> H >> W >> K;

	vector<string> area;
	for (int i = 0; i < H; ++i) {
		string str;
		in >> str;
		area.emplace_back(move(str));
	}

	int WW = pow(2, W);
	int HH = pow(2, H);
	int numK = 0;
	for (int h = 0; h < HH; ++h) {
		for (int w = 0; w < WW; ++w) {
			if (GetBkNum(area, h, w) == K)
				++numK;
		}
	}
	cout << numK;

	return 0;
}

