          tmp_grid[h][w] = 0;
        }
      }
    }

    rep(j, 0, 1 << W) {
      auto tmp_grid_ = tmp_grid;
      rep(w, 0, W) {
        if ((j>>w)&1) {
          rep(h, 0, H) {
            tmp_grid_[h][w] = 0;
          }
        }
      }
      int k = calc_black(tmp_grid_);
      if (k == K) {
        ans++;
      }
    }
  }

  cout << ans << endl;


  return 0;
};

