#include<stdio.h>

const static int MAX = 6;
int A[MAX][MAX], B[MAX][MAX];
int h, w, k, cnt, ans;
std::vector<int> bit;

int bit_search(int a, int m){
    if(a == m){
	for(int i = 0; i < h; i++){
	    for(int j = 0; j < w; j++){
		B[i][j] = A[i][j];
	    }
	}
	int cnt = 0;

	for(int i = 0; i < h; i++){
	    if(bit[i] == 1){
		for(int j = 0; j < w; j++){
		    B[i][j] = 0;
	    	}
	    }
	}
	for(int i = h; i < h + w; i++){
	    if(bit[i] == 1){
		for(int j = 0; j < h; j++){
		    B[j][i-h] = 0;
	    	}
	    }
	}

	for(int i = 0; i < h; i++){
	    for(int j = 0; j < w; j++){
		if(B[i][j] == 1) cnt++;
	    }
	}
	if(cnt == k) ans++;

	return 0;
    }
    bit_search(a+1, m);
    bit[a] = 1;
    bit_search(a+1, m);
    bit[a] = 0;
    return 0; 
}

int main(void){

    std::cin >> h >> w >> k;
    std::vector<std::string> str(h);
    bit.resize(h + w);
    ans = 0;

    for(int i = 0; i < h; i++){
	std::cin >> str[i];
    }

    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
	    if(str[i][j] == '#'){
		A[i][j] = 1;
	    }
        }
    }


    bit_search(0, h + w);
    std::cout << ans << std::endl;

}

