using namespace std;
int H,W,K,ans,black;

int main(){
    cin>>H>>W>>K;
    char c[H][W];
    for(int i=0;i<H*W;i++){cin>>c[i/W][i%W];black+=c[i/W][i%W]=='#';}
    //for(int i=0;i<H*W;i++)cout<<c[i/W][i%W]<<" \n"[i==W-1];

    for(int h_bit=0;h_bit<1<<H;h_bit++){
        bitset<32>hb(h_bit);
        //cout<<"h:"<<hb<<endl;
        for(int w_bit=0;w_bit<1<<W;w_bit++){
            bitset<32>wb(w_bit);
            //cout<<"w:"<<wb<<endl;
            if(wb.count()==W)continue;

            int cnt=0;

            for(int keta=0;keta<H;keta++){
                //cout<<(hb[keta])<<endl;
                if(hb[keta]){
                    for(int x=0;x<W;x++){
                        if(c[keta][x]=='#')cnt++;
                    }
                }
            }
            for(int keta=0;keta<W;keta++){
                //cout<<(wb[keta])<<endl;
                if(wb[keta]){
                    for(int x=0;x<H;x++){
                        if(!hb[x]&&c[x][keta]=='#')cnt++;
                    }
                }
            }
            // cout<<"cnt:"<<cnt<<endl;
            // if((black-cnt)==K)cout<<"ok"<<endl;
            ans+=((black-cnt)==K);
        }
    }
    cout<<ans<<endl;
    return 0;
}

