#define M 1000000007
typedef long long ll;
#define fin(ans) cout << (ans) << '\n'
/*

*/
ll mpow(ll x, ll n){ //x^n (mod M)
    ll ans = 1;
    while(n != 0){
        //したの桁から見ていって、その桁にあったら*xして、nをシフトするにつれxを二乗する
        if (n & 1) ans = ans * x % M;
        x = x * x % M;
        n = n >> 1;
    }
    return ans;
}
int main()
{
    int H,W,K;
    cin >> H >> W >> K;
    string s[H];
    REP(i,H){
        cin >> s[i];
    }
    int ans = 0;
    REP(i,mpow(2,H)){
        REP(j,mpow(2,W)){
            int black = 0;
            REP(n,H){
                REP(m,W){
                    if(((i >> n)&1) == 0 &&((j >> m)&1) == 0 && s[n][m] == '#'){
                        black++;
                    }
                }
            }
            if(black == K) ans++;
        }
    }
    fin(ans);
    return 0;
}

