using namespace std;

void Main() {
    // input
    int H, W, K;
    cin >> H >> W >> K;
    int field[H+1][W+1];
    for (int i = 1; i <= H; i++) {
        for (int j = 1; j <= W; j++) {
            char c;
            cin >> c;
            if (c == '.') {
                field[i][j] = 0; // 0 white
            } else {
                field[i][j] = 1; // 1 black
            }
        }
    }

    // translate
    int count = 0;
    int allH = 1;
    for (int i = 0; i < H; i++) {
        allH *= 2;
    }
    int allW = 1;
    for (int j = 0; j < W; j++) {
        allW *= 2;
    }

    for (int i = 0; i < allH; i++) {
        for (int j = 0; j < allW; j++) {
            bitset<8> bsH(i);
            bitset<8> bsW(j);

            int black_cnt = 0;
            for (int h = 0; h < H; h++) {
                if (bsH[h]) {
                    continue;
                }
                for (int w = 0; w < W; w++) {
                    if (bsW[w]) {
                        continue;
                    }
                    if (field[h+1][w+1] == 1) {
                        black_cnt++;
                    }
                }
            }

            // cout << "H: " << bsH << ", W: " << bsW << " cnt: " << black_cnt << endl; 
            if (black_cnt == K) {
                count++;
            }
        }
    }

    // output
    cout << count << endl;

}

