	int map[H][W];
	std::string data;
	for (int i = 0; i < H; ++i) {
		std::cin >> data;
		for (int j = 0; j < W; ++j) {
			if (data.substr(j, 1) == ".") {
				map[i][j] = 1;
			} else if (data.substr(j ,1) == "#") {
				map[i][j] = 0;
			}
		}
	}
	long int counter = 0;
	for (int bit1 = 0; bit1 < (1<<H); ++bit1) {
		std::vector<int> Sh;
		for (int i = 0; i < H; ++i) {
			if (bit1 & (1<<i)) {
				Sh.push_back(i);
			}
		}
		for (int bit2 = 0; bit2 < (1<<W); ++bit2) {
			std::vector<int> Sw;
			for (int j = 0; j < W; ++j) {
				if (bit2 & (1<<j)) {
					Sw.push_back(j);
				}
			}
			/*
			std::cout << "Sh : {";
			for (auto i : Sh) {
				std::cout << i << ",";
			}
			std::cout << "}" << std::endl;
			std::cout << "Sw : {";
			for (auto i : Sw) {
				std::cout << i << ",";
			}
			std::cout << "}" << std::endl;
			*/
			int map2[H][W];
			for (int h = 0; h < H; ++h) {
				for (int w = 0; w < W; ++w) {
					map2[h][w] = map[h][w];
				}
			}
			for (auto h : Sh) {
				for (int n = 0; n < W; ++n) {
					map2[h][n] = 2;
				}
			}
			for (auto w : Sw) {
				for (int m = 0; m < H; ++m) {
					map2[m][w] = 2;
				}
			}
			int count = 0;
			for (int k = 0; k < H; ++k) {
				for (int l = 0; l < W; ++l) {
					if (map2[k][l] == 0) {
						count += 1;
					}
				}
			}
			if (count == K) {
				counter += 1;
			}
		}
	}
	std::cout << counter << std::endl;
}

