std::string BigInteger::toString() const {
    std::string s = is_positive_ ? "" : "-";
    if (IsZero()) {
        s = '0';
        return s;
    }
    bool leading_zero = true;
    for (int i = digits_.size() - 1; i >= 0; --i) {
        if (!(digits_[i] == 0 && leading_zero)) {
            leading_zero = false;
            s += digits_[i] + '0';
        }
    }
    if (s.empty() || (s[0] == '-' && s.length() == 1)) s = '0';
    return s;
}

