using namespace std;

int H, W, K;
vector<string> C, T;

void input_init(void) {
	cin >> H >> W >> K;
	C.resize(H);
	for (int j = 0; j < H; ++j)
		cin >> C[j];
}

void paint(int y, int x) {
	T.clear();
	T.resize(H);
	for (int j = 0; j < H; ++j)
		T[j] = C[j];
	int col = 0;
	while (y > 0) {
		if ((y & 1) == 1) {
			T[col].clear();
			T[col] = string(W, '@');
		}
		y >>= 1;
		++col;
	}
	int row = 0;
	while (x > 0) {
		if ((x & 1) == 1) {
			for (int j = 0; j < H; ++j)
				T[j][row] = '@';
		}
		x >>= 1;
		++row;
	}
}

int cnt_check(void) {
	int k = 0;
	for (int j = 0; j < H; ++j) {
		for (int i = 0; i < W; ++i) {
			if (T[j][i] == '#')
				++k;
		}
	}
	return k;
}

int solve(void) {
	int cnt = 0;
	for (int j = 0; j < (1 << H) - 1; ++j) {
		for (int i = 0; i < (1 << W) - 1; ++i) {
			paint(j, i);
			if (cnt_check() == K)
				++cnt;
		}
	}
	return cnt;
}

int main(void) {
	input_init();
	int ans = solve();
	cout << ans << '\n';
	return 0;
}

