void solve_C(){
    int h, w, k;
    cin >> h >> w >> k;
    char cc[h][w], c[h][w];
    REP(i,h){
        REP(j,w){
            cin >> cc[i][j];
            c[i][j] = cc[i][j];
        }
    }

    int ans = 0;
    //white: . , black: # , red: ^
    for(int bith = 0; bith < (1 << h); bith++){
        for(int bitw = 0; bitw < (1 << w); bitw++){
            for(int i = 0; i < h; i++){
                if(bith & (1 << i)){
                    REP(a,w){
                    c[i][a] = '^';
                    }
                }
            }
            for(int j = 0; j < w; j++){
                if(bitw & (1 << j)){
                    REP(b,h) c[b][j] = '$';
                }
            }

            int black_sub = 0;
            REP(i,h){
                REP(j,w){
                    if(c[i][j] == '#') black_sub++;
                }
            }
            if(black_sub == k) ans++;

            REP(i,h){
                REP(j,w) c[i][j] = cc[i][j];
            }
        }
    }

    cout << ans << endl;
}

