class Solution {
public:
    int res = 0;
    int lim;
    int n, m, k;
    vector<string> tb;
    int c(int n, int m, int k) {
        this->n = n; this->k = k; this->m = m;
        this->lim = n + m;
        tb.resize(n);
        for(int i = 0; i < n; ++i) {
            cin >> tb[i];
        }
        dfs(0);
        return res;
    }

    int getb() {
        int ret = 0;
        for(int i = 0; i < n; ++i) {
            for(int j = 0; j < m; ++j) {
                if(tb[i][j] == '#') {
                    ret++;
                }
            }
        }
        return ret;
    }

    void print() {
        for(int i = 0; i < n; ++i) {
            for(int j = 0; j < m; ++j) {
              cout << tb[i][j] << " ";
            }
            cout << endl;
        }
        cout << "------------------" << endl;
    }

    void dfs(int st) {
        int c = getb();
        if(c < k) {
            return;
        }
        if(c == k) {
            res++;
            return;
        }
        for(int i = st; i < lim; ++i) {
            string tmp = "";
            if(i < n) {
                tmp = tb[i];
                for(int i1 = 0; i1 < m; ++i1) {
                    tb[i][i1] = 'R';
                }
                dfs(i + 1);
                for(int i1 = 0; i1 < m; ++i1) {
                    tb[i][i1] = tmp[i1];
                }
            }
            else {
                for(int i1 = 0; i1 < n; ++i1) {
                    tmp += tb[i1][i - n];
                    tb[i1][i - n] = 'R';
                }
                dfs(i + 1);
                for(int i1 = 0; i1 < n; ++i1) {
                    tb[i1][i - n] = tmp[i1];
                }
            }
        }
    }

};

