void subsets(vector<vector<int>>& res, vector<int>& sub, int n, vector<bool>& visited, int start) {
    if(sub.size() == n) {
        return;
    }

    for(int i = start; i < n; i++) {
        if(visited[i])
            continue;
        sub.pb(i);
        res.pb(sub);
        visited[i] = true;
        subsets(res, sub, n, visited, i+1);
        visited[i] = false;
        sub.pop_back();
    }
}

int cnt(vector<string>& mat, vector<int>& forb_h, vector<int>& forb_w) {
    int cnt = 0;
    unordered_set<int> forb_hm(all(forb_h));
    unordered_set<int> forb_wm(all(forb_w));
    for(int i = 0; i < mat.size(); i++) {
        if(forb_hm.count(i))
            continue;
        for(int j = 0; j < mat[0].size(); j++) {
            if(forb_wm.count(j))
                continue;
            if(mat[i][j]=='#')
                cnt++;
        }
    }
    return cnt;
}

