            if (bits & mask) {  // i番目のbitが立っている
                for (int j = 0; j < W; j++) {
                    if (d.at(i).at(j) == 1){
                        count ++;
                        d.at(i).at(j) = 0;
                    }
                }
            }
        }
        for (int bits1 = 0; bits1 < (1 << W); bits1++) {
            count1 = 0;
            for (int j = 0; j < W; j++) {
                int mask1 = 1 << j;
                if (bits1 & mask1) {  // j番目のbitが立っている
                    for (int k = 0; k < H; k++) {
                        count1 += d.at(k).at(j);
                    }
                }
            }

            if(black - count - count1 == K){
                ans++;
            }

        }

    }
    cout << ans << endl;
}

