class FenwickTree
{
private:
    vector<lli> ft;

public:
    FenwickTree() {}
    // initialization: n + 1 zeroes, ignore index 0
    FenwickTree(lli n) { ft.assign(n + 1, 0); }

    lli rsq(lli b)
    { // returns RSQ(1, b)
        lli sum = 0;
        for (; b; b -= LSOne(b))
            sum += ft[b];
        return sum;
    }

    lli rsq(lli a, lli b)
    { // returns RSQ(a, b)
        return rsq(b) - (a == 1 ? 0 : rsq(a - 1));
    }

    // adjusts value of the k-th element by v (v can be +ve/inc or -ve/dec)
    void adjust(lli k, lli v)
    { // note: n = ft.size() - 1
        for (; k < (lli)ft.size(); k += LSOne(k))
            ft[k] += v;
    }
};

class UnionFind
{ // OOP style
public:
    vector<lli> p, rank, setSize; // remember: vi is vector<int>
    lli numSets;
    UnionFind(lli N)
    {
        setSize.assign(N, 1);
        numSets = N;
        rank.assign(N, 0);
        p.assign(N, 0);
        for (lli i = 0; i < N; i++)
            p[i] = i;
    }
    lli findSet(lli i) { return (p[i] == i) ? i : (p[i] = findSet(p[i])); }
    bool isSameSet(lli i, lli j) { return findSet(i) == findSet(j); }
    void unionSet(lli i, lli j)
    {
        if (!isSameSet(i, j))
        {
            numSets--;
            lli x = findSet(i), y = findSet(j);
            // rank is used to keep the tree short
            if (rank[x] > rank[y])
            {
                p[y] = x;
                setSize[x] += setSize[y];
            }
            else
            {
                p[x] = y;
                setSize[y] += setSize[x];
                if (rank[x] == rank[y])
                    rank[y]++;
            }
        }
    }
    lli numDisjointSets() { return numSets; }
    lli sizeOfSet(lli i) { return setSize[findSet(i)]; }
};

lli gcd(lli x, lli y)
{
    if (x == 0)
        return y;
    return gcd(y % x, x);
}

plli Egcd(lli x, lli y)
{
    if (x == 0)
        return MP(0, 1);
    plli t = Egcd(y % x, x);
    return MP(t.S - t.F * (y / x), t.F);
}

lli power(lli x, lli y,lli p)
{
    lli res = 1;
    x = x %p;
    while (y > 0)
    {
        if (y & 1)
            res = (res * x)%p;
        //y must be even now
        y = y >> 1; //y=y/2
        x = (x * x) %p;
    }
    return res;
}

lli modI(lli a, lli m)
{
    lli m0 = m, y = 0, x = 1;
    if (m == 1)
        return 0;
    while (a > 1)
    {
        lli q = a / m;
        lli t = m;
        m = a % m;
        a = t;
        t = y;
        y = x - q * y;
        x = t;
    }
    if (x < 0)
        x += m0;
    return x;
}

void pairsort(int a[], int b[], int n)
{
    pair<int, int> v[n];
    REP(i, 0, n)
    {
        v[i].F = a[i];
        v[i].S = b[i];
    }
    sort(v, v + n);
    REP(i, 0, n)
    {
        a[i] = v[i].F;
        b[i] = v[i].S;
    }
}

