}

lli logint(lli x, lli y)
{
    lli ans = 0;
    lli a = 1;
    for (lli i = 0; i <= x; i++)
    {
        if (x < a)
        {
            return ans;
        }
        ans++;
        a *= y;
    }
    return -1;
}

void Miden(lli **p1, lli n)
{
    lli(*x)[n] = (lli(*)[n])p1;
    REP(i, 0, n)
    {
        REP(j, 0, n)
        {
            x[i][j] = 0;
        }
        x[i][i] = 1;
    }
    return;
}

void Mmult(lli **p1, lli **p2, lli **ans, lli x, lli y, lli z, lli m)
{
    lli(*a)[y] = (lli(*)[y])p1;
    lli(*b)[z] = (lli(*)[z])p2;
    lli(*c)[z] = (lli(*)[z])ans;
    REP(i, 0, x)
    {
        REP(j, 0, z)
        {
            c[i][j] = 0;
            REP(k, 0, y)
            {
                c[i][j] += a[i][k] * b[k][j];
                c[i][j] %= m;
            }
        }
    }
    return;
}

void Mpow(lli **p1, lli **ans, lli n, lli y, lli m)
{
    if (y == 0)
    {
        Miden(ans, n);
        return;
    }
    lli t[n][n];
    Mpow(p1, (lli **)t, n, y / 2, m);
    lli z[n][n];
    Mmult((lli **)t, (lli **)t, (lli **)z, n, n, n, m);
    if (y % 2)
    {
        Mmult((lli **)z, p1, ans, n, n, n, m);
    }
    else
    {
        Miden((lli **)t, n);
        Mmult((lli **)z, (lli **)t, ans, n, n, n, m);
    }
    return;
}

