char a[10][10];
bool solve(ll x, ll y, ll h, ll w, ll k){
	char temp[h + 1][w + 1];
	loop(i, 0, h)
		loop(j, 0, w)
			temp[i][j] = a[i][j];


	ll cnt = 0;
	while( cnt < h){
		if((1 << cnt) & x){
			loop(i, 0, w)
				temp[cnt][i] = '+';
		}
		cnt++;
	}

	cnt = 0;
	while( cnt < w){
		if((1 << cnt) & y){
			loop(i, 0, h)
				temp[i][cnt] = '+';
		}
		cnt++;
	}
	ll ans = 0;
	loop(i, 0, h){
		loop(j, 0, w){
			if(temp[i][j] == '#')
				ans++;
		}
		cnt++;
	}


	return (ans == k);
}
