}

char ch[7][7];
bool vis[7], visit[7];
char change[7][7];
int ans;

inline void dfs (int now) {
	if (now == n + m + 1) {
		for (int i = 1; i <= n; ++ i) {
			for (int j = 1; j <= m; ++ j) change[i][j] = ch[i][j];
		}
		int cnt = 0;
		for (int i = 1; i <= n; ++ i) {
			for (int j = 1; j <= m; ++ j) {
				if (vis[i] || visit[j]) change[i][j] = '.';
			}
		}
		for (int i = 1; i <= n; ++ i) {
			for (int j = 1; j <= m; ++ j) cnt += (change[i][j] == '#');
		}
		if (cnt == k) ++ ans;
		return;
	}
	if (now > n) {
		visit[now - n] = true; dfs (now + 1);
		visit[now - n] = false; dfs (now + 1);
		return;
	}
	if (now <= n) {
		vis[now] = true; dfs (now + 1);
		vis[now] = false; dfs (now + 1);
		return;
	}
	return;
}

int main () {
	cin >> n >> m >> k;
	for (int i = 1; i <= n; ++ i) {
		for (int j = 1; j <= m; ++ j) cin >> ch[i][j];
	}
	dfs (1);
	cout << ans << endl;
	return 0;
}

