int H, W, K;
int c[10][10];
bool red[20];

int redline(int n) {
    if (n == H + W) {
        int sum = 0;
        for (int i = 0; i < H; i++) {
            if (red[i]) {
                continue;
            }
            for (int j = 0; j < W; j++) {
                if (red[H + j]) {
                    continue;
                }
                if (c[i][j] == 1) {
                    ++sum;
                }
            }
        }
        if (sum == K) {
            return 1;
        } else {
            return 0;
        }
    }
    red[n] = false;
    int ans = redline(n + 1);
    red[n] = true;
    ans += redline(n + 1);
    ++n;
    return ans;
}

