int h, w, k;
char board[6][6];


int possible(int row_mask, int col_mask) {
	char new_board[6][6];
	for (int i = 0; i < h; ++i)
		for (int j = 0; j < w; ++j)
			new_board[i][j] = board[i][j];

	for (int mask = 1, cnt=0; mask < (1 << h); mask <<= 1, ++cnt) {
		if (!(row_mask & mask)) continue;

		for (int j = 0; j < w; ++j)
			new_board[cnt][j] = '.';
	}

	for (int mask = 1, cnt = 0; mask < (1 << w); mask <<= 1, ++cnt) {
		if (!(col_mask & mask)) continue;

		for (int i = 0; i < h; ++i)
			new_board[i][cnt] = '.';
	}

	int black_cnt = 0;
	for (int i = 0; i < h; ++i)
		for (int j = 0; j < w; ++j)
			if (new_board[i][j] == '#')
				++black_cnt;

	/*if (k == black_cnt) {
		cout << row_mask << ' ' << col_mask << '\n';
	}*/

	return black_cnt == k;
}

