void f(vector <string> d, vector <set <int>> deleted, int r, int c, int k){
	if(k < 0)
		return;

	if(k == 0){
		if(!ans.count(deleted))
			cnt++;		
		ans.insert(deleted);
		return;
	}

	for(int i = r; i < n; i++){
		vector <string> cp = d;
		vector <set <int>> cp_del = deleted;

		int tmp = 0;
		for(int j = 0; j < m; j++)
			if(cp[i][j] == '#'){
				cp[i][j] = '.';
				tmp++;
			}
		cp_del[0].insert(i);
		f(cp, cp_del, i+1, c, k - tmp);
	}

	for(int j = c; j < m; j++){
		vector <string> cp = d;
		vector <set <int>> cp_del = deleted;

		int tmp = 0;
		for(int i = 0; i < n; i++)
			if(cp[i][j] == '#'){
				cp[i][j] = '.';
				tmp++;
			}
		cp_del[1].insert(j);
		f(cp, cp_del, r, j+1, k - tmp);
	}
}

