const int N=10;
int a[N][N],b[N][N],n,m,k,cnt,ans,num[N][N],hang[N],lie[N];//num为被修改次数
void solvej(int now) {
	if(now==m+1) {
		int tmp=0;
		for(int i=1; i<=n; ++i)
			for(int j=1; j<=m; ++j)
				if(a[i][j]==1&&num[i][j]==0) tmp++;
		if(tmp==k) ans++;
		return ;
	}
	for(int i=0; i<=1; ++i) {
		lie[now]=i;
		if(i==1)
			for(int j=1; j<=n; ++j) num[j][now]++;
		solvej(now+1);
		if(i==1)
			for(int j=1; j<=n; ++j) num[j][now]--;
		lie[now]=0;
	}
}
void solvei(int now) { //处理行
	if(now==n+1) {
		solvej(1);//处理列
		return ;
	}
	for(int i=0; i<=1; ++i) {
		hang[now]=i;
		if(i==1)
			for(int j=1; j<=m; ++j) num[now][j]++;
		solvei(now+1);
		if(i==1)
			for(int j=1; j<=m; ++j) num[now][j]--;
		hang[now]=0;
	}
}
