#define FAST 		ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
#define time_passed	1.0 * clock() / CLOCKS_PER_SEC

int ans=0,cnt=0;
int h,w,k;
char a[6][6];
int r[6],c[6];
int dp[64][64];

void fun(int rn,int cn)
{
	if(dp[rn][cn]>-1)
		return;
	cnt++;
	int sum=0;
	fr(h)
	{
		if((rn&(1<<i)) != 0)
			sum=sum+r[i];
	}
	fr(w)
	{
		if((cn&(1<<i)) != 0)
			sum=sum+c[i];
	}
	fr(h)
	{
		if((rn&(1<<i)) != 0)
		{
			rep(j,0,w)
			{
				if((cn&(1<<j)) != 0)
				{
					if(a[i][j]=='#')
						sum--;
				}
			}
		}
	}
	dp[rn][cn]=sum;
	fr(h)
	{
		if((rn&(1<<i)) == 0)
		{
			fun((1<<i) | rn,cn);
		}
	}
	fr(w)
	{
		cnt++;
		if((cn&(1<<i)) == 0)
		{
			fun(rn,(1<<i) | cn);
			cnt++;
		}
	}
}

void solve()
{
	cin>>h>>w>>k;
	memset(r,0,sizeof(r));
	memset(c,0,sizeof(c));
	memset(dp,-1,sizeof(dp));
	int b=0;
	fr(h)
	{
		rep(j,0,w)
		{
			cin>>a[i][j];
			if(a[i][j]=='#')
			{
				r[i]++;
				c[j]++;
				b++;
			}
		}
	}
	k=b-k;
	int rn,cn;
	rn=0,cn=0;
	fun(rn,cn);
	fr(64)
	{
		rep(j,0,64)
		{
			if(dp[i][j]==k)
				ans++;
		}
	}
	cout<<ans<<endl;
}

signed main()
{
	FAST
	int test=1;
	//cin>>test;
	while(test--)
	{
		solve();
	}
	cerr<<endl<<"Time elapsed : "<<time_passed<<endl;
	return 0;
}

