using namespace std;
bool vis[7][7];
int check(int i, int j, vector<string> s, int n, int m) {
	int ctr = 0;
	for (int x = 0; x < 7; x++) {
		for (int y = 0; y < 7; y++) {
			vis[x][y] = false;
		}
	}
	for (int x = 0; x < n; x++) {
		if (i & (1 << x)) {
			for (int y = 0; y < m; y++) {
				if (s[x][y] == '#' && !vis[x][y]) {
					ctr++;
					vis[x][y] = true;
				}
			}
		}
	}

	for (int x = 0; x < m; x++) {
		if (j & (1 << x)) {
			for (int y = 0; y < n; y++) {
				if (s[y][x] == '#' && !vis[y][x]) {
					ctr++;
					vis[y][x] = true;
				}
			}
		}
	}
	return ctr;
}
