		vector<string> s(n);
		for (int i = 0; i < n; i++) {
			cin >> s[i];
		}
		int total_black = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (s[i][j] == '#')total_black++;
			}
		}

		int ans = 0;


		for (int i = 0; i < (1 << n); i++) {
			for (int j = 0; j < (1 << m); j++) {
				int get_count = check(i, j, s, n, m);
				// cout << get_count << " ";
				if (total_black - get_count == k)ans++;
			}
		}
		cout << ans;
	}
	return 0;
}

