};
struct sege{
  vector<P<int,V<int>>> seg;
  int b;
  sege(string a){
    b=1;
    while(b<a.sz)
      b*=2;
    seg=vector<P<int,V<int>>>(2*b-1);
    fo(i,a.sz){
      seg[i+b-1].fi=1;
      seg[i+b-1].se.pb(a[i]-'a');
    }
    for(int i=b-2;i>=0;i--){
      V<int> d=seg[2*i+1].se;
      fo(j,seg[2*i+2].se.sz){
        d.pb(seg[2*i+2].se[j]);
      }
      Sort(d);
      uni(d);
      seg[i].se=d;
      seg[i].fi=d.sz;
    }
  }
  V<int> mu;
  void update(int i,char a){
    i+=b-1;
    seg[i].se=mu;
    seg[i].se.pb(a-'a');
    seg[i].fi=1;
    while(i){
      i=(i-1)/2;
      V<int> d=seg[2*i+1].se;
      fo(j,seg[2*i+2].se.sz){
