lli J(lli R,lli C)
{
	set<lli> h,w;
	lli k=0;
	while(R!=0)
	{
		if(R%2!=0)
		h.insert(k);
		R/=2;
		k++;
	}
	k=0;
	while(C!=0)
	{
		if(C%2!=0)
		w.insert(k);
		C/=2;
		k++;
	}
	lli ttl=0;
	L(i,0,r-1)
	{
		L(j,0,c-1)
		{
			if((h.find(i)==h.end()&&w.find(j)==w.end())&&ip[i][j])
			ttl++;
		}
	}
	return ttl;
}
int main()
{
