	}
	lli R=pow(2,r)-1,C=pow(2,c)-1,ans=0;
	L(i,0,R)
	{
		L(j,0,C)
		{
			if(J(i,j)==k)
			ans++;
		}
	}
	cout<<ans<<endl;
}

