int main() {
  int h,w,k;
  cin>>h>>w>>k;

  vector<string> c(h, string(w,'.'));
  for(int i=0; i<h; i++){
    string si; cin>>si;
    c[i]=si;
  }

  vector<int> cntsharp_h(h,0);
  vector<int> cntsharp_w(w,0);
  int allsharp=0;
  for(int i=0; i<h; i++){
    for(int j=0; j<w; j++){
      bool cij_is_sharp=(c[i][j]=='#');
      cntsharp_h[i]+=cij_is_sharp;
      cntsharp_w[j]+=cij_is_sharp;
      allsharp+=cij_is_sharp;
    }
  }

  // 行,列の選び方パターン
  vector<vector<bool> > hchoice(pow(2,h),vector<bool>(h,0));
  vector<vector<bool> > wchoice(pow(2,w),vector<bool>(w,0));
  for(int i=0; i<pow(2,h); i++){
    int temp=i;
    for(int j=0; j<h; j++){
      hchoice[i][j]=temp%2; temp/=2;
    }
  }
  for(int i=0; i<pow(2,w); i++){
    int temp=i;
    for(int j=0; j<w; j++){
      wchoice[i][j]=temp%2; temp/=2;
    }
  }


  int res=0;
  for(int i=0; i<hchoice.size(); i++){
    for(int j=0; j<wchoice.size(); j++){
      // 行列ごとに#を数えて合計
      int cnti=0;
      for(int k=0; k<h; k++){
        if(hchoice[i][k]) cnti+=cntsharp_h[k];
      }
      for(int k=0; k<w; k++){
        if(wchoice[j][k]) cnti+=cntsharp_w[k];
      }

      // 交差点の確認
      for(int k=0; k<h; k++){
        if(hchoice[i][k]){
          for(int l=0; l<w; l++){
            if(wchoice[j][l]){
             if(c[k][l]=='#') cnti-=1; 
            }
          }
        }
      }

      if(cnti==k) res+=1;

    }
  }

  cout<<res<<endl;

}

