vector<string> getComb(int n) {
	vector<string> res;
	for(int i=0;i<(1<<n);i++) {
		string temp(n, '0');
		for(int j=0;j<n;j++)
			if((i & (1<<j)) != 0)
				temp[j] = '1';
		res.push_back(temp);
	}
	return res;
}

