    int ans = 0;

    Bit bit1(h);
    while (bit1.Next()) {
        Bit bit2(w);

        auto copy = c;

        rep(i, h) {
            if (bit1.IsSelected(i)) {
                rep(j, w) {
                    copy[i][j] = '.';
                }
            }
        }

        while (bit2.Next()) {
            auto copy_copy = copy;
            rep(j, w) {
                if (bit2.IsSelected(j)) {
                    rep(i, h) {
                        copy_copy[i][j] = '.';
                    }
                }
            }
            int num = 0;
            rep(i, h) {
                rep(j, w) {
                    if (copy_copy[i][j] == '#') ++num;
                }
            }
            if (num == k) ++ans;
        }
    }

    Write(ans);

    return 0;
}

