using namespace std;
bool squares[6][6];
bool painted_i[6];
bool painted_j[6];

int H,W,K;
int num_of_black(){
    int cnt = 0;
    for(int i=0;i<H;i++){
        if(painted_i[i]){
            continue;
        }
        for(int j=0;j<W;j++){
            if(painted_j[j]){
                continue;
            }
            if(squares[i][j] == true){
                cnt++;
            }
        }
    }
    return cnt;
}

int backtrack(int i, int j, int i_step, int j_step, int i_selected, int j_selected){

    if(i_selected==i && j == j_selected){
        return num_of_black()==K ? 1 : 0;
    }

    if(j_step>=W){
        return 0;
    }
    int sum = 0;
    if(i_selected == i){
        painted_j[j_step] = true;
        sum += backtrack(i,j,i_step,j_step+1,i_selected,j_selected+1);
        painted_j[j_step] = false;
        sum += backtrack(i,j,i_step,j_step+1,i_selected,j_selected);
        return sum;
    }

    if(i_step>=H){
        return 0;
    }

    painted_i[i_step] = true;
    sum += backtrack(i,j,i_step+1,j_step,i_selected+1,j_selected);
    painted_i[i_step] = false;
    sum += backtrack(i,j,i_step+1,j_step,i_selected,j_selected);
    return sum;

}

int main() {
    cin>>H>>W>>K;
    for(int i=0;i<H;i++){
        string s;
        cin>>s;
        for(int j=0;j<W;j++){
            squares[i][j] = (s[j]=='#');
        }
    }

    for(int i=0;i<6;i++){
        painted_i[i] = false;
    }
    for(int j=0;j<6;j++){
        painted_j[j] = false;
    }

    int cnt = 0;
    for(int i=0;i<=H;i++){
        for(int j=0;j<=W;j++){
            cnt += backtrack(i,j,0,0,0,0);
            //cout<<"i: "<<i<<" j: "<<j<<" "<<backtrack(i,j,0,0,0,0)<<"\n";
        }
    }
    cout<<cnt;

    return 0;
}

