struct DFS
{
  int c;
  int N,A;
  std::vector<int> &a;
  std::vector<std::vector<bool>> seen;
  std::vector<std::vector<std::vector<std::vector<int>>>> graph;

  DFS(std::vector<int> &w,int over):
    N(w.size()),
    A(over),
    a(w)
  {
    c=0;
    seen.assign(N+1,std::vector<bool>(A+1,false));
    graph.assign(N+1,std::vector<std::vector<std::vector<int>>>(A+1));

    graph[0][0].push_back(std::vector<int>{0});
  }

  const std::vector<std::vector<int>> &find(int row,int clm)
  {
    auto f=[&,this](int i)->bool
    {
      int nextRow=row-1;
      if(nextRow<0)
        return false;

      int nextClm=i==0?clm:clm-a[nextRow];
      if(nextClm<0)
        return false;

      std::vector<std::vector<int>> v;
      if(seen[nextRow][nextClm])
      {
        v=graph[nextRow][nextClm];
      }
      else
      {
        v=find(nextRow,nextClm);
      }
      graph[row][clm].reserve(graph[row][clm].size()+v.size());
      if(i==0)
      {
        for(auto &e:v)
          graph[row][clm].push_back(std::move(e));
      }
      else
      {
        for(auto &e:v)
        {
          e.push_back(a[nextRow]);
          graph[row][clm].push_back(std::move(e));
        }
      }

      return true;
    };

    seen[row][clm]=true;
    for(int i=0;i<=1;i++)
    {
      c++;
      if(f(i)==false)
        continue;
    }

    return graph[row][clm];
  }
};

int main()
{
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  int h,w,k;
  std::cin>>h>>w>>k;

  std::vector<std::vector<char>> g(h,std::vector<char>(w,0));
  std::vector<int> HValue(h,0);
  std::vector<int> WValue(w,0);
  for(int i=0;i!=h;i++)
  {
    for(int j=0;j!=w;j++)
    {
      std::cin>>g[i][j];

      if(g[i][j]=='#')
      {
        HValue[i]++;
        WValue[j]++;
      }
    }
  }

  int result=0;
  for(int bit=0;bit!=(1<<h);bit++)
  {
    std::vector<int> hvalue=HValue;
    std::vector<int> wvalue=WValue;

    int sum=0;
    for(int i=0;i!=h;i++)
    {
      if(bit&(1<<i))
      {
        for(int j=0;j!=w;j++)
        {
          if(g[i][j]=='#')
          {
            hvalue[i]=0;
            wvalue[j]--;
          }
        }
      }
      sum+=hvalue[i];
    }

    int over=sum-k;

    if(over<0)
      continue;

    DFS f(wvalue,over);
    const auto &r=f.find(f.N,f.A);
    result+=r.size();
  }

  std::cout<<result<<std::endl;

  return 0;
}

