int main()
{
    int h, w, k;
    cin >> h >> w >> k;
    string c[h];
    int hb[h] = {0}, wb[w] = {0}, ab = 0;
    for (int i = 0; i < h; i++)
    {
        cin >> c[i];
        for (int j = 0; j < w; j++)
        {
            if(c[i][j] == '#')hb[i]++;
        }
    }

    for (int i = 0; i < w; i++)
    {
        for (int j = 0; j < h; j++)
        {
            if(c[j][i] == '#')wb[i]++;
        }
    }

    for (int i = 0; i < h; i++)
    {
        for (int j = 0; j < w; j++)
        {
            if(c[i][j] == '#')ab++;
        }
    }

    int ans = 0;
    for (int i = 0; i < (1 << h); i++)
    {
        bitset<6> hbit(i);
        for (int j = 0; j < (1 << w); j++)
        {
            bitset<6> wbit(j);

            int buf = ab;
            for (int kk = 0; kk < h; kk++)
            {
                if(hbit[kk] == 1)
                {
                    buf -= hb[kk];
                }
            }
            for (int kk = 0; kk < w; kk++)
            {
                if(wbit[kk] == 1)buf -= wb[kk];
            }

            for (int kk = 0; kk < h; kk++)
            {
                for (int l= 0; l < w; l++)
                {
                    if(hbit[kk] == 1 && wbit[l] == 1 && c[kk][l] == '#')buf++;
                }
            }

            if(buf == k)ans++;
        }
    }


    cout << ans << endl;
}

