        S[i][col] = 2;
    }
}

int count_black(vector< vector <int> > &S, int H, int W, int K){
    int count;
    count = 0;
    REP(i, H){
        REP(j, W){
            if(S[i][j] == 1){count += 1;}
        }
    }
    return count;
}

void rep_set(vector<int> &A, int count){
    int i;
    int j;
    REP(i, 6){
        j = i + 1;
        if(count % (int)pow(2, j) >= (int)pow(2, j-1)){
            A[i] = 1;
        }
        else{
            A[i] = 0;
        }
    }

}


void renew(vector< vector <int> > &S, int H, int W, vector<int> &rep_H, vector<int> &rep_W){
    REP(i, H){
        if(rep_H[i] == 1){
            plus_row(S, i, W);
        }
    }
    REP(i, W){
        if(rep_W[i] == 1){
            plus_col(S, i, H);
        }
    }
}
void reset(vector< vector <int> > &S,vector< vector <int> > &init_S, int H, int W){
    REP(i, H){
        REP(j, W){
            S[i][j] = init_S[i][j];
        }
    }
}

