		REP(Bit2,1<<W){
			REP(i,H){
				REP(j,W){
					s2[i][j]=s[i][j];
				}
			}
			bool F[10]={},F2[10]={};
			REP(i,H){
				if(Bit&(1<<i)){
					F[i]=1;
				}
			}
			REP(i,W){
				if(Bit2&(1<<i)){
					F2[i]=1;
				}
			}
			REP(i,H){
				if(F[i]==1){
					REP(j,W){
						s2[i][j]='1';
					}
				}
			}
			REP(i,W){
				if(F2[i]==1){
					REP(j,H){
						s2[j][i]='1';
					}
				}
			}
			int cnt=0;
			REP(i,H){
				REP(j,W){
					if(s2[i][j]=='#'){
						cnt++;
					}
				}
			}
			if(cnt==X){
				ans++;
			}
		}
	}
	cout<<ans<<endl;
	return 0;
}

