vector<vector<int>> bitExplore(int n)
{
  vector<vector<int>> ret;
  for (int bit = 0; bit < (1 << n); ++bit)
  {
    vector<int> S;
    for (int i = 0; i < n; ++i)
    {
      if (bit & (1 << i))
      {
        S.push_back(i);
      }
    }

    ret.push_back(S);
  }
  return ret;
}


