void solve(){
    int h, w, kk; cin>>h>>w>>kk;
    int m1 = pow(2, h);
    int m2 = pow(2, w);
    char g[h][w];
    For(i, 0, h){
        For(j, 0, w){
            cin>>g[i][j];
        }
    }
    int ans = 0;
    For(k, 0, m1){
        For(l, 0, m2){
            vector<int> r(h, 0), c(w, 0);
            int mask1 = k;
            int mask2 = l;
            For(i, 0, h){
                if(mask1 % 2){
                    r[i]=1;
                }
                else{
                    r[i]=0;
                }
                mask1/=2;
            }
            For(i, 0, w){
                if(mask2 % 2){
                    c[i]=1;
                }
                else{
                    c[i]=0;
                }
                mask2 /= 2;
            }
            int b = 0;
            For(i, 0, h){
                For(j, 0, w){
                    if(!r[i] && !c[j] && g[i][j]=='#')
                        b++;
                }
            }
            if(b == kk){
                ans++;
            }
        }
    }
    cout<<ans;
}


