void dfs(int x,int y,int sum){
	int num=0;
	if(x==h&&y==w){
		if(pp-sum==k){
			ans++;
		}
		return ;
	}
	if(x==h){
		for(int i=0;i<h;i++){
			if(s[i][y]=='#'&&visit[i]==0){
				num++;
			}
		}
		dfs(x,y+1,sum+num);
		dfs(x,y+1,sum);
	}
	else{
		for(int i=0;i<w;i++){
			if(s[x][i]=='#'){
				num++;
			}
		}
		visit[x]=1;
		dfs(x+1,y,sum+num);
		visit[x]=0;
		dfs(x+1,y,sum);
	}
}
