int h,w,k;
vector<vector<char>>grid(6,vector<char>(6));
bool check(){
	int cnt=0;
	rep(i,h)rep(j,w){
		if(grid[i][j]=='#'){
			cnt++;
		}
	}
	if(cnt==k){
		return true;
	}
	return false;
}
void solve()
{

	cin>>h>>w>>k;

	rep(i,h){
		rep(j,w){
			cin>>grid[i][j];
		}		
	}
	vector<vector<char>>init=grid;
	int ans=0;
	rep(i,pow(2,h)){
		rep(j,pow(2,w)){
			grid=init;
			rep(k,h){
				if(i&(1<<k)){
					rep(l,w){
						grid[k][l]='.';
					}
				}
			}
			rep(k,w){
				if(j&(1<<k)){
					rep(l,h){
						grid[l][k]='.';
					}
				}
			}
			if(check()){
				ans++;
			}

		}
	}
	cout<<ans<<endl;


}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	solve();
	return 0;
}

