inline int check() {
  int ret = 0;
  for (int i = 1; i <= H; ++i)
    for (int j = 1; j <= W; ++j) ret += m[i][j] == 1;
  return ret == K;
}

void dfs(int r, int c) {
  if (r == H + 1 && c == W + 1) {
    ans += check();
    return;
  }
  if (r <= H) {
    dfs(r + 1, c);
    for (int i = 1; i <= W; ++i) m[r][i]--;
    dfs(r + 1, c);
    for (int i = 1; i <= W; ++i) m[r][i]++;
  } else {
    dfs(r, c + 1);
    for (int i = 1; i <= H; ++i) m[i][c]--;
    dfs(r, c + 1);
    for (int i = 1; i <= H; ++i) m[i][c]++;
  }
}

