ll solve(string s[], ll r[], ll c[], ll s1, ll s2, ll h, ll w, ll sum, ll k, vector<ll> &v){
	if(s1 == h){
		return solve2(s, r, c, s1, s2, h, w, sum, k, v);
	}

	ll so1 = solve(s, r, c, s1 + 1, s2, h, w, sum, k, v);
	v.pb(s1);
	ll so2 = solve(s, r, c, s1 + 1, s2, h, w, sum - r[s1], k, v);
	v.pop_back();
	return so1 + so2;
}

