bool check(int x)
{
    int tmp[MAXN][MAXN];
    for(int i=1;i<=h;++i)
    for(int j=1;j<=w;++j) tmp[i][j]=mp[i][j];
    for(int i=0;i<=(h-1);++i)
    if(x&(1<<i))
    for(int j=1;j<=w;++j) tmp[i+1][j]=0;
    for(int i=h;i<=h+w-1;++i)
