int res=0;
void cal(int r,int c){
	int ans=0;
	FOR(i,n){
		FOR(j,m){
			if(r&(1<<i) || c&(1<<j)) continue;
			if(arr[i][j]=='#')ans++;
		}
	}
	if(ans==k){res++;}
}
void go(int i,int j,int r,int c){
	if(i==n && j==m){
		cal(r,c);
		return ;
	}
	if(i==n || j==m){
		if(i==n){
			go(i,j+1,r,c|(1<<j));
			go(i,j+1,r,c);
		}
		else{
			go(i+1,j,r&(1<<i),c);
			go(i+1,j,r,c);
		}
		return ;
	}
	go(i+1,j+1,r|(1<<i),c|(1<<j));
	go(i+1,j+1,r,c);
	go(i+1,j+1,r|(1<<i),c);
	go(i+1,j+1,r,c|(1<<j));

}
