void solve()
{

int h,w,k; cin>>h>>w>>k;
bool ch[h][w];
int ans=0;
rep(i,0,h)
{
rep(j,0,w)
{
char r; cin>>r;
if(r=='#')
ch[i][j]=1;
else
ch[i][j]=0;
ans+=ch[i][j];
}
}
int a[h],b[w];
rep(i,0,h)
a[i]=0;
rep(i,0,w)
b[i]=0;
rep(i,0,h)
{
rep(j,0,w)
a[i]+=ch[i][j];
}
rep(i,0,w)
{
rep(j,0,h)
b[i]+=ch[j][i];
}
int H=(1<<h),W=(1<<w);
int na[H],nb[W];
rep(i,0,H)
{
int sum=0;
rep(j,0,h)
if(i & (1<<j))
sum+=a[j];
na[i]=sum;
}
rep(i,0,W)
{
int sum=0;
rep(j,0,w)
if(i & (1<<j))
sum+=b[j];
nb[i]=sum;
}

int fa=0;
rep(i,0,H)
{
rep(j,0,W)
{
int x=i;
int y=j;
vi aa,bb;
int p=0;
while(x)
{
if(x&1)
aa.pb(p);
p++;
x/=2;
}
p=0;
while(y)
{
if(y&1)
bb.pb(p);
p++;
y/=2;
}
int tt=0;
rep(p1,0,aa.size())
{
rep(p2,0,bb.size())
if(ch[aa[p1]][bb[p2]]==1)
tt++;
}
if( (na[i]+nb[j]-tt)==(ans-k) )
fa++;
}
}
cout<<fa;
return;
}
int main()
{
ios_base::sync_with_stdio(0);
	cin.tie(0);
	int t=1;
//	cin>>t;
while(t--)
{
solve();
}
return 0;
}

