ll ketawa(ll n){
  ll a=0;
  while(n!=0){
    a+=n%10;
    n/=10;
  }
  return a;
}
ll RepeatSquaring(ll N, ll P, ll M){//pow->double
    if(P==0) return 1;
    if(P%2==0){
        ll t = RepeatSquaring(N, P/2, M);
        return (t% M)*(t % M)%M;
    }
    return (N * RepeatSquaring(N, P-1, M))%M;
}
ll RS(ll N, ll P){//modがだるいときにつかう
    if(P==0) return 1;
    if(P%2==0){
        ll t = RS(N, P/2);
        return t*t;
    }
    return (N * RS(N, P-1));
}
