int getSum(vector<vector<int>>& c, vector<vector<bool>>& isRed, int H, int W) {
  int ans = 0;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (c[i][j] == 1 && !isRed[i][j]) ans++;
  }}
  return ans;
}


long long dfs(vector<vector<int>>& c, vector<vector<bool>> isRed, int H, int W, int K, int cur) {
  if (cur >= H + W) {
    if (getSum(c, isRed, H, W) == K) {
      // cout << "This red pattern counts!" << endl;
      // for (int i = 0; i < H; i++) {
      //   for (int j = 0; j < W; j++) {
      //     cout << isRed[i][j];
      //   }
      //   cout << endl;
      // }
      // cout << endl;
      return 1;
    } else return 0;
  } else if (cur < H) {
    int i = cur;
    long long ans = 0;
    ans += dfs(c, isRed, H, W, K, cur + 1);
    for (int j = 0; j < W; j++) isRed[i][j] = true;
    ans += dfs(c, isRed, H, W, K, cur + 1);
    return ans;
  } else {
    int j = cur - H;
    long long ans = 0;
    ans += dfs(c, isRed, H, W, K, cur + 1);
    for (int i = 0; i < H; i++) isRed[i][j] = true;
    ans += dfs(c, isRed, H, W, K, cur + 1);
    for (int i = 0; i < H; i++) isRed[i][j] = false;
    return ans;
  }
}


