bool isRight(int bit, int h, int w, int k, Grid grid){
    bool is = false;
    int cnt = 0;
    Grid tmpg = grid;
    FOR(i, 1, h){
        if (bit & 1 << i-1){//  そのbitが1ならばi行を塗る
            FOR(j, 1, w) tmpg[i][j] = false;
        }
    }
    FOR(i, 1, w){
        if (bit & 1 << i+h-1){//  そのbitが1ならばj列を塗る
            FOR(j, 1, h) tmpg[j][i] = false;
        }
    }
    FOR(i, 1, h){
        FOR(j, 1, w){
            if(tmpg[i][j] == true) cnt ++;
        }
    }
    if(cnt == k) is = true;
    return is;
}

