void solve(int i, vector<vector<char>> grid)
{
  if (i == max(n, m))
  {
    int aa = 0;
    for (int x = 0; x < n; x++)
      for (int y = 0; y < m; y++)
        if (grid[x][y] == '#')
          aa++;
    if (aa == k)
      ans++;
    return;
  }
  solve(i + 1, grid);
  if (i < m)
  {
    char b[n];
    for (int x = 0; x < n; x++)
      b[x] = grid[x][i], grid[x][i] = '3';
    solve(i + 1, grid);
    for (int x = 0; x < n; x++)
      grid[x][i] = b[x];
  }
  if (i < n)
  {
    for (int x = 0; x < m; x++)
      grid[i][x] = '3';
    solve(i + 1, grid);
  }
  if (i < n && i < m)
  {
    for (int x = 0; x < m; x++)
      grid[i][x] = '3';
    for (int x = 0; x < n; x++)
      grid[x][i] = '3';
    solve(i + 1, grid);
  }
}
