	int pos = 1;
	while(r) {
		if(r&1) {
			for(int i = 0 ; i < nc ; ++i) {
				grid[pos - 1][i] = 'R';
			}
		}
		++pos;
		r >>= 1;
	}
	pos = 1;
	while(c) {
		if(c&1) {
			for(int i = 0 ; i < nr ; ++i) {
				grid[i][pos - 1] = 'R';
			}
		}
		++pos;
		c >>= 1;
	}
	int cnt = 0;
	for(int i = 0 ; i < grid.size() ; ++i) {
		for(int j = 0 ;j < grid[i].size() ; ++j) {
			if(grid[i][j] == '#') {
				++cnt;
			}
		}
	}
	return (cnt == k);
}

void solve(vector<string>& grid, int& ans, int k, int nrows, int ncols) {
	int rlim = (1 << nrows), clim = (1 << ncols);
	for(int r = 0 ; r < rlim ; ++r) {
		for(int c = 0 ; c < clim ; ++c) {
			if(solveUtil(grid, r, c, k, nrows, ncols)) {
				++ans;
			}
		}
	}
}

