int Comp(int a,int b)
{
    int add=0;

    int dima=log2(a)+1,dimb=log2(b)+1;
    vector < int > V1,V2;

    for(int i=dima;i>=0;i--)
    if( ( a & (1<<i) ) > 0 )
    {
        V1.push_back(i);
        add+=R[i];
    }

    for(int i=dimb;i>=0;i--)
    if( ( b & (1<<i) ) > 0 )
    {
        V2.push_back(i);
        add+=C[i];
    }
    for(int i=0;i<V1.size();i++)
    for(int j=0;j<V2.size();j++)
    {
        int row=V1[i],col=V2[j];
        if(A[row][col]=='#') add--;
    }
    return add;
}

