int main(int argc, const char * argv[]) {
    int H, W, K;
    cin >> H >> W >> K;

    char **mat = new char*[H];
    for (int i = 0; i < H; i++) {
        mat[i] = new char[W];
    }

    int black = 0;
    int *black_g = new int[H];
    int *black_r = new int[W];

    for (int i = 0; i < H; i++) {
        int b = 0;
        for (int j = 0; j < W; j++) {
            cin >> mat[i][j];
            if (mat[i][j] == '#') {
                b++;
            }
        }
        black_g[i] = b;
        black += b;
    }

    const int BLACK = black;

    for (int j = 0; j < W; j++) {
        int b = 0;
        for (int i = 0; i < H; i++) {
            if (mat[i][j] == '#'){
                b++;
            }
        }
        black_r[j] = b;
    }

    int g_bit = 0;
    for (int i = 0; i < H; i++) {
        g_bit += (1 << i);
    }

    int r_bit = 0;
    for (int j = 0; j < W; j++) {
        r_bit += (1 << j);
    }

    bool *g_idx = new bool[H];
    bool *r_idx = new bool[W];
    int ans = 0;
    for (int i = 0; i <= g_bit; i++) {
        int black0 = BLACK;

        memset(g_idx, false, sizeof(bool) * H);
        get_bit(g_idx, H, i);
        for (int k = 0; k < H; k++) {
            if (g_idx[k]) {
                black0 -= black_g[k];
            }
        }

        for (int j = 0; j <= r_bit; j++) {
            black = black0;

            memset(r_idx, false, sizeof(bool) * W);
            get_bit(r_idx, W, j);

            for (int l = 0; l < W; l++) {
                if (r_idx[l]) {
                    black -= black_r[l];
                }
            }

            // 重複して引いたものを戻す。
            for (int k = 0; k < H; k++) {
                if (!g_idx[k]) {continue;}
                for (int l = 0; l < W; l++) {
                    if (!r_idx[l]) { continue;}

                    if (mat[k][l] == '#'){
                        black++;
                    }
                }
            }

            if (K == black) {
                ans++;
            }
        }
    }

    cout << ans << endl;


    delete[] black_g;
    delete[] black_r;

    for (int i = 0; i < H; i++) {
        delete[] mat[i];
    }
    delete[] mat;

    return 0;
}

