void solve()
{
    // initialise();
    ll n,m,k;
    s(n);s(m);s(k);
    ll arr[n][m];
    fre(i,0,n)
    {
        fre(j,0,m)
        {
            char ch;
            s(ch);
            arr[i][j] = (ch == '#');
        }
    }
    ll kd = (1 << n);
    ll pm = (1 << m);
    ll dp[kd][pm];
    memset(dp,0,sizeof(dp));
    fre(i,0,kd)
    {
        vecll dx(n,0);
        ll val = i;
        fre(pp,0,n)
        {
            if(val % 2 == 1)
            {
                dx[pp] = 1;
            }
            val /= 2;
        }
        fre(j,0,pm)
        {
            vecll dy(m,0);
            ll val1 = j;
            fre(pp,0,m)
            {
                if(val1 % 2 == 1)
                {
                    dy[pp] = 1;
                }
                val1 /= 2;
            }
            ll cnt = 0;
            fre(zz,0,n)
            {
                fre(xx,0,m)
                {
                    if(dx[zz] == 0 && dy[xx] == 0 && arr[zz][xx] == 1)
                    {
                        cnt += 1;
                    }
                }
            }
            if(cnt == k)
            {
                dp[i][j] = 1;
            }
        }
    }
    ll ans = 0;
    fre(i,0,kd)
    {
        fre(j,0,pm)
        {
            ans += dp[i][j];
        }
    }
    p(ans);endl;
}



int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);cout.tie(0);
    // facto();
    ll t=1;
    // s(t);
    w(t)
    {
        solve();
    }
    return 0;
}

