        for (int j = 0; j < c; ++j) {
            cin >> a[i][j];
        }
    }
    // debug(arr(a, r, c));
    int ans = 0;
    for (int l = 0; l < pow(2, r); ++l) {
        for (int m = 0; m < pow(2, c); ++m) {
            // To make the temporary array copying the original array
            char temp[r][c];
            for (int i = 0; i < r; ++i) {
                for (int j = 0; j < c; ++j) {
                    temp[i][j] = a[i][j];
                }
            }
            bitset<6> row(l);
            bitset<6> col(m);
            // Making the rows red
            for (int i = 0; i < r; ++i) {
                if (row[i]) {
                    for (int j = 0; j < c; ++j) temp[i][j] = 'R';
                }
            }
            // making the columns red
            for (int i = 0; i < c; ++i) {
                if (col[i]) {
                    for (int j = 0; j < r; ++j) temp[j][i] = 'R';
                }
            }
            // to find how many of them are black
            int mid_ans = 0;
            for (int i = 0; i < r; ++i) {
                for (int j = 0; j < c; ++j) {
                    if (temp[i][j] == '#') ++mid_ans;
                }
            }
            if (mid_ans == k) ++ans;
        }
    }
    cout << ans << "\n";
}

