using P = pair<int, int>;
using Graph = vector<vector<int>>;
int ans = 0;
int H, W, K; 

// header area
void func(vector<vector<char>> c, int depth){
    if(depth == H+W){
        // count black
        int count_black=0;
        rep(i, H){
            rep(j, W){
                if(c[i][j] == '#') count_black++;
            }
        }
        if(count_black == K) ans++;
    }
    else{
        // not
        func(c, depth+1);
        // do
        if (H > depth){
            // 行固定
            int gyo = depth;
            rep(k, W){
                if(c[gyo][k] == '#'){
                    c[gyo][k] = 'r';
                }
            }
        }
        else if(H+W > depth){
            // 列固定
            int retsu = depth-H;
            rep(k, H){
                if(c[k][retsu] == '#'){
                    c[k][retsu] = 'r';
                }
            }
        }
        else{
            cout << "error."  << endl;
        }
        func(c, depth+1);

    }
}

int main(){
    cin >> H >> W >> K;

    int count_black=0;
    vector<vector<char>> origin;
    rep(i, H){
        vector<char> tmp_vec;
        rep(j, W){
            char tmp; cin >> tmp;
            if(tmp == '#') count_black++;
            tmp_vec.push_back(tmp);
        }
        origin.push_back(tmp_vec);
    }
    vector<vector<char>> c(origin.size());
    copy(origin.begin(), origin.end(), c.begin());
    func(c, 0);

    cout << ans << endl;

    return 0;
}

