int h,w,k,ans;
v(v(char)) a;

void solution(int ind,string state){
  if(ind == h+w){
    v(v(char)) temp = a;
    for(int i = 0; i<h; i++){
      if(state[i] == '1'){
        for(int j = 0; j<w; j++)temp[i][j] = 'R';
      }
    }
    for(int i = h; i<h+w; i++){
      if(state[i] == '1'){
        for(int j = 0; j<h; j++)temp[j][i-h] = 'R';
      }
    }
    int blackcount  = 0;
    for(int i = 0; i<h; i++){
      for(int j = 0; j<w; j++)blackcount+=(temp[i][j] == '#');
    }
    if(blackcount == k)ans+=1;
    return;
  }
  solution(ind+1,state);
  string newstate  = state;
  newstate[ind] = '1';
  solution(ind+1,newstate);
}

