void dfs(int r,int c)
{
     //判断行
    if(r<=h)
    {
        row[r] = 1;
        dfs(r+1,c);
        row[r] = 0;
        dfs(r+1,c);
    }
    //判断列
    else if(c<=w)
    {
        col[c] = 1;
        dfs(r,c+1);
        col[c] = 0;
        dfs(r,c+1);
    }
   else
    {
        char s[maxn][maxn];
        //赋值
        for(int i=1;i<=h;i++)
        {
            for(int j=1;j<=w;j++)
            {
                s[i][j] = mp[i][j];
            }
        }
        //处理行
        for(int i =1;i<=h;i++)
        {
            if(row[i])
            {
                //这一行全部赋值为'.'
                   for(int j=1;j<=w;j++)
                   {
                       s[i][j]='.';
                   }
            }
        }
        //处理列
        for(int j =1;j<=w;j++)
        {
            if(col[j])
            {
                   for(int i=1;i<=h;i++)
                   {
                       s[i][j]='.';
                   }
            }
        }
        //统计
        int  n= 0;
        for(int i=1;i<=h;i++)
        {
            for(int j=1;j<=w;j++)
            {
               if(s[i][j]=='#') n++;
            }
        }
        if(n==k) cnt++;
       // return ;
    }

}
