	for(int i=0; i<H; i++)
	{
		for(int j=0; j<W; j++)
		{
			if(mass[i][j])
			{
				cnt++;
			}
		}
	}

	if(cnt == K)
	{
		return 1;
	}
	else
	{
		return 0;
	}
}

int colorResult(vector<vector<bool>> mass, vector<bool> depth)
{
	for(int i=0; i<H; i++)
	{
		if(depth[i])
		{
			for(int j=0; j<W; j++)
			{
				mass[i][j] = false;
			}
		}

	}
	for(int j=0; j<W; j++)
	{
		if(depth[H+j])
		{
			for(int i=0; i<H; i++)
			{
				mass[i][j] = false;
			}
		}
	}
	return count(mass);
}

int dfs(vector<vector<bool>> mass, vector<bool> depth, int index)
{
	if(index == H+W)
	{
		return colorResult(mass,depth);
	}

	vector<bool> tdepth = depth;
	vector<bool> fdepth = depth;

	tdepth[index] = true;
	fdepth[index] = false;

	return dfs(mass, tdepth, index + 1) + dfs(mass, fdepth, index + 1);
}

