int n,m,k;

int main()
{
    scanf("%d%d%d",&n,&m,&k);
    for(int i=0;i<n;i++)
        scanf("%s",g[i]);

    int sum = 0;
    for(int i=0;i<n;i++)
        for(int j=0;j<m;j++)
            if(g[i][j]=='#')
            {
                n_r[i] ++;
                n_c[j] ++;
                sum ++;
            }

    int ans = 0;
    for(int i=0;i<1<<n;i++)
    {
        for(int j=0;j<1<<m;j++)
        {
            int res = 0;
            for(int k=0;k<n;k++)
                if(i >> k & 1)
                {
                    a.push_back(k);
                    res += n_r[k];
                }

            for(int k=0;k<m;k++)
                if(j >> k & 1)
                {
                    b.push_back(k);
                    res += n_c[k];
                }
            for(auto t : a)
                for(auto p : b)
                    if(g[t][p]=='#')
                        res --;
            a.clear();
            b.clear();
            if(sum - res == k) ans++;
        }
    }
    printf("%d\n",ans);
    return 0;
}

