//第n行を0にして和を更新
void change_update(vector<vector<int>> &v ,int H, int W ,int n){
    for(int i=0;i<W;i++){
        v.at(i).at(n)=0;
    }
    for(int i=0;i<W;i++){
        int sum=0;
        for(int j=0;j<H;j++){
            sum+=v.at(i).at(j);
        }
        v.at(i).at(H)=sum;
    }
}

int main(){
    int H,W,K;
    int sum=0,SUM=0;
    cin>>H>>W>>K;
    vector<int>Hsec(H);
  	vector<vector<int>>Wsec(W,vector<int>(H+1));


    for(int i=0;i<H;i++){
      for(int j=0;j<W;j++){
        char letter;
        cin>>letter;

        if(letter=='#'){
            sum+=1;
            Hsec.at(i)+=1;
            Wsec.at(j).at(i)+=1;
            Wsec.at(j).at(H)+=1;
        }


      }


    }//入力終了

    vector<vector<int>> memory=Wsec;
    int ks=sum-K;
    int current=0;

    for(int tmp=0;tmp<(1<<H);tmp++){
        bitset<6>hbit(tmp);
        for(int i=0;i<H;i++){
            if(hbit.test(i)){
                current+=Hsec.at(i);
                change_update(Wsec,H,W,i);
            }   
        }

      	if(current<=ks){
            ks-=current;
            for(int pat=0;pat<(1<<W);pat++){
                bitset<6>wbit(pat);
                current=0;
                for(int i=0;i<W;i++){
                    if(wbit.test(i)){
                        current+=Wsec.at(i).at(H);
                    }       
                }
                if(current==ks){
                    SUM+=1;
                }

            }

        }
        ks=sum-K;
        Wsec=memory;
        current=0;

    }
    //列のみ

	cout<<SUM<<endl;

}

