    for (int bit = 0; bit < (1 << n); ++bit) {
        vector<int> vec(n);
        auto now_grid = grid;
        //ここで、列の各位が1かをみる
        for (int i = 0; i < n; ++i) {
            if (bit & (1 << i)) {
            //もし1だったら何か処理
            //今回はbit列を表示させる
            vec[i]=1;
            }

        }
        //0がえらばれた場所の#の数を数える
        // 行 0~h-1
        // 列 h~h+w
        rep(i,n){
          if(vec[i]==1){
            if(i>=0&&i<h){
                //たて
                rep(j,w){
                  now_grid[i][j] = '.';
                }
            }
            if(i>=h){
                //よこ
                rep(j,h){
                  now_grid[j][i-h] = '.';
                }
            }
          }
        }
        int c=0;
        rep(i,h){
          rep(j,w){
            if(now_grid[i][j]=='#') c++;
          }
        }
        if(c==k) cnt++;
    }
  cout << cnt << endl;
  return 0;
}

