int f(bitset<6> a, bitset<6> b, int h,int w, vector<string> g){
    for(int i=0;i<h;i++)
        if(a[i]==1)
            for(int j=0;j<w;j++) g[i][j]='.';

    for(int j=0;j<w;j++)
        if(b[j]==1)
            for(int i=0;i<h;i++) g[i][j]='.';

    int ans=0;
    for(int i=0;i<h;i++) for(int j=0;j<w;j++) ans+=(g[i][j]=='#'?1:0);
    return ans;
}

