void solve()
{
    int n, m, k;
    scanf("%d%d%d", &n, &m, &k);

    vector<vi> a(n, vi(m, 0));

    int total_black = 0;

    rep(i, 0, n) {
        rep(j, 0, m) {
            char c;
            cin >> c;
            a[i][j] = c == '#';
            total_black += a[i][j];
        }
    }

    int ways = 0;

    for(int row=0; row<=(1<<n)-1; row++) {
        int here = total_black;
        vector<bool> m_row(n, 0);

        for(int r=0; r<n; r++) {
            if(row & (1<<r)) {
                m_row[r] = 1;
                for(int c=0; c<m; c++)
                    here -= a[r][c];
            }   
        }

        for(int col=0; col<=(1<<m)-1; col++) {
            int here2 = here;
            vector<bool> m_col(m, 0);

            for(int c=0; c<m; c++) {
                if(col & (1<<c)) {
                    m_col[c] = 1;
                    for(int r=0; r<n; r++) {
                        if(!m_row[r])
                            here2 -= a[r][c];
                    }
                }
            }

            if(here2 == k)
                ways ++;
        }
    }   

    prin(ways);
}

