using Matrix = std::vector<std::string>;

int count(int h, int w, const Matrix& m, int rows_value, int columns_value)
{
  int result = 0;
  for (int row = 0; row < h; ++row) {
    if (rows_value & (1 << row)) continue;
    for (int col = 0; col < w; ++col) {
      if (columns_value & (1 << col)) continue;
      if (m.at(row).at(col) == '#') ++result;
    }
  }
  return result;
}

int solve(int h, int w, int k, const Matrix& m)
{
  int result = 0;
  for (int i = 0; i < 1 << h; ++i) {
    for (int j = 0; j < 1 << w; ++j) {
      if (count(h, w, m, i, j) == k) {
        ++result;
      }
    }
  }
  return result;
}

