          for(int m=0; m<(int)e.size(); m++) e2[m][l]='.';
        }
      }
      for(auto v:e2) {
        for(auto elem:v) if(elem=='#') count++;
      }
      if(count == K) ans++;
    }
  }
  cout << ans << endl;
}

