void dfs(int num,int opt,int sum){
    if (sum<k) return;
    if (opt==1){
        if (num==w){
            ans+=(sum==k);
            return;
        }
        dfs(num+1,opt,sum);
        int q[10];q[0]=0;

        for (int i=0;i<w;++i)
            if (c[i][num]=='#') q[++q[0]]=i,c[i][num]='.',--sum;
        dfs(num+1,opt,sum);
        for (int i=1;i<=q[0];++i)
            c[q[i]][num]='#',++sum;
    }
    else {
        if (num==h){
            dfs(0,1,sum);
            return;
        }
        dfs(num+1,opt,sum);

        int q[10];q[0]=0;
        for (int i=0;i<w;++i)
            if (c[num][i]=='#') q[++q[0]]=i,c[num][i]='.',--sum;
        dfs(num+1,opt,sum);
        for (int i=1;i<=q[0];++i)
            c[num][q[i]]='#',++sum;
    }

}

