void search(int z, vector<int> subset, bool row) {
  int n;
  if (row)
    n = h;
  else
    n = w;
  if (z == n) {
    if (row)
      rows.push_back(subset);
    else
      cols.push_back(subset);
  } else {
    search(z + 1, subset, row);
    subset.push_back(nums[z] - 1);
    search(z + 1, subset, row);
    subset.pop_back();
  }
}

bool solve(vector<int> a, vector<int> b) {
  vector<string> g = grid;
  for (int i : a) {
    for (int j = 0; j < w; j++) g[i][j] = '.';
  }
  for (int i : b) {
    for (int j = 0; j < h; j++) g[j][i] = '.';
