int main() {
  int h, w, k, ans = 0, sum;
  char c;
  cin >> h >> w >> k;
  vector<vector<int>> ctable(h + 1, vector<int>(w + 1, 0));
  for (int i = 1; i < h + 1; i++) {
    for (int j = 1; j < w + 1; j++) {
      cin >> c;
      if (c == '#') {
        ctable[0][0]++;
        ctable[0][j]++;
        ctable[i][0]++;
        ctable[i][j] = 1;
      }
    }
  }
  k = ctable[0][0] - k;
  for (int i = 0; i < (1 << h); i++) {
    for (int j = 0; j < (1 << w); j++) {
      sum = 0;
      for (int ia = 0; ia < h; ia++) {
        if (i & (1 << ia)) {
          sum += ctable[ia + 1][0];
        }
      }
      for (int ia = 0; ia < w; ia++) {
        if (j & (1 << ia)) {
          sum += ctable[0][ia + 1];
        }
      }
      for (int ia = 0; ia < h; ia++) {
        for (int ib = 0; ib < w; ib++) {
          if (i & (1 << ia) && j & (1 << ib)) {
            sum -= ctable[ia + 1][ib + 1];
          }
        }
      }
      if (sum == k) {
        ans++;
      }
    }
  }
