class CHAndV {
public:

  void solveOne(istream& cin, ostream& cout) {
    int h, w, k;
    cin >> h >> w >> k;
    vector<string> s(h);
    for (int _i = 0; _i < h; ++_i) {
      cin >> s[_i];
    }
    int res = 0;
    for (int m1 = 0; m1 < (1 << h); ++m1) {
      for (int m2 = 0; m2 < (1 << w); ++m2) {
        int black = 0;
        for (int i = 0; i < h; ++i) {
          for (int j = 0; j < w; ++j) {
            if (((m1 >> i) & 1) == 0 and ((m2 >> j) & 1) == 0 and s[i][j] == '#') {
              ++black;
            }
          }
        }
        if (black == k) ++res;
      }
    }
    cout << res << '\n';
  }

