void re_curse() {
    ll h, w, K;
    cin>>h>>w>>K;
    vector <vl> arr(h, vl(w,0));
    vector <vl> brr;
    for (int i = 0; i < h; ++i) {
        string s;
        cin>>s;
        for (int j = 0; j < w; ++j) {
            arr[i][j] = s[j];
        }
    }
    ll ans = 0;
    for (int i = 0; i < (1<<h); ++i) {
        for (int j = 0; j < (1<<w); ++j) {
            brr = arr;
            for (int r = 0; r < h; ++r) {
                if (i & (1<<r)) {
                    for (int k = 0; k < w; ++k) {
                        brr[r][k] = 0;
                    }
                }
            }
            for (int c = 0; c < w; ++c) {
                if (j & (1<<c)) {
                    for (int k = 0; k < h; ++k) {
                        brr[k][c] = 0;
                    }
                }
            }
            ll c = 0;
            for (int k = 0; k < h; ++k) {
                for (int l = 0; l < w; ++l) {
                    if (brr[k][l] == '#') {
                        ++c;
                    }
                }
            }
            if (c == K) {
                ++ans;
            }
        }
    }
    cout<<ans<<endl;
}

