int main(){
  int h,w,k;
  cin>>h>>w>>k;
  string str[h];
  int kuro[h][w];
  int tkuro[h][w];
  for(int i=0; i<h; i++)
    cin>>str[i];
  int mmax=1;
  for (int i=0; i<h+w; i++)
    mmax=mmax*2;
  int kaunto;
  int hantei=0;

  //黒なら1の整数配列に移す
  for (int i=0; i<h; i++)
    for (int j=0; j<w; j++)
      if(str[i].substr(j,j)=="#"){
	kuro[i][j]=1;
      }else{
	kuro[i][j]=0;
      }
  for (int m=0; m<mmax; m++){
    //tmpに移す
    for (int j=0; j<w; j++)
      for (int i=0; i<h; i++)
	tkuro[i][j]=kuro[i][j];
    //フラグが立っていれば消す
    for (int i=0; i<h; i++)
      if(m&(1<<i)){
	for(int j=0; j<w; j++)
	  tkuro[i][j]=0;
      }
    for (int i=h; i<h+w; i++)
      if(m&(1<<i)){
	for (int j=0; j<h; j++)
	  tkuro[j][i-h]=0;
      }
    //数える
    kaunto=0;
    for (int j=0; j<w; j++)
      for (int i=0; i<h; i++)
	kaunto=kaunto+tkuro[i][j];
    if(kaunto==k){
      hantei++;
    }
  }
  cout<<hantei<<"\n";
  return 0;
}

