	vector<vector<int>> main_calc(int a);
private:
	void recursive(int k, vector<int> vec, int id);
private:
	vector<vector<int>> ans;
	vector<int> dum;
	int lim;
};

comb::comb() {
}

comb::~comb() {
}

void comb::recursive(int k, vector<int> vec, int id) {
	if (vec.size() == k) {
		ans.push_back(vec);
		return;
	}
	else if (id == lim) {
		return;
	}
	else {
		recursive(k, vec, id + 1);
		vec.push_back(dum[id]);
		recursive(k, vec, id + 1);
	}
}

vector<vector<int>> comb::main_calc(int a) {
	ans.clear();
	dum.clear();
	lim = a;
	vector<int> vec;
	for (int i = 0; i < a; i++) {
		dum.push_back(i);
	}
	for (int i = 0; i < a; i++) {
		vec.clear();
		recursive(i, vec, 0);
	}

	return ans;
}

