/* modular arithmetic class implementation */
template<int MOD = 1'000'000'007>
struct Modular
{
	int value;
	static const int MOD_VAL = MOD;

	Modular(ll v = 0) { value = v % MOD; if (value < 0) value += MOD; }
	Modular(ll a, ll b) : value(0) { *this += a; *this /= b; }

	Modular& operator+=(const Modular& o) { value += o.value; if (value >= MOD) value -= MOD; return *this; }
	Modular& operator-=(const Modular& o) { value -= o.value; if (value < 0) value += MOD; return *this; }
	Modular& operator*=(const Modular& o) { value = (ll)value * o.value % MOD; return *this; }
	Modular& operator/=(const Modular& o) { return *this *= o.inv(); }
	Modular& operator++() { return *this += 1; }
	Modular& operator--() { return *this -= 1; }

	Modular exp(Modular a, ll k)
	{
		Modular res = 1;
		while (k) { if (k & 1LL) res *= a; a *= a; k >>= 1; }
		return res;
	}

	Modular inv() { return exp(value, MOD - 2); }

	friend Modular operator+(const Modular& a, const Modular& b) { return a += b; }
	friend Modular operator-(const Modular& a, const Modular& b) { return a -= b; }
	friend Modular operator-(const Modular& a) { return 0 - a; }
	friend Modular operator*(const Modular& a, const Modular& b) { return a *= b; }
	friend Modular operator/(const Modular& a, const Modular& b) { return a /= b; }

	friend ostream& operator<<(ostream& os, const Modular& m) { os << m.value; return os; }
	operator int() { return value; }

	bool operator==(const Modular& o) { return value == o.value; }
	bool operator!=(const Modular& o) { return value != o.value; }
};

