void choose_cols(const int &cur_nr_cols, const int &max_nr_cols, const vector<int> &chosen_lines,
                 const int &del_line_black, const int &last_chosen)
{
    static int offset = 0;
    static int del_col_black = 0;

    if (cur_nr_cols == max_nr_cols)
    {
        int del_total_black = del_col_black + del_line_black - offset;

        if (tot_nr_black - del_total_black == K)
        {
            ++res;
        }

        return;
    }

    for (int j = last_chosen + 1; j + max_nr_cols - 1 - cur_nr_cols <= W; ++j)
    {
        del_col_black += nr_black_col[j];
        for (const int &line : chosen_lines)
        {
            offset += A[line][j] == '#';
        }

        choose_cols(cur_nr_cols + 1, max_nr_cols, chosen_lines, del_line_black, j);

        for (const int &line : chosen_lines)
        {
            offset -= A[line][j] == '#';
        }
        del_col_black -= nr_black_col[j];
    }
}


void choose_lines(const int &cur_nr_lines, const int &max_nr_lines, const int &max_nr_cols, const int &last_chosen)
{
    static vector<int> chosen_lines;
    static int del_line_black = 0;

    if (cur_nr_lines == max_nr_lines)
    {
        choose_cols(0, max_nr_cols, chosen_lines, del_line_black, 0);
        return;
    }

    for (int i = last_chosen + 1; i + max_nr_lines - 1 - cur_nr_lines <= H; ++i)
    {
        del_line_black += nr_black_line[i];
        chosen_lines.emplace_back(i);

        choose_lines(cur_nr_lines + 1, max_nr_lines, max_nr_cols, i);

        del_line_black -= nr_black_line[i];
        chosen_lines.pop_back();
    }
}


int main()
{
    cin.sync_with_stdio(0);

    cin >> H >> W >> K;

    for (int i = 1; i <= H; ++i)
    {
        cin >> (A[i] + 1);
        for (int j = 1; j <= W; ++j)
        {
            nr_black_line[i] += A[i][j] == '#';
            nr_black_col[j] += A[i][j] == '#';
            tot_nr_black += A[i][j] == '#';
        }
    }

    for (int nr_lines = 0; nr_lines <= H; ++nr_lines)
    {
        for (int nr_cols = 0; nr_cols <= W; ++nr_cols)
        {
           choose_lines(0, nr_lines, nr_cols, 0);
        }
    }

    cout << res;
}

