void solve() {
    ll n, m, k;
    cin >> n >> m >> k;
    vvll g(n, vll(m));
    vvll g2(n, vll(m));
    ll count = 0;
    REP(i, n) {
        REP(j, m) {
            char c;
            cin >> c;
            if (c == '#') {
                g[i][j] = 1;
                g2[i][j] = 1;
                count++;
            }
        }
    }

    ll res = 0;
    function<ll(ll, ll, ll)> helper = [&](ll i, ll j, ll k) {
        if (i == -1 && j == -1) {
            ll count = 0;
            REP(ii, n) {
                REP(jj, m) {
                    count += g2[ii][jj];
                }
            }
            return count == k ? 1ll : 0ll;
        }
        ll res = 0;
        if (i != -1) {
            vll prv(m);
            REP(j, m) {
                prv[j] = g2[i][j];
                g2[i][j] = 0;
            }
            ll nxti = i+1;
            if (nxti == n) {
                nxti = -1;
                j = 0;
            }
            res += helper(nxti, j, k);
            REP(j, m) {
                g2[i][j] = prv[j];
            }
            res += helper(nxti, j, k);
        } else {
            vll prv(n);
            REP(i, n) {
                prv[i] = g2[i][j];
                g2[i][j] = 0;
            }
            ll nxtj = j+1;
            if (nxtj == m) {
                nxtj = -1;
                i = -1;
            }
            res += helper(i, nxtj, k);
            REP(i, n) {
                g2[i][j] = prv[i];
            }
            res += helper(i, nxtj, k);
        }
        return res;
    };
    res = helper(0, -1, k);
    // cout << fixed << setprecision(6);
    cout << res << "\n";
}

