using namespace std;

int numofbits(long bits)
{
    bits = (bits & 0x55555555) + (bits >> 1 & 0x55555555);
    bits = (bits & 0x33333333) + (bits >> 2 & 0x33333333);
    bits = (bits & 0x0f0f0f0f) + (bits >> 4 & 0x0f0f0f0f);
    bits = (bits & 0x00ff00ff) + (bits >> 8 & 0x00ff00ff);
    return (bits & 0x0000ffff) + (bits >>16 & 0x0000ffff);
}

void xnumofbits(int k, int& sum, vector<int> hw){
  int l;
  xrep(k){
    l = numofbits((k&-k)-1);
    sum += hw[l];
  }
}

void xnumofbits2(int k, int l, int& sub, string s, vector<string> ss){
  int p,q,r;
  xrep(k){
    r = l;
    //cout << "r=" << r << " sub=" << sub << endl;
    xrep(r){
      p = numofbits((k&-k)-1);
      q = numofbits((r&-r)-1);
      //cout << "k=" << k << " l=" << l << " p=" << p << " q=" << q << endl;
      s = ss[p];
      if(s[q]=='#') ++sub;
    }
  }
}

int binarysearch(int H, int W, int K,string s,vector<string> ss,vector<int> sh,vector<int> sw, int count){
  int hb=(int)pow(2,H),wb=(int)pow(2,W);
  int i,j,k,l,sum,sub,score=0;
  rep(i,hb){
    rep(j,wb){
      sum = 0; sub = 0;
      k = i;
      xnumofbits(k,sum,sh);
      k = j;
      xnumofbits(k,sum,sw);
      k = i;
      l = j;
      xnumofbits2(k,l,sub,s,ss);
     if((count-(sum-sub))==K) ++score;
     //cout << "i=" << i << " j=" << j << " sum=" << sum << " sub=" << sub << " dis=" << count-(sum-sub) << " score=" << score << endl;
     }
  }
  return score;
}

