bool ith(int mask, int i) { return (mask>>i)&1; }
void solve() {
  int res=0;
  REP(mask, 1<<(N+M)) {
    vector<string> B(A,A+N);
    REP(i,N) if(ith(mask,i)) {
      REP(j,M) B[i][j]='R';
    }
    REP(j,M) if(ith(mask,N+j)) {
      REP(i,N) B[i][j]='R';
    }
    int cnt=0;
    REP(i,N)REP(j,M)cnt+=(B[i][j]=='#');
    res+=cnt==K;
  }
  cout<<res<<endl;
}

