			++ans;
			check.insert(used);
		}
		return;
	}
	else if (black < k) {
		return;
	}

	set<pair<int,int>> new_used;
	for (int i = 0; i < n; ++i) {
		if (!used.count({0, i})) {
			new_used = used;
			new_used.insert({0, i});

			vector<vector<int>> new_grid = grid;
			int cnt = 0;
			for (int j = 0; j < m; ++j)
				if (new_grid[i][j])
					++cnt, new_grid[i][j] = 0;

			rec(black - cnt, new_grid, new_used);
		}
	}

	for (int j = 0; j < m; ++j) {
		if (!used.count({1, j})) {
			new_used = used;
			new_used.insert({1, j});

			vector<vector<int>> new_grid = grid;
			int cnt = 0;
			for (int i = 0; i < n; ++i)
				if (new_grid[i][j])
					++cnt, new_grid[i][j] = 0;

			rec(black - cnt, new_grid, new_used);
		}
	}
}

