inline void backtrack(int rx, int cx, int n, int m, int value, int x, int k)
{
    if(cx >= m)
    {
        if((x - value) == k) res++;
        return;
    }

    if(cx < m and rx >= n)
        backtrack(rx, cx + 1, n, m, value, x, k),
        backtrack(rx, cx + 1, n, m, value + col[cx], x, k);

    if(rx < n and cx == 0)
    {
        backtrack(rx + 1, cx, n, m, value, x, k);
        for(int i = 0; i<m; ++i)
            col[i] -= rc[rx][i];

        backtrack(rx + 1, cx, n, m, value + row[rx], x, k);

        for(int i = 0; i<m; ++i)
            col[i] += rc[rx][i];
    }

}

