class UnionFind{
    private: vi rank,p;
    public: 
        UnionFind(int n){
            F(i,0,n)p.pb(i);
            rank.assign(n,1);
        }

        int findSet(int s){
            return (p[s]==s) ? s : (p[s]=findSet(p[s]));
        }

        bool isSameSet(int i,int j){
            return findSet(i)==findSet(j);
        }

        void unionSet(int i,int j){
            if(isSameSet(i,j))return;

            int x=findSet(i),y=findSet(j);
            if(rank[x]>rank[y]){
                p[y]=x;
                rank[x]+=rank[y];
            }
            else {
                p[x]=y;
                //if(rank[x]==rank[y])rank[y]++;
                rank[y] += rank[x];
            }

        }

        int sz(int x){
            int px=findSet(x);
            return rank[px];
        }
};


