string DTB(int n, int x) 
{ 
    // Size of an integer is assumed to be 32 bits 
    string s;
    REP(i, 0, x, 1) s.append("0");
    for (int i = x-1; i >= 0; i--) { 
        int k = n >> i; 
        if (k & 1) 
            s[x-1-i]='1';
        else
            s[x-1-i]='0';
    } 
    return s;
} 

