int main(){
  int H, W, K;
  int ans = 0;
  int num = 0;
  string S = "";
  cin >> H >> W >> K;
  vector<vector<int>> c(H, vector<int>(W));
  vector<int> binH(H);
  vector<int> binW(W);

  for (int i = 0; i < H; i++){
    binH[i] = pow(2, i);
  }
  for (int i = 0; i < W; i++){
    binW[i] = pow(2, i);
  }

  for (int i = 0; i < H; i++){
    S = "";
    cin >> S;
    for (int j = 0; j < W; j++){
      if(S.c_str()[j] == '.'){
        c[i][j] = 0;
      }else if(S.c_str()[j] == '#'){
        c[i][j] = 1;
      }
    }
  }
  int maxH = pow(2, H);
  int maxW = pow(2, W);

  for (int iH = 0; iH < maxH; iH++){
    for (int iW = 0; iW < maxW; iW++){
      num = 0;
      for (int i = 0; i < H; i++){
        for (int j = 0; j < W; j++){
          if(c[i][j] * ((iH / binH[i]) % 2) * ((iW / binW[j]) % 2) == 1){
            num += 1;
          }
        }
      }
      if (num == K) ans += 1;
    }
  }
  cout << ans << "\n";
}

