int black()
{
	int res = 0;	
	for (int i = 0; i < r; ++i)
		for (int j = 0; j < c; ++j)
			res += (ar[i][j] == '#');
	return res;
}

bool check(int n)
{
	for (int i = 0; i < r; ++i)
	{
		if (n & (1 << i))
		{
			for (int j = 0; j < c; ++j)
				ar[i][j] = '.';
		}
	}

	for (int j = r; j < r+c; ++j)
	{
		if (n & (1 << j))
		{
			for (int i = 0; i < r; ++i)
				ar[i][j-r] = '.';
		}
	}

	return black() == k;
}

