void combinationUtil(vector<int> arr, int n, int r,  
                    int index, vector<int> data, int i);  

// The main function that prints all 
// combinations of size r in arr[]  
// of size n. This function mainly  
// uses combinationUtil()  
void printCombination(vector<int> arr, int n, int r)  
{  
    // A temporary array to store  
    // all combination one by one  
    vector<int> data(r);  

    // Print all combination using  
    // temprary array 'data[]'  
    combinationUtil(arr, n, r, 0, data, 0);  
}  

/* arr[] ---> Input Array  
n ---> Size of input array  
r ---> Size of a combination to be printed  
index ---> Current index in data[]  
data[] ---> Temporary array to store current combination  
i ---> index of current element in arr[] */
void combinationUtil(vector<int> arr, int n, int r,  
                    int index, vector<int> data, int i)  
{  
    // Current cobination is ready, print it  
    if (index == r)  
    {  
        int I = combinations.size();
        combinations.push_back(vector<int>(r));
        for (int j = 0; j < r; j++)  
        {
            combinations[I][j] = data[j]; 
        }
        return;  
    }  

    // When no more elements are there to put in data[]  
    if (i >= n)  
        return;  

    // current is included, put next at next location  
    data[index] = arr[i];  
    combinationUtil(arr, n, r, index + 1, data, i + 1);  

    // current is excluded, replace it with next (Note that  
    // i+1 is passed, but index is not changed)  
    combinationUtil(arr, n, r, index, data, i+1);  
}  

