class TaskC {
private:
	Debugger debugger;

	void fillRow(vector<string> &tab, int row, char ch){
		int cols = tab[0].size();
		for(int c = 0; c < cols; c++){
			tab[row][c] = ch;
		}
	}

	void fillCol(vector<string> &tab, int col, char ch){
		int rows = tab.size();
		for(int r = 0; r < rows; r++){
			tab[r][col] = ch;
		}
	}

public:
	void solveOne(int it){
		int rows, cols, k;
		cin >> rows >> cols >> k;
		vector<string> tab(rows);
		for(int i = 0; i < rows; i++){
			cin >> tab[i];
		}
		int ans = 0;
		for(int rowMask = 0; rowMask < 1<<rows; rowMask++){
			vector<string> tmp = tab;
			for(int i = 0; i < rows; i++){
				if(rowMask & (1<<i)){
					fillRow(tmp, i, 'r');
				}
			}

			for(int colMask = 0; colMask < 1<<cols; colMask++){
				vector<string> tmp2 = tmp;
				for(int j = 0; j < cols; j++){
					if(colMask & (1<<j)){
						fillCol(tmp2, j, 'r');
					}
				}
				int ones = 0;
				for(int i = 0; i < rows; i++){
					for(int j = 0; j < cols; j++){
						ones += tmp2[i][j] == '#';
					}
				}
				if(ones == k){
					ans++;
				}
			}
		}
		cout << ans << endl;
	}

	void solve(){
		int tc = 1;
		for(int it = 1; it <= tc; it++){
			solveOne(it);
		}
	}
};


