bool good(int lin, int col) {
    for (int i = 1; i <= n; i++)
        lin_chosen[i] = false;
    for (int j = 1; j <= m; j++)
        col_chosen[j] = false;

    for (int i = 1, cnt = 1; i <= lin; i <<= 1, cnt++)
        if (i & lin)
            lin_chosen[cnt] = true;

    for (int i = 1, cnt = 1; i <= col; i <<= 1, cnt++)
        if (i & col)
            col_chosen[cnt] = true;

    int remaining = 0;
    for (int i = 1; i <= m; i++)
        if (!lin_chosen[i])
            for (int j = 1; j <= m; j++)
                if (!col_chosen[j] && color[i][j] == '#')
                    remaining++;

    return remaining == k;
}

