int H, W, K;
vector<char> c{};
int result = 0;

void paint(int i, vector<char> map){
  if(i == (H + W)){
    if(std::count(map.begin(), map.end(), '#') == K){
      result++;
    }
    return;
  }

  vector<char> c1(H * W);
  c1 = map;
  vector<char> c2(H * W);
  c2 = map;

  paint(i + 1, c1);

  if(i < H){
    for(int l = 0; l < W; l++){
      c2[l + (i * W)] = '*';
    }
  }else{
    for(int l = 0; l < H; l++){
      c2[(i - H) + (l * W)] = '*';
    }
  }

  if(std::count(c2.begin(), c2.end(), '#') < K){
    return;
  }
  paint(i + 1, c2);

  return;
}

