                cp[i].push_back(j);
            }
        }
    }

    int res = 0;
    for (int i = 0; i < rp.size(); i++) {
        for (int j = 0; j < cp.size(); j++) {
            vector<vector<char>> tmpd = data;

            for (int k = 0; k < rp[i].size(); k++) {
                // rp[i][k]行目を赤く塗る
                for (int kk = 0; kk < w; kk++) {
                    tmpd[rp[i][k]][kk] = '-';
                }
