            for (int l = 0; l < cp[j].size(); l++) {
                for (int ll = 0; ll < h; ll++) {
                    tmpd[ll][cp[j][l]] = '-';
                }
            }

            // 調査
            int cnt = 0;
            rep(i, h) {
                rep(j, w) {
                    if (tmpd[i][j] == '#') cnt++;
                }
            }
            if (cnt == k) res++;
