	vector<pair<int, int>> out_vec;
	int index = 0;
	for (auto m : map) {
		if (m.second == i) {
			out_vec.push_back(make_pair(index, m.first));
		}
		index++;
	}
	return out_vec;
}

vector<pair<int, int>> find(vector<pair<int, int>> map, int i) {
	vector<pair<int, int>> out_vec;
	int index = 0;
	for (auto m : map) {
		if (m.first == i) {
			out_vec.push_back(make_pair(index, m.second));
		}
		index++;
	}
	return out_vec;
}

