int solve(int h, int w, int k, const std::vector<std::pair<int, int>>& blacks, std::vector<int> hist = {}, int head = 0)
{
    int ans = 0;
    if (k > 1) {
        for (int i = head; i < (blacks.size() - k + 1); i++) {
            hist.push_back(i);
            ans += solve(h, w, k - 1, blacks, hist, i + 1);
            hist.pop_back();
        }
    } else {
        std::array<int, 6> l, c;
        for (int k = head; k < (blacks.size()); k++) {
            l.fill(0);
            c.fill(0);
            int cc = 0, lc = 0;
            hist.push_back(k);
            for (auto& e : hist) {
                if (l.at(blacks.at(e).first) == 0) {
                    l.at(blacks.at(e).first) = 1;
                    lc++;
                };
                if (c.at(blacks.at(e).second) == 0) {
                    c.at(blacks.at(e).second) = 1;
                    cc++;
                };
            }
            bool ls = true, cs = true;
            for (int i = 0; i < blacks.size(); i++) {
                auto& e = blacks.at(i);
                if (std::find(hist.begin(), hist.end(), i) == hist.end())
                    if (l.at(e.first) == 1) {
                        ls = false;
                    }
                if (c.at(e.second) == 1) {
                    cs = false;
                }
                if (!(cs || ls))
                    break;
            }
            bool conf = false;
            for (int i = 0; i < blacks.size(); i++) {
                bool tmp = false;
                if (std::find(hist.begin(), hist.end(), i) == hist.end()) {
                    if (l.at(blacks.at(i).first) == 0) {
                        tmp = true;
                    }
                    if (c.at(blacks.at(i).second) == 0) {
                        tmp = true;
                    }
                    if (!tmp) {
                        conf = true;
                        break;
                    }
                }
            }
            if (!conf) {
                for (auto& e : hist) {
                    //std::cout << blacks.at(e).first << blacks.at(e).second << "\n";
                }
                int add = 1;
                if (ls)
                    add += w - cc + 1;
                if (cs)
                    add += h - lc + 1;
                ans += add;
            }
            hist.pop_back();
        }
    }
    return ans;
}

int main()
{
    int h, w, k;
    std::cin >> h >> w >> k;
    std::vector<std::pair<int, int>> blacks;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            char c;
            std::cin >> c;
            if (c == '#') {
                blacks.emplace_back(i, j);
            }
        }
    }

    int ans = solve(h, w, k, blacks);
    std::cout << ans << "\n";

    return 0;
}

