inline int sum(vector<vector<int>>& v, set<int>& rows, set<int>& cols) {
    int out = 0;
    for (int i = 0; i < v.size(); i++) {
        if (rows.count(i))
            continue;
        for (int j = 0; j < v[i].size(); j++) {
            if (cols.count(j))
                continue;
            out += v[i][j];
        }
    }
    return out;
}

