void solve(vector<vector<char>> c) {
  ll t = 0;
  vector<vector<char>> cd = c;
  for(ll bitw =0; bitw < (1<<w); bitw++) {
    for(ll i =0; i < w; i++) {
      if(bitw & (1 << i)) {
        REP(m, h) {
          cd[m][i] = 'x';
        }
      }
    }
    for(ll bith =0; bith < (1<<h); bith++) {
      vector<vector<char>> ce = cd;
      for(ll j =0; j < h; j++) {
        if(bith & (1 << j)) {
          REP(l, w) {
            ce[j][l] = 'x';
          }
        }
      }
      ll c = 0;
      REP(i, h) {
        REP(j, w) {
          if(ce[i][j] == '#') c++;
        }
      }
      if(c == k)  {
        t++;
      }
    }
    cd = c;
  }
  cout << t;
}

