        solve(y, x + 1, b_counter, f);
        string tmp = "";
        for(int i = 0;i < H;i++) {
            tmp += cell[i][x];
        }
        int rem = 0;
        for(int i = 0;i < H;i++) {
            if(cell[i][x] == '#') {
                rem++;
            }
            cell[i][x] = '.';
        }
        solve(y, x + 1, b_counter - rem, 1);
        for(int i = 0;i < H;i++) {
            cell[i][x] = tmp[i];
        }
    } else {
        solve(y + 1, x, b_counter, f);
        string tmp = cell[y];
        int rem = 0;
        for(int j = 0;j < W;j++) {
            if(cell[y][j] == '#') {
                rem++;
            }
            cell[y][j] = '.';
        }
        solve(y + 1, x, b_counter - rem, 1);
        cell[y] = tmp;
    }
}

