ll pow_mod (ll a , ll b , ll m) {
	ll ans = 1 ;
	while(b) {
		if (b&1) ans = (ans*a) % m ;
		b /= 2 ;
		a = (a*a) % m ;
	}
	return ans ;
}

bool isprime (ll num) {
