int solve2(string s[], int r[], int c[], int s1, int s2, int h, int w, int sum, int k, vector<int> &v){
	if(s2 == w){
		return (k == sum);
	}

	int so1 = solve2(s, r, c, s1, s2 + 1, h, w, sum, k, v);
	int temp = sum - c[s2];
	rep(j, 0, v.size()){
		if(s[v[j]][s2] == '#')
			temp++;
	}
	int so2 = solve2(s, r, c, s1, s2 + 1, h, w, temp,k, v);

	return so1 + so2;
}
int solve(string s[], int r[], int c[], int s1, int s2, int h, int w, int sum, int k, vector<int> &v){
	if(s1 == h){
		return solve2(s, r, c, s1, s2, h, w, sum, k, v);
	}

	int so1 = solve(s, r, c, s1 + 1, s2, h, w, sum, k, v);
	v.pb(s1);
	int so2 = solve(s, r, c, s1 + 1, s2, h, w, sum - r[s1], k, v);
	v.pop_back();
	return so1 + so2;
}

