int main(){
	int h, k, w;
	cin >> h >> w >> k;

	vector<vector<char> > arr(h, vector<char>(w));

	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			cin >> arr[i][j];
		}
	}

	int black = 0;
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (arr[i][j] == '#')black++;
		}
	}

	if (k == black) {
		cout << 1 << endl;
		return 0;
	}

	if (k > black) {
		cout << 0 << endl;
		return 0;
	}

	int ans = 0;
	int i = 0;
	while (i<h) {
		int discount = 0;

		for (int j = 0; j < w; j++) {
			if (arr[i][j] == '#') {
				discount++;
			}

		for (int r = 0; r < h; h++) {
		if (arr[r][j] == '#' && r != i) {
						discount++;
					}
					if (black - discount == k) {
						ans++;
					}
				}
			}
		i++;
	}
			cout << ans << endl;

	return 0;
}

