            int black_left = num_black;
            for (int y = 0; y < H; y++) {
                for (int x = 0; x < W; x++) {
                    if ((bits_y >> y & 1) || (bits_x >> x & 1)){
                        if (grid[y][x] == '#') {
                            black_left--;
                        }
                    }
                }
            }
            if (black_left == K) {
                ++ans;
            }
        }
