    int squares[6][6];
    int totalBlack{0};

    string squareInput;
    char black = '#';

    for (int i=0; i<numRows; ++i) {
        cin >> squareInput;
        for (int j=0; j<numCols; ++j) {
            if (squareInput[j] == black) {
                squares[i][j] = 1;
                ++totalBlack;
            }
            else squares[i][j] = 0;
        }
    }

    int numWaysToPaint{0};

    for (int r=0; r<1<<numRows; ++r) {
        int toPaintTemp[6][6];
        // initialize 
        for (int i=0; i<numRows; ++i) {
            for (int j=0; j<numCols; ++j) {
                toPaintTemp[i][j] = 0;
            }
        }

        // paint Row(s)
        for (int rshift=0; rshift<numRows; ++rshift) {
            if (r>>rshift&1) {
                for (int t=0; t<numCols; ++t) toPaintTemp[rshift][t] = 1;
            }
        }
        for (int c=0; c<1<<numCols; ++c) {
            // copy toPaintTemp
            int toPaint[6][6];
            for (int i=0; i<numRows; ++i) {
                for (int j=0; j<numCols; ++j) {
                    toPaint[i][j] = toPaintTemp[i][j];
                }
            }

            // Paint Col(s)
            for (int cshift=0; cshift<numCols; ++cshift) {
                if (c>>cshift&1) {
                   for (int t=0; t<numRows; ++t) toPaint[t][cshift] = 1;
                }
            }

            // count numbers of black being painted red
            int paintedRed = paint(squares, toPaint, numRows, numCols);
            if ((totalBlack - paintedRed) == blackLeft) ++numWaysToPaint;
        }
    } 

    cout << numWaysToPaint << endl;

    return 0;
}

