  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      cin >> c[i][j];
      if (c[i][j] == '#')
        all_black++;
    }
  }

  int h[10];
  int w[10];
  for (int i = 0; i < H; i++) {
    h[i] = 0;
    for (int j = 0; j < W; j++)
      h[i] += c[i][j] == '#' ? 1 : 0;
  }
  for (int i = 0; i < W; i++) {
    w[i] = 0;
    for (int j = 0; j < W; j++)
      w[i] += c[j][i] == '#' ? 1 : 0;
  }

  // 全探索
  int res = 0;
  for (int i = 0; i < (1 << H); i++) {
    for (int j = 0; j < (1 << W); j++) {
      int sum = 0;
      for (int k = 0; k < H; k++)
        if (i & (1 << k))
          sum += h[k];
      for (int l = 0; l < W; l++)
        if (j & (1 << l))
          sum += w[l];

      for (int k = 0; k < H; k++) {
        for (int l = 0; l < W; l++) {
          if ((i & (1 << k)) && (j & (1 << l))) {
            sum -= (c[k][l] == '#' ? 1 : 0);
          }
        }
      }
      if ((all_black - sum) == K)
        res++;
    }
  }
  cout << res << endl;

