int cal(vector<string> board,int high,int wide,int k){
  int p = 0;
  for(int i = 0;i<high;i++){
    for(int j = 0;j<wide;j++){
      if(board[i][j]=='#'){
        p++;
      }
    }
  }
  if(p==k){
    return 1;
  }else{
    return 0;
  }
}

int yokobo(vector<string> board,int loc,int high,int wide,int k){
  if(loc==wide){
    return cal(board,high,wide,k);
  }
  int p = yokobo(board,loc+1,high,wide,k);
  for(int i = 0;i<high,i++){
    board[i][loc]='.';
  }
  return p+yokobo(board,loc+1,high,wide,k);

int tatebo(vector<string> board,int loc,int high,int wide,int l){
  if(loc == high){
    return yokobo(board,0,high,wide,k);
  }
  int p =  tatebo(board,loc+1,high,wide,k);
  for(int i = 0;i<wide;i++){
    board[loc][i]= '.';
  }
  return tatebo(board,loc+1,high,wide,k)+p;

