int main() {
  lint H, W, K;
  cin >> H >> W >> K;

  auto C = tensor(H, W, '$');
  for(lint i=0; i<H; i++)
  for(lint j=0; j<W; j++) {
    cin >> C[i][j];
  }

  lint ans = 0;
  lint base = 2;
  lint exp = H;
  for(lint poly = 0; poly < pow(base, exp); poly++) {
    lint tmp = poly;
    vector<lint> coef;
    for(lint i=0; i<exp; i++) {
      coef.push_back(tmp % base);
      tmp /= base;
    }

    lint base2 = 2;
    lint exp2 = W;
    for(lint poly2 = 0; poly2 < pow(base2, exp2); poly2++) {
      lint tmp2 = poly2;
      vector<lint> coef2;
      for(lint i=0; i<exp2; i++) {
        coef2.push_back(tmp2 % base2);
        tmp2 /= base2;
      }

      auto D = C;
      for(lint i=0; i<H; i++)
      for(lint j=0; j<W; j++) {
        if(coef[i] || coef2[j]) D[i][j] = '$';
      }

      lint counter = 0;
      for(lint i=0; i<H; i++)
      for(lint j=0; j<W; j++) {
        counter += (D[i][j] == '#');
      }

      if(counter == K) ans++;
    }
  }
  cout << ans << endl;
}

