  // 外側はH
  rep(bits_H, 1<<H){
    // hを選ぶかどうか
    bool flag_H[H];
    rep(h, H){
      // bits_Hに順列の情報が入っている
      if (bits_H & (1<<h)) flag_H[h] = true;
      else flag_H[h] = false;
    }
    // 内側はW
    rep(bits_W, 1<<W){
        // Fを破壊しないようにコピーGを毎回作成する
        char G[10][10];
        rep(h, H){
          rep(w, W){
            G[h][w] = F[h][w];
          }
        }

        // wを選ぶかどうか
        bool flag_W[W];
        rep(w, W){
          // bits_Wに順列の情報が入っている
          if (bits_W & (1<<w)) flag_W[w] = true;
          else flag_W[w] = false;
        }

      // bitsの情報に応じてコピーしたGを条件通りに書き換えていく
      rep(h, H){
        if (flag_H[h]==true)
        rep(w, W){
          G[h][w] = '-';
        }
      }
      rep(w, W){
        if (flag_W[w]==true)
        rep(h, H){
          G[h][w] = '-';
        }
      }

      // #の個数が条件に一致するかどうかを調べる
      int check = 0;
      rep(h, H){
        rep(w, W){
          if (G[h][w] == '#') check++;
        }
      }
      // もし条件に合っていればansを1増やす
      if (check==K) ans++;
    }
  }
  cout << ans << endl;
}

