int n, m, k, tot;
ll ans;

set<set<pair<int,int>>> check;
void rec(int black, vector<vector<int>> grid, set<pair<int,int>>& used) {
	if (black == k) {
		if (!check.count(used)) {
			++ans;
			check.insert(used);
		}
		return;
	}
	else if (black < k) {
		return;
	}

	set<pair<int,int>> new_used;
	for (int i = 0; i < n; ++i) {
		if (!used.count({0, i})) {
			new_used = used;
			new_used.insert({0, i});

			vector<vector<int>> new_grid = grid;
			int cnt = 0;
			for (int j = 0; j < m; ++j)
				if (new_grid[i][j])
					++cnt, new_grid[i][j] = 0;

			rec(black - cnt, new_grid, new_used);
		}
	}

	for (int j = 0; j < m; ++j) {
		if (!used.count({1, j})) {
			new_used = used;
			new_used.insert({1, j});

			vector<vector<int>> new_grid = grid;
			int cnt = 0;
			for (int i = 0; i < n; ++i)
				if (new_grid[i][j])
					++cnt, new_grid[i][j] = 0;

			rec(black - cnt, new_grid, new_used);
		}
	}
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(nullptr);

	cin >> n >> m >> k;

	vector<vector<int>> grid(n, vector<int>(m));
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < m; ++j) {
			char c;
			cin >> c;

			if (c == '#')
				++tot, grid[i][j] = 1;
		}
	}

	set<pair<int,int>> used;
	rec(tot, grid, used);
	cout << ans << "\n";
}

