char board[10][10], temp[10][10];


int main() {
    int H, W, K;
    scanf("%d%d%d", &H, &W, &K);

    REP (i, 0, H) {
        REP (j, 0, W) {
            scanf(" %c", &board[i][j]);
        }
    }

    int ways = 0;

    for (int mR = 0; mR < (1 << H); ++mR) {
        for (int mC = 0; mC < (1 << W); ++mC) {
            REP (i, 0, H) {
                REP (j, 0, W) {
                    temp[i][j] = board[i][j];
                }
            }

            REP (i, 0, H) {
                REP (j, 0, W) {
                    if ((mR & (1 << i)) || (mC & (1 << j))) {
                        temp[i][j] = '-';
                    }
                }
            }

            int cnt = 0;

            REP (i, 0, H) {
                REP (j, 0, W) { 
                    cnt += (int)(temp[i][j] == '#');
                }
            }

            if (cnt == K) {
                ++ways;
            }
        }
    }

    printf("%d\n", ways);
    return 0;
}

