void solve(){
	int r,c,k;
	cin >> r >> c >> k;
	string grid[r];
	for(int i =0;i<r;i++)
		cin >> grid[i];
	int ans = 0;
	int rows  = (1<<r)-1;
	int cols = (1<<c) - 1;
	string cg[r];
	for(int i = 0;i<rows;i++){
		for(int j =0;j<cols;j++){
			memcpy(cg,grid,sizeof(cg));
			int bit =0;
			int ci = i;
			vi to_do;
			while(ci>0){
				if(ci&1){
					to_do.pb(bit);
				}
				ci>>=1;
				bit++;
			}
			for(auto e:to_do){
				for(int x=0;x<c;x++)
					cg[e][x] = 'r';
			}

			int cj = j;
			bit = 0;
			to_do.clear();
			while(cj>0){
				if(cj&1)
					to_do.pb(bit);
				cj>>=1;
				bit++;
			}

			for(auto e:to_do){
				for(int x=0;x<r;x++)
					cg[x][e] = 'r';
			}
			int cur =0;
			for(int x = 0;x<r;x++){
				for(int y = 0;y<c;y++){
					if(cg[x][y]=='#')
						cur++;
				}
			}
			if(cur==k)
				ans++;
		}
	}
	cout << ans << endl;
}

