void solve() {
    int n, m, k;
    read(n, m, k);
    vector<vector<char>> a(n + 1, vector<char>(m + 1));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            read(a[i][j]);
        }
    }
    int cnt = 0;
    for (int bitrow = 0; bitrow < (1<<n); ++bitrow) {
        for (int bitcol = 0; bitcol < (1<<m); ++bitcol) {
            vector<vector<bool>> b(n + 1, vector<bool>(m + 1, false));
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= m; ++j) {
                    if ((1 & (bitrow>>(i - 1))) || (1 & (bitcol>>(j - 1)))) {
                        b[i][j] = true;
                    }
                }
            }
            int c = 0;
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= m; ++j) {
                    if (b[i][j] == false  && a[i][j] == '#') {
                        ++c;
                    }
                }
            }
            if (c == k) {
                ++cnt;
            }
        }
    }
    writeln(cnt);
}

