void solve(){
	int h, w, k, ans = 0;
	cin >> h >> w >> k;
	char mat[h][w];

	loop(i, h) loop(j, w) cin >> mat[i][j];

	for(int i = 0; i < (1 << (h + w)); ++i){
		int mask = i;
		set <int> r, c;
		int rc = 0, cc = 0;

		while(mask && (rc < h)){
			if((mask&1)){
				r.insert(rc);
			}
			mask >>= 1;
			rc++;
		}

		while(mask && (cc < w)){
			if((mask&1)){
				c.insert(cc);
			}
			mask >>= 1;
			cc++;
		}

		int count = 0;

		loop(x, h){
			loop(y, w){
				if(r.count(x)) continue;
				if(c.count(y)) continue;

				count += (mat[x][y] == '#');
			}
		}

		if(count == k) { 
			ans++; 
			//debug(i); 
		}
	}

	cout << ans;
}


