void f(int n, int k, int now, int cnt, vector<int> v) {
	if (now == n)return;
	f(n, k, now + 1, cnt, v);
	vector<int> a = v;
	a.push_back(now);
	if (cnt + 1 == k) {
		w.push_back(a);
		return;
	}
	f(n, k, now + 1, cnt + 1, a);
}

void ff(int n, int k, int now, int cnt, vector<int> v) {
	if (now == n)return;
	ff(n, k, now + 1, cnt, v);
	vector<int> a = v;
	a.push_back(now);
	if (cnt + 1 == k) {
		z.push_back(a);
		return;
	}
	ff(n, k, now + 1, cnt + 1, a);
}



