				int cnt2 = 0;
				for (auto x : xv) {
					for (int l = 0; l < W; l++) {
						if (c[x][l] == '#') cnt2++;
					}
				}
				if (sum - cnt2 == K) cnt++;
			} else if (xv.empty() && !yv.empty()) {
				int cnt3 = 0;
				for (auto y : yv) {
					for (int l = 0; l < H; l++) {
						if (c[l][y] == '#') cnt3++;
					}
				}
				if (sum - cnt3 == K) cnt++;
			} else {
				int cnt4 = 0;
				for (auto x : xv) {
					for (auto y : yv) {
						if (c[x][y] == '#') cnt4++;
					}
				}
