				for (auto y : yv) {
					for (int l = 0; l < H; l++) {
						if (c[l][y] == '#') cnt5++;
					}
				}
				if (sum - cnt5 + cnt4 == K) cnt++;
			}
		}
	}
	cout << cnt << '\n'; 
	return 0;
}

