void color_row(vector<string>& g, int r) {
  REP(j, m) g[r][j] = '.';
}

void color_col(vector<string>& g, int c) {
  REP(i, n) g[i][c] = '.';
}

int black(int rmask, int cmask, vector<string> g) {
  REP(i, n) if(rmask & (1 << i)) color_row(i);
  REP(j, m) if(cmask & (1 << j)) color_col(j);
  int res = 0;
  REP(i, n) REP(j, m) res += g[i][j] == '#';
  return res;
}

