int search(int num, std::vector<std::vector<int>> color) {
    if (num == H + W) {
        if (count(color) == K) {
            return 1;
        }
        return 0;
    }
    int cnt = 0;
    cnt += search(num + 1, color);
    if (num < H) {
        for (int x = 0; x < W; x++) {
            color[num][x] = 0;
        }
    } else {
        for (int y = 0; y < H; y++) {
            color[y][num - H] = 0;
        }
    }
    if (count(color) >= K) {
        cnt += search(num + 1, color);
    }
    return cnt;
}


