    for (int i=0; i<H; i++) p[i] = i;
    for (int i=0; i<W; i++) q[i] = i;
    for (int i=0; i<H; i++){
        for (int j=0; j<W; j++){
            cin >> c[i][j];
        }
    }
    vector<vector<int>> A, B;
    for (int bit = 0; bit < (1<<H); ++bit) {
        vector<int> S;
        for (int i = 0; i < H; ++i) {
            if (bit & (1<<i)) { // 列挙に i が含まれるか
                S.push_back(i);
            }
        }
        A.push_back(S);
    }
    for (int bit = 0; bit < (1<<W); ++bit) {
        vector<int> S;
        for (int i = 0; i < W; ++i) {
            if (bit & (1<<i)) { // 列挙に i が含まれるか
                S.push_back(i);
            }
        }
        B.push_back(S);
    }
    for (auto x : A){
        for (auto y : B){
            // initialize
            for (int i=0; i<H; i++){
                for (int j=0; j<W; j++){
                    f[i][j] = c[i][j];
                }
            }
            for (auto i : x){
                for (int j=0; j<W; j++) f[i][j] = 'r';
            }
            for (auto j : y){
                for (int i=0; i<H; i++) f[i][j] = 'r';
            }
            // count black
            int black = 0;
            for (int i=0; i<H; i++){
                for (int j=0; j<W; j++){
                    if (f[i][j] == '#'){
                        black += 1;
                    }
                }
            }
            if (black == K) ans += 1;
        }
    }

    cout << ans << endl;
    return 0;
}

