void solve(){
	int h, w, k;
	cin >> h >> w >> k;

	int grid[h][w];
	for(int i = 0; i < h; ++i){
		for(int j = 0; j < w; ++j){
			char ch; cin >> ch;
			grid[i][j] = ch == '#';
		}
	}

	int choices = 0;

	int copied[h][w];

	for(int m1 = 0; m1 < (1 << h); ++m1){
		for(int m2 = 0; m2 < (1 << w); ++m2){
			for(int i = 0; i < h; ++i){
				for(int j = 0; j < w; ++j){
					if(((m1 >> i) & 1) or ((m2 >> j) & 1))
						copied[i][j] = 0;
					else
						copied[i][j] = grid[i][j];
				}
			}

			int su = 0;
			for(int i = 0; i < h; ++i)
				su += accumulate(copied[i], copied[i] + w, 0);

			if(su == k) ++choices;
		}
	}

	cout << choices << "\n";
}

