ll countBlack(const vector<vector<char>>& c, ull skipH, ull skipW)
{
    ll count = 0;
    for(ll i = 0; i < c.size(); i++)
    {
        if((skipH >> i & 0x1) == 1)
        {
            continue;
        }

        for(ll j = 0; j < c[i].size(); j++)
        {
            if((skipW >> j & 0x1) == 1)
            {
                continue;
            }

            if(c[i][j] == '#')
            {
                count++;
            }
        }
    }

    return count;
}

