ll fastpow(ll a, ll b, ll m = mod) {
    ll res = 1;
    while (b > 0) {
        if (b & 1) res = mul(res, a, m);
        a = mul(a, a, m);
        b >>= 1;
    }
    return res;
}

// Works when m is prime - Fermat's little theorem
ll modinv(ll a, ll m = mod) {
    return fastpow(a, m - 2, m);
}


