void solve() {
    lli h, w, k;
    cin >> h >> w >> k;
    vector<string> store;
    string st;

    for (lli i = 0; i < h; i++) {
        cin >> st;
        store.pb(st);
    }

    lli ans = 0;
    lli a = pow(2, h);
    lli b = pow(2, w);

    for (lli i = 0; i < a; i++) {
        lli no = i, cnt = 0;
        vector<lli> rows;
        while (no > 0) {
            lli rem = no % 2;
            if (rem == 1) {
                rows.pb(cnt);
            }
            no /= 2;
            cnt++;
        }
        for (lli j = 0; j < b; j++) {
            vector<string> tmp = store;
            lli no = j, cnt = 0;
            vector<lli> cols;
            while (no > 0) {
                lli rem = no % 2;
                if (rem == 1) {
                    cols.pb(cnt);
                }
                no /= 2;
                cnt++;
            }

            for (auto val1 : rows) {
                for (int p = 0; p < w; p++) {
                    tmp[val1][p] = '.';
                }
            }
            for (lli p = 0; p < h; p++) {
                for (auto val2 : cols) {
                    tmp[p][val2] = '.';
                }
            }

            lli check = 0;
            for (lli ii = 0; ii < h; ii++) {
                for (lli jj = 0; jj < w; jj++) {
                    if (tmp[ii][jj] == '#') {
                        check++;
                    }
                }
            }
            if (check == k) {
                ans++;
            }
        }
    }

    cout << ans << endl;
}

