ll modPow(ll x, ll y) {
  if (y == 0) return 1;
  if (y == 1) return x;
  if (y % 2 == 0) return modPow((x * x) % MOD, y / 2);
  else return (x * modPow((x * x) % MOD, y / 2)) % MOD;
}

