int countBlack(const vector< vector<char>> &field, const int &yBits, const int &xBits)
{
  int count = 0;
  int x = 0;
  int y = 0;
  for(auto row:field){
    x = 0;
    for(auto val:row){
      if( (yBits&(1<<y))==0 && (xBits&(1<<x))==0 ){
        if(val=='#'){
          count++;
        }
      }
      x++;
    }
    y++;
  }
  return count;
}

