void dp(int i, int j){
	if(j==0){
		if(i==H-1){
			dp(0,1);
			v.push_back(make_pair(i,0));
			dp(0,1);
			v.pop_back();
		}else{
			dp(i+1,0);
			v.push_back(make_pair(i,0));
			dp(i+1,0);
			v.pop_back();
		}
	}else if(j==1){
		if(i==W-1){
			dp(0,2);
			v.push_back(make_pair(i,1));
			dp(0,2);
			v.pop_back();
		}else{
			dp(i+1,1);
			v.push_back(make_pair(i,1));
			dp(i+1,1);
			v.pop_back();
		}
	}else{
		int curr=0;
		for(int i=0; i<v.size(); i++){
			if(v[i].second==0){
				curr+=row[v[i].first];
				for(int j=i+1; j<v.size(); j++){
					if(v[j].second==1){
						curr-=gabungan[v[i].first][v[j].first];
					}
				}
			}else{
				curr+=column[v[i].first];
			}
		}
		if(curr==(total-K)){
			solve++;
		}
	}
}

