int main() {
  int H, W, K; cin >> H >> W >> K;
  int C[H][W];
  for (int i = 0; i < H; i++) {
    string x; cin >> x;
    for (int j = 0; j < W; j++) {
      int y = x.at(j) == '#' ? 1 : 0;
      C[i][j] = y;
    }
  }

  int ans = 0;

  // For some reason, I falsely believed that O(2^(H+W)) where H + W <= 12 was not computable in the given time
  // Under pressure, I quickly assumed this, confusing 2^12 with 1e12
  // If I had done one check to see that 2^12 = 4096, which is easily computable with brute force bitwise search, then it would have made the difference between heaven and hell

  // O(HW * 2^(H + W))
  int full = (1 << (H + W)) - 1;
  for (int i = 0; i < full; i++) {
    // The bits of the last W digits represent the status of the columns while the next H digits represent the status of the rows 
    int value = 0;
    for (int r = 0; r < H; r++) {
      for (int c = 0; c < W; c++) {
        if ((i & (1 << c)) | (i & (1 << (r + W)))) {
          // Either the row or column that the element belongs to is activated - do not count
          continue;
        }
        value += C[r][c];
      }
    }

    if (value == K) ans++;
  }

  cout << ans << endl;
}

