void trace(const string &title, const grid_t &grid) {
  cout << title << "\n";
  for(int i = 1; i <= grid.size(); ++i) {
    for(int j = 1; j <= grid[i - 1].size(); ++j) {
      cout << grid[i - 1][j - 1];
    }
    cout << "\n";
  }

  cout << "\n";
}

int main() {
  int m, n, k;
  cin >> m >> n >> k;

  grid_t grid(m, row_t(n, ' '));
  for(int i = 1; i <= m; ++i) {
    for(int j = 1; j <= n; ++j) {
      cin >> grid[i - 1][j - 1];
    }
  }

  int match_cnt = 0;
  for(int i = 0; i < pow(2, m); ++i) {
    bitset<8> bs_i(i);
    auto bs_i_str = bs_i.to_string();
    reverse(bs_i_str.begin(), bs_i_str.end());
    //cout << "i: " << i << " " << bs_i_str << "\n";

    //trace("grid", grid);

    for(int j = 0; j < pow(2, n); ++j) {
      bitset<8> bs_j(j);
      auto bs_j_str = bs_j.to_string();
      reverse(bs_j_str.begin(), bs_j_str.end());      
      //cout << "\tj: " << j << " " << bs_j_str << "\n";

      grid_t grid_copy(grid);
      for(int p = 0; p < bs_i_str.size(); ++p) {
        if(bs_i_str[p] == '1') {
          for(int q = 1; q <= grid_copy[p].size(); ++q) {
            grid_copy[p][q - 1] = '*';
          }
        }
      }

      for(int p = 0; p < bs_j_str.size(); ++p) {
        if(bs_j_str[p] == '1') {
          for(int q = 1; q <= grid_copy.size(); ++q) {
            grid_copy[q - 1][p] = '*';
          }
        }
      }

      //trace("grid_copy", grid_copy);

      int red_cnt = 0;
      for(int p = 1; p <= grid_copy.size(); ++p) {
        for(int q = 1; q <= grid_copy[p - 1].size(); ++q) {
          if(grid_copy[p - 1][q - 1] == '#') {
            ++red_cnt;
          }
        }
      }
      if(red_cnt == k) {
        cout << ">>>>matched\n";
        ++match_cnt;
      }
    }
  }

  cout << match_cnt << "\n";
  return 0;
}

