constexpr ll MOD = 1e9 + 7;

inline ll pow_mod( ll a, ll b, ll mod = MOD) {
    ll res = 1; a %= mod; assert(b >= 0);
    for(;b;b>>=1) {
        if(b&1) res = (res * a) % mod;
        a = (a * a) % mod;
    }
    return res;
}

int h, w, k;

int solve(const vector<string>& mat) {
    int res = 0;
    for(int i = 0; i < (1 << h); ++i)
    {
        for(int j = 0; j < (1 << w); ++j)
        {
            int count_black = 0;
            for(int x = 0; x < h; ++x) {
                for(int y = 0; y < w; ++y) {
                    int banned = 0;
                    if(i & (1 << x)) banned++;
                    if(j & (1 << y)) banned++;
                    if(banned == 0 && mat[x][y] == '#') count_black++;
                }
            }
            if(count_black == k) res++;
        }
    }
    return res;
}

