int power(int a, int r) {
  int res = 1;
  while (r > 0) {
    if (r & 1) res *= a;
    a *= a;
    r >>= 1;
  }
  return res;
}

int d2b(int n) {
  int m = 0;
  for (int i = 0; n > 0; i++) {
    m = m + n % 2 * power(10, i);
    n = n / 2;
  }
  return m;
}

