    int H = h_select.size();
    int W = w_select.size();

    for(size_t i=0;i<h_select.size();i++){
        h_select[i] = 0;
    }
    for(size_t j=0;j<w_select.size();j++){
        w_select[j] = 0;
    }
    if(num==0){
        return;
    }

    int last = 1;
    for(int i=0;i<(H+W)-1;i++){
        last *=2;
    }

    for(int x=last,idx=0;x!=0;x/=2,idx++){
        if(num>=x){
            if(idx<H){
                h_select[idx] = 1;
            }else{
                w_select[idx-H] = 1;
            }
            num-=x;
        }
    }

    return;
}



