void dfs(ll level){
    ll blknum=0;;
    if(level == 0){
        // 計算
        REP(hi,h){
            REP(wi,w){
                if(selected[hi] == 1){
                    continue;
                }
                if(selected[wi + h] == 1){
                    continue;
                }
                if(info[hi][wi] == '#'){
                    blknum++;
                }
            }
        }

        if(blknum == k){
            ans++;
        }
        return;
    }

    selected[ (h+w) -level ] = 1;
    dfs(level-1);
    selected[ (h+w) -level ] = 0;
    dfs(level-1);

    return;
}

int main(void){
    cin >> h >> w >> k;
    REP(i, h){
        REP(j,w){
            char tmp;
            cin >> tmp;
            info[i][j] = tmp;
        }
    }
    dfs(h+w);
    cout << ans << endl;
    return 0;
}

