#include <bits/stdc++.h>
using namespace std;

int H, W, K;
char c[10][10];
bool visited[100][100];
int curr, curc;
int ans;

bool check() {
	int cur = 0;

	for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) if (c[i][j] == '#') cur++;
	if (cur == K) {
        //printf("%d %d\n", curr, curc);
	}
	return cur == K;
}

int dp(int row, int col) {
	int cur = 0;
	if (row >= H && col >= W) {
		if (!visited[curr][curc] && check()) {
            visited[curr][curc] = true;
            return 1;
		}
		else return 0;
	}
	if (row < H) {
		char orig[W];
		for (int i = 0; i < W; i++) {
			orig[i] = c[row][i];
			c[row][i] = '-';
		}
		curr |= 1 << row;
		cur += dp(row + 1, col);
		for (int i = 0; i < W; i++) {
			c[row][i] = orig[i];
		}
		curr &= ~(1 << row);
		cur += dp(row + 1, col);
	}
	if (col < W) {
		char orig[H];
		for (int i = 0; i < H; i++) {
			orig[i] = c[i][col];
			c[i][col] = '-';
		}
		curc |= 1 << col;
		cur += dp(row, col + 1);
		for (int i = 0; i < H; i++) {
			c[i][col] = orig[i];
		}
		curc &= ~(1 << col);
		cur += dp(row, col + 1);
	}
	return cur;
}

int main() {
	scanf("%d%d%d", &H, &W, &K);
	for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) scanf(" %c", &c[i][j]);
	ans = dp(0, 0);
	printf("%d\n", ans);
	return 0;
}

