lg ans,n,m,k;;
void sol(vector<vector<lg>>& gr,vector<lg> rows,vector<lg> cols,lg i,lg j,lg now)
{
    if(now<k)
    {
        return ;
    }
    if(i==n)
    {
        if(j==m)
        {
            if(now==k) ans++;
        }
        else
        {
            sol(gr,rows,cols,i,j+1,now);
            sol(gr,rows,cols,i,j+1,now-cols[j]);
        }
    }
    else
    {
        sol(gr,rows,cols,i+1,j,now);
        for(lg l=0;l<m;l++)
        {
            if(gr[i][l]==1) cols[l]--;
        }
        sol(gr,rows,cols,i+1,j,now-rows[i]);
    }
}

