// 選択
int
fSel(
	int piRow					// <I> 行
	, int piCol					// <I> 列
	, char *pcpRow				// <I> 選択行
	, char *pcpCol				// <I> 選択列
)
{
	int i, j;

	// 行選択
	if (piRow < siH) {

		// あり
		pcpRow[piRow] = D_ON;
		fSel(piRow + 1, piCol, pcpRow, pcpCol);

		// なし
		pcpRow[piRow] = D_OFF;
		fSel(piRow + 1, piCol, pcpRow, pcpCol);
	}

	// 列選択
	else if (piCol < siW) {

		// あり
		pcpCol[piCol] = D_ON;
		fSel(piRow, piCol + 1, pcpRow, pcpCol);

		// なし
		pcpCol[piCol] = D_OFF;
		fSel(piRow, piCol + 1, pcpRow, pcpCol);
	}

	// 選択終了
	else {

		// マス - セット
		char lc2Mass[D_SIZE_MAX][D_SIZE_MAX];
		memcpy(lc2Mass, sc2Mass, sizeof(lc2Mass));
		for (i = 0; i < siH; i++) {
			if (pcpRow[i] == D_ON) {
				for (j = 0; j < siW; j++) {
					lc2Mass[i][j] = 0;
				}
			}
		}
		for (i = 0; i < siW; i++) {
			if (pcpCol[i] == D_ON) {
				for (j = 0; j < siH; j++) {
					lc2Mass[j][i] = 0;
				}
			}
		}

		// 黒数 - 取得
		int liBCnt = 0;
		for (i = 0; i < siH; i++) {
			for (j = 0; j < siW; j++) {
				if (lc2Mass[i][j] == '#') {
					liBCnt++;
				}
			}
		}

		// パターン数 - 加算
		if (liBCnt == siBCnt) {
			siPCnt++;
		}
	}

	return 0;
}

