    if (h_hiddens[i]) continue;
    for (j = 0; j < W; j++) {
      if (w_hiddens[j]) continue;
      if (Matrix[i * W + j] == '#') count++;
    }
  }
  return count;
}

void count_case (int h_hiddens[], int w_hiddens[], int h_progress, int w_progress) {
  int count = count_black(h_hiddens, w_hiddens);

  if (w_progress < W) {
    count_case(h_hiddens, w_hiddens, h_progress, w_progress + 1);
    int w_hiddens_clone[W];
    memcpy(w_hiddens_clone, w_hiddens, sizeof(int) * W);
    w_hiddens_clone[w_progress] = 1;
    count_case(h_hiddens, w_hiddens_clone, h_progress, w_progress + 1);
  } else if (h_progress < H) {
    count_case(h_hiddens, w_hiddens, h_progress + 1, w_progress);
    int h_hiddens_clone[W];
    memcpy(h_hiddens_clone, h_hiddens, sizeof(int) * H);
    h_hiddens_clone[h_progress] = 1;
    count_case(h_hiddens_clone, w_hiddens, h_progress + 1, w_progress);
  } else if (count == K) {
    answer += 1;
  }
}

