int pow2(int n){
  int a = 1;
  for(int i = 0;i < n;i++){
    a = a*2;
  }
  return a;
}

void makeBinary(int num, int digit, int* array[digit]) {
  int copiedNum = num;
  for (int i = digit - 1; i >= 0; i++) {
  	if (copiedNum >= pow2(i)) {
  	  array[i] = 1;
  	  copiedNum -= pow2(i);
	} else {
  	 array[i] = 0;
    }
  }
}


