    const uint64_t wLim = (UINT64_C(0x1) << W);
    uint64_t r = 0;

    for (uint64_t h = 0; h < hLim; h++) {
        for (uint64_t w = 0; w < wLim; w++) {
            size_t cnt = 0;
            for (uint64_t sh = 0; sh < H; sh++) {
                for (uint64_t sw = 0; sw < W; sw++) {
                    if (((h >> sh) & UINT64_C(0x1)) == 0 && ((w >> sw) & UINT64_C(0x1)) == 0 && c[sh][sw] == '#') {
                        cnt++;
                    }
                }
            }

            if ((uint64_t)cnt == K) {
                r++;
            }
        }
    }

    printf("%"PRIu64, r);

    return 0;
}

