    int matrix[w][h];
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            char c;
            scanf("%c", &c);
            matrix[x][y] = c == '#';
        }
    }

    int ans = 0;

    //チェック
    for (int numY = 0; numY < powK(2, h); numY++) {
        int binaryY[h];
