  }
  return a;
}

void makeBinary(int num, int digit, int* array[digit]) {
  int copiedNum = num;
  for (int i = digit - 1; i >= 0; i++) {
  	if (copiedNum >= pow2(i)) {
  	  array[i] = 1;
  	  copiedNum -= pow2(i);
	} else {
  	 array[i] = 0;
    }
  }
}


