int powK(int num1, int num2) {
    int ans = 1;

    for (int i = 0; i < num2; i++) {
        ans = ans * num1;
    }

    return ans;
}

void makeBinaryNum(int num, int digit, int array[digit]) {
    int copiedNum = num;

    for (int i = digit - 1; i >= 0; i--) {
        if (powK(2, i) <= copiedNum) {
            array[i] = 1;
            copiedNum -= powK(2, i);
        } else {
            array[i] = 0;
        }
    }
}

