fun createEntryList(len: Int): List<String> {
    val entries = mutableListOf<String>()
    val bfs = ArrayDeque<String>()
    bfs.addLast("0")
    bfs.addLast("1")

    while(bfs.isNotEmpty()) {
        val item = bfs.removeFirst()

        if (item.length == len) {
            entries.add(item)
            continue
        }

        bfs.addLast("${item}0")
        bfs.addLast("${item}1")
    }

    return entries
}

