import java.util.*
fun getValue(from:Int, to:Int) : Long{
    var result = 0L
    repeat(36){
        if(35 - it <= to && 35 - it >= from){
            result = result.shl(1) or 0
        }
        else {
            result = result.shl(1) or 1
        }
    }
    return result
}

fun getVertical(column : Int, h : Int, w : Int) : Long {
    var result =0L
    repeat(h*w){
        val modValue = it % w
        if(modValue == column){
            result  = result.shl(1) or 0
        }
        else {
            result = result.shl(1) or 1
        }
    }
    return result
}

fun countOne(value : Long) : Int {
    var result = 0
    var countValue = value

    while(countValue > 0){
        val checkValue = countValue.and(1L)
        if(checkValue > 0){
            result += 1
        }
        countValue = countValue.shr(1)
    }
    return result
}

