fun bitFS(S: String): Long {
    val N = S.length
    var res = 0L
    for (p in 0 until (1L shl N)) {
        var ptn = p
        if ((ptn shr (N-1)) and 1 == 0L) continue
        var sum = 0L
        var term = 0L
        for (i in 0 until N) {
            term += S[i] - '0'
            if ((ptn and 1) == 1L) {
                sum += term
                term = 0
            } else {
                term *= 10
            }
            ptn = ptn shr 1
        }
        res += sum
    }
    return res
}


