fun solve() {
    val (h, w, k) = readIntegerList()
    val grid = Array(h) { br.readLine()!!.toCharArray() }
    val numOfBlack = grid.fold(0) { acc, line -> acc + line.count { it == '#' } }

    var ans = 0
    for (state in 0 until (1 shl h)) {
        for (state2 in 0 until (1 shl w)) {
            var tmp = numOfBlack
            for (i in 0 until h) {
                for (j in 0 until w) {
                    if (((((state shr i) and 1) == 1) || ((state2 shr j) and 1) == 1)
                        && grid[i][j] == '#') {
                        tmp--
                    }
                }
            }

            if (tmp == k) ans++
        }
