fun PrintWriter.solve(sc: FastScanner) {
    val h = sc.nextInt()
    val w = sc.nextInt()
    val k = sc.nextInt()
    val s = Array(h) { Array(w) { '.' } }
    for (i in 0 until h) {
        val _s = sc.nextLine()
        for (j in 0 until w) {
            s[i][j] = _s[j]
        }
    }
    var ans = 0L
    for (i in 0 until 1.shl(h)) {
        for (j in 0 until 1.shl(w)) {
            val r = Array(h) { false }
            val c = Array(w) { false }
            for (x in 0 until h) {
                if ((1.shl(x) and i) != 0) {
                    r[x] = true
                }
            }
            for (y in 0 until w) {
                if ((1.shl(y) and j) != 0) {
                    c[y] = true
                }
            }
            var count = 0
            for (a in 0 until h) {
                for (b in 0 until w) {
                    if (s[a][b] == '#' && !r[a] && !c[b]) {
                        count++
                    }
                }
            }
            if (count == k) {
                ans++
            }
        }
    }
    println(ans)
}

