}

fun rec_bit(seeds: List<Int>, pos: Int = 0, patterns: Array<Int> = emptyArray()): Array<Array<Int>> {
    return if (pos < seeds.size) {
        val res1 = rec_bit(seeds, pos + 1, patterns + seeds[pos])
        val res2 = rec_bit(seeds, pos + 1, patterns)
        res1 + res2
    } else {
        arrayOf(patterns)
    }
}

fun Array<CharArray>.transposed(): Array<CharArray> {
    val A = Array(this[0].size) { CharArray(this.size) }
    for (y in this.indices) {
        for (x in this[0].indices) {
            A[x][y] = this[y][x]
        }
    }
    return A
}

