fun createEntryList(len: Int): List<String> {
    val entries = mutableListOf<String>()
    val bfs = Stack<String>()
    bfs.push("0")
    bfs.push("1")

    while(bfs.isNotEmpty()) {
        val item = bfs.pop()

        if (item.length == len) {
            entries.add(item)
            continue
        }

        bfs.push("${item}0")
        bfs.push("${item}1")
    }

    return entries
}

