					for(int jj = 0; jj < w; jj++) {

						if((i >> ii & 1) == 1) {
							// 赤く塗りつぶすと考える
							continue;
						}

						if((j >> jj & 1) == 1) {
							// 赤く塗りつぶすと考える
							continue;
						}

						// 塗り潰されなかった全マスのii jj の1つ1つのマスが＃ならインクリメント
						if(c[ii][jj] == '#')count_temp++;	

					}

				}

				// 2^h*w パターンの各々の回で求める#の数ならインクリメント
				if(count_temp == k) ans++;

			}

		}

		System.out.println(ans);

	}

}

