    private void solve() {
        int H = sc.nextInt();
        int W = sc.nextInt();
        int K = sc.nextInt();

        String[] S = new String[H];
        for (int i = 0; i < H; i++) {
            S[i] = sc.next();
        }

        int mH = 1 << H;
        int mW = 1 << W;
        int ans = 0;
        for (int i = 0; i < mH; ++i) {
            for (int j = 0; j < mW; ++j) {
                char[][] C = new char[H][W];
                for (int r = 0; r < H; ++r) {
                    for (int c = 0; c < W; ++c) {
                        C[r][c] = S[r].charAt(c);
                    }
                }

                for (int r = 0; r < H; ++r) {
                    for (int c = 0; c < W; ++c) {
                        if ((i & (1 << r)) > 0 || (j & (1 << c)) > 0) {
                            C[r][c] = 'R';
                        }
                    }
                }

                int cnt = 0;
                for (int r = 0; r < H; r++) {
                    for (int c = 0; c < W; c++) {
                        if (C[r][c] == '#') {
                            ++cnt;
                        }
                    }
                }
                if (cnt == K) {
                    ++ans;
                }
            }
        }
        out.println(ans);
    }

