void solve()  throws IOException{
	int h=in.readInt();
	int w=in.readInt();
	int k=in.readInt();
	int numblack=0;
	boolean[][] black=new boolean[h][w];
	int[] roundh=new int[h];
	int[] roundw=new int[w];
	for (int i=0;i<h;++i) {
		String s=in.readString();
		for (int j=0;j<w;++j) {
			if (s.charAt(j)=='#') {
				black[i][j]=true;
				numblack++;
			}else
				black[i][j]=false;
		}
	}
	int ans=0;
	int rh=0;
	int rw=0;
	int nh=(int)Math.pow(2, h);
	int nw=(int)Math.pow(2, w);
	for (int ih=0;ih<nh;++ih) {
		rh++;
		int x=ih;
		int curr=h-1;
		while (x!=0) {
			int d= x % 2;
			if (d==1) {
				roundh[curr]=rh;
			}
			x/=2;
			curr--;
		}
		int leftblack=numblack;
		for (int i=0;i<h;++i) {
			if (roundh[i]==rh) {
				for (int j=0;j<w;++j) {
					if (black[i][j]) {
						leftblack--;
					}
				}
			}
		}
		for (int iw=0;iw<nw;++iw) {
			rw++;
			 x=iw;
			curr=w-1;
			while (x!=0) {
				int d= x % 2;
				if (d==1) {
					roundw[curr]=rw;
				}
				x/=2;
				curr--;
			}
			int leftblack2=leftblack;
			for (int i=0;i<h;++i) {
				if (roundh[i]!=rh) {
					for (int j=0;j<w;++j) {
						if (black[i][j] && roundw[j]==rw) {
							leftblack2--;
						}
					}
				}
			}
			if (leftblack2==k) {
				ans++;
			}
		}
	}
	out.printLine(ans);

}

