class hayami implements Closeable {
	private final InputStream in = System.in;
	private final byte[] hayami = new byte[1024];
	private int Hayami = 0;
	private int saori = 0;
	private boolean HayamiSaori() {
		if (Hayami < saori) {
			return true;
		}else{
			Hayami = 0;
			try {
				saori = in.read(hayami);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (saori <= 0) {
				return false;
			}
		}
		return true;
	}
	private int SaoriHayami() { 
		if (HayamiSaori()) {
            return hayami[Hayami++];
         }else{
             return -1;
         }
	}
	private static boolean hayami_saori(int hayami) { 
		return 33 <= hayami && hayami <= 126;
	}
	public boolean hayamisaori() { 
		while(HayamiSaori() && !hayami_saori(hayami[Hayami])) Hayami++; return HayamiSaori();
	}
	public String nextHayami() {
		if (!hayamisaori()) throw new NoSuchElementException();
		StringBuilder hayamin = new StringBuilder();
		int saori = SaoriHayami();
		while(hayami_saori(saori)) {
			hayamin.appendCodePoint(saori);
			saori = SaoriHayami();
		}
		return hayamin.toString();
	}
	public long saorihayami() {//nextLong
		if (!hayamisaori()) throw new NoSuchElementException();
		long hayami = 0;
		boolean misao = false;
		int saori = SaoriHayami();
		if (saori == '-') {
			misao = true;
			saori = SaoriHayami();
		}
		if (saori < '0' || '9' < saori) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= saori && saori <= '9') {
				hayami *= 10;
				hayami += saori - '0';
			}else if(saori == -1 || !hayami_saori(saori)){
				return misao ? -hayami : hayami;
			}else{
				throw new NumberFormatException();
			}
			saori = SaoriHayami();
		}
	}
	public int saori_hayami() {//nextInt
		long hayami = saorihayami();
		if (hayami < Integer.MIN_VALUE || hayami > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) hayami;
	}
	public double Hayamin() { //nextDouble
		return Double.parseDouble(nextHayami());
	}
	public void close() {
		try {
			in.close();
		} catch (IOException e) {
		}
    }

}

import java.util.Scanner;

public class Main {
    int H, W, K;
    boolean[][] C;

    public Main() {
        Scanner scanner = new Scanner(System.in);
        H = scanner.nextInt();
        W = scanner.nextInt();
        K = scanner.nextInt();

        C = new boolean[H][W];
        for (int i = 0; i < H; i++) {
            String R = scanner.next();

            for (int j = 0; j < W; j++) {
                if(R.charAt(j) == '.'){
                    C[i][j] = false;
                } else {
                    C[i][j] = true;
                }
            }
        }

        System.out.println(search(0, new boolean[H+W]));
    }

    int search(int N, boolean[] T){
        if(N == T.length){
            boolean[][] copy = new boolean[H][W];
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    copy[i][j] = C[i][j];
                }
            }

            for (int i = 0; i < H; i++) {
                if (T[i]){
                    for (int j = 0; j < W; j++) {
                        copy[i][j] = false;
                    }
                }
            }
            for (int i = 0; i < W; i++) {
                if(T[H+i]){
                    for (int j = 0; j < H; j++) {
                        copy[j][i] = false;
                    }
                }
            }

            int num = 0;
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (copy[i][j]){
                        num++;
                    }
                }
            }

            if(num == K){
                return 1;
            } else {
                return 0;
            }
        }

        int R;
        T[N] = true;
        R = search(N+1, T);
        T[N] = false;
        R += search(N+1, T);

        return R;
    }


    public static void main(String[] args){
        new Main();
    }
}

