	static int cnt;
	static int ways = 0;

	public static void main(String[] args) throws IOException {
		H = in.iscan(); W = in.iscan(); K = in.iscan();
		grid = new char[H][W];
		for (int i = 0; i < H; i++) grid[i] = in.sscan().toCharArray();
		// try all combinations of rows and columns
		sz1 = 1 << H; sz2 = 1 << W;
		for (int i = 0; i < sz1; i++) {
