                for(int l=0; l<h;l++){
                    if((i >> l&1)==1){
                        continue;
                    }
                    for(int m =0; m<w;m++){
                        if((j>>m&1)==1){
                            continue;
                        }
                        if(c[l][m] == '#'){
                            tempCnt++;
                        }
                    }
                }
                if(tempCnt == k){
                    ans++;
                }
            }
        }
        System.out.println(ans);
    }
}

