public class Main {
  private static int count(int h, int w, int bitset, char[][] cs) {
    int c = 0;
    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        if (((bitset >> (i + w)) & 1) == 1) {
          continue;
        }
        if (((bitset >> j) & 1) == 1) {
          continue;
        }

        if (cs[i][j] == '#') {
          c++;
        }
      }
    }
    return c;
  }

  private static int solve(int h, int w, int k, char[][] cs) {
    int answer = 0;
    for (int bitset = 0; bitset < (1 << (h + w)); bitset++) {
      if (count(h, w, bitset, cs) == k) {
        answer++;
      }
    }
    return answer;
  }

  private static void execute(ContestReader reader, ContestWriter out) {
    int h = reader.nextInt();
    int w = reader.nextInt();
    int k = reader.nextInt();
    char[][] cs = reader.nextCharArray(h);
    out.println(solve(h, w, k, cs));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    ContestWriter out = new ContestWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

