      int existBlack = 0;
      int ansCount = 0;
      int[][] inputList = new int[row][column];
      String input = "";
      for (int i = 0; i < row; i++) {
        input = sc.next();
        for (int x = 0; x < column; x++) {
          inputList[i][x] =
            parseI(parseS(input.charAt(x)).replace(".", "0").replace("#", "1"));
        }
      }

      for (int i = 0; i < (1 << row); i++) {
        for (int x = 0; x < (1 << column); x++) {

          for (int chRownum = 0; chRownum < row; chRownum++) {
            for (int chColNum = 0; chColNum < column; chColNum++) {
              if (inputList[chRownum][chColNum] == 0) {
                continue;
              } else if (parseS(
                String.format("%06d", parseI(Integer.toBinaryString(x)))
                  .charAt(chColNum)).equals("1")) {
                    continue;
                  } else
                if (parseS(
                  String.format("%06d", parseI(Integer.toBinaryString(i)))
                    .charAt(chRownum)).equals("1")) {
                      continue;
                    }
              existBlack++;
            }
          }
          if (existBlack == checkBlackCount) ansCount++;
