    boolean[][] cd = new boolean[H][W];
    for (int i =0; i<H; i++) {
      for (int j =0; j<W; j++) {
        if(c[i].charAt(j) == '.') cc[i][j] = false;
        if(c[i].charAt(j) == '#') cc[i][j] = true;
      }
    }
    for (int k =0; k<Math.pow(2,H+W); k++) {
      String bit = Integer.toBinaryString(k);//iをビットに変換
