      for (int i =0; i<H+W-length; i++) {
        bit = "0" + bit;
      }
      int count =0;
      for (int i =0; i<H; i++) {
        for (int j =0; j<W; j++) {
          cd[i][j] = cc[i][j];
        }
      }
      for (int i =0; i<H; i++) {
        if (bit.charAt(i) == '1') {
          for (int j =0; j<W; j++) {
            cd[i][j] = false;
          }
        }
      }
      for (int i =H; i<W+H; i++) {
