public class Main {

	static ArrayList<String>gyou = new ArrayList<String>();
	static ArrayList<String>retu = new ArrayList<String>();


	public static void main(String[]args) {
		try(Scanner scan = new Scanner(System.in)){

			int H = scan.nextInt();
