			for(int i = 0;i<H;i++) {
				s[i] = scan.next();
				c[i] = s[i].toCharArray();
			}

			int count = 0;


			for(int i = 0;i<=H;i++) {
				if(i!=0) {
				for(int z = 0;z<=H-i;z++) {
					gyou(i-1,H,z,String.valueOf(z));
				}
				}
			}

			for(int i = 0;i<=W;i++) {
				if(i!=0) {
				for(int z = 0;z<=W-i;z++) {
