					String R = "";
					if(i!=-1)G = gyou.get(i);
					if(j!=-1)R = retu.get(j);
					char[][]cha = new char[H][W];
					for(int k = 0;k<H;k++) for(int o = 0;o<W;o++)cha[k][o]=c[k][o];

					for(int w = 0;w<=G.length();w++) {
						int q = -1;
						if(w!=0) {
						 q=G.charAt(w-1)-'0';
						for(int x = 0;x<W;x++) cha[q][x] = '+';
						}
						for(int z = 0;z<=R.length();z++) {
							int d = -1;
							if(z!=0) {
								d=R.charAt(z-1)-'0';
								for(int xr = 0;xr<H;xr++) cha[xr][d] = '+';
