					if(co==K)count++;



				}

			}


			System.out.println(count);






		}


	}




	private static void gyou(int count,int H,int k,String S) {//count個選ぶ
		if(count!=0) {
			for(int i =k+1;i<=H-count;i++) {
				gyou(count-1,H,i,S+String.valueOf(i));
				}
		}else {
			//System.out.println(S);



			gyou.add(S);
			}
