	private static void retu(int count,int W,int k,String S) {//count個選ぶ
		if(count!=0) {
			for(int i =k+1;i<=W-count;i++) {
				retu(count-1,W,i,S+String.valueOf(i));
				}
		}else {
			//System.out.println(S);
			retu.add(S);
			}
	}




}

