                        if(sel[j + h] == 0 && c[i][j] == '#'){
                            num++;
                        }
                    }
                }
            }
            if(num == k){
                count++;
            }
            sel = succ(sel);
            num = 0;
        }

        System.out.println(count);
        sc.close();
    }

    static int[] succ(int[] bin){
        int i = 0;
        while(i < bin.length && bin[i] != 0){
            bin[i] = 0;
            i++;
        }
        if(i < bin.length){
            bin[i] = 1;
        }

        return bin;
    }
}

