public class Main {

    public int findChoices(char[][] grid, int k) {
        int ans = 0;
        for (int mask = 0; mask < 1 << (grid.length + grid[0].length); mask++) {
            int count = 0;
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[i].length; j++) {
                    if (grid[i][j] != '#') {
                        continue;
                    }
                    if ((mask & (1 << i)) != 0 || (mask & (1 << (grid.length + j))) != 0) {
                        continue;
                    }
                    count++;
                }
            }
            if (count == k) {
                ans++;
            }
        }
        return ans;
    }

