		int W = stdIn.nextInt();
		int K = stdIn.nextInt();
		char[][] c = new char[H][W];
		ArrayList<String> s = new ArrayList<String>();

		for(int i = 0; i < H; i ++) {
			s.add(stdIn.next());
		}

		for(int i = 0; i < H; i ++) {
			for(int j = 0; j < W; j ++) {
				c[i][j] = s.get(i).toCharArray()[j];
			}
		}

		int h = (int) Math.pow(2, H) - 1;
		int w = (int) Math.pow(2, W) - 1;

		int ans = 0;

		for(int i = h; 0 <= i; i --) {
			String hBin = String.format("%" + H + "s", Integer.toBinaryString(i)).replace(" ", "0");
			for(int j = w; 0 <= j; j --) {
