		FastScanner sc = new FastScanner(System.in);

		int h = sc.nextInt();
		int w = sc.nextInt();
		int k = sc.nextInt();

		boolean[][] c = new boolean[h][w];

		for(int i=0;i<h;i++){
			String s = sc.next();
			for(int j=0;j<w;j++){
				if(s.charAt(j) == '.'){
					c[i][j] = false;
				}
				else c[i][j] = true;
			}
		}

		boolean[] d = new boolean[h+w];
		int ans = solve_abc173_c_rec(0,0,h,w,d,c,k);
		System.out.println(ans);
	}

	public static int solve_abc173_c_rec(int i, int j, int h,int w, boolean[] d, boolean[][] c, int k){
		int ret = 0;

		if(i ==h && j == w){
			int count = 0;

			for(int x=0;x<h;x++){
				if(!d[x]) continue;
				for(int y=0;y<w;y++){
					if(d[h+y] && c[x][y]) count++;
//					System.out.println(i+"\t"+j+"\t"+x+"\t"+y);
				}
			}

			if(count == k) ret += 1;
			return ret;
		}

		if(i < h){
			d[i] = true;
			ret += solve_abc173_c_rec(i+1, j, h, w, d,c,k);

			d[i] = false;
			ret += solve_abc173_c_rec(i+1, j, h, w, d,c,k);
		}
		else if(j < w){
			d[h+j] = true;
			ret += solve_abc173_c_rec(i, j+1, h, w, d,c,k);

			d[h+j] = false;
			ret += solve_abc173_c_rec(i, j+1, h, w, d,c,k);
		}

		return ret;
	}
}

