                if (c[row][col] == "#") {
                    black = black + 1;
                }
                c[row][col] = sc.next();
            }
        }
        int sum = solve(c, black, k);

        System.out.println(sum);

    }

    public static int solve(String[][] c, int black, int k) {
        int sum=0;

        for (int row = 0; row < c.length; row++) {
            for (int col = 0; col < c[0].length; col++) {
                if (c[row][col] == "#") {
                    black--;
                    if (black == k) {
                        sum++;
                    }
                }
                c[row][col] = "k";
            }
        }
        return sum;
    }
}

