                                blackCount++;
                            }
                    }
                }

                if (blackCount == k) {
                    ans++;
                }
            }
        }

        System.out.println(ans);
    }

    static final long powLong(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) {
                r *= a;
            }
            e = e >> 1;
            a *= a;
        }
        return r;
    }
