import java.util.Scanner;
import java.util.stream.IntStream;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        final int H = sc.nextInt();
        final int W = sc.nextInt();
        final int K = sc.nextInt();

        final boolean[][] field = new boolean[H][W];
        final int[] hBlacks = new int[H];
        final int[] wBlacks = new int[W];

        int blacks = 0;
        for (int i = 0; i < H; i++) {
            String s = sc.next();

            for (int j = 0; j < W; j++) {
                if (s.charAt(j) == '#') {
                    field[i][j] = true;
                    hBlacks[i]++;
                    wBlacks[j]++;
                    blacks++;
                }
            }
        }

        // 総当たり
        int count = 0;
        for (int h = 0; h < (1 << H); h++) {
            final int hh = h;
            int[] is = IntStream.range(0, H).filter(i -> 0 < (1 << i & hh)).toArray();
            int hPaint = IntStream.of(is).map(i -> hBlacks[i]).sum();

            for (int w = 0; w < (1 << W); w++) {
                final int ww = w;
                int[] js = IntStream.range(0, W).filter(j -> 0 < (1 << j & ww)).toArray();
                int wPaint = IntStream.of(js).map(j -> wBlacks[j]).sum();

                int hwPaint = 0;
                for (int i : is) {
                    for (int j : js) {
                        if (field[i][j]) {
                            hwPaint++;
                        }
                    }
                }
                if (blacks - hPaint - wPaint + hwPaint == K) {
                    count++;
                }
            }
        }
        System.out.println(count);
    }
}

import java.util.HashSet;
import java.util.Scanner;

public class Main {
    public static void main(String... args) {
        Scanner scanner = new Scanner(System.in);

        int H = scanner.nextInt();
        int W = scanner.nextInt();
        int K = scanner.nextInt();

        int map[][] = new int[W][H];
        int blackCnt = 0;
        int patternCnt = 0;

        for (int i = 0; i < W; i++) {
            for (int j = 0; j < H; j++) {
                map[i][j] = -1;
            }
        }

        scanner.nextLine();
        for (int i = 0; i < H; i++) {
            String line = scanner.nextLine();
            char[] chars = line.toCharArray();
            for (int j = 0; j < W; j++) {
                map[j][i] = chars[j] == '.' ? 0 : 1;
                blackCnt += map[j][i];
            }
        }


        for (int xBit = 0; xBit < (1 << W); xBit++) {
            for (int yBit = 0; yBit < (1 << H); yBit++) {
                int bBlackCnt = blackCnt;
                HashSet<String> searched = new HashSet<>();
                for (int x = 0; x < W; x++) {
                    if ((xBit & (1 << x)) == 1) {
                        for (int y = 0; y < H; y++) {
                            if (map[x][y] == 1 && !searched.contains(x + "," + y)) {
                                bBlackCnt--;
                                searched.add(x + "," + y);
                            }
                        }
                    }
                }

                for (int y = 0; y < H; y++) {
                    if ((yBit & (1 << y)) == 1) {
                        for (int x = 0; x < W; x++) {
                            if (map[x][y] == 1 && !searched.contains(x + "," + y)) {
                                bBlackCnt--;
                                searched.add(x + "," + y);
                            }
                        }
                    }
                }

                if (bBlackCnt == K) {
                    patternCnt++;
                }
            }
        }

        System.out.println(patternCnt);
    }
}

