public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int h = In.ni();
        int w = In.ni();
        int k = In.ni();
        boolean[][] g = In.grid(h, w, '#');
        int n = h + w;
        int ans = 0;
        for (int i = 0; i < 1 << n; i++) {
            int[][] a = new int[h][w];
            for (int r = 0; r < h; r++) {
                for (int c = 0; c < w; c++) {
                    a[r][c] = g[r][c] ? 1 : 0;
                }
            }
            for (int r = 0; r < h; r++) {
                if (BitUtil.test(i, r)) {
                    for (int c = 0; c < w; c++) {
                        a[r][c] = 2;
                    }
                }
            }
            for (int c = 0; c < w; c++) {
                if (BitUtil.test(i, h + c)) {
                    for (int r = 0; r < h; r++) {
                        a[r][c] = 2;
                    }
                }
            }
            int cnt = 0;
            for (int r = 0; r < h; r++) {
                for (int c = 0; c < w; c++) {
                    if (a[r][c] == 1) {
                        cnt++;
                    }
                }
            }
            if (cnt == k) {
                ans++;
            }
        }
        out.append(ans);
    }
}


