    {
        public static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);

            // 整数配列の入力
            var inputLongArray = Console.ReadLine().Split(' ').Select(i => long.Parse(i)).ToArray();
            var h = inputLongArray[0];
            var w = inputLongArray[1];
            var k = inputLongArray[2];

            var hw = new char[h, w];

            for (int i = 0; i < h; i++)
            {
                string inputstr = Console.ReadLine();
                for (int j = 0; j < w; j++)
                {
                    hw[i, j] = inputstr[j];
                }
            }

            var iter = Math.Pow(2, h + w);
            var a = new bool[h + w];
            long ans = 0;
            for (int i = 0; i < iter; i++)
            {
                var tmp = new char[h, w];
                Array.Copy(hw, tmp, hw.Length);
                long cnt = 0;
                for (int j = 0; j < h + w; j++)
                {
                    a[j] = ((i >> j) & 1) == 1;
                }
                for (int hh = 0; hh < h; hh++)
                {
                    for (int ww = 0; ww < w; ww++)
                    {
                        if (tmp[hh,ww] != '#' || a[hh] || a[ww + h])
                        {
                            tmp[hh, ww] = 'R';
                        }
                        else
                        {
                            cnt++;
                        }
                    }
                }
                if (cnt == k)
                {
                    ans++;
                }
            }

            Console.WriteLine(ans);

            Console.Out.Flush();
        }
