			var (h, w, k) = cin.ReadValue<int, int, int>();
			var c = new char[h][];
			for (int i = 0; i < h; i++)
			{
				c[i] = cin.ReadString().ToCharArray();
			}

			long ans = 0;
			for (int i = 0; i < 1 << h; i++)
			{
				for (int j = 0; j < 1 << w; j++)
				{
					int num = 0;
					for (int x = 0; x < h; x++)
					{
						for (int y = 0; y < w; y++)
						{
							if (i / (1 << x) % 2 == 1 && j / (1 << y) % 2 == 1 && c[x][y] == '#') num++;
						}
					}
					if (num == k) ans++;
				}
			}
			Console.WriteLine(ans);
		}

