    }

    public static IEnumerable<int[]> Combination(IEnumerable<int> list, int num)
    {
        if(num == 1)
        {
            foreach(var item in list)
            {
                yield return new int[] { item };
            }
            yield break;
        }

        foreach(var item in list)
        {
            var a = new int[] { item };
            var unused = list.SkipWhile(x => x != item).Skip(1).ToArray();

            foreach (var item1 in Combination(unused, num - 1))
            {
                yield return a.Concat(item1).ToArray();
            }
        }
    }
