    {
        if (nums.Count == 0)
        {
            var empty = new List<List<int>>();
            empty.Add(new List<int>());
            return empty;
        }

        var head = nums[0];
        var tail = nums.Skip(1).ToList();

        var tailPowerSet = PowerSet(tail);
        var tailPowerSerPlusHead = tailPowerSet.Select(list =>
        {
            var copy = new List<int>(list);
            copy.Add(head);
            return copy;
        }).ToList();
        tailPowerSet.AddRange(tailPowerSerPlusHead);
        return tailPowerSet;
    }
}

