            int ans = 0;
            for(int gBit = 0; gBit < (1 << H); ++gBit)
            {
                for(int rBit = 0; rBit < (1 << W); ++rBit)
                {
                    char[,] map = new char[H, W];
                    copyMap(out map);
                    if (Paint(map, gBit, rBit) == true)
                    {
                        ++ans;
                    }
