        public static bool Paint(char[,] map, int gBit, int rBit)
        {
            for (int i = 0; i < H; ++i)
            {
                //その行が塗られる対象なら
                if ((gBit & (1 << i)) > 0)
                {
                    //行を塗る
                    for(int x = 0; x < W; ++x)
                    {
                        map[i, x] = '.';
                    }
                }
            }
            for (int i = 0; i < W; ++i)
            {
                if ((rBit & (1 << i)) > 0)
                {
                    //列を塗る
                    for (int x = 0; x < H; ++x)
