            for(int i = 0; i < H; ++i)
            {
                for (int j = 0; j < W; ++j)
                {
                    if(map[i,j] == '#') { count++; }
                }
            }
            return count == K;
        }

        public static void copyMap(out char[,] map)
        {
            map = new char[H, W];
            for (int i = 0; i < H; ++i)
