    public sealed class Program : BaseProgram
    {
        public static void Main(string[] _) { using (new SetConsole()) { Solve(); } }
        public static void Solve()
        {
            var (h, w, k) = GetArray<int>();
            var map = new List<string>();
            for (int i = 0; i < h; i++)
            {
                var cw = GetString();
                map.Add(cw);
            }

            var results = 0;
            for (int i = 0; i < 1 << h; i++)
            {
                for (int j = 0; j < 1 << w; j++)
                {
                    var count = 0;
                    for (int a = 0; a < h; a++)
                    {
                        for (int b = 0; b < w; b++)
                        {
                            if ((((i >> a) & 1) & ((j >> b) & 1)) > 0)
                            {
                                if (map[a][b] == '#')
                                {
                                    count++;
                                }
                            }
                        }
                    }
                    if (k == count)
                    {
                        results++;
                    }
                }
            }

            Write(results);
        }
    }


