    class Atria
    {
        static void Main(string[] args)
        {
            int[] s = ReadLine().Split(' ').Select(int.Parse).ToArray();
            int h = s[0];
            int w = s[1];
            int k = s[2];
            char[,] map = new char[h, w];
            //red → Rとする
            for (int i = 0; i < h; i++)
            {
                string input = ReadLine();
                for (int j = 0; j < w; j++)
                {
                    map[i, j] = input[j];
                }
            }
            //実装部
            //行と列を選んで(2^6 * 2^6)シュミレーション
            char[,] tmpmap = new char[h, w];
            int ans = 0;
            for (int hbit = 0; hbit < (1 << h); hbit++)
            {
                for (int wbit = 0; wbit < (1 << w); wbit++)
                {
                    Array.Copy(map, tmpmap, map.Length);
