        public static void Main() { var r = GetResult(); Debug.WriteLine(r); Console.Write(r); }

        private static object GetResult()
        {
            var (H, W, K) = Read3Longs();
            var C = new int[H, W];
            for (var i = 0; i < H; i++)
            {
                var j = 0;
                foreach (var c in ReadText())
                {
                    C[i, j] = c == '#' ? 1 : 0;
                    j++;
                }
            }
            var maxH = Math.Pow(2, H);
            var maxW = Math.Pow(2, W);
            var count = 0;
            for (var h = 0; h < maxH; h++)
            {
                var bitH = Convert.ToString(h, 2).PadLeft((int)H,'0');
                for (var w = 0; w < maxW; w++)
                {
                    var bitW = Convert.ToString(w, 2).PadLeft((int)W,'0');
                    if (IsValid(H, W, K, C, bitH, bitW))
                    {
                        count++;
                    }
                }
            }
            return count;
        }
        private static bool IsValid(long H, long W, long K, int[,] c, string bitH, string bitW)
        {
            var sum = 0;
            for(var i = 0; i < H; i++)
            {
                for(var j = 0; j < W; j++)
                {
                    sum += c[i, j] * int.Parse(bitH[i].ToString()) * int.Parse(bitW[j].ToString());
                }
            }
            return sum == K;
        }

        #region Console.Read

        public static string ReadText() { return Console.ReadLine(); }
        public static List<string> ReadTexts() { return Console.ReadLine().Split(' ').ToList(); }
        public static long ReadLong() { return long.Parse(Console.ReadLine()); }
        public static (long, long) Read2Longs() { var ls = ReadLongs(); return (ls[0], ls[1]); }
        public static (long, long, long) Read3Longs() { var ls = ReadLongs(); return (ls[0], ls[1], ls[2]); }
        public static (long, long, long, long) Read4Longs() { var ls = ReadLongs(); return (ls[0], ls[1], ls[2], ls[3]); }
        public static (long, long, long, long, long) Read5Longs() { var ls = ReadLongs(); return (ls[0], ls[1], ls[2], ls[3], ls[4]); }
        public static List<long> ReadLongs() { return Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToList(); }

        #endregion
    }
}

using System;
using CompLib.Util;

public class Program
{
    public void Solve()
    {
        var sc = new Scanner();
        int h = sc.NextInt();
        int w = sc.NextInt();
        int k = sc.NextInt();
        string[] c = new string[h];
        for (int i = 0; i < h; i++)
        {
            c[i] = sc.Next();
        }

        int lR = 1 << h;
        int lC = 1 << w;
        int ans = 0;
        for (int i = 0; i < lR; i++)
        {
            for (int j = 0; j < lC; j++)
            {
                int cnt = 0;
                for (int l = 0; l < h; l++)
                {
                    for (int m = 0; m < w; m++)
                    {
                        if (c[l][m] == '#' && (i & (1 << l)) == 0 && (j & (1 << l)) == 0)
                        {
                            cnt++;
                        }
                    }
                }

                if (cnt == k) ans++;
            }
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

namespace CompLib.Util
{
    using System;
    using System.Linq;

    class Scanner
    {
        private string[] _line;
        private int _index;
        private const char Separator = ' ';

        public Scanner()
        {
            _line = new string[0];
            _index = 0;
        }

        public string Next()
        {
            if (_index >= _line.Length)
            {
                string s;
                do
                {
                    s = Console.ReadLine();
                } while (s.Length == 0);

                _line = s.Split(Separator);
                _index = 0;
            }

            return _line[_index++];
        }

        public string ReadLine()
        {
            _index = _line.Length;
            return Console.ReadLine();
        }

        public int NextInt() => int.Parse(Next());
        public long NextLong() => long.Parse(Next());
        public double NextDouble() => double.Parse(Next());
        public decimal NextDecimal() => decimal.Parse(Next());
        public char NextChar() => Next()[0];
        public char[] NextCharArray() => Next().ToCharArray();

        public string[] Array()
        {
            string s = Console.ReadLine();
            _line = s.Length == 0 ? new string[0] : s.Split(Separator);
            _index = _line.Length;
            return _line;
        }

        public int[] IntArray() => Array().Select(int.Parse).ToArray();
        public long[] LongArray() => Array().Select(long.Parse).ToArray();
        public double[] DoubleArray() => Array().Select(double.Parse).ToArray();
        public decimal[] DecimalArray() => Array().Select(decimal.Parse).ToArray();
    }
}

