class Program
{
    static void Main(string[] args)
    {
        var arr = arrInt();
        int h = arr[0];
        int w = arr[1];
        int k = arr[2];
        var mapMoto = mapChar(h);
        int count = 0;
        for (int bit = 0; bit < (1 << h+w); bit++)
        {
            //mapのクローンを作成する。
            List<char[]> map = mapCharCopy(mapMoto);
            for (int i = 0; i < h+w; i++)
            {
                if ((bit & (1 << i)) > 0)
                {
                    if(i < h)
                    {
                        //i行目を変換
                        changeGyou(w, i, map);
                    } else
                    {
                        //i列目を変換
                        changeRetu(h, i - h , map);
                    }
                }
            }
            //数がk個か数える
            if (equalK(h, w, k, map)) count++;
        }
        Console.WriteLine(count);


    }

    static void changeGyou(int w , int gyou , List<char[]> map)
    {
        for (int i = 0; i < w; i++) map[gyou][i] = '.';
    }

    static void changeRetu(int h, int retu, List<char[]> map)
    {
        for (int i = 0; i < h; i++) map[i][retu] = '.';
    }

    static bool equalK(int h, int w, int k , List<char[]> map)
    {
        int count = 0;
        for(int i = 0; i < h; i++)
        {
            for(int j = 0; j < w; j++)
            {
                if (map[i][j] == '#') count++;
            }
        }
        if (count == k) return true;
        return false;
    }



    //入力受け取り用
    static string crS() { return Console.ReadLine(); }
    static int crI() { return int.Parse(Console.ReadLine()); }
    static int[] arrInt(){return Console.ReadLine().Split(' ').Select(v => int.Parse(v)).ToArray();}
    static long[] arrLong(){ return Console.ReadLine().Split(' ').Select(v => long.Parse(v)).ToArray(); }
    static string[] arrStr(){return Console.ReadLine().Split(' ').ToArray();}
    static List<int[]> mapInt(int h)
    {
        List<int[]> mapInt = new List<int[]>();
        for (int i = 0; i < h; i++)
        {
            mapInt.Add(arrInt());
        }
        return mapInt;
    }

    static List<char[]> mapChar(int h)
    {
        List<char[]> mapChar = new List<char[]>();
        for (int i = 0; i < h; i++)
        {
            string s = crS();
            mapChar.Add(s.ToCharArray());
        }
        return mapChar;
    }

    static List<char[]> mapCharCopy(List<char[]> map)
    {
        List<char[]> copyMap = new List<char[]>();
        foreach (var arr in map)
        {
            List<char> list = new List<char>();
            foreach (var ele in arr)
            {
                list.Add(ele);
            }
            copyMap.Add(list.ToArray());
        }
        return copyMap;
    }
}

