using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ABC0613
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] inpp= Console.ReadLine().Split(' ');
            int H = int.Parse(inpp[0]);
            int W = int.Parse(inpp[1]);
            int K = int.Parse(inpp[2]);
            int b = 0;

            var mtr = new string[W];
            var h = new int[H]; var w = new int[W];

            for(int i=0;i<H;i++)
            {
                string inp = Console.ReadLine();
                mtr[i] += inp;
                int temp=0;

                for (int j=0;j<W;j++)
                {
                    if (inp.Substring(j,1) == "#")
                    {
                        w[j]++;
                        temp++;
                    }
                }
                h[i] += temp;
                b += temp;

            }

            int b_k = b - K;
            int ans = 0;

            if (b_k > 0)
            {
                //行・列
                for (int i = 0; i < H; i++)
                {
                    int hi = h[i];
                    if (hi == b_k)
                        continue;

                    for (int j = 0; j < W; j++)
                    {
                        int sum = hi + w[j];
                        if (mtr[i].Substring(j, 1) == "#") sum--;
                        if (sum == b_k) ans++;
                    }

                    for (int k = 0; k < i; k++)
                    {
                        int sum = hi + h[k];
                        if (sum == b_k) ans++;
                    }
                }

                //一行・一列だけ
                ans += h.Count(n => n == b_k); ans += w.Count(n => n == b_k);

                for (int j = 0; j < W; j++)
                {
                    int wj = w[j];
                    if (wj == b_k)
                        continue;

                    for (int k = 0; k < j; k++)
                    {
                        int sum = wj + w[k];
                        if (sum == b_k) ans++;
                    }

                }

            }
            else if (b_k == 0) ans++;
            Console.WriteLine(ans);
        }
    }
}

