    class Program
    {
        static void Main(string[] args)
        {
            int H = RInt;
            int W = RInt;
            int K = RInt;

            char[,] map = new char[H, W];
            for (int i = 0; i < H; i++)
            {
                var input = Console.ReadLine();
                for (int j = 0; j < W; j++)
                {
                    map[i, j] = input[j];
                }
            }

            var bitH = BitSearch(H);
            var bitW = BitSearch(W);

            int ans = 0;
            for (int i = 0; i < bitH.Length; i++)
            {
                for (int j = 0; j < bitW.Length; j++)
                {
                    int count = 0;
                    for (int k = 0; k < H; k++)
                    {
                        for (int l = 0; l < W; l++)
                        {
                            if (bitH[i][k] == 0 && bitW[j][l] == 0)
                            {
                                if (map[k, l] == '#') count++;
                            }
                        }
                    }
                    if (count == K) ans++;
                }
            }
            Console.WriteLine(ans);
        }

        /// <summary>
        /// bit全探索　メソッドバージョン
        /// </summary>
        /// <param name="n"></param>
        /// <returns>int[1<<n][]</returns>
        public static int[][] BitSearch(int n)
        {
            int[][] ret = new int[1 << n][];
            for (int bit = 0; bit < (1 << n); ++bit)
            {
                int[] S = new int[n];
                for (int i = 0; i < n; i++)
                {
                    if ((bit & (1 << i)) != 0)
                    {
                        S[i] = 1;
                    }
                    else S[i] = 0;
                }

                ret[bit] = S.ToArray();
            }
            return ret;
        }
    }


