        class PriorityQueue<T> where T : IComparable<T>
        {
            public PriorityQueue()
            {
                buffer = new List<T>();
            }

            List<T> buffer;
            public void Enqueue(T elem)
            {
                int n = buffer.Count;
                buffer.Add(elem);
                while (n != 0)
                {
                    int i = (n - 1) / 2;
                    if (buffer[n].CompareTo(buffer[i]) > 0)
                    {
                        T temp = buffer[n];
                        buffer[n] = buffer[i];
                        buffer[i] = temp;
                    }
                    n = i;
                }
            }

            public T Dequeue()
            {
                var t = Peek();
                Pop();
                return t;
            }

            void Pop()
            {
                int n = buffer.Count - 1;
                buffer[0] = buffer[n];
                buffer.RemoveAt(n);
                for (int i = 0, j; (j = 2 * i + 1) < n;)
                {
                    if ((j != n - 1) && (buffer[j].CompareTo(buffer[j + 1]) < 0)) { j++; }
                    if (buffer[i].CompareTo(buffer[j]) < 0)
                    {
                        T temp = buffer[j];
                        buffer[j] = buffer[i];
                        buffer[i] = temp;
                    }
                    i = j;
                }
            }

            public T Peek()
            {
                return buffer[0];
            }

            public int Count()
            {
                return buffer.Count;
            }
        }

        public void Solve()
        {
            int H;int W;int K;
            Multi(out H, out W, out K);
            var map = new string[H].Select(s => GetStr().ToCharArray()).ToArray();
            var cnt = 0;
            for(int h = 0; h < 1 << H; h++)
            {
                for(int w = 0; w < 1 << W; w++)
                {
                    var tmp = new char[H][];
                    for(int i = 0; i < H; i++)
                    {
                        tmp[i] = map[i].ToArray();
                    }

                    for(int i = 0; i < H; i++)
                    {
                        if (((h >> i) & 1) != 1) continue;
                        tmp[i] = new char[W].Select(s => '_').ToArray();
                    }
                    for(int i = 0; i < W; i++)
                    {
                        if (((w >> i) & 1) != 1) continue;
                        for(int j = 0; j < H; j++)
                        {
                            tmp[j][i] = '_';
                        }
                    }
                    if (tmp.Sum(t => t.Count(c => c == '#')) == K)
                    {
                        cnt++;
                    }
                }
            }
            Console.WriteLine(cnt);
        }
