class num2choice
{
    public int[] choice;
    public int choiceCnt;   //選択された個数
    private int m_n;

    public num2choice(int n)
    {
        choice = new int[n];
        m_n = n;
    }

    public void Convert(int num)
    {
        int i;
        choiceCnt = 0;

        for (i = 0; i < m_n; i++)
        {
            if ((num & 0x1) != 0)
            {
                choice[i] = 1;
                choiceCnt++;
            }
            else
            {
                choice[i] = 0;
            }
            num = num >> 1;
        }
    }

}

