namespace AtCoder.Abc
{
    class QuestionC
    {
        public static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);

            var sp = Console.ReadLine().Split(' ');
            var h = int.Parse(sp[0]);
            var w = int.Parse(sp[1]);
            var k = int.Parse(sp[2]);
            int[,] b = new int[h, w];
            int kc = 0;
            for (int i = 0; i < h; i++)
            {
                var s = Console.ReadLine().ToCharArray();
                for (int j = 0; j < w; j++)
                {
                    if (s[j] == '.')
                    {
                        b[i, j] = 1;
                    } else if (s[j] == '#')
                    {
                        b[i, j] = 2;
                        kc++;
                    }
                }
            }
            if (kc < k)
            {
                Console.WriteLine(0);
            }

            int total = 0;
            for (int i = 0; i < (1 << h); i++)
            {
                for (int j = 0; j < (1 << w); j++)
                {
                    bool f = false;
                    var kcc = GetKC(b, h, w, i, j);
                    if (kcc == k)
                    {
                        if (i == ((1 << h)-1))
                        {
                            total = 2;
                            f = true;
                            break;
                        }else
                        {
                            total++;
                        }
                    }
                    if (f) break;
                }
            }
            Console.WriteLine(total);

            Console.Out.Flush();
        }

        public static int GetKC(int[,] b, int h, int w, int hp, int wp)
        {
            int[,] mask = new int[h, w];

            for(int i = 0; i < h; i++)
            {
                if ((hp & (1 << i)) == 0) continue;
                for (int j = 0; j < w; j++)
                {
                    mask[i, j] = 1;
                }
            }
            for(int j = 0; j < w; j++)
            {
                if ((wp & (1 << j)) == 0) continue;
                for (int i =0; i < h; i++)
                {
                    mask[i, j] = 1;
                }
            }
            int kc = 0;
            for (int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    if (b[i, j] == 2 && mask[i, j] != 1) kc++;
                }
            }
            return kc;
        }
    }
}

