    public static void BubbleSort<T>(T[] a)
        where T : IComparable<T>
    {
        int n = a.Length;
        for (int i = 0; i < n - 1; i++)
            for (int j = n - 1; j > i; j--)
                if (a[j].CompareTo(a[j - 1]) < 0)
                    Swap(ref a[j], ref a[j - 1]);
    }

    public static void Swap<T>(ref T a, ref T b)
    {
        T c = a;
        a = b;
        b = c;
    }

