    {
        //行数、列数、Kの値を保持する
        var HWK = Console.ReadLine().Split().Select(e => int.Parse(e)).ToArray();
        var rows = HWK[0];
        var cols = HWK[1];
        var k = HWK[2];
        //表内容をstring型で保持する
        var table = new string[rows];
        for (var cnt = 0; cnt < rows; cnt++)
        {
            table[cnt] = Console.ReadLine();
        }var ans = 0;
        var kCnt = 0;
        //行数 + 1分ループして行の全検索を実施
        //for (var i = 0; i < (rows << 1); i++)
        for (var i = 0; i < (Math.Pow(2,rows)); i++)
        {
            //列数 + 1分ループして列の全検索を実施
            //行列合わせて、最大で2^12回
            //for (var j = 0; j < (cols << 1); j++)
            for (var j = 0; j < Math.Pow(2,cols); j++)
            {
                kCnt = 0;
                //Console.WriteLine($"i = {i},j = {j}");
                for (var y = 0; y < rows; y++)
                {
                    if ((i >> y & 1) == 1)
                    {
                        continue;
                    }

                    for (var x = 0; x < cols; x++)
                    {

                        //Console.WriteLine($"i = {i},y = {y},j = {j},x = {x}");

                        if ((j >> x & 1) == 1)
                        {
                            continue;
                        }
                        if (table[y][x] == '#')
                        {
                            kCnt++;
                        }
                    }
                }
                if (kCnt == k)
