class Program
{
    static void Main()
    {
        var ar = Console.ReadLine().Split().Select(int.Parse).ToArray();
        var H = ar[0];
        var W = ar[1];
        var K = ar[2];
        var itemAry = new char[H, W];
        var ans = 0;
        //データ取得
        for (int i = 0; i < H; i++)
        {
            var items = Console.ReadLine().ToCharArray();
            for (int j = 0; j < W; j++) itemAry[i, j] = items[j];
        }
        //全行全列について、塗りつぶしの組み合わせをbit全探索
        //i,j==1のbitを塗りつぶしとする
        for (int i = 0; i < (1 << H); i++)
        {
            for (int j = 0; j < (1 << W); j++)
            {
                var count = 0;
                //今の塗りつぶし状態が条件に合うか走査
                for (int k = 0; k < H; k++)
                {
                    //i行が塗りつぶされている
                    if (((i >> k) & 1) == 1) continue;
                    for (int l = 0; l < W; l++)
                    {
                        if (((j >> l) & 1) == 1) continue;
                        //塗りつぶされておらず、黒
                        if (itemAry[k, l] == '#') count++;
                    }
                }
                if (count == K) ans++;
            }
        }
        Console.WriteLine(ans);
    }
}

