    public class ABC_C
    {
        /// <summary>
        /// H 行 W 列
        /// 上から i 行目、左から j 列目 ( 1 ≤ i ≤ H , 1 ≤ j ≤ W ) のマスの色は文字 c i , j
        /// c i , j が . のとき白
        /// # のとき黒
        /// </summary>
        int h, w, k;
        long ans;
        bool[][] arr;
        bool[] redh, redw;
        public ABC_C()
        {
            (h, w, k) = ReadIntArray().ToTpl3();

            arr = new bool[h][];
            redh = new bool[h];
            redw = new bool[w];

            for (int i = 0; i < h; i++)
            {
                arr[i] = Read.Select(v => v == '#').ToArray();
            }

            for (int bit = 0; bit < 1 << h; bit++)
            {
                for (int i = 0; i < h; i++)
                {
                    redh[i] = ((bit >> i & 1) == 1);
                }

                for (int s = 0; s < 1 << w; s++)
                {
                    for (int i = 0; i < w; i++)
                    {
                        redw[i] = ((s >> i & 1) == 1);
                    }
                    if (Check()) ans++;
                }
            }
            ans.Cw();
        }

        bool Check()
        {
            long cou = 0;
            for (int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    if (arr[i][j] && (!redh[i]) && (!redw[j])) cou++;
                    if (cou > k) return false;
                }
            }
            return (cou == k);
        }
    }

