        static int hmax = 0;
        static int wmax = 0;
        static void Main(string[] args)
        {
            var D = RL2IE().ToList();
            H=D[0];
            W=D[1];
            K = D[2];
            hmax = (int)Math.Pow(2, H)-1;
            wmax = (int)Math.Pow(2, W)-1;

            //var whitestr = ".";
            var blackstr = '#';

            var bitlst = new List<int>();
            for (var i = 0; i < H; i++)
            {
                var line = 0;
                var str = RL();
                for (int seek = 0; seek < W; seek++)
                {
                    var bit = str[seek] == blackstr ? 1 : 0;
                    line |= (bit << seek);
                }
                bitlst.Add(line);
            }

            var ret=dfs(hmax, wmax, bitlst, 0);



            Console.WriteLine(ret);
            Console.ReadLine();

        }
        static int dfs(int hlst, int wlst,List<int> bitlst,int count)
        {
            var num = checkcount(hlst, wlst, bitlst);
            if (num == K) count++;
            if (hlst <= 0 && wlst <= 0) return count;
            else if (hlst<=0) {
                wlst--; 
                hlst = hmax;

                /*while (checkcount(hlst, wlst, bitlst) < K)
                {
                    wlst--;
                    if (wlst <= 0) break;
                }*/
            }
            else hlst--;
            return dfs(hlst, wlst, bitlst,count);

        }
        static int checkcount(int hlst, int wlst,List<int> bitlst)
        {
            var count = 0;
            var masked = bitlst.Select(x => x & wlst).ToList();

            for (int i = 0; i < masked.Count(); i++)
            {
                if ((hlst & (1 <<i))==0) masked[i]=0;
            }
            foreach (var mask in masked)
            {
                count += numofbit(mask);
            }
            //Console.WriteLine(count);
            return count;
        }
        static int numofbit(long bits)
        {
            bits = ((bits & 0xAAAAAAAA) >> 1) + (bits & 0x55555555);
            bits = ((bits & 0xCCCCCCCC) >> 2) + (bits & 0x33333333);
            bits = ((bits & 0xF0F0F0F0) >> 4) + (bits & 0x0F0F0F0F);
            bits = ((bits & 0xFF00FF00) >> 8) + (bits & 0x00FF00FF);
            bits = ((bits & 0xFFFF0000) >> 16) + (bits & 0x0000FFFF);
            return (int)bits;

        }
        static IEnumerable<int> RL2IE() { return spr(RL()).Select(x => (int)c2i(x)); }
        static string RL() { return Console.ReadLine().Trim(); }
        static IEnumerable<string> spr(string s) { return s.Split(' '); }
        static Int64 c2i(string c) { return Int64.Parse(c); }
        //static double c2d(string c) { return double.Parse(c); }
        static string bool2ret(bool b) { return b ? "Yes" : "No"; }
    }
}

