class Program
{
    static void Main(string[] args)
    {
        var input = Console.ReadLine().Split(" ");
        var H = int.Parse(input[0]);
        var W = int.Parse(input[1]);
        var K = int.Parse(input[2]);

        var table = new List<List<char>>();
        for(int i = 0; i < H; i++)
        {
            var row = new List<char>();
            var line = Console.ReadLine();
            for(int j = 0; j < W; j++)
            {
                row.Add(line[j]);
            }
            table.Add(row);
        }

        var count = 0;
        for (int hBit = 0; hBit < (1 << H); ++hBit)
        {
            // 行に対してBit全探索
            var rows = GenerateCopyList(table);
            for (int i = 0; i < H; ++i)
            {
                if((hBit & (1 << i)) != 0)
                {
                    for(int j = 0; j < W; j++)
                    {
                        rows[i][j] = '.';
                    }
                }
            }
            for (int wBit = 0; wBit < (1 << W); ++wBit)
            {
                var columns = GenerateCopyList(rows);
                // 列に対してBit全探索
                for (int i = 0; i < W; ++i)
                {
                    if ((wBit & (1 << i)) != 0)
                    {
                        for(int j =0; j < H; j++)
                        {
                            columns[j][i] = '.';
                        }
                    }
                }
                if (CountSharp(columns) == K) count++;
            }
        }

        Console.WriteLine(count);
    }

    private static List<List<char>> GenerateCopyList(List<List<char>> source)
    {
        var copyList = new List<List<char>>();
        foreach(var row in source)
        {
            copyList.Add(new List<char>(row));
        }
        return copyList;
    }

    private static int CountSharp(List<List<char>> list)
    {
        var count = 0;
        foreach(var row in list)
        {
            foreach (var item in row)
            {
                if (item == '#') count++;
            }
        }

        return count;
    }

}

