            Console.SetOut(sw);

            //Input int array
            int[] inputArray = Console.ReadLine().Split(' ').Select(i => int.Parse(i)).ToArray();
            (int h, int w, int k) = (inputArray[0], inputArray[1], inputArray[2]);

            char[,] c = new char[h, w];
            for (int i = 0; i < h; i++)
            {
                var ss = Console.ReadLine().AsSpan();
                for (int j = 0; j < w; j++)
                {
                    c[i, j] = ss[j];
                }
            }

            List <bool[]> boolPatterns = new List<bool[]>();
            var boolArray = new bool[h+w];
            GetBoolPermutation(boolArray, 0);

            var results = new List<int>();
            foreach (var pattern in boolPatterns)
            {
                bool[] hbool = new bool[h];
                Array.Copy(pattern, hbool, h);

                bool[] wbool = new bool[w];
                Array.Copy(pattern, h,wbool,0,w);

                char[,] cc = new char[h,w];
                Array.Copy(c, cc, c.Length);

                for (int i = 0; i < h; i++)
                {
                    for (int j = 0; j < w; j++)
                    {
                        if (hbool[i] || wbool[j]) 
                        {
                            cc[i, j] = '.';
                        }
                    }
                }

                int result = 0;
                for (int i = 0; i < h; i++)
                {
                    for (int j = 0; j < w; j++)
                    {
                        if (cc[i, j] == '#') result++; 
                    }
                }
                results.Add(result);
            }

            Console.WriteLine(results.Where(item => item == k).Count()); 

            Console.Out.Flush();

            void GetBoolPermutation(bool[] bools, int first)
            {
                if (first == bools.Length) 
                {
                    boolPatterns.Add(bools.ToArray());
                    return;
                }

                bools[first] = true;
                GetBoolPermutation(bools, first + 1);
                bools[first] = false;
                GetBoolPermutation(bools, first + 1);
            }
        }
    }
