            {
                for (int x = 0; x < w; x++)
                {
                    //黒いマス
                    if (((i >> y) & 1) == 0 && ((j >> x) & 1) == 0 && Grid[y][x] == '#')
                    {
                        count++;
                    }
                }
            }

            return count;
