			//ビット全探索
			for (int hPattern = 0; hPattern < Math.Pow(2, H); hPattern++) {
				for (int wPattern = 0; wPattern < Math.Pow(2, W); wPattern++) {
					var testmap = new bool[H, W];
					//検証用の地図を作成する
					for (int i = 0; i < H; i++) {
						for (int j = 0; j < W; j++) {
							testmap[i, j] = map[i,j];
						}
					}

					for (int i = 0; i < H; i++) {
						var x = (hPattern >> i) & 1;
						if (x==1) {//1のとき、すべて赤にする
							for (int j = 0; j < W; j++) {
								testmap[i, j] = false;
							}
						}
					}

					for (int j = 0; j < W; j++) {
						var y = (wPattern >> j) & 1;
						if (y == 1) {//1のとき、すべて赤にする
							for (int i = 0; i < H; i++) {
								testmap[i, j] = false;
							}
						}
					}

					//testMapの黒の数を数える
					var kuroCount = 0;
					for (int i = 0; i < H; i++) {
						for (int j = 0; j < W; j++) {
							if (testmap[i,j]) {
								kuroCount++;
							}
						}
					}
					if (kuroCount == K) {
						count++;
					}
				}
			}

			//答えの出力
			var ans = count;
			Console.WriteLine(ans);

		}

