		long K = GetLong();
		var grid = new char[H, W];
		for(long i = 0; i < H; i++)
		{
			var S = GetString();
			for(long j = 0; j < W; j++)
				grid[i, j] = S[(int)j];
		}

		long ans = 0;
		for(long s = 0; s < leftShift(1, H); s++)
		{
			for(long t = 0; t < leftShift(1, W); t++)
			{
				long cnt = 0;
				for(long i = 0; i < H; i++)
				{
					if(contains(s, i))
						continue;

					for(long j = 0; j < W; j++)
					{
						if(contains(t, j))
							continue;

						if(grid[i, j] == '#')
							cnt++;
					}
				}
				if(cnt == K)
					ans++;
			}
		}
		WriteLine(ans);
	}
