class Program
{
    static void Main(string[] args)
    {
        var hwk = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var h = hwk[0];
        var w = hwk[1];
        var k = hwk[2];

        // 黒をTrue
        var board = new bool[h][].Select(t => t = new bool[w]).ToArray();

        for (int i = 0; i < h; i++)
        {
            var line = Console.ReadLine();
            for(int j = 0; j < w; j++)
            {
                if (line[j] == '#') board[i][j] = true;
            }
        }

        long ans = 0;

        // bit全探索
        foreach(var item in BitFullSearch(h + w))
        {
            var tate = item.Take(h).ToArray();
            var yoko = item.Skip(h).ToArray();
            bool[][] newBorad = new bool[h][].Select(t => t = new bool[w]).ToArray();

            for(int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++) newBorad[i][j] = board[i][j];
            }

            for (int i = 0; i < tate.Length; i++)
            {
                if(tate[i])
                    for (int j = 0; j < w; j++) newBorad[i][j] = false;
            }
            for (int i = 0; i < yoko.Length; i++)
            {
                if(yoko[i])
                    for (int j = 0; j < h; j++) newBorad[j][i] = false;
            }

            if (newBorad.Sum(aa => aa.Count(bb => bb)) == k) ans++;
        }

        Console.WriteLine(ans);
    }

    public static IEnumerable<bool[]> BitFullSearch(int n)
    {
        if (n <= 0)
        {
            yield return new bool[] { };
            yield break;
        }

        for (int i = 0; i < Math.Pow(2, n); i++)
        {
            var array = new bool[n];
            for (int j = 0; j < n; j++)
            {
                var targetBit = (i >> j) & 1;
                if (targetBit == 1) array[j] = true;
            }

            yield return array;
        }
    }
}

