        int[] hwk = Console.ReadLine().Split().Select(int.Parse).ToArray();
        var h = hwk[0];
        var w = hwk[1];
        var k = hwk[2];

        var ans = 0;
        string[] c = new string[h];
        for (int i = 0; i < c.Length; i++)
        {
            c[i] = Console.ReadLine();
        }

        //bit探索(bit全探索)
        for (int x = 0; x < Math.Pow(2, h); x++)
        {
            var array1 = new bool[h];

            // 右からk桁目を取り出す
            for (int s = 0; s < h; s++)
            {
                var y = (x >> s) & 1;
                if (y == 1) array1[s] = true;
            }

            for (int z = 0; z < Math.Pow(2, w); z++)
            {
                var array2 = new bool[w];

                // 右からk桁目を取り出す
                for (int j = 0; j < w; j++)
                {
                    var zz = (z >> j) & 1;
                    if (zz == 1) array2[j] = true;
                }

                var tmp = 0;
                for (int a = 0; a < h; a++)
                {
                    if (array1[a] == true) continue;
                    for (int b = 0; b < w; b++)
                    {
                        if (array2[b] == false)
                        {
                            if (c[a][b] == '#') tmp++;
                        }
                        if (tmp > k) break;
                    }
                    if (tmp > k) break;
                }

                if (tmp == k) ans++;
            }
        }

        // 出力
        Console.WriteLine(ans);
    }
}

