    class Solver
    {
        public void Solve()
        {
            var line1 = Console.ReadLine().Split().Select(elem => int.Parse(elem)).ToArray();
            var H = line1[0];
            var W = line1[1];
            var K = line1[2];

            var matrix = new List<List<char>>();
            foreach (var i in Enumerable.Range(0, H))
            {
                var row = new List<char>();
                foreach (var c in Console.ReadLine())
                {
                    row.Add(c);
                }

                matrix.Add(row);
            }

            int answer = 0;
            for (int patternH = 0; patternH < (1 << H); patternH++)
            {
                for (int patternW = 0; patternW < (1 << W); patternW++)
                {
                    var work = matrix.Select(elem => elem.Select(elem2 => elem2).ToList()).ToList();
                    foreach (var h in Enumerable.Range(0, H))
                    {
                        foreach (var w in Enumerable.Range(0, W))
                        {
                            if ((patternH & (1 << h)) > 0)
                            {
                                foreach (var i in Enumerable.Range(0, W))
                                {
                                    work[h][i] = 'R';
                                }
                            }

                            if ((patternW & (1 << w)) > 0)
                            {
                                foreach (var i in Enumerable.Range(0, H))
                                {
                                    work[i][w] = 'R';
                                }
                            }
                        }
                    }

                    var count = work.Sum(elem => elem.Count(elem2 => elem2 == '#'));
                    if (count == K)
                    {
                        answer++;
                    }
                }
            }

            Console.WriteLine($"{answer}");
        }
    }
}

