namespace atcoder
{
    class Program
    {
        static void Main(string[] args)
        {
            var hwk = Console.ReadLine().Split(' ').Select(num => int.Parse(num)).ToArray();
            var h = hwk[0];
            var w = hwk[1];
            var k = hwk[2];

            var board = new char[h, w];

            for (var i = 0; i < h; i++)
            {
                var line = Console.ReadLine().ToArray();
                for (var j = 0; j < w; j++)
                {
                    board[i, j] = line[j];
                }
            }

            var deletedRowsSet = new List<HashSet<int>>();
            DigRows(0, new HashSet<int>());
            var result = 0;
            deletedRowsSet.ForEach(rowSet => DigColumns(0, rowSet, new HashSet<int>()));

            Console.WriteLine(result);

            void DigColumns(int current, HashSet<int> deletedRows, HashSet<int> deletedColumns)
            {
                if (current == w)
                {
                    if (SearchBlacks(deletedRows, deletedColumns) == k) result++;
                    return;
                }
                DigColumns(current + 1, deletedRows, deletedColumns.ToHashSet());
                deletedColumns.Add(current);
                DigColumns(current + 1, deletedRows, deletedColumns.ToHashSet());
            }

            void DigRows(int current, HashSet<int> deletedRows)
            {

                if (current == h)
                {
                    if (SearchBlacks(deletedRows, new HashSet<int>()) >= k)
                        deletedRowsSet.Add(deletedRows);

                    return;
                }

                DigRows(current + 1, deletedRows.ToHashSet());
                deletedRows.Add(current);
                DigRows(current + 1, deletedRows.ToHashSet());
            }

            int SearchBlacks(HashSet<int> rows, HashSet<int> columns)
            {
                var result = 0;
                for (var i = 0; i < h; i++)
                {
                    if (!rows.Contains(i))
                    {
                        for (var j = 0; j < w; j++)
                        {
                            if (!columns.Contains(j) && board[i, j] == '#') result++;
                        }
                    }
                }
                return result;
            }
        }
    }
}

