            int ans = 0;
            for (int i = 0; i < (1 << h); i++)//1<<0=1 1<<1=2 1<<2=4　なので1<<nはn+1桁の2進数で表せる最大の数
            {
                var dh = new int[h];
                for (int j = 0; j < h; j++)
                {
                    if (((i >> j) & 1) == 1) { dh[j] = 1; }//iのjビット目が１か
                }
                for (int ii = 0; ii < (1 << w); ii++)//1<<0=1 1<<1=2 1<<2=4　なので1<<nはn+1桁の2進数で表せる最大の数
                {
                    var dw = new int[w];
                    for (int jj = 0; jj < w; jj++)
                    {
                        if (((ii >> jj) & 1) == 1) { dw[jj] = 1; }//iのjビット目が１か
                    }
                    if (CheckTrue(dh, dw) == k) ans++;
                }
            }
                Console.WriteLine(ans);
