class Class1
{
    static void Main(string[] args)
    {
        List<int> HKW = Console.ReadLine().Split(' ').Select(_ => int.Parse(_)).ToList();
        int H = HKW[0];
        int W = HKW[1];
        int K = HKW[2];
        var ct = new char[H][];

        for (int i = 0; i < H; i++)
        {
            ct[i] = Console.ReadLine().ToCharArray();
        }

        int result = 0;
        // 最大は2^(6+6) = 2^12で 4096通りなので計算量は大したことない
        for (int i = 0; i < (1 << H); i++)
        {
            for (int j = 0; j < (1 << W); j++)
            {
//                Console.WriteLine($"START: i={i},j={j}");

                int blakcs = 0;
                for (int x = 0; x < H; x++)
                {
                    if ((i >> x & 1) == 1)
                    {
//                        Console.WriteLine($"SKIP_X: x={x}");
                        continue;
                    }

                    for (int y = 0; y < W; y++)
                    {
//                        Console.WriteLine($"LOOP: x={x},y={y}");

                        if ((j >> y & 1) == 1)
                        {
//                            Console.WriteLine($"SKIP_Y: y={y}");
                            continue;
                        }

                        if (ct[x][y] == '#')
                        {
                            blakcs++;
                        }
                    }
                }


                if (blakcs == K)
                {
//                    Console.WriteLine($"i={i},j={j}, result++");
                    result++;
                }
            }
        }


        Console.WriteLine($"result: {result}");
    }
}

