class Program
{
    static void Main(string[] args)
    {
        var line = Console.ReadLine().Split(' ');
        var h = int.Parse(line[0]);
        var w = int.Parse(line[1]);
        var k = int.Parse(line[2]);

        var inputArray = new bool[h][];
        var ans = 0;


        for(var r = 0; r < h; r++)
        {
            var l = Console.ReadLine().ToCharArray();
            var ar = new bool[w];
            inputArray[r] = ar;
            for(var c = 0; c < w; c++)
            {
                if (l[c] == '#')
                {
                    inputArray[r][c] = true;
                }
                else
                {
                    inputArray[r][c] = false;
                }
            }
        }

        for (int x = 0; x < Math.Pow(2, h); x++)
        {
            var array = new bool[h][];
            for(var num = 0; num < h; num++)
            {
                    array[num] = inputArray[num].Clone() as bool[];
            }

            // 右からk桁目を取り出す
            for (int j = 0; j < h; j++)
            {
                var y = (x >> j) & 1;
                if (y == 1)
                {
                    for (var i = 0; i < w; i++)
                    {
                        array[j][i] = false;
                    }
                }
            }

            for (int z = 0; z < Math.Pow(2, w); z++)
            {
                var tempArray = new bool[h][];
                for (var num2 = 0; num2 < h; num2++)
                {
                    tempArray[num2] = array[num2].Clone() as bool[];
                }


                for (int i = 0; i < w; i++)
                {
                    var a = (z >> i) & 1;
                    if(a == 1)
                    {
                        for (var j = 0; j < h; j++)
                        {
                            tempArray[j][i] = false;
                        }
                    }
                }

                var black = 0;

                foreach (var row in tempArray)
                {
                    foreach (var column in row)
                    {
                        if (column)
                        {
                            black += 1;
                        }
                    }
                }

                if (black == k)
                {
                    ans += 1;
                }

            }



        }
        Console.WriteLine(ans);
        Console.ReadLine();

    }

}

