        public static void Main()
        {

            var args = Console.ReadLine().Split().Select(x => int.Parse(x)).ToArray();
            var h = args[0];
            var w = args[1];
            var k = args[2];
            var ans = 0;

            var board = new bool[h][];
            var boardlow = new int[h];

            for (int i = 0; i < h; i++)
            {
                board[i] = Console.ReadLine().ToArray().Select(x => x == '#').ToArray();
                boardlow[i] = board[i].Count(x => x == true);
            }

            k = boardlow.Sum() - k;

            Solve();

            void Solve()
            {

                for (int i = 0, l = (1 << (h + w)); i < l; i++)
                {

                    var res = 0;
                    var buf = new List<int>();

                    for (int j = 0; j < h; j++)
                        if ((i  & (1 << j)) != 0)
                        {

                            res += boardlow[j];
                            buf.Add(j);

                        }

                    if (res > k) continue;

                    for (int j = 0; j < w; j++)
                        if ((i & (1 << (j + h))) != 0)
                        {

                            for (int ii = 0; ii < h; ii++)
                                if ((!buf.Contains(ii)) && board[ii][j] == true)
                                    res++;

                        }

                    if (res == k)
                        ans++;

                }

                Console.WriteLine(ans);

            }


        }
    }

