namespace AtCoder.Abc173
{
    class C
    {
        public static void Main()
        {
            var hwk = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
            var h = hwk[0];
            var w = hwk[1];
            var k = hwk[2];

            var matrix = new int[h][];

            for (int y = 0; y < h; y++)
                matrix[y] = Console.ReadLine().ToCharArray().Select(c => c == '#' ? 1 : 0).ToArray();
            int blackN = matrix.Aggregate(0, (acc, array) => acc += array.Sum());
            int diff = blackN - k;

            if (diff < 0)
            {
                Console.WriteLine(0);
                return;
            }

            int count = 0;


            int yfoot = (1 << h) - 1;
            int xfoot = (1 << w) - 1;
            for (int y = 0; y <= yfoot; y++)
            {
                int n = diff;
                var selectedY = new List<int>();
                int yy = y;
                for (int yi = 0; yi < h; yi++)
                {
                    if ((yy & 1) != 0)
                    {
                        n -= matrix[yi].Sum();
                        selectedY.Add(yi);
                    }
                    yy >>= 1;
                }
                if (n < 0)
                    continue;

                for (int x = 0; x <= xfoot; x++)
                {
                    int m = n;
                    int xx = x;
                    for (int xi = 0; xi < w; xi++)
                    {
                        if ((xx & 1) != 0)
                        {
                            for (int yi = 0; yi < h; yi++)
                            {
                                if (selectedY.Contains(yi))
                                    continue;
                                m -= matrix[yi][xi];
                            }
                        }
                        xx >>= 1;
                    }
                    if (m == 0)
                        count++;
                }
            }

            Console.WriteLine(count);
        }
    }
}

