    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var (height, width, k) = inputStream.ReadValue<int, int, int>();
            var map = new char[height][];

            for (int i = 0; i < height; i++)
            {
                map[i] = inputStream.ReadLine().ToCharArray();
