                            if (!hFlag[row] && !wFlag[column] && map[row][column] == '#')
                            {
                                blacks++;
                            }
                        }
                    }

                    if (blacks == k)
                    {
                        count++;
                    }
                }
            }

            yield return count;
        }
    }
