        var hList = Enumerable.Range(0, hwk[0]).ToArray();

        int Count = 0;

        foreach (var item in wCombinationList)
        {
            if(item.lest == 0)
            {
                Count++;
            }
            for (int i = 1; i <= hwk[1]; ++i)
            {
                foreach (var item1 in Combination(hList, i))
                {
                    int count = 0;
                    foreach (var hId in item1)
                    {
                        foreach (var wId in item.lestlist)
                        {
                            if (c[hId, wId]) count++;
                        }
                    }
                    if (item.lest - count == 0)
                    {
                        Count++;
                    }
                }
            }
        }
        WriteLine(Count);
    }

    public static IEnumerable<int[]> Combination(IEnumerable<int> list, int num)
    {
        if(num == 1)
        {
            foreach(var item in list)
            {
                yield return new int[] { item };
            }
            yield break;
        }

        foreach(var item in list)
        {
            var a = new int[] { item };
            var unused = list.SkipWhile(x => x != item).Skip(1).ToArray();

            foreach (var item1 in Combination(unused, num - 1))
            {
                yield return a.Concat(item1).ToArray();
            }
        }
    }
