class Program
{
	/*
	Cf. 計算量について
	n = 20くらいまでならbit全探索できるよ
	*/

	//n通りのマスクを吐き出す関数（2^0から2^(n-1)まで）
	static List<int> GetMasks(int n){
		//マスクを格納するリストを初期化
		List<int> maskLs = new List<int>();

		//順にリストに格納
		int tempo = 1;
		for(int i=0; i<n; i++){
			maskLs.Add(tempo);
			//1ビット左シフト
			tempo = tempo << 1;
		}

		return maskLs;
	}

	//Main
	static void Main(string[] args)
	{
		//読み込む
		string[] S = Console.ReadLine().Split(' ');
		int H = int.Parse(S[0]);
		int W = int.Parse(S[1]);
		int N = H + W;
		int K = int.Parse(S[2]);

		//グリッドを取得
		char[][] grid = new char[H][];
		for(int i=0; i<H; i++){
			string line = Console.ReadLine();
			grid[i] = new char[H];
			grid[i] = line.ToCharArray();
		}

		//1. 2^n通りの上限値（半開区間で考える：0 〜 2^N - 1（0 <= i < max）までの全整数を探索すれば良い）
		int max = (int)Math.Pow(2, N);

		//2. マスクを取得
		List<int> maskLs = new List<int>();
		maskLs = GetMasks(N);

		//3. それぞれ、マスクと照らし合わせて計算
		int ans = 0;

		for(int i=0; i<max; i++){
			//黒いマスのカウンター
			int cnt = 0;

			//マスをカウントするが、マスクと照合してフラグが立っていた場合、スキップ
			for(int j=0; j<H; j++){
				//j行のフラグが立っている場合、スキップ
				if((maskLs[j] & i) != 0){
					continue;
				}
				else{
					for(int k=0; k<W; k++){
						//k列のフラグが立っている場合、スキップ
						if((maskLs[k+H] & i) != 0){
							continue;
						}
						//そうでない場合、黒マスならカウント
						else if(grid[j][k] == '#'){
							cnt ++;
						}
					}
				}
			}

			//ちょうどK個なら、答えを増やす
			if(cnt == K){
				ans ++;
			}
		}

		Console.WriteLine(ans);
	}
}

