            char[,] c = new char[H, W];

            for (int i = 0; i < H; i++)
            {
                string s = Console.ReadLine();
                for (int j = 0; j < W; j++)
                {
                    c[i, j] = s[j];
                }
            }

            int count = 0;

            // 組合せをBitで表現
            int H_max = 0;
            for (int i = 0; i < H; i++)
            {
                H_max += (1 << i);
            }
            int W_max = 0;
            for (int i = 0; i < W; i++)
            {
                W_max += (1 << i);
            }

            for (int i = 0; i < H_max; i++)
            {
                char[,] temp_c1 = new char[H, W];
                Array.Copy(c, temp_c1, c.Length);

                for (int i2 = 0; i2 < H; i2++)
                {
                    if ((i >> i2 & 0x0001) == 0x0001)
                    {
                        changeXcolor(temp_c1, i2, W);
                    }
                }

                for (int j = 0; j < W_max; j++)
                {
                    char[,] temp_c2 = new char[H, W];
                    Array.Copy(temp_c1, temp_c2, temp_c1.Length);

                    for (int j2 = 0; j2 < W; j2++)
                    {
                        if ((j >> j2 & 0x0001) == 0x0001)
                        {
                            changeYcolor(temp_c2, j2, H);
                        }
                    }
                    if (K == getCount(temp_c2, H, W))
                    {
                        count++;
                    }
                }
            }

            Console.WriteLine(count);
        }

        static void changeXcolor(char[,] c, int num, int max)
        {
            for (int i = 0; i < max; i++)
            {
                c[num, i] = '.';
            }
        }

        static void changeYcolor(char[,] c, int num, int max)
        {
            for (int i = 0; i < max; i++)
            {
                c[i, num] = '.';
            }
        }

        static int getCount(char[,] c, int H, int W)
        {
            int count = 0;
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    if (c[i, j].Equals('#'))
                    {
                        count++;
                    }
                }
            }
            return count;
        }
    }
