                            wl.Add(i);

                    var tmp = (string[,])field.Clone();

                    foreach (var v in hl)
                        for (int i = 0; i < W; i++)
                            tmp[v, i] = "r";

                    foreach (var v in wl)
                        for (int i = 0; i < H; i++)
                            tmp[i, v] = "r";

                    if (Count(tmp) == K) sum++;
                }

            }

            Console.WriteLine(sum);
        }

        static int Count(string[,] field)
        {
            int cnt = 0;
            for (int i = 0; i < field.GetLength(0); i++)
                for (int j = 0; j < field.GetLength(1); j++)
                    if (field[i, j] == "#") cnt++;

            return cnt;
        }
    }
