	public class Solver : SolverBase
	{
		public void Run() {
			ReadInt3(out var H, out var W, out var K);
			List<string> lines = new List<string>();
			for (int i = 0; i < H; i++) {
				var line = ReadLine();
				lines.Add(line);
			}

			int ans = 0;

			// 残す行をBIT全探索
			// 全探索に使用する全bit数
			var n = H;

			// bit mask の生成
			// 2^n     = 1 << n
			for (ulong mask = 0; mask <= ((1ul << n) - 1); mask++) {

				var lineCnt = new int[W];

				// 各bitを下から舐める
				for (int i = 0; i < n; i++) {

					//iビット目が立っている？
					if (0 != (mask & (1ul << i))) {
						// 黒ますならインクリメント
						for (int j = 0; j < W; j++) {
							if (lines[i][j] == '#') {
								lineCnt[j]++;
							}
						}
					}
				}

				// さらにBIT全探索 = W方向
				var nw = W;

				for (ulong maskw = 0; maskw <= ((1ul << nw) - 1); maskw++) {

					var cnt = 0;

					// 各bitを下から舐める
					for (int i = 0; i < nw; i++) {

						//iビット目が立っている？
						if (0 != (maskw & (1ul << i))) {
							// 黒ますならインクリメント
							cnt += lineCnt[i];
						}
					}

					if (cnt == K) {
						++ans;
					}
				}
			}
			WriteLine(ans);
		}
