using System.Text.RegularExpressions;

class Program
{
    const string Yes = "Yes";
    const string No = "No";
    const char White = '.';
    const char Black = '#';
    const long Mod = 1000000007;

    static void Main(string[] args) {
        checked {
#if DEBUG
            MyDebugger.Test(process, "../TextFile1.txt");
            //TestCaseMaker.MakeTestCase1("../TextFile2.txt");
            //MyDebugger.Test(process, "../TextFile2.txt");
#else
            object ret = process(new StreamReader(Console.OpenStandardInput()));
            Console.WriteLine(ret);
#endif
        }
    }

    static object process(TextReader input) {
        var spl = input.ReadLine().Split(' ');
        var h = int.Parse(spl[0]);
        var w = int.Parse(spl[1]);
        var k = int.Parse(spl[2]);

        var tbl = new char[h][];
        for (int i = 0; i < tbl.Length; i++) {
            tbl[i] = input.ReadLine().ToCharArray();
        }

        var list = new List<P>();
        for(int i=0; i<h; i++) {
            for(int j=0; j<w; j++) {
                if(tbl[i][j] == Black) {
                    list.Add(new P { h=i, w=j});
                }
            }
        }

        var bsh = new BitSearch(h);
        var bsw = new BitSearch(w);

        long ret = 0;

        do {
            bsw.Reset();
            do {
                int c = 0;
                foreach(var p in list) {
                    if(!bsh[p.h] && !bsw[p.w]) {
                        c++;
                    }
                }
                if(c==k) ret++;
            }while(bsw.Next());
        }while(bsh.Next());

        return ret;
    }

    class P
    {
        public int h;
        public int w;
    }

    class BitSearch
    {
        private int max;
        private int x;
        public int Length { get; }

        //0~n-1
        public bool this[int i] {
            get {
                var si = Length - i - 1;
                return ((x >> si) & 0x01) == 1;
            }
        }

        public BitSearch(int n) {
            this.Length = n;
            this.max = (int)Math.Pow(2, n) - 1;
            this.x = 0;
        }
        public bool Next() {
            if (x >= max) {
                return false;
            }
            x += 1;
            return true;
        }
        public void Reset() {
            x = 0;
        }
    }

    static int[] ToIntArray(string strs, int n) {
        var ret = new int[n];
        if (n == 0) return ret;
        var spl = strs.Split(' ');
        for (int i = 0; i < n; i++)
            ret[i] = int.Parse(spl[i]);
        return ret;
    }
}

using System;
