using Pi = Pair<int, int>;

class Solver
{
    public Scanner sc;
    public void Solve()
    {
        int H, W, K;
        sc.Make(out H, out W, out K);
        var G = sc.Grid(H);var res = 0;
        for(int i=0;i<(1<<H);i++)
            for(int j = 0; j < (1 << W); j++)
            {
                var P = Create(H, id => G[id].ToArray());
                for(int k = 0; k < H; k++)
                {
                    if ((1 & i >> k) == 0) continue;
                    for (int l = 0; l < W; l++)
                    {
                        P[k][l] = '1';
                    }
                }

                for (int k = 0; k < W; k++)
                {
                    if ((1 & j >> k) == 0) continue;
                    for (int l = 0; l < H; l++)
                    {
                        P[l][k] = '1';
                    }
                }
                var ct = 0;
                for (int k = 0; k < H; k++)
                {
                    for (int l = 0; l < W; l++)
                    {
                        if (P[k][l] == '#') ct++;
                    }
                }
                if (ct == K) res++;
            }
        Console.WriteLine(res);
    }
}

