            string[] c = new string[h];

            for(int i = 0; i < h; i++)
            {
                c[i] = Console.ReadLine();
            }

            int ans = 0;
            for (int i = 0; i < (1 << (h + w)); i++)
            {
                int res = countScore(i, c, h, w);
                if (res == k) ans++;

            }


            Console.WriteLine(ans);

        }

        private static int countScore(int bit, string[] c,int h, int w)
        {
            var res = 0;

            for (int i = 0; i < c.Length; i++)
            {
                for (int j = 0; j < c[i].Length; j++)
                {
                    if ((bit & (1 << i)) != 0 || (bit & (1 << (h + j))) != 0)
                    {
                        continue;
                    }
                    else if (c[i][j] == '#')
                    {
                        res++;
                    }
                }

            }

            return res;

        }

    }
