using System;
using System.Collections;
using System.Collections.Generic;

class Program {
    static void Main (string[] args) {
        var tempstr = Console.ReadLine ().Split (' ');
        int H = int.Parse (tempstr[0]);
        int W = int.Parse (tempstr[1]);
        int K = int.Parse (tempstr[2]);
        ulong table = 0;
        for (int i = 0; i < H; i++) {
            var tempstr2 = Console.ReadLine ().ToCharArray ();
            for (int j = 0; j < W; j++) {
                if (tempstr2[j] == '#') {
                    table += ((ulong) 1 << (W * i + j));
                }
            }
        }
        int ans = 0;
        for (int bit = 0; bit < (1 << (H + W)); bit++) {
            ulong tabledash = ~table;
            for (int i = 0; i < H + W; i++) {
                if ((1 & (bit >> i)) == 1) {
                    if (i < H) {
                        for (int k = 0; k < W; k++) {
                            tabledash |= ((ulong) 1 << (W * i + k));
                        }
                    } else {
                        for (int k = 0; k < H; k++) {
                            tabledash |= ((ulong) 1 << (i - H + W * k));

                        }
                    }
                }
            }
            tabledash = ~tabledash;
            int num = 0;
            for (int i = 0; i < H * W; i++) {
                if (((ulong) 1 & (tabledash >> i)) == 1) {
                    num++;
                }
            }
            if (num == K) {
                ans++;
            }
        }
        Console.WriteLine (ans);
    }

}

