public class Hello
{
    public static int h, w;
    public static void Main()
    {
        string[] line = Console.ReadLine().Trim().Split(' ');
        h = int.Parse(line[0]);
        w = int.Parse(line[1]);
        var b = int.Parse(line[2]);
        var ps = new List<P>();
        for (int i = 0; i < h; i++)
        {
            var s = Console.ReadLine().Trim();
            for (int j = 0; j < w; j++)
                if (s[j] == '#') ps.Add(new P { x = i, y = j });
        }
        getAns(b, ps);
    }
    static int check(List<P> ps, int x, int y)
    {
        var count = 0;
        foreach (var t in ps)
        {
            var cx = (x >> t.x) & 1;
            var cy = (y >> t.y) & 1;
            if (cx == 0 && cy == 0) count++;
        }
        return count;
    }
    static void getAns(int b, List<P> ps)
    {
        var imax = 1 << h;
        var jmax = 1 << w;
        var ans = 0;
        for (int i = 0; i < imax; i++)
        {
            for (int j = 0; j < jmax; j++)
            {
                if (check(ps, i, j) == b) ans++;
            }
        }
        Console.WriteLine(ans);
    }
}

