class Program
{
	static int H,W,K,ans;
	static char[][] grid;

	//全探索
	static void Search(int cnt, List<int> selectedH, List<int> selectedW){
		if(cnt < H){
			List<int> Hls = new List<int>(selectedH);
			Hls.Add(cnt);
			cnt ++;
			Search(cnt, Hls, selectedW);
			Search(cnt, selectedH, selectedW);
		}
		else if(cnt < H + W){
			List<int> Wls = new List<int>(selectedW);
			Wls.Add(cnt - H);
			cnt ++;
			Search(cnt, selectedH, Wls);
			Search(cnt, selectedH, selectedW);
		}
		else{
			Solve(selectedH, selectedW);
		}
	}

	//答えを出す
	static void Solve(List<int> selectedH, List<int> selectedW){
		int cnt = 0;

		for(int i=0; i<H; i++){
			if(selectedH.Contains(i)){
				continue;
			}
			else{
				for(int j=0; j<W; j++){
					if(selectedW.Contains(j)){
						continue;
					}
					else{
						if(grid[i][j] == '#'){
							cnt ++;
						}
					}
				}
			}
		}

		if(cnt == K){
			ans ++;
		}
	}

	//Main
	static void Main(string[] args)
	{
		//読み込む
		string[] S = Console.ReadLine().Split(' ');
		H = int.Parse(S[0]);
		W = int.Parse(S[1]);
		K = int.Parse(S[2]);

		grid = new char[H][];

		//読み込む
		for(int i=0; i<H; i++){
			string line = Console.ReadLine();
			grid[i] = new char[H];
			grid[i] = line.ToCharArray();
		}

		//計算させる
		List<int> Hls = new List<int>();
		List<int> Wls = new List<int>();
		Search(0, Hls, Wls);

		Console.WriteLine(ans);
	}
}

