    public class Solve
    {
        public static void Answer()
        {
            var HWK = IO.RSInt;
            var H = HWK[0];
            var W = HWK[1];
            var K = HWK[2];

            var map = new string[H];
            for (int i = 0; i < H; i++)
            {
                var s = ReadLine();
                map[i] = s;
            }

            var ans = 0;
            for (int bitH = 0; bitH < (1 << H); bitH++)
            {
                var flags_H = new int[H];
                for (int j = 0; j < H; j++)
                {
                    var intFlag_H = (bitH >> j) & 1;
                    flags_H[j] = intFlag_H;
                }

                for (int bit = 0; bit < (1 << W); bit++)
                {
                    var flags = new int[W];

                    for (int i = 0; i < W; i++)
                    {
                        var intFlag = (bit >> i) & 1;
                        flags[i] = intFlag;
                    }

                    int cnt = 0;
                    for (int k = 0; k < H; k++)
                    {
                        for (int l = 0; l < W; l++)
                        {
                            if (flags_H[k] == 0 && flags[l] == 0)
                            {
                                if (map[k][l] == '#')
                                {
                                    cnt++;
                                }
                            }
                        }
                    }
                    if (cnt == K) ans++;
                }
            }
            WriteLine(ans);
        }
    }

