using System;
using System.Linq;
using System.Collections.Generic;

namespace ABC
{
    class ProgramC
    {
        const int white = 0;
        const int black = 1;
        const int red = 2;

        static void Main(string[] args)
        {

            var inputs = Console.ReadLine().Split(" ");
            var h = int.Parse(inputs[0]);
            var w = int.Parse(inputs[1]);
            var k = int.Parse(inputs[2]);

            var matrix = new char[h, w];

            var result = 0;

            for (var i = 0; i < h; i++)
            {
                var list = Console.ReadLine().ToCharArray();
                for (var j = 0; j < w; j++)
                {
                    matrix[i, j] = list[j];
                }
            }

            // 行と列の選択状態をbitで表現する
            // 1 << h は2^hとなり、全bit立った状態+1になる
            for (var i = 0; i < (1 << h); i++)
            {
                for (var j = 0; j < (1 << w); j++)
                {
                    var cnt = 0;
                    // bitシフトループ
                    for (var si = 0; si < h; si++)
                    {
                        for (var sj = 0; sj < w; sj++)
                        {
                            if (((i >> si) & 1) == 1) continue;
                            if (((j >> sj) & 1) == 1) continue;
                            if (matrix[si, sj] == '#')
                                cnt++;
                            if (k < cnt) break;
                        }
                    }

                    if (k == cnt)
                    {
                        result++;
                    }
                }
            }

            Console.WriteLine(result);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;

public static class Program
{
    public static void Main()
    {
        var hwk = ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
        var c = new bool[hwk[0], hwk[1]];
        var verticalCount = new int[hwk[1]];
        int blackCount = 0;
        for (int i = 0; i < hwk[0]; ++i)
        {
            var line = ReadLine();
            for(int j = 0; j < hwk[1]; ++j)
            {
                var isBlack = line[j] == '#';
                c[i, j] = isBlack;
                if (isBlack)
                {
                    verticalCount[j] += 1;
                    ++blackCount;
                }
            }
        }


        var wCombinationList = new List<(int[] lestlist, int lest)>();

        var wList = Enumerable.Range(0, hwk[1]).ToArray();

        wCombinationList.Add((wList.ToArray(), blackCount - hwk[2]));

        for (int i = 1; i < hwk[1]; ++i)
        {
            foreach (var item in Combination(wList, i))
            {
                int count = 0;
                foreach(var wId in item)
                {
                    count += verticalCount[wId];
                }
                if (blackCount - count >= hwk[2]) wCombinationList.Add((wList.Except(item).ToArray(), blackCount - count - hwk[2]));
            }
        }

        var hList = Enumerable.Range(0, hwk[0]).ToArray();

        int Count = 0;

        foreach (var item in wCombinationList)
        {
            if(item.lest == 0)
            {
                Count++;
            }
            for (int i = 1; i < hwk[1]; ++i)
            {
                foreach (var item1 in Combination(hList, i))
                {
                    int count = 0;
                    foreach (var hId in item1)
                    {
                        foreach (var wId in item.lestlist)
                        {
                            if (c[hId, wId]) count++;
                        }
                    }
                    if (item.lest - count == 0)
                    {
                        Count++;
                    }
                }
            }
            if (hwk[2] == 0) Count++;
        }
        if (hwk[2] == 0)
        {
            for (int i = 1; i < hwk[0]; ++i)
            {
                Count += Combination(hList, i).Count();
            }
            Count+=2;
        }
        WriteLine(Count);
    }

    public static IEnumerable<int[]> Combination(IEnumerable<int> list, int num)
    {
        if(num == 1)
        {
            foreach(var item in list)
            {
                yield return new int[] { item };
            }
            yield break;
        }

        foreach(var item in list)
        {
            var a = new int[] { item };
            var unused = list.SkipWhile(x => x != item).Skip(1).ToArray();

            foreach (var item1 in Combination(unused, num - 1))
            {
                yield return a.Concat(item1).ToArray();
            }
        }
    }
}

