namespace ABC
{
    class ABC173C
    {
        const string FILE = "/tmp/data.txt";

        static int R;
        static int C;
        static void Main(string[] args)
        {
#if DEBUG
            Console.SetIn(new StreamReader(FILE));
#endif
            var Ia = RIa(3);
            R = Ia[0];
            C = Ia[1];
            int K = Ia[2];

            int kTotal;
            int[,] matrix = RC(R, C, out kTotal);

            int Rmax = 0x01 << R;
            int Cmax = 0x01 << C;


            long ans = 0;
            for (int r = 0; r < Rmax; ++r)
            {
                for (int c = 0; c < Cmax; ++c)
                {
                    int[,] mat = new int[R, C];
                    for (int i = 0; i < R; ++i)
                    {
                        for (int j = 0; j < C; ++j)
                        {
                            mat[i, j] = matrix[i, j];
                        }
                    }

                    if (paint(r, c, mat, K, kTotal))
                    {
                        ans += 1;
                    }
                }
            }
            Console.WriteLine(ans);

#if DEBUG
            Console.WriteLine("*** end ***");
            Console.SetIn(Console.In);
            Console.ReadKey();
            Console.WriteLine();
#endif
        }

        private static bool paint(int r, int c, int[,] matrix, int K, int kcurrent)
        {
            for (int count = 0, i = 0x01; i <= r; i <<= 1, count += 1)
            {
                if ((i & r) != 0)
                {
                    for (int j = 0; j < C; ++j)
                    {
                        if (matrix[count, j] == 1)
                        {
                            matrix[count, j] = 0;
                            kcurrent -= 1;
                            if (kcurrent < K)
                            {
                                return false;
                            }
                        }
                    }
                }
            }

            for (int count = 0, i = 0x01; i <= c; i <<= 1, count += 1)
            {
                if ((i & c) != 0)
                {
                    for (int j = 0; j < R; ++j)
                    {
                        if (matrix[j, count] == 1)
                        {
                            matrix[j, count] = 0;
                            kcurrent -= 1;
                            if (kcurrent < K)
                            {
                                return false;
                            }
                        }
                    }
                }
            }
            return kcurrent == K;
        }

        static int RI()
        {
            return int.Parse(Console.ReadLine());
        }

        static int[] RIa(int n)
        {
            string[] sa = Console.ReadLine().Split(' ');
            int[] la = new int[n];
            for (int i = 0; i < n; ++i)
            {
                la[i] = int.Parse(sa[i]);
            }
            return la;
        }

        static int[,] RC(int r, int c, out int ktotal)
        {
            ktotal = 0;
            int[,] la = new int[r, c];
            for (int i = 0; i < r; ++i)
            {
                char[] ca = Console.ReadLine().ToCharArray();
                for (int j = 0; j < c; ++j)
                {
                    if (ca[j] == '#')
                    {
                        la[i, j] = 1;
                        ktotal += 1;
                    }
                }
            }
            return la;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static bool IsK(string[] grid, int bx, int by, int k)
    {
        var count = 0;
        for (int y = 0; y < grid.Length; y++)
        {
            if (((1 << y) & by) != 0)
            {
                continue;
            }
            for (int x = 0; x < grid[0].Length; x++)
            {
                if (((1 << x) & bx) != 0)
                {
                    continue;
                }
                if (grid[y][x] == '#')
                {
                    count++;
                }
            }
        }

        return count == k;
    }

    public static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var H = vals[0];
        var W = vals[1];
        var K = vals[2];
        var grid = new string[H];
        for (int y = 0; y < H; y++)
        {
            grid[y] = Console.ReadLine();
        }

        var count = 0;
        for (int y = 0; y < (1 << H); y++)
        {
            for (int x = 0; x < (1 << W); x++)
            {
                if (IsK(grid, x, y, K))
                {
                    count++;
                }
            }
        }

        Console.WriteLine(count);
    }
}

