class Program
{
    static void Main(string[] args)
    {
        int[] pow2 = {1, 2, 4, 8, 16, 32, 64, 128, 256, 512};
        string[] input = Console.ReadLine().Split(' ');
        int h = int.Parse(input[0]);
        int w = int.Parse(input[1]);
        int k = int.Parse(input[2]);
        int r = 0;
        char[,] board = new char[h,w];
        char[,] calcBoard = new char[h,w];

        for (int i = 0; i < h; i++)
        {
            char[] line = Console.ReadLine().ToCharArray();
            for (int j = 0; j < w; j++)
            {
                board[i, j] = line[j];
            }
        }


        for (int i = 0; i < pow2[h]; i++)
        {
            for (int j = 0; j < pow2[w]; j++)
            {
                bool[] ri = new bool[6];
                bool[] rj = new bool[6];

                for (int x = 0; x < h; x++)
                {
                    for (int y = 0; y < w; y++)
                    {
                        calcBoard[x, y] = board[x, y];
                    }
                }
                int count = 0;

                for (int ki = 0; ki < 6; ki++) ri[ki] = i / pow2[ki] % 2 == 1;
                for (int kj = 0; kj < 6; kj++) rj[kj] = j / pow2[kj] % 2 == 1;
                for (int a = 0; a < h; a++)
                {
                    for (int b = 0; b < w; b++)
                    {
                        if (ri[a] || rj[b])
                        {
                            calcBoard[a, b] = '@';
                        }


                        if (calcBoard[a, b] == '#')
                        {
                            count++;
                        }
                    }
                }

                if (count == k)
                {
                    r++;
                }
            }
        }

        Console.WriteLine(r);
    }
