function createMasks(width, height) {
    const maskArray = [];
    for (let y = 0; y < 2 ** height - 1; y++) {
        const row = y.toString(2).padStart(height, 0);
        for (let x = 0; x < 2 ** width; x++) {
            const col = x.toString(2).padStart(width, 0);
            const rc = [row, col];
            maskArray.push(correctMask(rc));
        }
    }
    return maskArray;
}

function correctMask(rc) {
    const [row, col] = rc;
    const mask = [];
    for (let y = 0; y < row.length; y++) {
        for (let x = 0; x < col.length; x++) {
            mask.push(Number(row[y]) | Number(col[x]));
        }
    }
    return mask;
}

