const byteToDigits = (byte) => {
  let digit = 0
  const digits = {}

  while (byte > 0) {
    if (byte % 2 === 1) {
      digits[digit] = true
    }

    byte = Math.floor(byte / 2)
    digit++
  }

  return digits
}

