function Main(input) {

	// 1行目がinput[0], 2行目がinput[1], …に入る
	input = input.split("\n");

    let H = input[0].split(" ")[0];
    let W = input[0].split(" ")[1];
    let K = input[0].split(" ")[2];

    input.shift();

    let board = Array(H);
    let res = 0;

    for (let i = 0; i < H; i++) {

        let rows = input[i].split("");
        board[i] = rows.map(value => {
            if (value == ".") return 0;
            else return 1;
        });

    } //ここまでboard初期化

    for (let i = 0; i < 2 ** H; i++) {

        for (let j = 0; j < 2 ** W; j++) {

            let row_len = i.toString(2).split("").length;
            let col_len = j.toString(2).split("").length;

            let row_bit = i.toString(2).split("").map((value, index) => {
                if (value == "1") return row_len - index - 1;
                else return "";
            }).filter(value => value !== "");

            let column_bit = j.toString(2).split("").map((value, index) => {
                if (value == "1") return col_len - index - 1;
                else return "";
            }).filter(value => value !== "");

            let tmp_board = fillColumnAsRed(board, column_bit);
            tmp_board = fillRowAsRed(tmp_board, row_bit);
            //処理完了

            let sum = 0;
            tmp_board.forEach(value => {
                sum += value.filter(v => v === 1).length;
            })

            if (sum == K) res++;

        }

    }

    console.log(res);

}

function fillRowAsRed(board, rows){

    board = board.map((value, index) => {

        if(rows.indexOf(index) > -1) return value.fill(0);
        else return value;

    });

    return board;

}

function fillColumnAsRed(board, columns){

    board = board.map((value) => {

        return value.map((v, index) => {

            if(columns.indexOf(index) > -1) return 0;
            else return v;

        });

    });

    return board;

}

