func solve(hw []string, h, w, k int) int {
	answer := 0

	for is := 0; is < (1<<h); is++ {
		for js := 0; js < (1<<w); js++ {
			cnt := 0
			for i := 0; i < h; i++ {
				for j := 0; j < w; j++ {
					if (is >> i)&1 == 1 {
						continue
					}
					if (js >> j)&1 == 1  {
						continue
					}
					if string(hw[i][j]) == "#" {
						cnt++
					}
				}
			}
			if cnt == k {
				answer++
			}
		}
	}

	return answer
}

