	ans := 0
	for y := 0; y < (1<<H)-1; y++ {
		for x := 0; x < (1<<W)-1; x++ {
			sum := 0
			for n := 0; n < H; n++ {
				if ((1 << n) & y) != 0 {
					continue
				}

				for m := 0; m < W; m++ {
					if ((1 << m) & x) != 0 {
						continue
					}
					if C[n][m] == "#" {
						sum++
					}
				}
			}
			if sum == K {
				ans++
			}
		}
	}
	fmt.Printf("%d\n", ans)
}

