const Black int = 35

func countBlack(h, w int, m [][]int) int {
	count := 0
	debug("new table")
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			if m[i][j] == Black {
				count++
			}
		}
		debug(m[i])
	}
	debug("result : ", count)
	return count
}

func solve(h, w, a int, m [][]int) int {
	result := 0
	for i := 0; i < 1<<h; i++ {
		for k := 0; k < 1<<w; k++ {
			tmp := make([][]int, h)
			for j := 0; j < h; j++ {
				tmp[j] = make([]int, w)
				copy(tmp[j], m[j])
			}
			for j := 0; j < h; j++ {
				hPainted := (1 << j & i)
				if hPainted > 0 {
					debug("painted ", j, 1<<j, i, hPainted)
					for l := 0; l < w; l++ {
						tmp[j][l] = 1
					}
				}
			}
			for j := 0; j < w; j++ {
				wPainted := (1 << j & k)
				if wPainted > 0 {
					for l := 0; l < h; l++ {
						tmp[l][j] = 1
					}
				}
			}
			debug("i", strconv.FormatInt(int64(i), 2))
			debug("k", strconv.FormatInt(int64(k), 2))
			if countBlack(h, w, tmp) == a {
				result++
			}
		}
	}
	return result
}

