import "fmt"

func main() {
	var h, w, k int
	count := 0

	// 標準入力から3つ値を受け取る
	fmt.Scan(&h, &w, &k)

	// 行列を保持するスライス
	c := make([]string, h, h)

	// 拡張for文(foreach)
	// cの各要素に対して標準入力の値を格納
	for i := range c {
		fmt.Scan(&c[i])
	}

	// 各行のステイ・赤を決める数値
	for i := 0; i < 1<<h; i++ {
		// 各列のステイ・赤を決める数値
		for l := 0; l < 1<<w; l++ {
			// 数えた黒の数を入れる変数sharpNum
			sharpNum := countSharp(c, i, l)

			if sharpNum == k {
				count++
			}
		}
	}

	fmt.Println(count)
}

// iは該当行を変更させるかどうかを確認する指標。2進数表記で対象行が1なら赤に変える、0ならそのまま
// lは該当列を変更させるかどうかを確認する指標。2進数表記で対象列が1なら赤に変える、0ならそのまま
func countSharp(c []string, i, l int) int {
	sharpNum := 0

	for p := 0; p < len(c); p++ {
		// 行の変更有無を持つ数値の該当行の値を調べる
		if (i >> p & 1) == 1 {
			continue //赤なので、すべて黒＝後の処理は必要ない
		}

		// 黒のまま残るか、残らないかチェック→残る場合は黒としてカウントする
		for q := 0; q < len(c[0]); q++ {
			if (l >> q & 1) == 1 {
				continue
			}

			if c[p][q] == '#' {
				sharpNum++
			}
		}
	}

	return sharpNum
}

