	var K int
	fmt.Scan(&H)
	fmt.Scan(&W)
	fmt.Scan(&K)
	sc.Split(bufio.ScanWords)
	tmp := make([][]bool, H)
	for i := 0; i < H; i++ {
		str := nextLine()
		l := []bool{}
		for j := 0; j < W; j++ {
			if string(str[j]) == "#" {
				l = append(l, true)
			} else {
				l = append(l, false)
			}
		}
		tmp[i] = l
	}
	test := [][][]bool{tmp}
	for i := 0; i < H; i++ {
		for _, t := range test {
			tt := chc(t, i)
			test = append(test, tt)
		}
	}
	for i := 0; i < W; i++ {
		for _, t := range test {
			test = append(test, chl(t, i))
		}
	}
	count := 0
	for _, t := range test {
		if helper(t) == K {
			count++
		}
	}
	fmt.Print(count)
}
func chc(m [][]bool, p int) [][]bool {
	ret := make([][]bool, len(m))
	for i, l := range m {
		tmp := []bool{}
		for _, c := range l {
			if i == p {
				tmp = append(tmp, false)
			} else if c == true {
				tmp = append(tmp, true)
			} else {
				tmp = append(tmp, false)
			}
		}
		ret[i] = tmp
	}
	return ret
}
func chl(m [][]bool, p int) [][]bool {
	ret := make([][]bool, len(m))
	for j, l := range m {
		tmp := []bool{}
		for i, c := range l {
			if i == p {
				tmp = append(tmp, false)
			} else if c == true {
				tmp = append(tmp, true)
			} else {
				tmp = append(tmp, false)
			}
		}
		ret[j] = tmp
	}
	return ret
}
func helper(ma [][]bool) int {
	count := 0
	for _, l := range ma {
		for _, c := range l {
			if c == true {
				count++
			}
		}
	}
	return count
}
