var (
	H, W, K    int
	black, red [][]bool
)

func main() {
	defer writer.Flush()
	readVariables()
	var answer int
	for br := 0; br < 1<<H; br++ {
		for bc := 0; bc < 1<<W; bc++ {
			clearRed()
			for i := 0; i < H; i++ {
				if 1<<i&br > 0 {
					setRowRed(i)
				}
			}
			for j := 0; j < W; j++ {
				if 1<<j&bc > 0 {
					setColRed(j)
				}
			}
			k := count()
			if k == K {
				answer++
			}
		}
	}
	println(answer)
}

func count() int {
	var result int
	for i := 0; i < H; i++ {
		for j := 0; j < W; j++ {
			if black[i][j] && !red[i][j] {
				result++
			}
		}
	}
	return result
}

func setRowRed(i int) {
	for j := 0; j < W; j++ {
		red[i][j] = true
	}
}
func setColRed(j int) {
	for i := 0; i < H; i++ {
		red[i][j] = true
	}
}

func clearRed() {
	for i := 0; i < H; i++ {
		for j := 0; j < W; j++ {
			red[i][j] = false
		}
	}
}

func readVariables() {
	H, W, K = nextInt(), nextInt(), nextInt()
	black = make([][]bool, H)
	red = make([][]bool, H)
	for i := 0; i < H; i++ {
		black[i] = make([]bool, W)
		red[i] = make([]bool, W)
	}
	for i := 0; i < H; i++ {
		row := nextStr()
		for j := 0; j < W; j++ {
			black[i][j] = row[j] == '#'
		}
	}
}

