var (
	scanner  *bufio.Scanner
	byWord   bool   //flag for tokenization
	eof      bool   //flag of end-of-file
	splitter string //delimiter for Ints(), etc.
)

func main() {
	h, w, k := Ints3()
	total_black := 0
	grid := make([][]bool, h)
	for i := 0; i < h; i++ {
		grid[i] = make([]bool, w)
		l := Line()
		for j := 0; j < w; j++ {
			if l[j] == '#' {
				grid[i][j] = true
				total_black++
			}
		}
	}
	row_black := make([]int, h)
	col_black := make([]int, w)
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			if grid[i][j] {
				row_black[i]++
				col_black[j]++
			}
		}
	}
	ans := 0
	for i := 0; i < (1 << h); i++ {
		for j := 0; j < (1 << w); j++ {
			temp := total_black
			var rows []int
			ii := i
			for x := 0; x < h; x++ {
				if ii%2 == 1 {
					rows = append(rows, x)
					temp -= row_black[x]
				}
				ii /= 2
			}
			jj := j
			for y := 0; y < w; y++ {
				if jj%2 == 1 {
					temp -= col_black[y]
					for _, x := range rows {
						if grid[x][y] {
							temp++
						}
					}
				}
				jj /= 2
			}
			if temp == k {
				ans++
			}
		}
	}
	fmt.Println(ans)
}

