	for i := 0; i < h; i++ {
		var s string
		fmt.Scanf("%s", &s)
		line := []int{}
		for j := 0; j < w; j++ {
			if s[j] == '.' {
				line = append(line, 0)
			} else {
				line = append(line, 1)
			}
		}
		cells = append(cells, line)
	}

	max := int(math.Pow(2, float64(h+w)))
	answer := 0
	for x := 0; x < max; x++ {
		c := countBlack(paint(cells, h, w, x), h, w)
		if c == k {
			answer++
		}
	}
	fmt.Printf("%d\n", answer)
}

func countBlack(cells [][]int, h, w int) int {
	count := 0
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			if cells[i][j] == 1 {
				count++
			}
		}
	}
	return count
}

func paint(cells [][]int, h, w, choice int) [][]int {

	result := [][]int{}
	for i := 0; i < h; i++ {
		line := []int{}
		for j := 0; j < w; j++ {
			line = append(line, cells[i][j])
		}
		result = append(result, line)
	}

	for i := 0; i < h; i++ {
		if (choice>>uint64(i))%2 == 1 {
			for j := 0; j < w; j++ {
				result[i][j] = 0
			}
		}
	}
	choice = choice >> uint64(h)
	for j := 0; j < w; j++ {
		if (choice>>uint64(j))%2 == 1 {
			for i := 0; i < h; i++ {
				result[i][j] = 0
			}
		}
	}

	return result
}

