		c[i] = io.Next()
	}
	ans := solve(h, w, k, c)
	io.Println(ans)
}

func solve(h, w, k int, c []string) (ans int) {
	for i, iMax := 0, 1<<h; i < iMax; i++ {
		ignoreRows := map[int]struct{}{}
		for shift := 0; shift < h; shift++ {
			if i>>shift&1 == 1 {
				ignoreRows[shift] = struct{}{}
			}
		}
		for j, jMax := 0, 1<<w; j < jMax; j++ {
			ignoreCols := map[int]struct{}{}
			for shift := 0; shift < w; shift++ {
				if j>>shift&1 == 1 {
					ignoreCols[shift] = struct{}{}
				}
			}
			cnt := count(c, ignoreRows, ignoreCols)
			if cnt == k {
				ans++
			}
		}
	}
	return ans
}

func count(c []string, ignoreRows, ignoreCols map[int]struct{}) int {
	ret := 0
	for i, row := range c {
		if _, ok := ignoreRows[i]; ok {
			continue
		}
		for j, char := range row {
			if _, ok := ignoreCols[j]; ok {
				continue
			}
			if char == '#' {
				ret++
			}
		}
	}
	return ret
}

// Io is I/O object
type Io struct {
	reader    *bufio.Reader
	writer    *bufio.Writer
	tokens    []string
	nextToken int
}

// NewIo returns a new Io instance
func NewIo(r io.Reader, w io.Writer) *Io {
	return &Io{
		reader: bufio.NewReader(r),
		writer: bufio.NewWriter(w),
	}
}

// Flush flushes writer
func (io *Io) Flush() {
	err := io.writer.Flush()
	if err != nil {
		panic(err)
	}
}

// NextLine scans a line from stdin
func (io *Io) NextLine() string {
	var buffer []byte
	for {
		line, isPrefix, err := io.reader.ReadLine()
		if err != nil {
			panic(err)
		}
		buffer = append(buffer, line...)
		if !isPrefix {
			break
		}
	}
	return string(buffer)
}

// Next return a word from stdin
func (io *Io) Next() string {
	for io.nextToken >= len(io.tokens) {
		line := io.NextLine()
		io.tokens = strings.Fields(line)
		io.nextToken = 0
	}
	r := io.tokens[io.nextToken]
	io.nextToken++
	return r
}

// NextInt returns an integer from stdin
func (io *Io) NextInt() int {
	i, err := strconv.Atoi(io.Next())
	if err != nil {
		panic(err)
	}
	return i
}

// Println is a wrapper of fmt.Fprintln
func (io *Io) Println(a ...interface{}) {
	fmt.Fprintln(io.writer, a...)
}

