func makePattern(num int) [][]int {
    length := int(math.Pow(2, float64(num)))
    result := make([][]int, length)

    for i := 0; i < length; i++ {
        bi := i
        s := []int{}
        for n := 0; n < num; n++ {
            if bi % 2 != 0 {
                s = append(s, n)
            }
            bi = bi / 2

        }
        result[i] = s
    }

    return result
}

func contains(s []int, e int) bool {
	for _, v := range s {
		if e == v {
			return true
		}
	}
	return false
}

func countElem(c [][]bool, exRows []int, exCols []int) int {
	count := 0
	for i := 0; i < len(c); i++ {
		if (contains(exRows, i)) {
			continue
		}
		for j := 0; j < len(c[i]); j++ {
			if (contains(exCols, j)) {
				continue
			}
			if (c[i][j]) {
				count++
			}
		}
	}
	return count
}

func main() {
	var h, w, k int
	fmt.Scanf("%d %d %d", &h, &w, &k)
	c := make([][]bool, h)
	rowCount := make([]int, h)
	total := 0
	for i := 0; i < h; i++ {
		c[i] = make([]bool, w)
		rowCount[i] = 0;
		for j := 0; j < w; j++ {
			var tmp int
			fmt.Scanf("%c", &tmp)
			if (tmp == int('#')) {
				c[i][j] = true
				rowCount[i]++
			} else {
				c[i][j] = false
			}
		}
		fmt.Scanf("%s")		// 行末まで捨てる
		total += rowCount[i]
	}
    // fmt.Printf("%v", &c)

	answer := 0;
	rowPattern := makePattern(h)
	columnPattern := makePattern(w)
	for i := 0; i < len(rowPattern); i++ {
		remain := total
		for x := 0; x < len(rowPattern[i]); x++ {
			remain -= rowCount[rowPattern[i][x]]
		}
		if remain < k{
			continue
		}
		for j := 0; j < len(columnPattern); j++ {
			if k == countElem(c, rowPattern[i], columnPattern[j]) {
				answer++
			}
		}
	}
    fmt.Printf("%d", answer)
}

