func solve(sc *scanner, wr *bufio.Writer) int {
	H := sc.i()
	W := sc.i()
	K := sc.i()
	C := make([][]int, H)
	for h := 0; h < H; h++ {
		C[h] = make([]int, W)
		s := sc.s()
		for w, c := range s {
			if c == '#' {
				C[h][w] = 1
			}
		}
	}

	total := 0

	var fn func(r []int)
	var fn2 func(r, c []int)

	fn = func(r []int) {
		if len(r) > H {
			return
		}

		fn2(r, []int{})

		v := 0
		if len(r) > 0 {
			v = r[len(r)-1] + 1
		}
		for i := v; i < H; i++ {
			fn(append(r, i))
		}
	}

	fn2 = func(r, c []int) {
		if len(c) > W {
			return
		}

		count := 0
		for i := 0; i < H; i++ {
			foundR := false
			for _, v := range r {
				if v == i {
					foundR = true
				}
			}
			if foundR {
				continue
			}
			for j := 0; j < W; j++ {
				foundC := false
				for _, v := range c {
					if v == j {
						foundC = true
					}
				}
				if foundC {
					continue
				}

				count += C[i][j]
			}
		}

		if count == K {
			total++
		}

		// fmt.Println("count", count, "total", total, "r", r, "c", c)

		v := 0
		if len(c) > 0 {
			v = c[len(c)-1] + 1
		}
		for i := v; i < W; i++ {
			fn2(r, append(c, i))
		}
	}

	fn([]int{})

	fmt.Println(total)

	return 0
}

