func countColor(targetColor color, c [][]color) int {
	count := 0
	for _, ci := range c {
		for _, cij := range ci {
			if cij == targetColor {
				count++
			}
		}
	}
	return count
}

func cloneColors(src [][]color) [][]color {
	dst := make([][]color, len(src))
	for i, srcLine := range src {
		dstLine := make([]color, len(srcLine))
		dst[i] = dstLine

		for j, srcColor := range srcLine {
			dstLine[j] = srcColor
		}
	}
	return dst
}

func AllBits(bitsLen int, callback func(bits []bool)) {
	for deci := 0; deci < 1<<bitsLen; deci++ {
		bits := make([]bool, bitsLen)
		for digit := 0; digit < bitsLen; digit++ {
			bits[bitsLen-1-digit] = deci&(1<<digit) > 0
		}

		callback(bits)
	}
}

