func main() {
	var H, W, K int
	fmt.Scanf("%d %d %d", &H, &W, &K)

	var total int
	hCounts := make([]int, H)
	wCounts := make([]int, W)
	bord := make([][]int, H)
	for i := 0; i < H; i++ {
		var s string
		fmt.Scanf("%s", &s)
		line := strings.Split(s, "")

		bord[i] = make([]int, W)
		for k, v := range line {
			if v == "#" {
				total++
				hCounts[i]++
				wCounts[k]++
				bord[i][k] = 1
			}
		}
	}
	var ret int
	hKeys := Powerset2(H)
	wKeys := Powerset2(W)

	for _, hk := range hKeys {
		for _, wk := range wKeys {
			v := exec(total, hCounts, wCounts, bord, hk, wk)
			if v == K {
				ret++
			}
		}
	}
	fmt.Println(ret)
}

func exec(total int, hCounts []int, wCounts []int, bord [][]int, hk []int, wk []int) int {
	ret := total
	for k, v := range hk {
		if v == 1 {
			ret -= hCounts[k]
		}
	}
	for k, v := range wk {
		if v == 1 {
			ret -= wCounts[k]
		}
	}

	for hk, hv := range hk {
		for wk, wv := range wk {
			if hv == 1 && wv == 1 && bord[hk][wk] == 1 {
				ret++
			}
		}
	}

	return ret
}

func Powerset2(num int) [][]int {
	length := int(math.Pow(2, float64(num)))
	result := make([][]int, length)

	index := 0
	result[index] = []int{0}
	index++

	result[index] = []int{1}
	index++

	for n := 1; n < num; n++ {
		tmp := index
		for i := 0; i < tmp; i++ {
			result[index] = copyAndAppend(result[i], 1)
			index++
		}

		for i := 0; i < tmp; i++ {
			result[i] = copyAndAppend(result[i], 0)
		}

	}

	return result
}

func copyAndAppend(nums []int, n int) []int {
	dst := make([]int, len(nums)+1)
	copy(dst, nums)
	dst[len(nums)] = n
	return dst
}

func getKeys(size int) [][]int {
	ret := make([][]int, 0, 0)

	if size == 1 {
		ret = append(ret, []int{0})
		ret = append(ret, []int{1})
		return ret
	}

	childs := make([][]int, 0, 0)
	childs = getKeys(size - 1)
	ret = append(ret, add(childs, 0)...)
	fmt.Println("ch")
	fmt.Println(ret)

	ret = append(ret, add(childs, 1)...)
	fmt.Println("cp")
	fmt.Println(ret)
	return ret
}

func add(a [][]int, n int) [][]int {
	var ret [][]int
	for _, v := range a {
		v = append(v, n)
		ret = append(ret, v)
	}
	return ret
}

