	w := sc.ReadInt()
	k := sc.ReadInt()
	c := make([][]color, h)
	for i := 0; i < h; i++ {
		ci := make([]color, w)
		c[i] = ci
		line := sc.ReadString()
		for j, char := range line {
			switch char {
			case '.':
				ci[j] = colorWhite
			case '#':
				ci[j] = colorBlack
			default:
				panic(fmt.Sprintf("unexpcted character: %v", char))
			}
		}
	}

	count := 0
	AllBits(h, func(lineBits []bool) {
		redlinedSquares := cloneColors(c)
		for i, willLine := range lineBits {
			if willLine {
				for j := 0; j < w; j++ {
					redlinedSquares[i][j] = colorRed
				}
			}
		}

		AllBits(w, func(columnBits []bool) {
			squares := cloneColors(redlinedSquares)
			for j, willCol := range columnBits {
				if willCol {
					for i := 0; i < h; i++ {
						squares[i][j] = colorRed
					}
				}
			}

			if countColor(colorBlack, squares) == k {
				count++
			}
		})
	})

	fmt.Println(count)
}

func countColor(target color, c [][]color) int {
	count := 0
	for _, ci := range c {
		for _, cij := range ci {
			if cij == target {
				count++
			}
		}
	}
	return count
}

func cloneColors(src [][]color) [][]color {
	dst := make([][]color, len(src))
	for i, srcLine := range src {
		dstLine := make([]color, len(srcLine))
		dst[i] = dstLine

		for j, srcColor := range srcLine {
			dstLine[j] = srcColor
		}
	}
	return dst
}

func AllBits(bitsLen int, f func(bits []bool)) {
	for k := 0; k < Pow(2, uint(bitsLen)); k++ {
		bits := make([]bool, bitsLen)
		for i := 0; i < bitsLen; i++ {
			mask := Pow(2, uint(i))
			if k&mask > 0 {
				bits[bitsLen-1-i] = true
			}
		}

		f(bits)
	}
}

