func solve() {
	fmt.Scanf("%d %d %d", &H, &W, &K)
	S := make([][]bool, H)
	for i := 0; i < H; i++ {
		var s string
		fmt.Scanf("%s", &s)
		S[i] = make([]bool, W)
		for j, c := range s {
			if c == '.' {
				S[i][j] = false
			} else {
				S[i][j] = true
			}
		}
	}

	hl := bit(H)
	wl := bit(W)
	ans := 0
	for _, h := range hl {
		for _, w := range wl {
			if check(h, w, S) {
				ans += 1
			}
		}
	}
	fmt.Println(ans)
}

func check(hl []bool, wl []bool, S [][]bool) bool {
	SCopy := make([][]bool, len(S))
	for i, s := range S {
		SCopy[i] = make([]bool, len(S[i]))
		for j, b := range s {
			SCopy[i][j] = b
		}
	}

	for i, b := range hl {
		if b {
			continue
		}
		for j := 0; j < W; j++ {
			SCopy[i][j] = false
		}
	}

	for i, b := range wl {
		if b {
			continue
		}
		for j := 0; j < H; j++ {
			SCopy[j][i] = false
		}
	}

	c := 0
	for _, s := range SCopy {
		for _, b := range s {
			if b {
				c += 1
			}
		}
	}

	return c == K
}

