func bit(size int) [][]bool {
	b := make([][]bool, size*size)
	for i := 0; i < size*size; i++ {
		b[i] = make([]bool, size)
		for j := 0; j < size; j++ {
			if i>>j&1 == 1 {
				b[i][j] = true
			} else {
				b[i][j] = false
			}
		}
	}
	return b
}

