  const wPickFn = (n: number, wPicks: PickData[]): number =>
    n >= grid.width
      ? (() => {
          const hCnt = getBlackCnt(
            range(grid.height).map((i) => ({ index: i, isPicked: true })),
            wPicks,
            grid
          );
          const wCnt = getBlackCnt(
            hPicks,
            range(grid.width).map((j) => ({ index: j, isPicked: true })),
            grid
          );
          const hwCnt = getBlackCnt(hPicks, wPicks, grid);
          return initialBlackCnt - (hCnt + wCnt - hwCnt);
