const range = (length: number) =>
  [...Array(length).keys()]

function main(input: string) {
  const [header, ...lines] = input.split('\n')
  const [h, w, k] = header.split(' ').map(Number)

  // すべてのマス
  const cells = lines.flatMap((v, row) =>
    v.split('').map((color, col) => ({ color, row, col }))
  )

  // 行・列選びパターン
  const pattarn = range(1 << h << w).map(mask => {
    const rows = new Set(range(h).filter(v => (mask >> w >> v) & 1))
    const cols = new Set(range(w).filter(v => (mask >> v) & 1))

    return { rows, cols }
  })

  const result = pattarn.filter(({ rows, cols }) => {
    const blackCells = cells.filter(cell =>
      cell.color === '#' && !rows.has(cell.row) && !cols.has(cell.col)
    )

    return blackCells.length === k
  })

  console.log(result.length)
}

