// 盤面はそこまで大きくない
// 列や行を入れ替えても計算に支障はない（合計なので、順番は関係ない）
// K を下回った場合はそれ以上増やしても意味がない
// よくわからん！指数オーダーだけど全部試そう！

function _c(input: string) {
  const [_HWK, ...C] = input.split('\n');
  const [H, W, K] = _HWK.split(' ').map((s) => parseInt(s));
  const Black = [] as (1 | 0)[][];
  let sum = 0;
  for (let y = 0; y < H; y++) {
    const line = C[y];
    Black[y] = [];
    for (let x = 0; x < line.length; x++) {
      const color = line[x];
      if (color === '#') {
        Black[y].push(1);
        sum++;
      } else {
        Black[y].push(0);
      }
    }
  }
  // console.log(Black, sum);

  const target = sum - K; // 消したい数

  // 全パターンマスクして、消した数を数える
  let patterns = 0;
  for (let maskY = 0; maskY < 2 ** H; maskY++) {
    for (let maskX = 0; maskX < 2 ** W; maskX++) {
      calculate: {
        let masked = 0;
        for (let y = 0; y < Black.length; y++) {
          const line = Black[y];
          const isMaskedY = ((maskY >> y) & 1) === 1;
          for (let x = 0; x < line.length; x++) {
            if (line[x] === 1) {
              // 行または列がマスクされているならば、インクリメント
              if (isMaskedY || ((maskX >> x) & 1) === 1) {
                masked++;

                // 超えてしまったら望みはない
                if (masked > target) {
                  break calculate;
                }
              }
            }
          }
        }
        if (masked === target) {
          patterns++;
        }
      }
    }
  }

  console.log(patterns);
}

