      picksH
        .filter(([, b]) => b)
        .map(([i]) =>
          picksW
            .filter(([, b]) => b)
            .map(([j]) => (css[i][j] === "Black" ? 1 : 0) as number)
            .reduce((acc, x) => acc + x, 0)
        )
        .reduce((acc, x) => acc + x, 0);

    const initialBlackCnt = getBlackCnt(
      range(H).map((i) => [i, true]),
      range(W).map((j) => [j, true])
    );

    const pickWFn = (n: number, picksH: [number, boolean][], picksW: [number, boolean][]): number =>
