void problem() {
  auto H = scan!int;
  auto W = scan!int;
  auto K = scan!int;
  auto MAP = H.iota.map!(x => scan).array;

  long solve() {
    long ans;

    foreach(wx; 0..2^^(W)) {
      auto w = (W+1).iota.map!(b => wx >> b & 1).array;
      foreach(hx; 0..2^^(H)) {
        auto h = (H+1).iota.map!(b => hx >> b & 1).array;

        w.deb;
        h.deb;

        int count;
        foreach(x; 0..W) {
          foreach(y; 0..H) {
            if (w[x] == 0 && h[y] == 0) {
              if (MAP[y][x] == '#') count++;
            }
          }
        }

        if (count == K) ans++;
        count.deb;
      }
      "----".deb;
    }

    return ans;
  }

  solve().writeln;
}

