def solve(H, W, K, C):
    from itertools import compress, product
    def f(hs, ws):
        k = 0
        for h in range(H):
            if h in hs:
                continue
            for w in range(W):
                if w in ws:
                    continue
                if C[h][w] == "#":
                    k += 1
        return k == K
    ans = 0
    for hs in (set(compress(range(H), p)) for p in product([True, False], repeat=H)):
        for ws in (set(compress(range(W), p)) for p in product([True, False], repeat=W)):
            if f(hs, ws):
                ans += 1
    return ans

