import itertools
import pprint

def count_black(A):
    ans = 0
    for a in A:
        ans += a.count("#")
    return(ans)

def make(n):
    ans = []
    for i in range(2 ** n):
        addition = []
        now = bin(i)[2:]
        now = "0" * (n - len(now)) + now
        for j in range(n):
            if now[j] == "1":
                addition.append(j + 1)
        ans.append(addition)
    return(ans)

def remove(C, r):
    rem_col = set(r[0])
    rem_row = set(r[1])
    kouho_col = {i + 1 for i in range(len(C))}
    kouho_row = {i + 1 for i in range(len(C[0]))}
    col = kouho_col - rem_col
    row = kouho_row - rem_row
    ret = []
    for i in col:
        c = C[i - 1]
        new_col = []
        for j in row:
            new_col.append(c[j - 1])
        ret.append(new_col)
    return(ret)


