def resolve():
    m, n, k = map(int, input().split())
    grid = [list(input()) for _ in range(m)]
    ans = 0
    for U, V in product(range(1 << m), range(1 << n)):
        tmp = [a[:] for a in grid]
        for i in range(m):
            if not U >> i & 1:
                continue
            for j in range(n):
                tmp[i][j] = '.'
        for j in range(n):
            if not V >> j & 1:
                continue
            for i in range(m):
                tmp[i][j] = '.'
        ans += sum(tmp[i][j] == '#' for i in range(m) for j in range(n)) == k
    print(ans)
