# generate a binary array, len = limit
def generate_selection(limit=0):
    result = []
    arr = [0 for i in range(limit)]
    max_result_len = limit**2

    while True:
        result.append(arr.copy())

        pos_to_change = -1
        for i in range(limit-1,-1,-1):
            if arr[i] == 0:
                pos_to_change = i
                break

        if pos_to_change == -1:
            break

        arr[pos_to_change] = 1
        for i in range(pos_to_change+1,limit):
            arr[i] = 0

    return result

