from collections import Counter

def solve(R, C, K, A):
  ans = 0
  for mask in range(1 << C):
    rsums = []
    for row in A:
      rsums.append(0)
      for c in range(C):
        if row[c] == '#' and mask >> c & 1:
          rsums[-1] += 1

    count = {0: 1}
    for s in rsums:
      count2 = Counter()
      for k in count:
        v = count[k]
        count2[k] += v
        count2[k + s] += v
      count = count2
    ans += count[K]
  return ans


