def print_red(field, high):
    for i in range(len(high)):
        if high[i] == 1:
            field[i] = ['X' for _ in range(len(field[0]))]
    return field

def count_sharp_without_width(field, width):
    count = 0
    for i in range(len(field)): #高さ(横線)
        for j in range(len(width)): #横(縦ライン)
            if width[j] == 1:
                continue
            if field[i][j] == '#':
                count += 1
    return count

def main():
    h, w, k = list(map(int,input().split()))
    field = [list(input()) for _ in range(h)]
    #print(field)

    ans = 0

    for high in itertools.product([1, 0], repeat=h):
        field_temp = deepcopy(field)
        field_temp = print_red(field_temp, high)
        count_k = 0
        #print(field_temp)
        for i in range(h):
            count_k += field_temp[i].count('#') 
        #print(count_k)
        if count_k < k: continue # kを下回ったらブレイク

        for width in itertools.product([1, 0], repeat=w):
            #print(width)
            count_k = count_sharp_without_width(field_temp, width)
            if count_k == k:
                ans += 1
    print(ans)
