    count = 0
    for i in range(1 << (h + w)):
        m = deepcopy(matrix)
        for j in range(h):
            if (i >> j) & 1 == 1:
                m[j] = [red for _ in range(w)]

        for j in range(w):
            if (i >> (j + h)) & 1 == 1:
                for k in range(h):
                    m[k][j] = red

        black_count = 0
        for j in range(h):
            for k in range(w):
                if m[j][k] == black:
                    black_count += 1

        if black_count == K:
            count += 1

    print(count)


