import sys

def calc_hash_bool(Len, hash):
    bools = [False] * Len
    for i in range(Len-1, -1, -1):
        remainder = hash %2
        if(remainder==1):
            bools[i] = True
        hash //= 2
    return bools

def calc_combinations(height, width, boards, demand_black):
    """
    縦: 2^6 = 64
    横: 2^6 = 64
    64^2 = 4096通り
    """
    combinations = 0
    #hashを2進数で考えて000000-> どれも選ばない, 111111->全て選択(色を染める)、というように
    for hash_h in range(2**height):
        bool_h = calc_hash_bool(height, hash_h)
        for hash_v in range(2**width):
            bool_v = calc_hash_bool(width, hash_v)
            N_black = 0
            for i in range(height):
                for j in range(width):
                    if(bool_h[i]==False and bool_v[j]==False and boards[i][j]=="#"):
                        N_black += 1
            if(N_black==demand_black):
                combinations += 1
    return combinations



