def solve(L,H,W,K):
	R,C = [],[]
	rows = [i for i in range(H)]
	cols = [i for i in range(W)]
	for r in range(H+1):
		R.append(list(combinations(rows,r)))
	for c in range(W+1):
		C.append(list(combinations(cols,c)))
	RR,CC = [],[]
	for i in R:
		for j in i:
			jj = list(j)
			RR.append(jj)
	for i in C:
		for j in i:
			jj = list(j)
			CC.append(jj)
	ans = 0
	blacks = 0
	for i in range(H):
		for j in range(W):
			if(L[i][j] == '#'):
				blacks += 1
	for rc in RR:
		for cc in CC:
			curr = blacks
			for r in range(H):
				for c in range(W):
					if(r in rc or c in cc):
						if(L[r][c] == '#'):
							curr -= 1
			if(curr == K):
				ans += 1
	return ans



