def count_kuro(c, bit_i, bit_j):
    list_i = []
    for i in range(H):
        if bit_i>>i&1:
            list_i.append(i)
    list_j = []
    for j in range(W):
        if bit_j>>j&1:
            list_j.append(j)

    tansaku = [
        (i,j) for i in range(H) for j in range(W)
        if i in list_i and j in list_j
    ]

    return sum([c[dot[0]][dot[1]]=='#' for dot in tansaku])


