import numpy as np

def paint_red(array, rows, cols):
    ret = deepcopy(array)
    for i in rows:
        ret[i, :] = "r"
    for j in cols:
        ret[:, j] = "r"

    return ret

def get_idx(bins):
    indices = []
    for i, c in enumerate(reversed(bins)):
        if c == "1":
            indices.append(i)

    return indices

