        for j in range(W):
            C[i][j] = c[j]
    return H, W, K, C


def solve(H, W, K, C):
    ans = 0
    D = [["." for j in range(W)] for i in range(H)]

    for p in range(1<<H):
        for q in range(1<<W):
            # init
            for i in range(H):
                for j in range(W):
                    D[i][j] = C[i][j]

            # simulate
            for i in range(H):
                if (p >> i) & 1 == 1:
                    for j in range(W):
                        D[i][j] = "."
            for j in range(W):
                if (q >> j) & 1 == 1:
                    for i in range(H):
                        D[i][j] = "."

            # count
            count = 0
            for i in range(H):
                for j in range(W):
                    if D[i][j] == "#":
                        count += 1
            if count == K:
                ans += 1
    return ans


