def solve(H, W, K, C):
    answer = 0
    for hn in range(min(K + 1, H + 1)):
        for wn in range(min(K + -hn + 1, W + 1)):
            for h_idxs in comb(range(H), hn):
                for w_idxs in comb(range(W), wn):
                    cs = C.copy()
                    cs[h_idxs,:] = 0
                    cs[:, w_idxs] = 0
                    answer += cs.sum() == K
    return answer

