def resolve():
    h,w,K = map(int, input().split())
    mas = [list(input()) for i in range(h)]
    wk = []
    hk = []
    for i in range(h):
        plus = 0
        for j in range(w):
            if mas[i][j] == "#":
                plus += 1
        hk.append(plus)
    for i in range(w):
        plus = 0
        for j in range(h):
            if mas[j][i] == "#":
                plus += 1
        wk.append(plus)
    total = sum(wk)

    ans = 0
    for i in range(2**h):
        vert = []
        for k in range(h):
            vert.append((i>>k)&1)
        for j in range(2**w):
            hor = []
            for m in range(w):
                hor.append((j>>m)&1)
            subt = 0

            for n in range(len(vert)):
                subt += vert[n] * hk[n]
            for n in range(len(hor)):
                subt += hor[n] * wk[n]
            for n in range(len(vert)):
                for o in range(len(hor)):
                    if (vert[n] == 1) and (hor[o] == 1) and (mas[n][o] == "#"):
                        subt -= 1

            if total-subt == K:
                ans += 1


    print(ans)
