import sys
import itertools

import numpy as np


def main():
    def readline() -> str:
        s = sys.stdin.readline()
        return s.rstrip()

    h, w, k = map(int, readline().split())  # type: int, int, int
    field: np.ndarray = np.array(
        tuple(
            tuple(0 if c == "." else 1 for c in readline()) for _ in range(h)
        )
    )

    answer: int = 0

    for pattern_num in range(2 ** (h + w)):
        test_field = field.copy()
        pattern_num_bin = format(pattern_num, f"0{h+ w}b")
        h_bin: str = pattern_num_bin[:h]
        w_bin: str = pattern_num_bin[h:]

        for row in range(h):
            if h_bin[row] == "1":
                test_field[row] = np.ones((w,)) * 2

        for column in range(w):
            if w_bin[column] == "1":
                test_field[:, column] = np.ones((h,)) * 2

        if np.sum(test_field == 1) == k:
            answer += 1

    print(answer)


if __name__ == '__main__':
    main()

