def main(n, m, k, lst):
    ways = 0
    for i in range(2**(n+m)):
        binS = "0" * ((n+m) - len(str(bin(i))[2:])) + str(bin(i))[2:]
        lst1 = lst.copy()
        ind, ind1 = 0, 0
        for j in range(len(binS)):
            if binS[j] == "1":
                if j+1 <= m:
                    for r in range(len(lst1)):
                        lst1[r] = lst1[r][:j-ind] + lst1[r][j+1-ind:]
                    ind += 1
                else:
                    c = j - m - ind1
                    lst1 = lst1[:c] + lst1[c+1:]
                    ind1 += 1
        if count(lst1) == k:
            ways += 1
    return ways

