import itertools
import copy

def red_gyou(c, gyou, W):
  for i in range(W):
    c[gyou][i] = 0

def red_retsu(c, retsu, H):
  for j in range(H):
    c[j][retsu] = 0

def blacks(c, H):
  black = 0
  for i in range(H):
    black += sum(c[i])
  return black

