import sys
import itertools


def resolve(in_):
    h, w, k = map(int, next(in_).split())
    c = [row.strip() for row in in_]
    # for i in range(h):
    #     print(c[i].decode())

    ans = 0
    black_char = ord(b'#')
    red_mask = itertools.product(
        itertools.product((True, False), repeat=h),
        itertools.product((True, False), repeat=w),
    )
    for not_red_row, not_red_col in red_mask:
        black_n = 0
        # print(not_red_row, not_red_col)
        for i, j in itertools.product(range(h), range(w)):
            # print(f'  {i=} {j=}')
            if c[i][j] == black_char and not_red_row[i] and not_red_col[j]:
                black_n += 1
                if black_n > k:
                    break
        else:
            if black_n == k:
                ans += 1

    return ans


def main():
    answer = resolve(sys.stdin.buffer)
    print(answer)


if __name__ == '__main__':
