def calc(C):
    num = 0
    for i in range(H):
        c = C[i]
        for j in range(W):
            if C[i][j] == "#":
                num += 1
    return num

def maskC(C, rowcol):
    masked_C = []
    for i in range(H):
        row = []
        for j in range(W):
            row.append(C[i][j])
        masked_C.append(row)

    rows, cols = [], []
    for index in rowcol:
        if index < H:
            rows.append(index)
        else:
            cols.append(index - H)

    for row in rows:
        masked_C[row] = ["!"] * W
    for col in cols:
        for i in range(H):
            masked_C[i][col] = "!"
    return masked_C


def search(C, From=0, rowcol=[], result=0):
    # print(rowcol)
    masked_C = maskC(C, rowcol)
    num = calc(masked_C)
    # if rowcol == [0, 2]:
    #     print(masked_C)
    # print(num)
    if num == K:
        result += 1
    for i in range(From, H + W):
        result = search(C, i+1, rowcol + [i], result)
    return result

