def main():
    h, w, k = MI()
    C = []
    for _ in range(h):
        C.append(input())
    c_h = [0]*h
    c_w = [0]*w
    cnt = 0
    for i in range(h):
        for j in range(w):
            if C[i][j] == '#':
                c_h[i] += 1
                c_w[j] += 1
                cnt += 1
    ans = 0
    for i in range(2**h):
        for j in range(2**w):
            cnt_temp = cnt
            row = []
            col = []
            for ii in range(h):
                if ((i >> ii) & 1):
                    cnt_temp -= c_h[ii]
                    row.append(ii)
            for jj in range(w):
                if ((j >> jj) & 1):
                    cnt_temp -= c_w[jj]
                    col.append(jj)
            for ro in row:
                for co in col:
                    if C[ro][co] == '#':
                        cnt_temp += 1
            if cnt_temp == k:
                ans += 1
    print(ans)

