                bi.append(i)
                bj.append(j)

    row_iters = [itertools.combinations(range(H), i) for i in range(0,H+1)]
    column_iters = [itertools.combinations(range(W), i) for i in range(0,W+1)]

    dellist = lambda items, indexes: [item for index, item in enumerate(items) if index not in indexes]
    # 行を削除してみる
    count = 0

    for row_iters in row_iters:
        for target_rows in row_iters:
            row_del_position = [i_position for i_position, i in enumerate(bi) for target_row in target_rows if i == target_row]
            new_bi = dellist(bi, row_del_position)
            new_bj = dellist(bj, row_del_position)
            if len(new_bi)>=K:
                for column_iters in column_iters:
                    for target_columns in column_iters:
                        column_del_position = [j_position for j_position, j in enumerate(bj) for target_column in target_columns if j == target_column]
                        new_bi = dellist(bi, column_del_position)
                        new_bj = dellist(bj, column_del_position)
                        if len(new_bi) == K:
