def ten2bi(i, N):
    bi_list = []    #二進数表記のリスト(ex. ten2bi(31, 5)  -> [1, 1, 1, 1, 1])
    for j in range(N):
        if i >= 2**(N - j - 1):
            bi_list.append(1)
            i -= 2**(N - j - 1)
        else:
            bi_list.append(0)

    return bi_list

