    for h in range(H):
        if 2**h & tate != 0:
            for w in range(W):
                if C[h][w] == "#":
                    sum -= 1

    for w in range(W):
        if 2**w & yoko != 0:
            for h in range(H):
                if C[h][w] == "#":
                    sum -= 1

    for h in range(H):
        for w in range(W):
            if 2**h & tate != 0 and 2**w & yoko != 0 and C[h][w] == "#":
                sum += 1

    return sum

