def count_black(matrix, mask_rows=[], mask_cols=[]):
  num_black = 0
  for i, row in enumerate(matrix):
    if i in mask_rows:
      continue
    for j, col in enumerate(row):
      if j in mask_cols:
        continue
      if col == "#":
        num_black += 1
  return num_black

def get_patterns(linenum):
  results = []
  patterns = 2**linenum
  for i in range(patterns):
    cmb = []
    if i & 1 == 1:
      cmb.append(0)
    if i & 2 == 2:
      cmb.append(1)
    if i & 4 == 4:
      cmb.append(2)
    if i & 8 == 8:
      cmb.append(3)
    if i & 16 == 16:
      cmb.append(4)
    if i & 32 == 32:
      cmb.append(5)
    results.append(cmb)
  return results

