def simulate(mh, mw, H, W, K, grid):
    flags = [[1 for _ in range(W)] for _ in range(H)]
    for h in range(H):
        if not (mh>>h)&1:
            continue
        for w in range(W):
            flags[h][w] = 0
    for w in range(W):
        if not (mw>>w)&1:
            continue
        for h in range(H):
            flags[h][w] = 0
    cnt = 0
    for h in range(H):
        for w in range(W):
            if flags[h][w] and grid[h][w] == '#':
                cnt += 1
    if cnt == K:
        # print(flags)
        # print(mh, mw)
        return 1
    return 0

