from copy import deepcopy

def kaijo(n):
    if n==0:
        return 1
    if n==1:
        return n
    return n*kaijo(n-1)

def Comb(n,r):
    if n==0:
        return 1
    return kaijo(n)/(kaijo(r)*kaijo(n-r))

