import copy


def count_black(cells):
    count = 0
    for col in cells:
        count += col.count('#')
    return count


def draw_red_and_count(cells, xs, ys):
    for x in xs:
        for col in cells:
            col[x] = '@'
    for y in ys:
        for i in range(len(cells[y])):
            cells[y][i] = '@'
    return count_black(cells)


def main():
    H, W, K = list(map(int, input().split()))
    cells = [[0 for j in range(W)] for i in range(H)]
    for x in range(H):
        Cs = list(input())
        for y in range(W):
            cells[x][y] = Cs[y]

    Xs = []
    for i in range(2 ** W):
        Xs.append([j for j in range(W) if (i >> j) & 1])
    Ys = []
    for i in range(2 ** H):
        Ys.append([j for j in range(H) if (i >> j) & 1])

    ans = 0
    for xs in Xs:
        for ys in Ys:
            black_count = draw_red_and_count(copy.deepcopy(cells), xs, ys)
            if black_count == K:
                ans += 1
    print(ans)


