def count_black(table):
    count = 0
    for line in table:
        for s in line:
            if s == "#":
                count += 1
    return count


def paint_col(table, col_index):
    for index, line in enumerate(table):
        table[index] = line[:col_index] + "." + line[col_index + 1:]


def paint_row(table, row_index):
    table[row_index] = "." * len(table[row_index])


def bin_tuple_to_index_tuple(bin_tup):
    res = []
    for idx, v in enumerate(bin_tup):
        if v == 1:
            res.append(idx)
    return res


result = 0
