    row_tup = bin_tuple_to_index_tuple(row)
    table_tmp = table.copy()
    for r in row_tup:
        paint_row(table_tmp, r)
    for col in itertools.product([0, 1], repeat=W):
        table_tmp_t = table_tmp.copy()
        col_tup = bin_tuple_to_index_tuple(col)
        for c in col_tup:
            paint_col(table_tmp_t, c)
        if count_black(table_tmp_t) == K:
            result += 1

