    "powerset([1,2,3]) --> () (1,) (2,) (3,) (1,2) (1,3) (2,3) (1,2,3)"
    s = list(iterable)
    return chain.from_iterable(combinations(s, r) for r in range(len(s)+1))

def main():
    H, W, K = map(int, input().split())

    rows = []
    for h in range(H):
        rows.append(input())

    row_choices = list(powerset(range(H)))
    col_choices = list(powerset(range(W)))

    ans = 0
    for r_set, c_set in product(row_choices, col_choices):
        selected_rows = [r for i, r in enumerate(rows) if i not in r_set]
        n_blacks = 0
        for r in selected_rows:
            n_blacks += len([c for j, c in enumerate(r) if j not in c_set and c == '#'])

        if n_blacks == K:
            ans += 1

    print(ans)



