def count_black(grid):
    num_blacks = 0

    for row in grid:
        for c in row:
            if c == '#':
                num_blacks += 1

    return num_blacks


def deep_copy_grid(grid):
    copy = []

    for row in grid:
        temp = []

        for col in row:
            temp.append(col)

        copy.append(temp)

    return copy


def paint_red(grid, select_rows, select_cols):
    for select_row in select_rows:
        for j in range(len(grid[select_row])):
            grid[select_row][j] = 'r'

    for select_col in select_cols:
        for i in range(len(grid)):
            grid[i][select_col] = 'r'

    return


