# do a search over the total space of [br, er), [bc, ec)
# compile all cumulative counts of black squares
# record the total number of black squares

def cumul(grid):
  R, C = len(grid), len(grid[0])
  cumu = [[0 for _ in range(R)] for _ in range(C)]
  for r in range(R):
    pr = 0
    for c in range(C):
      nb = 1 if grid[r][c] == '#' else 0
      cr = pr + nb
      cumu[r][c] = cr if r == 0 else cr + cumu[r-1][c]

  return cumu

def ct_black(cu, rb, re, cb, ce):
  # count number of remaining black after painting
  # this intersection
  ul = cu[rb][cb]
  ll = cu[-1][cb] - cu[re-1][cb]
  ur = cu[rb][-1] - cu[rb][ce-1]
  lr = cu[-1][-1] - cu[re-1][-1] - cu[-1][ce-1] + cu[re-1][ce-1]
  return ul + ll + ur + lr




def main():
  R, C, K = map(int, input().split())
  grid = []
  for r in range(R):
    grid.append(list(input()))

  cumu = cumul(grid)

  n_configs = 0
  for rb in range(R):
    for re in range(rb, R):
      for cb in range(C):
        for ce in range(cb, C):
          if ct_black(cumu, rb, re, cb, ce) == K:
            n_configs += 1


  print(n_configs, flush=True)

