import sys
from itertools import chain, combinations


def powerset(iterable):
    "powerset([1,2,3]) --> () (1,) (2,) (3,) (1,2) (1,3) (2,3) (1,2,3)"
    s = list(iterable)
    return chain.from_iterable(combinations(s, r) for r in range(len(s)+1))


def main():
    """Main program."""
    height, width, target = (int(i) for i in sys.stdin.readline().split())
    grid = [[0 for _ in range(width)] for _ in range(height)]
    total_black = 0
    for row in range(height):
        for col, color in enumerate(sys.stdin.readline().strip()):
            if color == '#':
                grid[row][col] = 1
                total_black += 1

    soln = 0
    for rows_selected in powerset(range(height)):
        for cols_selected in powerset(range(width)):
            if len(cols_selected) == width:
                continue

            selected_black = 0
            for row in rows_selected:
                selected_black += sum(grid[row])

            for col in cols_selected:
                for row in range(height):
                    if row not in rows_selected:
                        selected_black += grid[row][col] 

            if total_black - selected_black == target:
                soln += 1
    print(soln)


