import copy

def dfs(hi, wi, wc, wh, ww, wk, d):
    if d == 0 and wi >= ww:
        d = 1
    elif d == 1 and hi >= wh:
        d = 2

    if d == 0:
        newc = copy.deepcopy(wc)
        for i in range(wh):
            newc[i][wi] = '.'
        rval = dfs(hi, wi+1, wc, wh, ww, wk, d)
        rval += dfs(hi, wi+1, newc, wh, ww, wk, d)
        return rval
    elif d == 1:
        newc = copy.deepcopy(wc)
        for i in range(ww):
            newc[hi][i] = '.'
        rval = dfs(hi+1, wi, wc, wh, ww, wk, d)
        rval += dfs(hi+1, wi, newc, wh, ww, wk, d)
        return rval
    else:
        cnt = 0
        for i in range(wh):
            for j in range(ww):
                if wc[i][j] == '#':
                    cnt = cnt + 1
        if cnt == wk:
            return 1
        else:
            return 0

