def kuro(x,y,c):
    dcr=0
    for cc in c:
        if cc[0] in x:
            dcr+=1
        if cc[1] in y:
            dcr+=1   
    for i in x:
        for j in y:
            if [i,j] in c:
                dcr-=1
    return dcr

def nshinsu(x,h):
    lis=[]
    xx=x
    for i in range(h-1,-1,-1):
        if xx >= 2**i:
            lis.append(i)
            xx=xx-(2**i)
    return lis
