from __future__ import annotations

import itertools
from dataclasses import dataclass
from typing import List


@dataclass
class Cell:
    row_idx: int
    col_idx: int
    color: str

    def to_red(self) -> Cell:
        return Cell(self.row_idx, self.col_idx, color='R')


@dataclass
class Board:
    cells: List[Cell]

    @classmethod
    def create(cls, H: int, W: int, C: List[List[str]]) -> Board:
        cells = []

        for i in range(H):
            for j in range(W):
                cell = Cell(i + 1, j + 1, C[i][j])
                cells.append(cell)

        return Board(cells)

    def count_black_cells(self) -> int:
        return len([cell for cell in self.cells if cell.color == '#'])

    def paint_row(self, row_idx: int) -> Board:
        new_cells = []

        for cell in self.cells:
            if cell.row_idx == row_idx:
                new_cells.append(cell.to_red())
            else:
                new_cells.append(cell)

        return Board(new_cells)

    def paint_col(self, col_idx: int) -> Board:
        new_cells = []

        for cell in self.cells:
            if cell.col_idx == col_idx:
                new_cells.append(cell.to_red())
            else:
                new_cells.append(cell)

        return Board(new_cells)


def actual(H, W, K, C):
    count = 0

    # ある行や列を赤く塗るかどうかをビットパターンで表現する
    # ex: H=2, W=3 で、1行目と、2列目と3列目を塗る場合
    #     (0,  1, |  0,   1,   1)
    #     H=1 H=2 | W=1, W=2, W=3
    paint_patterns = list(itertools.product(range(2), repeat=H + W))

    for pattern in paint_patterns:
        board = Board.create(H, W, C)

        row_paint_pattern = pattern[:H]  # ex: (0, 1)
        col_paint_pattern = pattern[H:]  # ex: (0, 1, 1)

        for row_idx, will_paint_the_row in enumerate(row_paint_pattern, start=1):
            if will_paint_the_row == 1:
                board = board.paint_row(row_idx)

        for col_idx, will_paint_the_col in enumerate(col_paint_pattern, start=1):
