def solution(A,n,m,k):
	cnt = 0
	for i in range(n+1):
		R = list(itertools.combinations(range(n),i))
		for row in R:
			for j in range(m+1):
				C = list(itertools.combinations(range(m),j))
				for column in C:
					B = [A[i][:] for i in range(n)]
					s = 0
					for r in row:
						B[r] = ['.' for _ in range(m)]
					for c in column:
						for ro in range(n):
