import numpy as np


def count_sharp(C: List[List[str]]) -> int:
    n = 0
    for row in C:
        for e in row:
            if e == "#":
                n += 1
    return n


def main(H: int, W: int, K: int, C: List[List[str]]):
    ans = 0

    h_list = [x for x in range(0, H)]
    w_list = [x for x in range(0, W)]

    for num_row in range(H):
        for num_col in range(W):
            row_combs = list(combinations(h_list, num_row))
            col_combs = list(combinations(w_list, num_col))

            for row_comb in row_combs:
                for col_comb in col_combs:
                    C_np = np.array(C)
                    for row in row_comb:
                        C_np[row, :] = "*"
                    for col in col_comb:
                        C_np[:, col] = "*"

                    if count_sharp(C_np) == K:
                        ans += 1

    print(ans)


