# do a search over the total space of [br, er), [bc, ec)
# compile all cumulative counts of black squares
# record the total number of black squares

def cumul(grid):
  R, C = len(grid), len(grid[0])
  cumu = [[0 for _ in range(C+1)] for _ in range(R+1)]
  for r in range(R):
    pr = 0
    for c in range(C):
      nb = 1 if grid[r][c] == '#' else 0
      cr = pr + nb
      cumu[r+1][c+1] = cr + cumu[r][c+1]
      pr = cr

  return cumu

def ct_black(cu, rb, re, cb, ce):
  # count number of remaining black after painting
  # this intersection
  ul = cu[rb][cb]
  ll = cu[-1][cb] - cu[re-1][cb]
  ur = cu[rb][-1] - cu[rb][ce]
  lr = cu[-1][-1] - cu[re][-1] - cu[-1][ce] + cu[re][ce]
  return ul + ll + ur + lr




def main():
  R, C, K = map(int, input().split())
  grid = []
  for r in range(R):
    grid.append(list(input()))

  cumu = cumul(grid)

  n_configs = 0
  for rb in range(R+1):
    for re in range(rb, R+1):
      for cb in range(C+1):
        for ce in range(cb, C+1):
          if ct_black(cumu, rb, re, cb, ce) == K:
            n_configs += 1


  print(n_configs, flush=True)

