import copy
import itertools


def solve(h, w, k, stage):
    res = 0
    is_sel_rs = itertools.product((False, True), repeat=h)
    is_sel_cs = itertools.product((False, True), repeat=w)
    for irs, ics in itertools.product(is_sel_rs, is_sel_cs):
        st = copy.deepcopy(stage)
        for r0, ir in enumerate(irs):
            if ir:
                for c in range(w):
                    st[r0][c] = "*"
        for c0, ic in enumerate(ics):
            if ic:
                for r in range(h):
                    st[r][c0] = "*"
        num_blacks = 0
        for r, c in itertools.product(range(h), range(w)):
            if st[r][c] == "#":
                num_blacks += 1
        if num_blacks == k:
            res += 1
    return res


def main():
    h, w, k = (int(z) for z in input().split())
    stage = [list(input()) for _ in range(h)]
    res = solve(h, w, k, stage)
    print(res)


if __name__ == '__main__':
    main()

