def rec_col(count, n):
  if n == len(c):
    yield count
  else:
    yield from rec_col(list(count), n+1)
    for i, color in enumerate(c[n]):
      if color == "#":
        count[i] += 1
    yield from rec_col(list(count), n+1)

def rec_row(result, count, n):
  if n == len(count):
    yield result
  else:
    yield from rec_row(result + count[n], count, n+1)
    yield from rec_row(result, count, n+1)

