## io ##
def IS(): return sys.stdin.readline().rstrip()
def II(): return int(IS())
def MII(): return list(map(int, IS().split()))
#======================================================#
def main():
    h, w, k = MII()
    cc = [IS() for _ in range(h)]
    all_blacks = 0
    for c in cc:
        all_blacks += sum(1 for s in c if s == '#')
    cnt = 0
    for hbit in range(1<<h):
        blacks = all_blacks
        hb = []
        # 行を選ぶ
        for i in range(h):
            if hbit & (1<<i):
                hb.append(i)
        # 選んだ行の黒を取り除く
        for hbi in hb:
            blacks -= sum([1 for s in cc[hbi] if s == '#'])
        # すでにk個以下であればskip
        if blacks < k:
            continue

        # 列を選択
        for wbit in range(1<<w):
            wb = []
            for i in range(w):
                if wbit & (1<<i):
                    wb.append(i)
            # 列の黒を取り除く（ただし横で選んだ部分は重複させない）
            wblack = 0
            for wbi in wb:
                for i in range(h):
                    # 行で選ばれている場合はスキップ
                    if i in hb:
                        continue
                    if cc[i][wbi] == '#':
                        wblack += 1
            if blacks - wblack == k:
                cnt += 1
    print(cnt)

