fn count_black(cells: &Vec<Vec<bool>>, row_flags: i32, col_flags: i32) -> i32 {
    let h = cells.len();
    let w = cells[0].len();

    let mut cnt = 0;
    for (i, row) in cells.iter().enumerate() {
        for (j, v) in row.iter().enumerate() {
            if *v && !check_bit(row_flags, h, i) && !check_bit(col_flags, w, j) {
                cnt += 1;
            }
        }
    }    
    cnt
}

fn check_bit(b: i32, sz: usize, idx: usize) -> bool {
    (b >> (sz - idx - 1)) & 1 > 0
}

