  macro_rules! num_cast {
    ($v0:expr)                   => { num_traits::cast::cast($v0).unwrap() };
    ($v0:expr, $arg:ty, $ret:ty) => { num_traits::cast::cast::<$arg, $ret>($v0).unwrap() };
