use std::fmt::Debug;
use std::str::FromStr;

pub struct TokenReader {
    reader: std::io::Stdin,
    tokens: Vec<String>,
    index: usize,
}

impl TokenReader {
    pub fn new() -> Self {
        Self {
            reader: std::io::stdin(),
            tokens: Vec::new(),
            index: 0,
        }
    }

    pub fn next<T>(&mut self) -> T
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index += 1;
        self.tokens[self.index - 1].parse().unwrap()
    }

    pub fn vector<T>(&mut self) -> Vec<T>
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index = self.tokens.len();
        self.tokens.iter().map(|tok| tok.parse().unwrap()).collect()
    }

    pub fn load_next_line(&mut self) {
        let mut line = String::new();
        self.reader.read_line(&mut line).unwrap();

        self.tokens = line
            .split_whitespace()
            .map(String::from)
            .collect();
        self.index = 0;
    }
}

type Mat = Vec<Vec<char>>;

fn bit(num: usize, pos: usize) -> usize {
    (num & (1 << pos)) >> pos
}

fn make_moves(mat: &Mat, rows: usize, cols: usize) -> Mat {
    let mut res = mat.to_owned();
    for i in 0..mat.len() {
        if bit(rows, i) == 1 {
            (0..mat[0].len()).for_each(|j| res[i][j] = '_');
        }
    }
    for j in 0..mat[0].len() {
        if bit(cols, j) == 1 {
            (0..mat.len()).for_each(|i| res[i][j] = '_');
        }
    }
    res
}

fn count_black(mat: &Mat) -> usize {
    mat.iter().map(|row| row.iter().filter(|&ch| *ch == '#').count()).sum()
}

fn solve(mat: &Mat, left: usize) -> usize {
    let rows = mat.len();
    let cols = mat[0].len();

    let mut res = 0;
    for i in 0..(1 << rows) {
        for j in 0..(1 << cols) {
            let new = make_moves(mat, i, j);
            res += if count_black(&new) == left { 1 } else { 0 };
        }
    }
    res
}

fn main() {
    let mut reader = TokenReader::new();
    let rows = reader.next::<usize>();
    let _ = reader.next::<usize>();
    let left = reader.next::<usize>();
    let mat = (0..rows).map(|_| reader.next::<String>().chars().collect()).collect();

    let res = solve(&mat, left);
    println!("{}", res);
}

