fn count_blacks(cells: &Vec<Vec<char>>, iset: usize, jset: usize) -> usize {
    let h = cells.len();
    let w = cells[0].len();

    let mut cells = cells.clone();

    for i in 0..h {
        if (iset & (1 << i)) != 0 {
            for j in 0..w {
                cells[i][j] = 'X';
            }
        }
    }
    for j in 0..w {
        if (jset & (1 << j)) != 0 {
            for i in 0..h {
                cells[i][j] = 'X';
            }
        }
    }
    return cells.iter()
        .flat_map(|row| row.iter())
        .filter(|&&c| c == '#')
        .count();
}

