// blocksと消す行と列のbit列を計算して#がk個ならtrueを返す
fn calc_black(mut blocks: Vec<Vec<char>>, num:i32, h: usize, w:usize, k: i32) -> bool {
    let mut result_count: i32 = 0;
    // numの2進数化
    for i in 0..calc_keta(num, 2) {
        let index = calc_keta(num & 1 << i, 2);
        if index == 0 {
            continue;
        }
        if index > 0 && index <= h {
            for j in 0..w {
                blocks[index-1][j] = 'r';
            }
        } else {
            for j in 0..h {
                //println!("h={}, w={}, index = {}, num = {}",j, index - h, index, num);
                blocks[j][index - 1 - h] = 'r';
            }
        }
        /*
        match index {
            h_index @ 0..=h => {
                for i in 0..w {
                    blocks[h_index][i] = '#';
                }  
            },
            w_index @ h..=w => {
                for i in 0..h {
                    blocks[i][w_index] = '#';
                }
            },
            _ => (),
        }
        */
    }

    // カウントを取る
    for i in 0..h {
        for j in 0..w {
            if blocks[i][j] == '#' {
                result_count += 1;
            }
        }
    }
    return result_count == k;
}

// baseのp乗
fn pow(base: i32, p: i32) -> i32 {
    let mut result: i32 = base;
    for _i in 0..p {
        result *= base;
    }

    result
}
fn calc_keta(mut num: i32, kisu: i32) -> usize {
    let mut count = 0;
    if num == 0 {
        return 0;
    }
    while num / kisu != 0{
        count += 1;
        num /= kisu;
    }
    count += 1;
    return count;
}

use proconio::marker::*;
use proconio::*;

fn main() {
    input! {
        h: usize,
        w: usize,
        k: usize,
        c: [Chars; h],
    };
    let mut row = vec![0; h];
    let mut col = vec![0; w];
    let mut mat = vec![vec![0; w]; h];
    let mut acc = 0;
    let mut ans = 0;

    for i in 0..h {
        for j in 0..w {
            let t = if c[i][j] == '#' { 1 } else { 0 };
            row[i] += t;
            col[j] += t;
            mat[i][j] = t;
            acc += t;
        }
    }

    let hg = 1usize << h;
    let wg = 1usize << w;

    for div_i in 0..hg {
        for div_j in 0..wg {
            let mut num = acc;
            let mut di = div_i;
            loop {
                let i = di.trailing_zeros() as usize;
                let mut dj = div_j;
                loop {
                    let j = dj.trailing_zeros() as usize;

                    if i < h && j < w {
                        num += mat[i][j];
                    }

                    if j >= w {
                        break;
                    }
                    dj &= dj - 1;
                }

                if i >= h {
                    break;
                }
                di &= di - 1;
            }

            let mut di = div_i;

            loop {
                let i = di.trailing_zeros() as usize;
                if i < h {
                    num -= row[i];
                }

                if i >= h {
                    break;
                }
                di &= di - 1;
            }

            let mut dj = div_j;
            loop {
                let j = dj.trailing_zeros() as usize;
                if j < w {
                    num -= col[j];
                }
                if j >= w {
                    break;
                }
                dj &= dj - 1;
            }

            if num == k {
                ans += 1;
            }
        }
    }

    println!("{}", ans);
}

