#[inline(always)]
fn abc173_c() {
  let stdin  = stdin();
  let stdout = stdout();
  let mut scanner = my::Scanner::with_capacity(12, stdin.lock());
  #[allow(unused_variables, unused_mut)]
  let mut writer  = stdout.lock();
  #[allow(unused_variables, unused_mut)]
  let mut itoa    = my::ItoA::with_capacity(10);

  #[allow(dead_code)]
  const WHITE : u8 = b'.';
  #[allow(dead_code)]
  const BLACK : u8 = b'#';
  #[allow(dead_code)]
  const RED   : u8 = 0;

  let h = my::atoi::<usize>(scanner.read_until(my::SP));
  let w = my::atoi::<usize>(scanner.read_until(my::SP));
  let k = my::atoi::<usize>(scanner.read_until(my::LF));

  let mut total_black = 0;

  let orig = scanner.fold(h, my::LF, Vec::with_capacity(h), | mut v, s | {
    let cnt = s.iter().filter(| x | **x == BLACK).count() as u8;
    total_black += cnt;

    let mut x = s.to_vec();
    x.insert(0, cnt);
    v.push(x);
    v
  });

  let mut ans = 0;
  let row = 2 << (h - 1);
  let col = 2 << (w - 1);

  for i in 0..row {
    for j in 0..col {
      let mut cnt    = 0;
      let mut vec    = orig.to_vec();
      let mut remain = total_black;

      for k in 0..h {
        if ((i >> k) & 0x01) == 1 {
          remain -= vec[k][0];
          vec[k][0] = 0;
        }
      }
      if (remain as usize) < k {
        continue;
      }

      for k in 0..w {
        if ((j >> k) & 0x01) == 1 {
          for l in 0..h {
            vec[l][k + 1] = RED;
          }
        }
      }

      for k in 0..h {
        if vec[k][0] == 0 {
          continue;
        }

        for l in 0..w {
          if vec[k][l + 1] == BLACK {
            cnt += 1;
          }
        }
      }
      if cnt == k {
        ans += 1;
      }
    }
  }

  my_write!(writer, itoa.from_usize(ans), b"\n");
  writer.flush().unwrap();
}

