fn enum_pats(n: usize, x: usize, cur: &mut Vec<usize>) -> Vec<Vec<usize>> {
    if x >= n {
        return vec![cur.clone()];
    }

    let mut res = enum_pats(n, x + 1, cur);
    cur.push(x);
    let mut tmp = enum_pats(n, x + 1, cur);
    cur.pop();
    res.append(&mut tmp);
    return res;
}

