      let mut cnt = 0;
      for i in 0..h {
        if rows & (1 << i) != 0 {
          for j in 0..w {
            if cols & (1 << j) != 0 {
              if c[i][j] == '#' {
                cnt += 1;
              }
            }
          }
        }
      }
      if cnt == k {
        res += 1;
      }
    }
  }

  println!("{}", res);
}

