fn main() {
    let mut lines = BufReader::new(io::stdin()).split(b'\n').into_iter();
    let line = lines.next().unwrap().unwrap();
    let hwk: Vec<usize> = String::from_utf8(line)
        .unwrap()
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();
    let h = hwk[0];
    let w = hwk[1];
    let k = hwk[2];
    let mut b = vec![false; h * w];
    for (i, line) in lines.enumerate() {
        for (j, x) in line.unwrap().iter().enumerate() {
            if *x == b'#' {
                b[i * h + j] = true;
            }
        }
    }
    let mut ans = 0;
    for i in 0..1 << h {
        for j in 0..1 << w {
            let mut cnt = 0;
            for r in (0..h).filter(|r| (i >> r) & 1 == 0) {
                cnt += (0..w).filter(|c| (j >> c) & 1 == 0 && b[r * h + c]).count()
            }
            if cnt == k {
