use std::io;
use std::io::prelude::*;
use std::io::BufReader;

fn main() {
    let mut x = String::new();
    io::stdin().read_line(&mut x).unwrap();
    let hwk: Vec<usize> = x
        .trim_end()
        .split(' ')
        .map(|s| s.parse().unwrap())
        .collect();
    let h = hwk[0];
    let w = hwk[1];
    let k = hwk[2];
    let mut b: [[usize; 6]; 6] = Default::default();
    let lines = BufReader::new(io::stdin()).split(b'\n').into_iter();
    for (row, line) in b.iter_mut().zip(lines) {
        for (cell, x) in row.iter_mut().zip(line.unwrap()) {
            if x == b'#' {
                *cell = 1;
            }
        }
    }
    let mut ans = 0;
    for i in 0..1 << h {
        for j in 0..1 << w {
            let mut cnt = 0;
            for r in 0..h {
                if (i >> r) & 1 == 0 {
                    for c in 0..w {
                        if (j >> c) & 1 == 0 {
                            cnt += b[r][c];
                        }
                    }
                }
            }
            if cnt == k {
                ans += 1;
            }
        }
    }
    println!("{}", ans);
}

