use utils::adj4_iter;

fn run() {
    let h: usize = scan();
    let w: usize = scan();
    let k: usize = scan();
    let mut grid: Vec<Vec<bool>> = Vec::new();
    for _ in 0..h {
        let s: Vec<char> = scan::<String>().chars().collect();
        let v = s.into_iter().map(|c| c == '#').collect();
        grid.push(v);
    }
    let mut ans = 0;

    for s in 0..1 << (h + w) {
        let mut ys = Vec::new();
        for y in 0..h {
            if s >> y & 1 == 1 {
                ys.push(y);
            }
        }
        let mut xs = Vec::new();
        for x in 0..w {
            if s >> (x + h) & 1 == 1 {
                xs.push(x);
            }
        }
        let mut cnt = 0;
        for &y in &ys {
            for &x in &xs {
                if grid[y][x] {
                    cnt += 1;
                }
            }
        }
        if cnt == k {
            ans += 1;
        }
    }
    println!("{}", ans);
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}
