fn solve() {
    input! {
        h: usize,
        w: usize,
        k: usize,
        board: [chars; h],
    }

    let h_p = 1 << h;
    let w_p = 1 << w;

    let mut ans = 0;

    for i in 0..h_p {
        for j in 0..w_p {
            let mut black = 0;
            for ii in 0..h {
                for jj in 0..w {
                    if i >> ii & 1 != 1 && j >> jj & 1 != 1 && board[ii][jj] == '#' {
                        black += 1;
                    }
                }
            }

            if black == k {
                ans += 1;
            }
        }
    }

    println!("{}", ans);
}

