fn fill(table: &mut Table<char>, rows: usize) {
    for y in 0..table.height() {
        if rows & (1 << y) == 0 {
            continue;
        }
        for cell in table.row_mut(y).unwrap() {
            *cell = '.';
        }
    }
}

