    let table = read_char_table();
    let mut ans = 0;
    for y_mask in 0..1<<h {
        for x_mask in 0..1<<w {
            let mut t = table.clone();
            fill(&mut t, y_mask);
            t.transpose();
            fill(&mut t, x_mask);
            let count: usize = t.rows().map(|row| row.iter().filter(|&&c| c == '#').count()).sum();
            if count == k {
                ans += 1;
            }
        }
    }
    println!("{}", ans);
}

