#[inline(always)]
fn for_each_bitflag<T, F>(mut n: T, mut func: F)
  where T: Copy +
           PartialEq +
           ::std::ops::Not<Output=T> +
           ::std::ops::BitAnd<Output=T> +
           ::std::ops::BitXor<Output=T> +
           num_traits::identities::Zero +
           num_traits::identities::One +
           num_traits::ops::wrapping::WrappingAdd,
        F: FnMut(T)
{
  loop {
    let tmp = n & (!n).wrapping_add(&T::one());
    if tmp == T::zero() {
      break;
    }
    func(tmp);
    n = n ^ tmp;
  }
}

#[inline(always)]
fn abc173_c() {
  let stdin  = stdin();
  let stdout = stdout();
  let mut scanner = my::Scanner::with_capacity(12, stdin.lock());
  let mut writer  = stdout.lock();
  let mut itoa    = my::ItoA::with_capacity(10);

  let h = my::atoi::<usize>(scanner.read_until(my::SP));
  let w = my::atoi::<usize>(scanner.read_until(my::SP));
  let k = my::atoi::<u32>(scanner.read_until(my::LF));

  let orig = scanner.fold(h, my::LF, Vec::with_capacity(h), | mut v, s | {
    let n: u8 = (0..w).fold(0, | x, i | {
      x | if s[i] == b'.' { 0 } else { 1 << i }
    });
    v.push(n);
    v
  });

  let mut ans = 0;
  let mut vec = Vec::with_capacity(h);
  vec.resize(h, 0);

  for row in 0..1 << h {
    for col in 0..1 << w {
      vec.copy_from_slice(&orig);

      for_each_bitflag(row, | x: u8 | {
        vec[x.trailing_zeros() as usize] = 0
      });

      let cnt = (0..h).fold(0, | x, i | {
        vec[i] &= !col;
        x + vec[i].count_ones()
      });

      if cnt == k {
        ans += 1;
      }
    }
  }

  my_write!(writer, itoa.from(ans), b"\n");
  writer.flush().unwrap();
}

