mod my {
  use std::ops::{ Add, Sub, Mul, Div, Rem, Not };
  use num_traits::cast::NumCast;
  use num_traits::identities::{ Zero, One };
  use num_traits::ops::wrapping::WrappingAdd;

  #[allow(dead_code)]
  pub const SP: u8 = b' ';
  #[allow(dead_code)]
  pub const LF: u8 = b'\n';

  macro_rules! num_cast {
    ($v0:expr)          => { num_traits::cast::cast($v0).unwrap() };
    ($v0:expr, $ret:ty) => { num_traits::cast::cast::<_, $ret>($v0).unwrap() };
  }

  //----------------------------------------------------------------------
  #[allow(dead_code)]
  #[inline(always)]
  pub fn atoi<T>(s: &[u8]) -> T
    where T: Add<Output=T> +
             Sub<Output=T> +
             Mul<Output=T> +
             NumCast +
             Zero
  {
    let n = T::zero();

    if s.is_empty() {
      return n;
    }

    match s[0] {
      b'+' => s[1..].iter().fold(n, | x, b | { (x * num_cast!(10)) + num_cast!(b - b'0') }),
      b'-' => s[1..].iter().fold(n, | x, b | { (x * num_cast!(10)) - num_cast!(b - b'0') }),
      _    => s[0..].iter().fold(n, | x, b | { (x * num_cast!(10)) + num_cast!(b - b'0') }),
    }
  }

  //----------------------------------------------------------------------
  #[derive(Debug)]
  pub struct ItoA {
    buf: Vec<u8>,
  }

  impl ItoA {
    #[allow(dead_code)]
    #[inline(always)]
    pub fn with_capacity(cap: usize) -> Self {
      ItoA {
        buf: Vec::with_capacity(cap),
      }
    }

    #[allow(dead_code)]
    #[inline(always)]
    pub fn from<T>(&mut self, mut n: T) -> &[u8]
      where T: Copy +
               PartialEq +
               PartialOrd +
               Div<Output=T> +
               Rem<Output=T> +
               Not<Output=T> +
               NumCast +
               Zero +
               One +
               WrappingAdd
    {
      let zero = T::zero();
      let one  = T::one();
      let ten  = num_cast!(10);

      self.buf.clear();
      if n == zero {
        self.buf.push(b'0');
        return self.buf.as_slice();
      }

      let mut is_negative = false;
      if n < zero {
        is_negative = true;
        n = (!n).wrapping_add(&one);
      }

      while n > zero {
        self.buf.push(num_cast!(n % ten, u8) + b'0');
        n = n / ten;
      }
      if is_negative {
        self.buf.push(b'-');
      }
      self.buf.reverse();
      self.buf.as_slice()
    }
  } // impl ItoA

  //----------------------------------------------------------------------
  #[derive(Debug)]
  pub struct Scanner<R> {
    reader: R,
    buf   : Vec<u8>,
  }

  impl<R> Scanner<R>
    where R: ::std::io::BufRead
  {
    #[allow(dead_code)]
    #[inline(always)]
    pub fn with_capacity(cap: usize, reader: R) -> Self {
      Scanner {
        reader: reader,
        buf   : Vec::with_capacity(cap),
      }
    }

    #[allow(dead_code)]
    #[inline(always)]
    pub fn read_until(&mut self, delim: u8) -> &[u8] {
      self.buf.clear();
      let mut len = self.reader.read_until(delim, &mut self.buf).unwrap();
      if len == 0 {
        return self.buf.as_slice();
      }

      len -= 1;
      if self.buf[len] == delim {
        self.buf.truncate(len);
      }
      self.buf.as_slice()
    }

    #[allow(dead_code)]
    #[inline(always)]
    pub fn for_each<F>(&mut self, n: usize, delim: u8, mut func: F)
      where F: FnMut(&[u8])
    {
      for _ in 0..n - 1 {
        func(self.read_until(delim));
      }
      func(self.read_until(LF))
    }

    #[allow(dead_code)]
    #[inline(always)]
    pub fn fold<T, F>(&mut self, n: usize, delim: u8, mut init: T, mut func: F) -> T
      where F: FnMut(T, &[u8]) -> T
    {
      for _ in 0..n - 1 {
        init = func(init, self.read_until(delim));
      }
      func(init, self.read_until(LF))
    }
  } // impl<R> Scanner<R>
} // mod my

fn solve() {
    let (h, w, k): (usize, usize, usize) = (read::<usize>(), read::<usize>(), read::<usize>());
    let mut map = vec![];
    for i in 0..h {
        let s: Vec<char> = read::<String>().chars().collect();
        map.push(s);
    }
    let mut ans = 0;

    for i in 0..(2usize.pow(h as u32) - 1) {
        for j in 0..(2usize.pow(w as u32) - 1) {
            let mut srow = HashSet::new();
            // 消す行
            for k in 0..h {
                if i >> k & 1 == 1 {
                    srow.insert(k);
                }
            }
            let mut scol = HashSet::new();
            // 消す列
            for k in 0..w {
                if j >> k & 1 == 1 {
                    scol.insert(k);
                }
            }
            let mut tmp = 0;
            for i1 in 0..h {
                for j1 in 0..w {
                    if map[i1][j1] == '#' && !srow.contains(&i1) && !scol.contains(&j1) {
                        tmp += 1;
                    }
                }
            }
            if tmp == k {
                ans += 1;
            }
        }
    }
    println!("{}", ans);
}

