#[fastout]
pub fn main() {
    input! {
        h: usize, w: usize, k: usize,
        c: [Chars; h],
    }

    let mut v = vec![vec![0; w]; h];
    for y in 0..h {
        for x in 0..w {
            if y == 0 {
                if x == 0 {
                    v[y][x] = if c[y][x] == '.' { 0 } else { 1 };
                } else {
                    v[y][x] = v[y][x - 1] + if c[y][x] == '.' { 0 } else { 1 };
                }
            } else {
                if x == 0 {
                    v[y][x] = v[y - 1][x] + if c[y][x] == '.' { 0 } else { 1 };
                } else {
                    v[y][x] = v[y - 1][x] + v[y][x - 1] - v[y - 1][x - 1]
                        + if c[y][x] == '.' { 0 } else { 1 };
                }
            }
        }
    }

    let mut count = 0;
    for ybit in 0..(1 << h) {
        for xbit in 0..(1 << w) {
            let mut blacks = v[h - 1][w - 1];
            let ys: Vec<_> = (0..h).into_iter().filter(|y| ybit >> y & 1 == 1).collect();
            let xs: Vec<_> = (0..w).into_iter().filter(|x| xbit >> x & 1 == 1).collect();
            let dup: usize = ys
                .iter()
                .map(|y| xs.iter().filter(|x| c[*y][**x] == '#').count())
                .sum();
            blacks += dup;
            let yc: usize = ys
                .iter()
                .map(|y| (0..w).into_iter().filter(|i| c[*y][*i] == '#').count())
                .sum();
            let xc: usize = xs
                .iter()
                .map(|x| (0..h).into_iter().filter(|i| c[*i][*x] == '#').count())
                .sum();
            blacks -= xc + yc;
            if blacks == k {
                count += 1;
            }
        }
    }
    println!("{}", count);
}

