fn dfs(n:usize,select:&mut Vec<Vec<bool>>,select_list:&mut Vec<bool>){

    if select_list.len() == n {
        select.push(select_list.to_vec());
        return;
    }

    for i in 0..2{
        if i == 0{
            select_list.push(true);
        }else{
            select_list.push(false);
        }
        dfs(n,select,select_list);
        select_list.pop();
    }
}

