fn to_bin_vec(i: usize, n: usize) -> Vec<bool> {
    let mut i = i;
    let mut v = vec![];
    for _ in 0..n {
        v.push(i % 2 == 1);
        i /= 2;
    }
    // v.reverse();
    v
}

