#[inline(always)]
fn find_bit<F>(n: usize, mut func: F)
  where F: FnMut(usize)
{
  let mut tmp = n;
  let mut x   = tmp & (!tmp).wrapping_add(1);
  while x != 0 {
    func(x);
    tmp ^= x;
    x = tmp & (!tmp).wrapping_add(1);
  }
}

#[inline(always)]
fn abc173_c() {
  let stdin  = stdin();
  let stdout = stdout();
  let mut scanner = my::Scanner::with_capacity(12, stdin.lock());
  let mut writer  = stdout.lock();
  let mut itoa    = my::ItoA::with_capacity(10);

  let h = my::atoi::<usize>(scanner.read_until(my::SP));
  let w = my::atoi::<usize>(scanner.read_until(my::SP));
  let k = my::atoi::<usize>(scanner.read_until(my::LF));

  let orig = scanner.fold(h, my::LF, Vec::with_capacity(h), | mut v, s | {
    let mut n = 0;
    for i in 0..w {
      n |= if s[i] == b'.' { 0 } else { 1 } << ((w - 1) - i);
    }
    v.push(n);
    v
  });

  let mut ans = 0;
  let row = 1 << h;
  let col = 1 << w;

  let mut map = rustc_hash::FxHashMap::default();
  for i in 0..std::cmp::max(h, w) {
    map.insert(1 << i, i);
  }

  let mut vec = Vec::with_capacity(h);
  vec.resize(h, 0);
  for i in 0..orig.len() {
    vec[i] = orig[i];
  }

  for i in 0..row {
    for j in 0..col {
      for k in 0..orig.len() {
        vec[k] = orig[k];
      }
      find_bit(i, | x | { vec[map[&x]] = 0 });

      let mut mask = 0;
      find_bit(j, | x | { mask |= 1 << map[&x] });

      let mut cnt = 0;
      for k in 0..vec.len() {
        vec[k] &= !mask;
        find_bit(vec[k], | _ | { cnt += 1 });
      }

      if cnt == k {
        ans += 1;
      }
    }
  }

  my_write!(writer, itoa.from_usize(ans), b"\n");
  writer.flush().unwrap();
}

fn main() {
  abc173_c();
