                for j in 0..w {
                    if hbit & 1 << i == 0 && wbit & 1 << j == 0 && m[i][j] == '#' {
                        black += 1;
                    }
                }
            }

            if black == k {
                ans += 1;
            }
        }
    }

    println!("{}", ans);
}

