#[inline(always)]
fn each_bit<T, F>(mut n: T, mut func: F)
  where T: Copy +
           PartialEq +
           ::std::ops::Not<Output=T> +
           ::std::ops::BitAnd<Output=T> +
           ::std::ops::BitXor<Output=T> +
           num_traits::identities::Zero +
           num_traits::identities::One +
           num_traits::ops::wrapping::WrappingAdd,
        F: FnMut(T)
{
  let zero = T::zero();
  let one  = T::one();

  let mut tmp = n & (!n).wrapping_add(&one);
  while tmp != zero {
    func(tmp);
    n   = n ^ tmp;
    tmp = n & (!n).wrapping_add(&one);
  }
}

