fn abc173_c() {
    input! {
        h: usize,
        w: usize,
        k: usize,
        ss: [Chars; h],
    }
    let grid = Array::from_shape_vec(
        (h, w),
        ss.concat()
            .iter()
            .map(|&c| if c == '#' { 1 } else { 0 })
            .collect(),
    )
    .unwrap();
    println!("{}", check_v(&grid, k, 0));

    fn check_v(grid: &Array2<usize>, k: usize, v: usize) -> usize {
        let sum = grid.sum();
        if sum < k {
            return 0;
        }
        let mut total = 0;
        total += check_h(&grid, k, 0);
        for i in v..grid.shape()[1] {
            total += check_v(
                &stack![
                    Axis(1),
                    grid.slice(s![.., ..i]),
                    grid.slice(s![.., (i + 1)..])
                ],
                k,
                i,
            );
        }
        return total;
    }

    fn check_h(grid: &Array2<usize>, k: usize, h: usize) -> usize {
        let sum = grid.sum();
        if sum < k {
            return 0;
        }
        let mut total = if sum == k { 1 } else { 0 };
        for i in h..grid.shape()[0] {
            total += check_h(
                &stack![
                    Axis(0),
                    grid.slice(s![..i, ..]),
                    grid.slice(s![(i + 1).., ..])
                ],
                k,
                i,
            );
        }
        return total;
    }
}

