struct Node {
    h: usize,
    w: usize,
    k: i32,
    c: Vec<Vec<char>>,
    ans: i32
}

impl Node {
    fn dfs(
        &mut self,
        bit: Vec<i32>
    ) {
        let mut cnt = 0;

        for i in 0..self.h {
            for j in 0..self.w { 
                let mask_h = bit.get(i).unwrap_or(&0) == &1;
                let mask_w = bit.get(self.h + j).unwrap_or(&0) == &1;
                if mask_h || mask_w {
                    continue
                }
                if self.c[i][j] == '#' {
                    cnt = cnt + 1;
                }
            }
        }

        if bit.len() == (self.h + self.w) {
            if cnt == self.k {
                self.ans = self.ans + 1;
            }
            return;
        }

        // Not Selected
        self.dfs(bit.iter().cloned().chain(vec![0]).collect());
        // Selected
        self.dfs(bit.iter().cloned().chain(vec![1]).collect());
    }
}

