                    bits.push(i);
                }
            }
            vbitw.push(bits);
            bitw += 1;
        }
    }
    let mut vbith = Vec::new();
    {
        let mut bith = 0;
        loop {
            let mut bits = Vec::new();
            if bith >= (1 << h) {break;}
