        let mut char_line = Vec::new();
        for ch in line.as_str().chars() {
            char_line.push(ch);
        }
        buf.push(char_line);
    }

    let mut count = 0;
    let mut l: Vec<usize> = vec![0usize; h + w];

    println!("{}", dfs(h, w, k, &buf, &mut l, 0));
}

fn dfs(h: usize, w: usize, k: usize, c: &Vec<Vec<char>>, l: &mut Vec<usize>, i: usize) -> usize {
    let mut count: usize = 0;
    if i == l.len() {
        let mut sharp_count = 0;
        let mut h_buf = Vec::new();
        let mut w_buf = Vec::new();
        for j in 0..l.len() {
            if j < h {
                h_buf.push(l[j])
            } else {
                w_buf.push(l[j])
            }
        }

        for ch_h in 0..h {
            if h_buf[ch_h] == 1 {
                continue;
            }
            for ch_w in 0..w {
                if w_buf[ch_w] == 1 {
                    continue;
                }
                if sharp_count > k {
                    break;
                }
                if c[ch_h][ch_w] == '#' {
                    sharp_count += 1;
                }
            }
        }

        if sharp_count == k {
            count += 1;
        } else {
            count = 0;
        }
    } else {
        for j in 0..2 {
            l[i] = j;
            count += dfs(h, w, k, c, l, i + 1);
        }
    }
    count
}

