  {
    let (h, w, k) = scan!(usize, usize, usize);
    let c = scan_bytes_map!(ByteChar; h);

    let mut ans = 0;
    for row_set in 0..1 << h {
      for col_set in 0..1 << w {
        let mut cnt_black = 0;
        for i in 0..h {
          for j in 0..w {
            if row_set & (1 << i) == 0 && col_set & (1 << j) == 0 && c[i][j].0 == b'#' {
              cnt_black += 1;
            }
          }
        }
        if cnt_black == k {
          ans += 1;
        }
      }
    }
    println!("{}", ans);
  }
  #[allow(unreachable_code)]
  Ok(())
}

use itertools::iproduct;
use proconio::{input, marker::Chars};

fn main() {
    input!(h: usize, w: usize, k: usize, g: [Chars; h]);
    println!(
        "{}",
        iproduct!(0..1 << h, 0..1 << w)
            .filter(|&(bs, cs)| {
                iproduct!(
                    (0..h).filter(|&i| bs >> i & 1 == 1),
                    (0..w).filter(|&j| cs >> j & 1 == 1)
                )
                .filter(|&(i, j)| g[i][j] == '#')
                .count()
                    == k
            })
            .count()
    );
}

use proconio::{input, fastout, marker::Chars};

#[fastout]
fn main() {
    input! {
        h: usize,
        w: usize,
        k: usize,
        c: [Chars; h],
    }
    let mut res = 0;

    for i in 0..((2 as usize).pow(h as u32)) {
        for j in 0..((2 as usize).pow(w as u32)) {
            let mut temp_c = c.clone();
            for ii in 0..h {
                if ((i+1) & (1 << ii)) > 0 {
                    for i_j in 0..w {
                        temp_c[ii][i_j] = 'r';
                    }
                }
            }
            for jj in 0..w {
                if ((j+1) & (1 << jj)) > 0 {
                    for j_i in 0..h {
                        temp_c[j_i][jj] = 'r';
                    }
                }
            }

            // cnt #
            let mut temp_cnt_k = 0;
            for cnt_i in 0..h {
                for cnt_j in 0..w {
                    if temp_c[cnt_i][cnt_j] == '#' {
                        temp_cnt_k += 1;
                    }
                }
            }
            if temp_cnt_k == k {
                res += 1;
            }
        }
    }

    println!("{:?}", res);
}
